-- 14) Import the existing 58 beginner lessons without overwriting future edits.
with seed as (
  select $academy_seed$[{"id":"html:0","course_id":"html","title":"HTML چیست؟","content_html":"<p>HTML مخفف HyperText Markup Language است. با آن ساختار محتوای یک صفحه وب را مشخص می‌کنیم؛ مثلاً عنوان، پاراگراف، تصویر و لینک.</p><ul><li>HTML زبان نشانه‌گذاری است، نه زبان برنامه‌نویسی.</li><li>مرورگر تگ‌ها را می‌خواند و محتوا را نمایش می‌دهد.</li></ul>","starter_code":"<h1>سلام دنیا</h1>\n<p>این اولین صفحه من است.</p>","exercise":"یک صفحه ساده بساز که عنوان «آکادمی من» و یک پاراگراف معرفی داشته باشد.","sort_order":0},{"id":"html:1","course_id":"html","title":"ساختار استاندارد صفحه","content_html":"<p>هر سند HTML با اعلام نوع سند شروع می‌شود. عنصر html ریشه صفحه است، head اطلاعات صفحه را نگه می‌دارد و body محتوای قابل مشاهده را.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>صفحه من</title>\n</head>\n<body>\n  <h1>سلام!</h1>\n</body>\n</html>","exercise":"یک سند کامل HTML با lang فارسی، charset، عنوان صفحه و بخش body بساز.","sort_order":1},{"id":"html:2","course_id":"html","title":"عنوان‌ها و پاراگراف‌ها","content_html":"<p>برای عنوان‌ها از h1 تا h6 استفاده می‌شود. تگ p برای پاراگراف است. عنوان‌ها باید ترتیب منطقی داشته باشند و فقط برای بزرگ کردن متن استفاده نشوند.</p>","starter_code":"<h1>عنوان اصلی</h1>\n<h2>عنوان بخش</h2>\n<p>این یک پاراگراف است.</p>","exercise":"برای یک مقاله، یک عنوان اصلی، دو عنوان فرعی و سه پاراگراف ایجاد کن.","sort_order":2},{"id":"html:3","course_id":"html","title":"لینک‌ها","content_html":"<p>تگ a برای ساخت لینک است. آدرس مقصد را در ویژگی href قرار می‌دهیم. برای باز کردن لینک در زبانه جدید از target استفاده می‌شود و بهتر است rel نیز تنظیم شود.</p>","starter_code":"<a href=\"https://example.com\">بازدید از سایت</a>\n<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\">در زبانه جدید</a>","exercise":"یک لینک به سایت دلخواه و یک لینک که در زبانه جدید باز شود بساز.","sort_order":3},{"id":"html:4","course_id":"html","title":"تصاویر و متن جایگزین","content_html":"<p>تگ img تصویر را نمایش می‌دهد. ویژگی src مسیر تصویر و alt توضیح متنی تصویر است. متن alt برای دسترس‌پذیری و زمانی که تصویر بارگذاری نشود اهمیت دارد.</p>","starter_code":"<img src=\"photo.jpg\" alt=\"نمایی از طبیعت\" width=\"300\">","exercise":"یک تصویر اضافه کن و برای آن alt توصیفی و عرض ۲۵۰ پیکسل تعیین کن.","sort_order":4},{"id":"html:5","course_id":"html","title":"فهرست‌ها","content_html":"<p>برای فهرست بدون ترتیب از ul و برای فهرست شماره‌دار از ol استفاده کن. هر مورد فهرست داخل li قرار می‌گیرد.</p>","starter_code":"<ul>\n  <li>HTML</li>\n  <li>CSS</li>\n</ul>\n<ol>\n  <li>یادگیری</li>\n  <li>تمرین</li>\n</ol>","exercise":"فهرست شماره‌دار سه مرحله‌ای و فهرست بدون ترتیب سه مهارت بساز.","sort_order":5},{"id":"html:6","course_id":"html","title":"عناصر معنایی HTML","content_html":"<p>عناصر معنایی نامی دارند که نقش محتوا را روشن می‌کند. header برای سربرگ، nav برای ناوبری، main برای محتوای اصلی، section برای بخش و footer برای پابرگ مناسب است.</p><p>از این عناصر به‌جای استفاده بی‌دلیل از div استفاده کن تا ساختار صفحه برای مرورگرها و ابزارهای کمکی قابل فهم‌تر باشد.</p>","starter_code":"<header>سربرگ سایت</header>\n<nav><a href='#home'>خانه</a></nav>\n<main>\n  <section><h2>درباره ما</h2><p>متن بخش</p></section>\n</main>\n<footer>پابرگ</footer>","exercise":"صفحه‌ای با header، nav، main، section و footer بساز.","sort_order":6},{"id":"html:7","course_id":"html","title":"ساخت فرم","content_html":"<p>فرم‌ها اطلاعات را از کاربر می‌گیرند. عنصر form محدوده فرم را می‌سازد و label عنوان هر ورودی را مشخص می‌کند. ویژگی for در label باید با id ورودی برابر باشد.</p>","starter_code":"<form>\n  <label for='fullname'>نام:</label>\n  <input id='fullname' name='fullname'>\n  <button type='submit'>ارسال</button>\n</form>","exercise":"فرمی با ورودی نام و دکمه ارسال بساز و label مرتبط اضافه کن.","sort_order":7},{"id":"html:8","course_id":"html","title":"انواع ورودی‌ها","content_html":"<p>ویژگی type نوع ورودی را مشخص می‌کند. email برای ایمیل، password برای رمز، number برای عدد، date برای تاریخ و checkbox برای انتخاب روشن/خاموش کاربرد دارند.</p><p>برای هر ورودی یک label قابل کلیک فراهم کن و در صورت نیاز از required استفاده کن.</p>","starter_code":"<label for='email'>ایمیل</label>\n<input id='email' type='email' required>\n<label for='age'>سن</label>\n<input id='age' type='number' min='1' max='120'>\n<label><input type='checkbox'> قوانین را می‌پذیرم</label>","exercise":"ورودی ایمیل، رمز عبور، تاریخ و checkbox ایجاد کن.","sort_order":8},{"id":"html:9","course_id":"html","title":"دکمه‌ها و ارسال فرم","content_html":"<p>دکمه داخل فرم به‌طور پیش‌فرض ممکن است فرم را ارسال کند. type='submit' برای ارسال و type='button' برای عملیاتی که نباید فرم را ارسال کند استفاده می‌شود.</p>","starter_code":"<form action='/register' method='post'>\n  <input name='username' required>\n  <button type='submit'>ثبت‌نام</button>\n  <button type='button' onclick='alert('سلام')'>نمایش پیام</button>\n</form>","exercise":"فرمی بساز که دکمه ارسال و دکمه عادی با عملکرد متفاوت داشته باشد.","sort_order":9},{"id":"html:10","course_id":"html","title":"جدول‌ها","content_html":"<p>برای داده‌های جدولی از table استفاده کن. tr ردیف، th عنوان ستون و td خانه داده است. caption عنوان جدول را می‌دهد و thead و tbody بخش‌های جدول را جدا می‌کنند.</p>","starter_code":"<table>\n  <caption>نمره‌ها</caption>\n  <thead><tr><th>نام</th><th>نمره</th></tr></thead>\n  <tbody><tr><td>سارا</td><td>۱۸</td></tr></tbody>\n</table>","exercise":"جدولی با سه ستون نام، درس و نمره و حداقل دو ردیف داده بساز.","sort_order":10},{"id":"html:11","course_id":"html","title":"صدا و ویدیو","content_html":"<p>عناصر audio و video برای پخش رسانه هستند. ویژگی controls کنترل‌های پخش را نمایش می‌دهد. می‌توان چند source با قالب‌های متفاوت تعریف کرد تا مرورگر گزینه سازگار را انتخاب کند.</p>","starter_code":"<video controls width='320'>\n  <source src='movie.mp4' type='video/mp4'>\n  مرورگر شما از ویدیو پشتیبانی نمی‌کند.\n</video>\n<audio controls src='sound.mp3'></audio>","exercise":"یک عنصر video با controls و متن جایگزین در صورت پشتیبانی‌نشدن اضافه کن.","sort_order":11},{"id":"html:12","course_id":"html","title":"ویژگی‌های عمومی و data","content_html":"<p>ویژگی‌هایی مانند id و class روی عناصر مختلف قابل استفاده‌اند. id باید در صفحه یکتا باشد؛ class برای گروهی از عناصر مناسب است. ویژگی‌های data-* برای نگهداری داده‌های سفارشی در HTML هستند.</p>","starter_code":"<article id='lesson-1' class='card' data-level='beginner'>\n  <h2>درس اول</h2>\n  <p>شروع یادگیری</p>\n</article>","exercise":"برای یک کارت id، class و data-level تعریف کن.","sort_order":12},{"id":"html:13","course_id":"html","title":"div و span","content_html":"<p>div یک ظرف بلوکی عمومی و span یک ظرف درون‌خطی عمومی است. وقتی عنصر معنایی مناسب وجود ندارد، از آن‌ها برای گروه‌بندی و استایل‌دهی استفاده کن؛ نه اینکه همه صفحه را با div بسازی.</p>","starter_code":"<div class='profile'>\n  <h2>مشخصات</h2>\n  <p>نام: <span class='highlight'>علی</span></p>\n</div>","exercise":"با div دو بخش بساز و با span یک کلمه را درون پاراگراف مشخص کن.","sort_order":13},{"id":"html:14","course_id":"html","title":"دسترس‌پذیری و HTML درست","content_html":"<p>برای دسترس‌پذیری، تصویر معنادار باید alt مناسب داشته باشد، فرم‌ها label داشته باشند، ترتیب عنوان‌ها منطقی باشد و لینک‌ها متن توصیفی داشته باشند. از عنصر درست برای کار درست استفاده کن.</p>","starter_code":"<img src='team.jpg' alt='اعضای تیم در جلسه کاری'>\n<h1>آموزش وب</h1>\n<h2>درس‌های رایگان</h2>\n<a href='/courses'>مشاهده دوره‌های آموزشی</a>","exercise":"برای تصویر alt، برای ورودی label و برای دکمه متن واضح قرار بده.","sort_order":14},{"id":"css:0","course_id":"css","title":"CSS چیست؟","content_html":"<p>CSS مخفف Cascading Style Sheets است و ظاهر عناصر HTML را کنترل می‌کند؛ مانند رنگ، اندازه، فاصله و چیدمان.</p><p>قانون CSS از انتخابگر و مجموعه‌ای از ویژگی‌ها و مقدارها تشکیل می‌شود.</p>","starter_code":"h1 {\n  color: crimson;\n  font-size: 32px;\n}","exercise":"رنگ عنوان را قرمز و اندازه آن را ۳۲ پیکسل کن.","sort_order":0},{"id":"css:1","course_id":"css","title":"سه روش افزودن CSS","content_html":"<p>CSS را می‌توان در ویژگی style، داخل تگ style یا در فایل جداگانه با پسوند css نوشت. برای پروژه‌های واقعی، فایل جداگانه معمولاً نگهداری را ساده‌تر می‌کند.</p>","starter_code":"<!-- در فایل HTML -->\n<link rel=\"stylesheet\" href=\"style.css\">\n\n/* در فایل style.css */\nbody { font-family: Arial; }","exercise":"یک فایل style.css بساز و آن را به فایل HTML وصل کن.","sort_order":1},{"id":"css:2","course_id":"css","title":"انتخابگرها","content_html":"<p>انتخابگر مشخص می‌کند کدام عنصر استایل بگیرد. نام تگ، کلاس با نقطه و شناسه با # انتخابگرهای رایج هستند.</p>","starter_code":"p { color: #444; }\n.card { padding: 16px; }\n#main-title { color: red; }","exercise":"با انتخابگر تگ، کلاس و شناسه سه عنصر متفاوت را استایل بده.","sort_order":2},{"id":"css:3","course_id":"css","title":"رنگ و پس‌زمینه","content_html":"<p>رنگ را می‌توان با نام، کد HEX یا تابع rgb مشخص کرد. ویژگی background-color رنگ پس‌زمینه را تعیین می‌کند.</p>","starter_code":"body { background-color: #101018; }\nh1 { color: #ff303b; }\n.note { color: rgb(180,180,190); }","exercise":"برای صفحه پس‌زمینه تیره و برای متن رنگ روشن انتخاب کن.","sort_order":3},{"id":"css:4","course_id":"css","title":"مدل جعبه‌ای","content_html":"<p>هر عنصر در CSS مانند یک جعبه است: محتوا، padding، border و margin. استفاده از box-sizing: border-box محاسبه اندازه‌ها را قابل پیش‌بینی‌تر می‌کند.</p>","starter_code":"* { box-sizing: border-box; }\n.card {\n  padding: 20px;\n  border: 1px solid #ccc;\n  margin: 12px;\n}","exercise":"یک کارت با padding، border و margin بساز و box-sizing را تنظیم کن.","sort_order":4},{"id":"css:5","course_id":"css","title":"Flexbox و واکنش‌گرایی","content_html":"<p>Flexbox برای چیدمان یک‌بعدی کاربرد دارد. با media query می‌توان ظاهر صفحه را برای نمایشگرهای کوچک تغییر داد.</p>","starter_code":".row { display: flex; gap: 12px; }\n@media (max-width: 600px) {\n  .row { flex-direction: column; }\n}","exercise":"سه کارت را با Flexbox کنار هم بچین و در عرض کمتر از ۶۰۰ پیکسل ستونی کن.","sort_order":5},{"id":"css:6","course_id":"css","title":"آبشار و وراثت CSS","content_html":"<p>وقتی چند قانون روی یک عنصر اثر می‌گذارند، آبشار CSS با توجه به اهمیت، اختصاصیت و ترتیب قوانین تصمیم می‌گیرد کدام مقدار اعمال شود. بعضی ویژگی‌ها مانند color به فرزندان به ارث می‌رسند.</p>","starter_code":"body { color: #333; }\n.card { color: #b21e35; }\n.card p { color: inherit; }","exercise":"رنگ متن body را تعیین کن و رنگ یک عنصر فرزند را جداگانه تغییر بده.","sort_order":6},{"id":"css:7","course_id":"css","title":"اختصاصیت انتخابگرها","content_html":"<p>انتخابگر id معمولاً از class اختصاصی‌تر است و class از انتخابگر نام تگ اختصاصی‌تر. برای جلوگیری از پیچیدگی، تا حد ممکن از کلاس‌های قابل استفاده مجدد استفاده کن و به !important وابسته نشو.</p>","starter_code":"p { color: gray; }\n.note { color: crimson; }\n#intro { color: navy; }","exercise":"برای یک عنصر قانون تگ، کلاس و شناسه بنویس و نتیجه را مقایسه کن.","sort_order":7},{"id":"css:8","course_id":"css","title":"واحدهای اندازه‌گیری","content_html":"<p>px واحد ثابت، درصد نسبی به اندازه والد، em وابسته به اندازه فونت عنصر والد و rem وابسته به اندازه فونت ریشه است. برای اندازه‌های قابل تطبیق معمولاً rem و درصد انتخاب‌های مناسبی‌اند.</p>","starter_code":"html { font-size: 16px; }\nh1 { font-size: 2rem; }\n.container { width: 90%; max-width: 1100px; }\n.card { padding: 1em; }","exercise":"یک کارت با rem برای فونت و درصد برای عرض بساز.","sort_order":8},{"id":"css:9","course_id":"css","title":"فونت و خوانایی متن","content_html":"<p>با font-family نوع قلم، font-size اندازه، font-weight ضخامت و line-height فاصله خطوط را کنترل می‌کنی. برای متن فارسی، قلم مناسب و فاصله خطوط کافی خوانایی را بهتر می‌کند.</p>","starter_code":"body { font-family: Tahoma, Arial, sans-serif; }\np { font-size: 16px; line-height: 1.9; }\nh1 { font-weight: 800; }","exercise":"برای متن فارسی فونت مناسب، line-height و اندازه خوانا تنظیم کن.","sort_order":9},{"id":"css:10","course_id":"css","title":"display و جریان عناصر","content_html":"<p>display رفتار چیدمان عنصر را تعیین می‌کند. block تمام عرض در دسترس را می‌گیرد، inline در جریان متن قرار می‌گیرد، inline-block امکان تعیین ابعاد را می‌دهد و none عنصر را از چیدمان حذف می‌کند.</p>","starter_code":".badge { display: inline-block; padding: 6px 10px; }\n.hidden { display: none; }\n.card { display: block; }","exercise":"دو عنصر را با inline-block کنار هم قرار بده و تفاوت block را بررسی کن.","sort_order":10},{"id":"css:11","course_id":"css","title":"موقعیت‌دهی عناصر","content_html":"<p>position با مقادیر static، relative، absolute، fixed و sticky موقعیت عنصر را کنترل می‌کند. absolute نسبت به نزدیک‌ترین والد موقعیت‌دار محاسبه می‌شود؛ sticky هنگام پیمایش می‌تواند به لبه صفحه بچسبد.</p>","starter_code":".parent { position: relative; }\n.label { position: absolute; top: 8px; right: 8px; }\nheader { position: sticky; top: 0; }","exercise":"یک نشان کوچک را در گوشه بالای کارت با position قرار بده.","sort_order":11},{"id":"css:12","course_id":"css","title":"CSS Grid","content_html":"<p>Grid برای چیدمان دوبعدی ردیف و ستون مناسب است. با grid-template-columns ستون‌ها و با gap فاصله خانه‌ها را تعیین می‌کنی. repeat و minmax ساخت شبکه‌های منعطف را آسان می‌کنند.</p>","starter_code":".grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 16px;\n}\n@media (max-width: 650px) {\n  .grid { grid-template-columns: 1fr; }\n}","exercise":"یک شبکه سه‌ستونه بساز و فاصله بین کارت‌ها را تنظیم کن.","sort_order":12},{"id":"css:13","course_id":"css","title":"شبه‌کلاس‌ها","content_html":"<p>شبه‌کلاس‌ها وضعیت عنصر را هدف می‌گیرند. :hover هنگام قرار گرفتن نشانگر، :focus هنگام دریافت تمرکز و :first-child برای اولین فرزند کاربرد دارند. برای کاربران صفحه‌کلید، حالت focus را حذف نکن.</p>","starter_code":"a:hover { color: crimson; }\ninput:focus { outline: 2px solid crimson; }\nli:first-child { font-weight: bold; }","exercise":"برای لینک حالت hover و برای ورودی حالت focus تعریف کن.","sort_order":13},{"id":"css:14","course_id":"css","title":"شبه‌عنصرها","content_html":"<p>شبه‌عنصرهایی مانند ::before و ::after بخشی مجازی برای نمایش تزئینات ایجاد می‌کنند. برای محتوای مهم و ضروری به آن‌ها تکیه نکن؛ چون هدف اصلی‌شان ارائه ظاهری است.</p>","starter_code":".title::after {\n  content: '';\n  display: block;\n  width: 50px;\n  height: 3px;\n  background: crimson;\n}","exercise":"با ::before یک نشان تزئینی پیش از عنوان ایجاد کن.","sort_order":14},{"id":"css:15","course_id":"css","title":"رنگ، شفافیت و سایه","content_html":"<p>برای رنگ می‌توان از HEX، rgb و hsl استفاده کرد. opacity شفافیت کل عنصر و box-shadow سایه جعبه را کنترل می‌کند. برای متن، کنتراست کافی با پس‌زمینه ضروری است.</p>","starter_code":".card {\n  color: #222;\n  background: rgba(255,255,255,.95);\n  box-shadow: 0 8px 24px rgba(0,0,0,.15);\n}","exercise":"برای کارت پس‌زمینه نیمه‌شفاف و سایه ملایم بساز.","sort_order":15},{"id":"css:16","course_id":"css","title":"انتقال و تبدیل","content_html":"<p>transition تغییر ویژگی را نرم می‌کند و transform عنصر را جابه‌جا، چرخان یا بزرگ و کوچک می‌کند. فقط ویژگی‌هایی را متحرک کن که تجربه کاربر را بهتر می‌کنند.</p>","starter_code":".button { transition: transform .2s, background .2s; }\n.button:hover { transform: translateY(-2px); }","exercise":"با hover کارت را کمی بزرگ کن و تغییر را با transition نرم کن.","sort_order":16},{"id":"css:17","course_id":"css","title":"متغیرهای CSS","content_html":"<p>متغیرهای سفارشی با دو خط تیره تعریف می‌شوند و با var خوانده می‌شوند. آن‌ها برای رنگ‌های برند، فاصله‌ها و تنظیمات مشترک بسیار مفیدند.</p>","starter_code":":root {\n  --brand: #e32636;\n  --space: 16px;\n}\n.button { background: var(--brand); padding: var(--space); }","exercise":"رنگ اصلی را در :root تعریف کن و در دو عنصر استفاده کن.","sort_order":17},{"id":"js:0","course_id":"js","title":"JavaScript چیست؟","content_html":"<p>JavaScript زبان برنامه‌نویسی است که می‌تواند به صفحه وب رفتار اضافه کند؛ مثل واکنش به کلیک، محاسبه و تغییر محتوا.</p>","starter_code":"console.log('سلام از JavaScript!');","exercise":"با console.log یک پیام خوش‌آمدگویی در کنسول نمایش بده.","sort_order":0},{"id":"js:1","course_id":"js","title":"متغیرها","content_html":"<p>برای نگهداری داده از let و const استفاده می‌کنیم. مقدار const دوباره به متغیر نسبت داده نمی‌شود؛ let برای مقداری است که ممکن است تغییر کند.</p>","starter_code":"const academy = 'NEXORA';\nlet lessons = 6;\nlessons = 7;\nconsole.log(academy, lessons);","exercise":"نام آکادمی را با const و تعداد درس‌ها را با let ذخیره و چاپ کن.","sort_order":1},{"id":"js:2","course_id":"js","title":"نوع داده‌ها","content_html":"<p>رشته، عدد، مقدار بولی، آرایه و شیء از انواع داده رایج هستند. typeof نوع بسیاری از مقدارها را نشان می‌دهد.</p>","starter_code":"const name = 'Ali';\nconst age = 18;\nconst active = true;\nconsole.log(typeof name);\nconsole.log(typeof age);","exercise":"یک رشته، عدد، مقدار بولی، آرایه و شیء بساز و نوع داده‌ها را بررسی کن.","sort_order":2},{"id":"js:3","course_id":"js","title":"شرط‌ها","content_html":"<p>با if و else می‌توان بر اساس درست یا نادرست بودن یک شرط مسیرهای متفاوتی اجرا کرد. برای مقایسه مقدار و نوع، معمولاً از === استفاده کن.</p>","starter_code":"const score = 75;\nif (score >= 50) {\n  console.log('قبول شدی');\n} else {\n  console.log('بیشتر تمرین کن');\n}","exercise":"بر اساس نمره، پیام قبولی یا نیاز به تمرین نمایش بده.","sort_order":3},{"id":"js:4","course_id":"js","title":"تابع‌ها","content_html":"<p>تابع مجموعه‌ای از دستورهاست که می‌توان آن را دوباره اجرا کرد. تابع می‌تواند ورودی بگیرد و با return نتیجه برگرداند.</p>","starter_code":"function greet(name) {\n  return 'سلام ' + name;\n}\nconsole.log(greet('دوست من'));","exercise":"تابعی بنویس که نام را بگیرد و پیام خوش‌آمدگویی برگرداند.","sort_order":4},{"id":"js:5","course_id":"js","title":"رویداد کلیک","content_html":"<p>رویدادها به ما اجازه می‌دهند به کار کاربر واکنش نشان دهیم. در این مثال با کلیک روی دکمه، متن صفحه تغییر می‌کند.</p>","starter_code":"<button id=\"helloBtn\">کلیک کن</button>\n<p id=\"message\"></p>\n<script>\ndocument.querySelector('#helloBtn').addEventListener('click', () => {\n document.querySelector('#message').textContent = 'آفرین!';\n});\n<\\/script>","exercise":"با کلیک روی دکمه، متن یک پاراگراف را تغییر بده.","sort_order":5},{"id":"js:6","course_id":"js","title":"عملگرهای ریاضی و مقایسه","content_html":"<p>عملگرهای +، -، * و / محاسبه می‌کنند. عملگرهای ===، !==، بزرگ‌تر و کوچک‌تر برای مقایسه‌اند. برای مقایسه مقدار و نوع، از مقایسه سخت‌گیرانه استفاده کن.</p>","starter_code":"const price = 120;\nconst count = 3;\nconsole.log(price * count);\nconsole.log(count >= 2);\nconsole.log(5 === '5'); // false","exercise":"دو عدد را با عملگرهای +، * و === مقایسه و نتیجه را چاپ کن.","sort_order":6},{"id":"js:7","course_id":"js","title":"عملگرهای منطقی","content_html":"<p>عملگر && وقتی هر دو شرط درست باشند نتیجه درست می‌دهد؛ || وقتی دست‌کم یکی درست باشد و ! مقدار منطقی را برعکس می‌کند.</p>","starter_code":"const age = 20;\nconst hasTicket = true;\nconsole.log(age >= 18 && hasTicket);\nconsole.log(!hasTicket);","exercise":"شرطی بنویس که فقط در صورت درست بودن دو شرط پیام دسترسی بدهد.","sort_order":7},{"id":"js:8","course_id":"js","title":"حلقه for","content_html":"<p>حلقه for برای تکرار تعداد مشخصی از دفعات مناسب است. بخش آغاز، شرط ادامه و تغییر شمارنده در سرآیند حلقه نوشته می‌شوند.</p>","starter_code":"for (let i = 1; i <= 5; i++) {\n  console.log('شماره ' + i);\n}","exercise":"اعداد ۱ تا ۱۰ را با حلقه for در کنسول چاپ کن.","sort_order":8},{"id":"js:9","course_id":"js","title":"حلقه while و کنترل تکرار","content_html":"<p>while تا زمانی اجرا می‌شود که شرط درست باشد. مراقب باش شرط در نهایت نادرست شود؛ وگرنه حلقه بی‌نهایت ایجاد می‌شود. break حلقه را متوقف و continue به تکرار بعدی می‌رود.</p>","starter_code":"let number = 1;\nwhile (number <= 5) {\n  console.log(number);\n  number++;\n}","exercise":"با while تا رسیدن شمارنده به ۵ ادامه بده و سپس متوقف شو.","sort_order":9},{"id":"js:10","course_id":"js","title":"آرایه‌ها","content_html":"<p>آرایه چند مقدار را در یک متغیر نگه می‌دارد. اندیس آرایه از صفر شروع می‌شود؛ length تعداد عناصر را می‌دهد و می‌توان با اندیس به یک عضو دسترسی داشت.</p>","starter_code":"const skills = ['HTML', 'CSS', 'JavaScript'];\nconsole.log(skills[0]);\nconsole.log(skills.length);","exercise":"آرایه‌ای از سه نام درس بساز و عضو اول و آخر را چاپ کن.","sort_order":10},{"id":"js:11","course_id":"js","title":"افزودن و حذف از آرایه","content_html":"<p>push عضو را به انتها اضافه و pop عضو آخر را حذف می‌کند. unshift به ابتدا اضافه و shift عضو اول را حذف می‌کند. این روش‌ها آرایه اصلی را تغییر می‌دهند.</p>","starter_code":"const tasks = ['مطالعه'];\ntasks.push('تمرین');\ntasks.pop();\nconsole.log(tasks);","exercise":"یک درس به انتهای آرایه اضافه و سپس آخرین عضو را حذف کن.","sort_order":11},{"id":"js:12","course_id":"js","title":"پیمایش آرایه با forEach","content_html":"<p>forEach یک تابع را برای هر عضو آرایه اجرا می‌کند. این روش برای انجام کاری روی هر عضو مناسب است و آرایه جدید برنمی‌گرداند.</p>","starter_code":"const names = ['سارا', 'علی', 'مینا'];\nnames.forEach(name => {\n  console.log('سلام ' + name);\n});","exercise":"نام هر عضو آرایه را با forEach در کنسول چاپ کن.","sort_order":12},{"id":"js:13","course_id":"js","title":"متد map و filter","content_html":"<p>map از هر عضو آرایه مقداری می‌سازد و آرایه جدید برمی‌گرداند. filter فقط عضوهایی را نگه می‌دارد که شرط را بگذرانند؛ هر دو آرایه اصلی را دست‌نخورده می‌گذارند.</p>","starter_code":"const numbers = [1, 2, 3, 4];\nconst doubled = numbers.map(n => n * 2);\nconst even = numbers.filter(n => n % 2 === 0);\nconsole.log(doubled, even);","exercise":"از آرایه نمره‌ها با map نمره‌ها را دو برابر و با filter نمره‌های بالای ۵۰ را جدا کن.","sort_order":13},{"id":"js:14","course_id":"js","title":"شیءها","content_html":"<p>شیء داده‌ها را به شکل ویژگی و مقدار نگه می‌دارد. به ویژگی‌ها با نقطه یا براکت دسترسی پیدا می‌کنی. برای داده‌های مرتبط، شیء ساختار روشنی ایجاد می‌کند.</p>","starter_code":"const student = {\n  name: 'مریم',\n  age: 19,\n  active: true\n};\nconsole.log(student.name);\nstudent.age = 20;","exercise":"شیئی برای دانش‌آموز با name، age و course بساز و مقدارها را بخوان.","sort_order":14},{"id":"js:15","course_id":"js","title":"توابع پیکانی و پارامتر پیش‌فرض","content_html":"<p>تابع پیکانی شکل کوتاه‌تری برای تعریف تابع است. می‌توان برای پارامتر مقدار پیش‌فرض گذاشت تا اگر ورودی ارسال نشد از آن استفاده شود.</p>","starter_code":"const greet = (name = 'دوست') => {\n  return 'سلام ' + name;\n};\nconsole.log(greet());\nconsole.log(greet('سارا'));","exercise":"تابع پیکانی بساز که اگر نامی داده نشد، مقدار پیش‌فرض استفاده کند.","sort_order":15},{"id":"js:16","course_id":"js","title":"انتخاب عناصر صفحه با DOM","content_html":"<p>DOM نمای درختی صفحه است. با querySelector اولین عنصر مطابق انتخابگر و با querySelectorAll همه موارد مطابق را پیدا می‌کنی. سپس می‌توان متن یا ویژگی‌های آن‌ها را تغییر داد.</p>","starter_code":"const heading = document.querySelector('h1');\nif (heading) {\n  heading.textContent = 'عنوان تازه';\n}","exercise":"با querySelector عنوان صفحه را پیدا کن و متنش را تغییر بده.","sort_order":16},{"id":"js:17","course_id":"js","title":"رویدادها و event","content_html":"<p>با addEventListener به رویدادهایی مثل click و input گوش می‌دهیم. شیء event اطلاعات رویداد را دارد و currentTarget عنصری را نشان می‌دهد که شنونده روی آن نصب شده است.</p>","starter_code":"const button = document.querySelector('button');\nbutton.addEventListener('click', event => {\n  event.currentTarget.textContent = 'کلیک شد';\n});","exercise":"رویداد کلیک را ثبت کن و نوع رویداد را از شیء event بخوان.","sort_order":17},{"id":"js:18","course_id":"js","title":"کار با فرم و ورودی کاربر","content_html":"<p>برای دریافت مقدار ورودی از value استفاده کن. رویداد submit فرم را می‌توان کنترل کرد و با preventDefault از بارگذاری دوباره صفحه جلوگیری کرد. داده کاربر را قبل از استفاده بررسی کن.</p>","starter_code":"const form = document.querySelector('form');\nform.addEventListener('submit', event => {\n  event.preventDefault();\n  const name = document.querySelector('#name').value.trim();\n  console.log(name);\n});","exercise":"با submit مقدار ورودی را بخوان و از بارگذاری دوباره صفحه جلوگیری کن.","sort_order":18},{"id":"js:19","course_id":"js","title":"اعتبارسنجی ساده فرم","content_html":"<p>اعتبارسنجی یعنی بررسی اینکه داده ورودی قابل قبول است. برای ایمیل و فیلدهای ضروری می‌توان از ویژگی‌های HTML مثل required و type استفاده کرد و در JavaScript پیام دقیق‌تری نمایش داد.</p>","starter_code":"const username = 'Nexora';\nif (username.trim().length < 3) {\n  console.log('نام باید حداقل ۳ حرف باشد');\n} else {\n  console.log('نام معتبر است');\n}","exercise":"بررسی کن ورودی خالی نباشد و ایمیل شامل @ باشد.","sort_order":19},{"id":"js:20","course_id":"js","title":"ذخیره‌سازی در localStorage","content_html":"<p>localStorage داده متنی را در مرورگر همان دستگاه نگه می‌دارد و پس از بستن صفحه باقی می‌ماند. این داده به‌صورت خودکار بین دستگاه‌ها همگام نمی‌شود و برای رمز عبور یا اطلاعات حساس مناسب نیست.</p>","starter_code":"localStorage.setItem('theme', 'dark');\nconst theme = localStorage.getItem('theme');\nconsole.log(theme);\n// localStorage.removeItem('theme');","exercise":"نام کاربر را ذخیره کن و در بارگذاری بعدی بخوان.","sort_order":20},{"id":"js:21","course_id":"js","title":"JSON و تبدیل داده","content_html":"<p>JSON قالبی متنی برای تبادل داده است. JSON.stringify شیء را به متن تبدیل می‌کند و JSON.parse متن معتبر JSON را به داده JavaScript تبدیل می‌کند.</p>","starter_code":"const user = { name: 'Ali', level: 1 };\nconst text = JSON.stringify(user);\nconst copy = JSON.parse(text);\nconsole.log(copy.name);","exercise":"یک شیء را با JSON.stringify به متن و با JSON.parse به شیء تبدیل کن.","sort_order":21},{"id":"js:22","course_id":"js","title":"مدیریت خطا با try و catch","content_html":"<p>گاهی اجرای یک دستور با خطا روبه‌رو می‌شود. try کد پرخطر را در بر می‌گیرد و catch خطا را دریافت می‌کند تا برنامه بتواند واکنش کنترل‌شده نشان دهد.</p>","starter_code":"try {\n  const data = JSON.parse('{bad json}');\n  console.log(data);\n} catch (error) {\n  console.log('داده معتبر نیست');\n}","exercise":"تبدیل یک متن نامعتبر JSON را در try/catch قرار بده و پیام خطا را نمایش بده.","sort_order":22},{"id":"js:23","course_id":"js","title":"تاریخ و زمان","content_html":"<p>شیء Date برای کار با تاریخ و زمان استفاده می‌شود. getFullYear سال و getMonth ماه را از صفر تا یازده برمی‌گرداند؛ برای نمایش ماه انسانی معمولاً یک واحد اضافه می‌کنیم.</p>","starter_code":"const now = new Date();\nconsole.log(now.getFullYear());\nconsole.log(now.getMonth() + 1);\nconsole.log(now.toLocaleDateString('fa-IR'));","exercise":"تاریخ و ساعت فعلی را با شیء Date نمایش بده.","sort_order":23},{"id":"js:24","course_id":"js","title":"پروژه کوچک: شمارنده","content_html":"<p>در این تمرین یک شمارنده می‌سازیم. متغیر count وضعیت را نگه می‌دارد و هر کلیک مقدار را یک واحد افزایش می‌دهد. در پروژه واقعی، HTML دکمه و خروجی باید در صفحه وجود داشته باشند.</p>","starter_code":"let count = 0;\nconst button = document.querySelector('#plus');\nconst output = document.querySelector('#count');\nbutton.addEventListener('click', () => {\n  count++;\n  output.textContent = count;\n});","exercise":"شمارنده‌ای با دکمه‌های افزایش، کاهش و صفرکردن بساز.","sort_order":24}]$academy_seed$::jsonb as payload
),
rows as (
  select * from jsonb_to_recordset((select payload from seed)) as x(
    id text, course_id text, title text, content_html text,
    starter_code text, exercise text, sort_order integer
  )
)
insert into public.academy_lessons(id,course_id,title,content_html,starter_code,exercise,sort_order,status)
select id,course_id,title,content_html,starter_code,exercise,sort_order,'published'
from rows
on conflict (id) do nothing;

-- Public defaults. These contain no secrets.
insert into public.academy_site_settings(key,value,is_public) values
('brand',jsonb_build_object('name','NEXORA FORGE ACADEMY','slogan','BUILD THE FUTURE','direction','rtl','language','fa'),true),
('registration',jsonb_build_object('enabled',true,'guest_access',true,'email_confirmation',true),true),
('catalog',jsonb_build_object('show_draft_courses',false),true)
on conflict (key) do nothing;


-- Super-admin controlled role management; no browser-side role table writes.
create or replace function public.academy_set_user_role(
  p_user_id uuid,
  p_role text,
  p_enabled boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.academy_is_super_admin() then
    raise exception 'Super-admin permission required';
  end if;
  if p_role not in ('student','admin','super_admin') then
    raise exception 'Invalid role';
  end if;
  if p_user_id = auth.uid() and p_role = 'super_admin' and not p_enabled then
    raise exception 'Cannot remove your own super-admin role';
  end if;

  if p_enabled then
    insert into public.academy_user_roles(user_id,role)
    values(p_user_id,p_role)
    on conflict do nothing;
  else
    delete from public.academy_user_roles
    where user_id=p_user_id and role=p_role;
  end if;

  insert into public.academy_activity_logs(actor_user_id,action,entity_type,entity_id,details)
  values(auth.uid(),case when p_enabled then 'role_granted' else 'role_revoked' end,
    'user',p_user_id::text,jsonb_build_object('role',p_role));
end;
$$;
revoke all on function public.academy_set_user_role(uuid,text,boolean) from public, anon;
grant execute on function public.academy_set_user_role(uuid,text,boolean) to authenticated;

create or replace function public.academy_admin_student_overview()
returns table (
  user_id uuid,
  email text,
  display_name text,
  created_at timestamptz,
  completed_lessons bigint,
  quiz_attempts bigint
)
language sql
stable
security definer
set search_path = public
as $$
  select p.user_id, u.email, p.display_name, u.created_at,
    (select count(*) from public.academy_lesson_progress lp
      where lp.user_id=p.user_id and lp.status='completed'),
    (select count(*) from public.academy_quiz_attempts qa where qa.user_id=p.user_id)
  from public.academy_profiles p
  join auth.users u on u.id=p.user_id
  where public.academy_is_admin()
  order by u.created_at desc;
$$;
revoke all on function public.academy_admin_student_overview() from public, anon;
grant execute on function public.academy_admin_student_overview() to authenticated;

-- NEXORA FORGE ACADEMY: 324-lesson curriculum (36 per course)
-- Archives old published lessons without deleting records or student history.
-- Safe to rerun: stable course and lesson IDs are upserted.

update public.academy_lessons l set status='archived',archived_at=coalesce(l.archived_at,now()),updated_at=now() where l.status='published' and l.course_id in (select c.id from public.academy_courses c where c.language_id in ('html','css','javascript') and c.level_id in ('beginner','intermediate','advanced'));
insert into public.academy_courses(id,language_id,level_id,title,slug,description,status,sort_order,estimated_hours)
select x.id,x.language_id,x.level_id,x.title,x.slug,x.description,x.status,x.sort_order,x.estimated_hours
from jsonb_to_recordset($courses$[{"id":"html","language_id":"html","level_id":"beginner","title":"HTML مقدماتی","slug":"html-course","description":"ساختار صفحات وب را از پایه یاد بگیر.","status":"published","sort_order":1,"estimated_hours":18},{"id":"html-intermediate","language_id":"html","level_id":"intermediate","title":"HTML متوسط","slug":"html-intermediate-course","description":"فرم‌های کامل، ساختار معنایی، رسانه و دسترس‌پذیری.","status":"published","sort_order":2,"estimated_hours":22},{"id":"html-advanced","language_id":"html","level_id":"advanced","title":"HTML پیشرفته","slug":"html-advanced-course","description":"استانداردهای مدرن، دسترس‌پذیری عمیق و معماری صفحات.","status":"published","sort_order":3,"estimated_hours":26},{"id":"css","language_id":"css","level_id":"beginner","title":"CSS مقدماتی","slug":"css-course","description":"رنگ، تایپوگرافی، مدل جعبه‌ای و چیدمان پایه.","status":"published","sort_order":1,"estimated_hours":18},{"id":"css-intermediate","language_id":"css","level_id":"intermediate","title":"CSS متوسط","slug":"css-intermediate-course","description":"Flexbox و Grid، واکنش‌گرایی، فرم و حرکت.","status":"published","sort_order":2,"estimated_hours":22},{"id":"css-advanced","language_id":"css","level_id":"advanced","title":"CSS پیشرفته","slug":"css-advanced-course","description":"معماری CSS، طراحی سیستم و بهینه‌سازی رابط.","status":"published","sort_order":3,"estimated_hours":26},{"id":"javascript","language_id":"javascript","level_id":"beginner","title":"JavaScript مقدماتی","slug":"javascript-course","description":"مبانی زبان، داده، شرط، حلقه، تابع و DOM.","status":"published","sort_order":1,"estimated_hours":18},{"id":"javascript-intermediate","language_id":"javascript","level_id":"intermediate","title":"JavaScript متوسط","slug":"javascript-intermediate-course","description":"DOM، رویداد، آرایه، فرم و ماژول.","status":"published","sort_order":2,"estimated_hours":22},{"id":"javascript-advanced","language_id":"javascript","level_id":"advanced","title":"JavaScript پیشرفته","slug":"javascript-advanced-course","description":"ناهمگامی، API، معماری، امنیت و تست.","status":"published","sort_order":3,"estimated_hours":26}]$courses$::jsonb)
as x(id text,language_id text,level_id text,title text,slug text,description text,status text,sort_order integer,estimated_hours numeric)
on conflict(language_id,level_id) do update set title=excluded.title,slug=excluded.slug,description=excluded.description,status='published',sort_order=excluded.sort_order,estimated_hours=excluded.estimated_hours,updated_at=now();
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-html-01","course_id":"html","title":"HTML چیست و مرورگر چگونه آن را می‌خواند","slug":"html-beginner-01","summary":"در این درس HTML چیست و مرورگر چگونه آن را می‌خواند را به‌صورت عملی یاد می‌گیری. HTML زبان نشانه‌گذاری برای توصیف ساختار و معنای محتوای صفحه است؛ زبان برنامه‌نویسی برای محاسبه و تصمیم‌گیری نیست. مرورگر تگ‌ها را تحلیل می‌کند و از آن‌ها درختی از عناصر می‌سازد.","content_html":"<h3>هدف درس</h3><p>HTML زبان نشانه‌گذاری برای توصیف ساختار و معنای محتوای صفحه است؛ زبان برنامه‌نویسی برای محاسبه و تصمیم‌گیری نیست. مرورگر تگ‌ها را تحلیل می‌کند و از آن‌ها درختی از عناصر می‌سازد.</p><h3>نمونه و بررسی</h3><p>این دو عنصر را در مرورگر باز کن و بررسی کن که مرورگر چگونه عنوان و بند متن را به دو گره جدا در ساختار صفحه تبدیل می‌کند.</p><pre><code>&lt;h1&gt;آکادمی NEXORA FORGE&lt;/h1&gt;\n&lt;p&gt;اینجا یاد می‌گیریم وب‌سایت چگونه ساخته می‌شود.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>یک صفحه معرفی شخصی با یک عنوان اصلی و دو پاراگراف بساز. در توضیح خود بنویس HTML چه چیزی را مشخص می‌کند و چه کاری را به CSS می‌سپارد.</p><h3>نکته مهم</h3><p>اشتباه رایج: تصور اینکه HTML به‌تنهایی ظاهر نهایی و رفتار تعاملی را کنترل می‌کند.</p><h3>معیار موفقیت</h3><p>عنوان اصلی و پاراگراف‌ها به‌صورت عنصرهای جدا در DOM دیده شوند و بتوانی نقش HTML را از CSS توضیح بدهی.</p>","starter_code":"<h1>آکادمی NEXORA FORGE</h1>\n<p>اینجا یاد می‌گیریم وب‌سایت چگونه ساخته می‌شود.</p>","exercise":"یک صفحه معرفی شخصی با یک عنوان اصلی و دو پاراگراف بساز. در توضیح خود بنویس HTML چه چیزی را مشخص می‌کند و چه کاری را به CSS می‌سپارد.","status":"published","sort_order":1,"estimated_minutes":20},{"id":"curriculum-324-html-02","course_id":"html","title":"ساخت اولین فایل HTML","slug":"html-beginner-02","summary":"در این درس ساخت اولین فایل HTML را به‌صورت عملی یاد می‌گیری. یک فایل متنی با پسوند .html بساز و آن را با مرورگر باز کن. مرورگر فایل را تفسیر می‌کند؛ لازم نیست برای یک صفحه ساده سرور نصب کنی.","content_html":"<h3>هدف درس</h3><p>یک فایل متنی با پسوند .html بساز و آن را با مرورگر باز کن. مرورگر فایل را تفسیر می‌کند؛ لازم نیست برای یک صفحه ساده سرور نصب کنی.</p><h3>نمونه و بررسی</h3><p>فایل را دقیقاً با نام index.html ذخیره کن؛ سپس عنوان تب و متن داخل بدنه را جداگانه تغییر بده تا تفاوت head و body روشن شود.</p><pre><code>&lt;!doctype html&gt;\n&lt;html lang=\"fa\" dir=\"rtl\"&gt;\n  &lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;title&gt;اولین صفحه&lt;/title&gt;&lt;/head&gt;\n  &lt;body&gt;&lt;h1&gt;سلام وب!&lt;/h1&gt;&lt;/body&gt;\n&lt;/html&gt;</code></pre><h3>تمرین</h3><p>فایلی به نام index.html بساز، کد را وارد کن، ذخیره کن و با مرورگر بازش کن. عنوان تب مرورگر را هم تغییر بده.</p><h3>نکته مهم</h3><p>اگر تغییرات دیده نمی‌شوند، فایل را ذخیره و صفحه را تازه‌سازی کن.</p><h3>معیار موفقیت</h3><p>فایل بدون تغییر پسوند ذخیره شود، در مرورگر باز شود و تغییر title در تب قابل مشاهده باشد.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n  <head><meta charset=\"UTF-8\"><title>اولین صفحه</title></head>\n  <body><h1>سلام وب!</h1></body>\n</html>","exercise":"فایلی به نام index.html بساز، کد را وارد کن، ذخیره کن و با مرورگر بازش کن. عنوان تب مرورگر را هم تغییر بده.","status":"published","sort_order":2,"estimated_minutes":25},{"id":"curriculum-324-html-03","course_id":"html","title":"ساختار استاندارد سند","slug":"html-beginner-03","summary":"در این درس ساختار استاندارد سند را به‌صورت عملی یاد می‌گیری. DOCTYPE حالت استاندارد HTML را فعال می‌کند. عنصر html ریشه سند است؛ head اطلاعات و تنظیمات سند را نگه می‌دارد و body محتوای قابل مشاهده را در بر می‌گیرد.","content_html":"<h3>هدف درس</h3><p>DOCTYPE حالت استاندارد HTML را فعال می‌کند. عنصر html ریشه سند است؛ head اطلاعات و تنظیمات سند را نگه می‌دارد و body محتوای قابل مشاهده را در بر می‌گیرد.</p><h3>نمونه و بررسی</h3><p>درخت سند را از html شروع کن و جایگاه head، body و main را در ابزار توسعه مرورگر پیدا کن.</p><pre><code>&lt;!doctype html&gt;\n&lt;html lang=\"fa\" dir=\"rtl\"&gt;\n&lt;head&gt;\n  &lt;meta charset=\"UTF-8\"&gt;\n  &lt;title&gt;ساختار سند&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;main&gt;&lt;h1&gt;صفحه اصلی&lt;/h1&gt;&lt;/main&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre><h3>تمرین</h3><p>یک سند کامل بساز و جایگاه doctype، html، head و body را مشخص کن. سپس یک main به بدنه اضافه کن.</p><h3>نکته مهم</h3><p>محتوای قابل مشاهده را داخل head قرار نده.</p><h3>معیار موفقیت</h3><p>سند شامل doctype، html، head و body باشد و main فقط محتوای اصلی را در بر بگیرد.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>ساختار سند</title>\n</head>\n<body>\n  <main><h1>صفحه اصلی</h1></main>\n</body>\n</html>","exercise":"یک سند کامل بساز و جایگاه doctype، html، head و body را مشخص کن. سپس یک main به بدنه اضافه کن.","status":"published","sort_order":3,"estimated_minutes":30},{"id":"curriculum-324-html-04","course_id":"html","title":"زبان صفحه و جهت نوشتار","slug":"html-beginner-04","summary":"در این درس زبان صفحه و جهت نوشتار را به‌صورت عملی یاد می‌گیری. ویژگی lang زبان اصلی محتوا را اعلام می‌کند و dir جهت متن را تعیین می‌کند. این اطلاعات به مرورگر، صفحه‌خوان و ابزارهای ترجمه کمک می‌کنند.","content_html":"<h3>هدف درس</h3><p>ویژگی lang زبان اصلی محتوا را اعلام می‌کند و dir جهت متن را تعیین می‌کند. این اطلاعات به مرورگر، صفحه‌خوان و ابزارهای ترجمه کمک می‌کنند.</p><h3>نمونه و بررسی</h3><p>مقدار lang و dir را تغییر بده و رفتار متن فارسی و عبارت انگلیسی را در یک صفحه راست‌به‌چپ مقایسه کن.</p><pre><code>&lt;html lang=\"fa\" dir=\"rtl\"&gt;\n&lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;title&gt;متن فارسی&lt;/title&gt;&lt;/head&gt;\n&lt;body&gt;&lt;p&gt;این صفحه فارسی و راست‌چین است.&lt;/p&gt;&lt;/body&gt;\n&lt;/html&gt;</code></pre><h3>تمرین</h3><p>یک صفحه فارسی بساز و lang را fa و dir را rtl قرار بده. در یک بخش کوتاه انگلیسی، جهت را فقط برای همان بخش ltr کن.</p><h3>نکته مهم</h3><p>جهت کل صفحه را با فاصله یا کاراکترهای ساختگی اصلاح نکن؛ از ویژگی dir استفاده کن.</p><h3>معیار موفقیت</h3><p>زبان سند fa و جهت اصلی rtl باشد و بخش انگلیسی مستقل با ltr نمایش داده شود.</p>","starter_code":"<html lang=\"fa\" dir=\"rtl\">\n<head><meta charset=\"UTF-8\"><title>متن فارسی</title></head>\n<body><p>این صفحه فارسی و راست‌چین است.</p></body>\n</html>","exercise":"یک صفحه فارسی بساز و lang را fa و dir را rtl قرار بده. در یک بخش کوتاه انگلیسی، جهت را فقط برای همان بخش ltr کن.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"curriculum-324-html-05","course_id":"html","title":"عنوان صفحه و اطلاعات head","slug":"html-beginner-05","summary":"در این درس عنوان صفحه و اطلاعات head را به‌صورت عملی یاد می‌گیری. عنصر title نام سند را در تب مرورگر و نتایج جست‌وجو نمایش می‌دهد. meta charset رمزگذاری نویسه‌ها را مشخص می‌کند تا حروف فارسی خراب نشوند.","content_html":"<h3>هدف درس</h3><p>عنصر title نام سند را در تب مرورگر و نتایج جست‌وجو نمایش می‌دهد. meta charset رمزگذاری نویسه‌ها را مشخص می‌کند تا حروف فارسی خراب نشوند.</p><h3>نمونه و بررسی</h3><p>عنوان تب را تغییر بده و meta description را در کد منبع پیدا کن؛ توجه کن که description متن قابل مشاهده داخل صفحه نیست.</p><pre><code>&lt;head&gt;\n  &lt;meta charset=\"UTF-8\"&gt;\n  &lt;meta name=\"description\" content=\"آموزش رایگان HTML به زبان فارسی\"&gt;\n  &lt;title&gt;آموزش HTML | NEXORA FORGE&lt;/title&gt;\n&lt;/head&gt;</code></pre><h3>تمرین</h3><p>برای یک صفحه آموزش HTML عنوانی دقیق و توضیح meta description کوتاه بنویس. صفحه را باز کن و عنوان تب را بررسی کن.</p><h3>نکته مهم</h3><p>title را خالی نگذار و برای هر صفحه عنوان مرتبط و متمایز انتخاب کن.</p><h3>معیار موفقیت</h3><p>تب مرورگر title درست داشته باشد و meta description در head با محتوای صفحه هماهنگ باشد.</p>","starter_code":"<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"description\" content=\"آموزش رایگان HTML به زبان فارسی\">\n  <title>آموزش HTML | NEXORA FORGE</title>\n</head>","exercise":"برای یک صفحه آموزش HTML عنوانی دقیق و توضیح meta description کوتاه بنویس. صفحه را باز کن و عنوان تب را بررسی کن.","status":"published","sort_order":5,"estimated_minutes":20},{"id":"curriculum-324-html-06","course_id":"html","title":"عنصر، تگ و ویژگی","slug":"html-beginner-06","summary":"در این درس عنصر، تگ و ویژگی را به‌صورت عملی یاد می‌گیری. تگ نشانه متنی مانند h1 است؛ عنصر معمولاً از تگ آغاز، محتوا و تگ پایان تشکیل می‌شود. ویژگی‌ها اطلاعات یا تنظیمات بیشتری به عنصر می‌دهند.","content_html":"<h3>هدف درس</h3><p>تگ نشانه متنی مانند h1 است؛ عنصر معمولاً از تگ آغاز، محتوا و تگ پایان تشکیل می‌شود. ویژگی‌ها اطلاعات یا تنظیمات بیشتری به عنصر می‌دهند.</p><h3>نمونه و بررسی</h3><p>در پیوند نمونه، href را مقصد و target و rel را ویژگی‌های رفتاری جداگانه بررسی کن؛ نام تگ با نام عنصر یکی نیست.</p><pre><code>&lt;a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\"&gt;باز کردن نمونه&lt;/a&gt;</code></pre><h3>تمرین</h3><p>یک پیوند بساز و href آن را به نشانی دلخواه تغییر بده. نام ویژگی و مقدار آن را از هم تشخیص بده.</p><h3>نکته مهم</h3><p>نام ویژگی را بدون مقدار لازم یا با کوتیشن ناقص ننویس.</p><h3>معیار موفقیت</h3><p>پیوند مقصد درست داشته باشد و ویژگی‌های اختیاری آن با هدف بازشدن و امنیت پیوند سازگار باشند.</p>","starter_code":"<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\">باز کردن نمونه</a>","exercise":"یک پیوند بساز و href آن را به نشانی دلخواه تغییر بده. نام ویژگی و مقدار آن را از هم تشخیص بده.","status":"published","sort_order":6,"estimated_minutes":25},{"id":"curriculum-324-html-07","course_id":"html","title":"تیترها از h1 تا h6","slug":"html-beginner-07","summary":"در این درس تیترها از h1 تا h6 را به‌صورت عملی یاد می‌گیری. تیترها ساختار سلسله‌مراتبی محتوا را نشان می‌دهند. h1 عنوان اصلی صفحه و h2 و h3 زیرعنوان بخش‌ها هستند؛ اندازه ظاهری معیار انتخاب نیست.","content_html":"<h3>هدف درس</h3><p>تیترها ساختار سلسله‌مراتبی محتوا را نشان می‌دهند. h1 عنوان اصلی صفحه و h2 و h3 زیرعنوان بخش‌ها هستند؛ اندازه ظاهری معیار انتخاب نیست.</p><h3>نمونه و بررسی</h3><p>ساختار تیترها را در نمای دسترس‌پذیری یا outline بررسی کن و ببین آیا زیرعنوان‌ها زیر بخش درست قرار گرفته‌اند.</p><pre><code>&lt;h1&gt;راهنمای HTML&lt;/h1&gt;\n&lt;h2&gt;ساختار سند&lt;/h2&gt;\n&lt;h3&gt;بخش head&lt;/h3&gt;\n&lt;h2&gt;متن و پیوندها&lt;/h2&gt;</code></pre><h3>تمرین</h3><p>برای مقاله‌ای با سه بخش، یک h1 و چند h2 و h3 منطقی بساز. ترتیب را بر اساس ساختار موضوع انتخاب کن.</p><h3>نکته مهم</h3><p>از تیترها فقط برای بزرگ‌کردن متن استفاده نکن و سطح‌ها را بی‌دلیل نپر.</p><h3>معیار موفقیت</h3><p>فقط یک عنوان اصلی مناسب وجود داشته باشد و سطوح زیرعنوان ترتیب معنایی قابل دفاعی داشته باشند.</p>","starter_code":"<h1>راهنمای HTML</h1>\n<h2>ساختار سند</h2>\n<h3>بخش head</h3>\n<h2>متن و پیوندها</h2>","exercise":"برای مقاله‌ای با سه بخش، یک h1 و چند h2 و h3 منطقی بساز. ترتیب را بر اساس ساختار موضوع انتخاب کن.","status":"published","sort_order":7,"estimated_minutes":30},{"id":"curriculum-324-html-08","course_id":"html","title":"پاراگراف و شکست خط","slug":"html-beginner-08","summary":"در این درس پاراگراف و شکست خط را به‌صورت عملی یاد می‌گیری. p برای یک بند مستقل متن است. br فقط وقتی مناسب است که شکست خط بخشی از معنا باشد؛ برای فاصله‌گذاری بین بخش‌ها از آن استفاده نکن.","content_html":"<h3>هدف درس</h3><p>p برای یک بند مستقل متن است. br فقط وقتی مناسب است که شکست خط بخشی از معنا باشد؛ برای فاصله‌گذاری بین بخش‌ها از آن استفاده نکن.</p><h3>نمونه و بررسی</h3><p>سه بند را جداگانه بخوان و شکست خط نشانی را با br مقایسه کن؛ br نباید برای فاصله تزئینی استفاده شود.</p><pre><code>&lt;p&gt;HTML ساختار محتوا را مشخص می‌کند.&lt;/p&gt;\n&lt;p&gt;CSS ظاهر صفحه را کنترل می‌کند.&lt;/p&gt;\n&lt;p&gt;نشانی ما:&lt;br&gt;هرات، افغانستان&lt;/p&gt;</code></pre><h3>تمرین</h3><p>سه پاراگراف مستقل بنویس و فقط در یک نشانی یا شعر از br استفاده کن. تفاوت آن‌ها را توضیح بده.</p><h3>نکته مهم</h3><p>برای ایجاد فاصله عمودی چندین br پشت سر هم قرار نده.</p><h3>معیار موفقیت</h3><p>پاراگراف‌ها مستقل باشند و br فقط برای شکست خطی با معنای واقعی استفاده شود.</p>","starter_code":"<p>HTML ساختار محتوا را مشخص می‌کند.</p>\n<p>CSS ظاهر صفحه را کنترل می‌کند.</p>\n<p>نشانی ما:<br>هرات، افغانستان</p>","exercise":"سه پاراگراف مستقل بنویس و فقط در یک نشانی یا شعر از br استفاده کن. تفاوت آن‌ها را توضیح بده.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"curriculum-324-html-09","course_id":"html","title":"تأکید معنایی با strong و em","slug":"html-beginner-09","summary":"در این درس تأکید معنایی با strong و em را به‌صورت عملی یاد می‌گیری. strong اهمیت زیاد و em تأکید گفتاری را منتقل می‌کند. این عناصر معنایی‌اند؛ صرفاً ابزار ضخیم یا مورب کردن متن نیستند.","content_html":"<h3>هدف درس</h3><p>strong اهمیت زیاد و em تأکید گفتاری را منتقل می‌کند. این عناصر معنایی‌اند؛ صرفاً ابزار ضخیم یا مورب کردن متن نیستند.</p><h3>نمونه و بررسی</h3><p>متن را با صفحه‌خوان یا ابزار دسترس‌پذیری بررسی کن و تفاوت اهمیت strong با تأکید em را توضیح بده.</p><pre><code>&lt;p&gt;&lt;strong&gt;هشدار:&lt;/strong&gt; پیش از بستن صفحه فایل را ذخیره کن.&lt;/p&gt;\n&lt;p&gt;این نکته &lt;em&gt;بسیار مهم&lt;/em&gt; است.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>یک راهنمای کوتاه بنویس و در آن یک هشدار مهم و یک واژه با تأکید معنایی قرار بده.</p><h3>نکته مهم</h3><p>برای ظاهر صرف از CSS استفاده کن، نه اینکه معنای متن را با strong عوض کنی.</p><h3>معیار موفقیت</h3><p>strong و em بر اساس معنا انتخاب شوند و نه صرفاً برای تغییر ظاهر حروف.</p>","starter_code":"<p><strong>هشدار:</strong> پیش از بستن صفحه فایل را ذخیره کن.</p>\n<p>این نکته <em>بسیار مهم</em> است.</p>","exercise":"یک راهنمای کوتاه بنویس و در آن یک هشدار مهم و یک واژه با تأکید معنایی قرار بده.","status":"published","sort_order":9,"estimated_minutes":20},{"id":"curriculum-324-html-10","course_id":"html","title":"پیوند به صفحه دیگر","slug":"html-beginner-10","summary":"در این درس پیوند به صفحه دیگر را به‌صورت عملی یاد می‌گیری. عنصر a با href پیوند می‌سازد. متن پیوند باید مقصد را برای کاربر روشن کند؛ عباراتی مثل «اینجا کلیک کن» اطلاعات کمی می‌دهند.","content_html":"<h3>هدف درس</h3><p>عنصر a با href پیوند می‌سازد. متن پیوند باید مقصد را برای کاربر روشن کند؛ عباراتی مثل «اینجا کلیک کن» اطلاعات کمی می‌دهند.</p><h3>نمونه و بررسی</h3><p>دو فایل هم‌پوشه بساز و مسیر نسبی about.html را آزمایش کن؛ سپس مقصد پیوند خارجی را جداگانه باز کن.</p><pre><code>&lt;a href=\"about.html\"&gt;درباره آکادمی&lt;/a&gt;\n&lt;a href=\"https://developer.mozilla.org/\"&gt;مرجع MDN&lt;/a&gt;</code></pre><h3>تمرین</h3><p>دو فایل index.html و about.html بساز و بین آن‌ها پیوند نسبی برقرار کن. یک پیوند خارجی هم اضافه کن.</p><h3>نکته مهم</h3><p>برای پیوند داخلی نام و مسیر فایل را دقیق وارد کن.</p><h3>معیار موفقیت</h3><p>پیوند داخلی به فایل واقعی برسد و متن پیوند مقصد را بدون ابهام معرفی کند.</p>","starter_code":"<a href=\"about.html\">درباره آکادمی</a>\n<a href=\"https://developer.mozilla.org/\">مرجع MDN</a>","exercise":"دو فایل index.html و about.html بساز و بین آن‌ها پیوند نسبی برقرار کن. یک پیوند خارجی هم اضافه کن.","status":"published","sort_order":10,"estimated_minutes":25},{"id":"curriculum-324-html-11","course_id":"html","title":"پیوند ایمیل و تلفن","slug":"html-beginner-11","summary":"در این درس پیوند ایمیل و تلفن را به‌صورت عملی یاد می‌گیری. طرح‌های mailto و tel در href می‌توانند برنامه ایمیل یا تماس دستگاه را باز کنند. عملکرد آن‌ها به دستگاه و برنامه‌های نصب‌شده وابسته است.","content_html":"<h3>هدف درس</h3><p>طرح‌های mailto و tel در href می‌توانند برنامه ایمیل یا تماس دستگاه را باز کنند. عملکرد آن‌ها به دستگاه و برنامه‌های نصب‌شده وابسته است.</p><h3>نمونه و بررسی</h3><p>پیوندها را روی دستگاه دارای برنامه ایمیل و تماس آزمایش کن؛ به‌خاطر نمونه بودن نشانی‌ها، ارسال واقعی انجام نده.</p><pre><code>&lt;a href=\"mailto:hello@example.com\"&gt;ارسال ایمیل&lt;/a&gt;\n&lt;a href=\"tel:+93700000000\"&gt;تماس با ما&lt;/a&gt;</code></pre><h3>تمرین</h3><p>در صفحه تماس، پیوند ایمیل و تلفن بساز. از شماره و ایمیل آزمایشی استفاده کن و بدان که کلیک روی آن‌ها چه می‌کند.</p><h3>نکته مهم</h3><p>این پیوندها ارسال خودکار انجام نمی‌دهند؛ برنامه مناسب دستگاه را باز می‌کنند.</p><h3>معیار موفقیت</h3><p>هر دو پیوند دارای scheme درست باشند و کاربر بداند که mailto و tel برنامه دستگاه را باز می‌کنند.</p>","starter_code":"<a href=\"mailto:hello@example.com\">ارسال ایمیل</a>\n<a href=\"tel:+93700000000\">تماس با ما</a>","exercise":"در صفحه تماس، پیوند ایمیل و تلفن بساز. از شماره و ایمیل آزمایشی استفاده کن و بدان که کلیک روی آن‌ها چه می‌کند.","status":"published","sort_order":11,"estimated_minutes":30},{"id":"curriculum-324-html-12","course_id":"html","title":"تصویر و ویژگی src","slug":"html-beginner-12","summary":"در این درس تصویر و ویژگی src را به‌صورت عملی یاد می‌گیری. عنصر img تصویر را در صفحه قرار می‌دهد. src مسیر فایل تصویر و alt جایگزین متنی آن است. img عنصر تهی است و تگ پایان ندارد.","content_html":"<h3>هدف درس</h3><p>عنصر img تصویر را در صفحه قرار می‌دهد. src مسیر فایل تصویر و alt جایگزین متنی آن است. img عنصر تهی است و تگ پایان ندارد.</p><h3>نمونه و بررسی</h3><p>نام فایل تصویر و مسیر پوشه images را با ساختار پروژه خودت هماهنگ کن و عمداً یک مسیر اشتباه را برای دیدن رفتار alt امتحان کن.</p><pre><code>&lt;img src=\"images/workshop.jpg\" alt=\"دانش‌آموز در حال تمرین کدنویسی\" width=\"640\"&gt;</code></pre><h3>تمرین</h3><p>یک پوشه images بساز، تصویر مجاز خودت را در آن قرار بده و مسیر src را درست تنظیم کن. صفحه را در مرورگر بررسی کن.</p><h3>نکته مهم</h3><p>مسیر نسبی را نسبت به محل فایل HTML حساب کن.</p><h3>معیار موفقیت</h3><p>تصویر بارگذاری شود، مسیر نسبی درست باشد و alt محتوای مهم تصویر را منتقل کند.</p>","starter_code":"<img src=\"images/workshop.jpg\" alt=\"دانش‌آموز در حال تمرین کدنویسی\" width=\"640\">","exercise":"یک پوشه images بساز، تصویر مجاز خودت را در آن قرار بده و مسیر src را درست تنظیم کن. صفحه را در مرورگر بررسی کن.","status":"published","sort_order":12,"estimated_minutes":35},{"id":"curriculum-324-html-13","course_id":"html","title":"متن جایگزین تصویر","slug":"html-beginner-13","summary":"در این درس متن جایگزین تصویر را به‌صورت عملی یاد می‌گیری. alt باید هدف یا محتوای مهم تصویر را منتقل کند. تصویر تزئینی معمولاً alt خالی دارد؛ نوشتن نام فایل یا عبارت «عکس» کمک چندانی نمی‌کند.","content_html":"<h3>هدف درس</h3><p>alt باید هدف یا محتوای مهم تصویر را منتقل کند. تصویر تزئینی معمولاً alt خالی دارد؛ نوشتن نام فایل یا عبارت «عکس» کمک چندانی نمی‌کند.</p><h3>نمونه و بررسی</h3><p>برای تصویر اطلاعاتی و تزئینی altهای متفاوت بگذار و بررسی کن تصویر تزئینی با alt خالی برای صفحه‌خوان نادیده گرفته شود.</p><pre><code>&lt;img src=\"logo.svg\" alt=\"نشان NEXORA FORGE\"&gt;\n&lt;img src=\"divider.png\" alt=\"\"&gt;</code></pre><h3>تمرین</h3><p>برای یک تصویر آموزشی، یک عکس تزئینی و یک نمودار، alt مناسب بنویس. برای نمودار، اطلاعات ضروری را در متن صفحه هم شرح بده.</p><h3>نکته مهم</h3><p>alt خالی برای تصویر اطلاعاتی مناسب نیست؛ متن جایگزین باید متناسب با کاربرد تصویر باشد.</p><h3>معیار موفقیت</h3><p>تصویر تزئینی alt خالی داشته باشد و اطلاعات نمودار در متن جایگزین یا توضیح صفحه موجود باشد.</p>","starter_code":"<img src=\"logo.svg\" alt=\"نشان NEXORA FORGE\">\n<img src=\"divider.png\" alt=\"\">","exercise":"برای یک تصویر آموزشی، یک عکس تزئینی و یک نمودار، alt مناسب بنویس. برای نمودار، اطلاعات ضروری را در متن صفحه هم شرح بده.","status":"published","sort_order":13,"estimated_minutes":20},{"id":"curriculum-324-html-14","course_id":"html","title":"فهرست نامرتب ul","slug":"html-beginner-14","summary":"در این درس فهرست نامرتب ul را به‌صورت عملی یاد می‌گیری. ul برای مجموعه‌ای است که ترتیب آیتم‌هایش اهمیت ندارد. هر گزینه باید داخل li قرار گیرد؛ ظاهر نشانه‌گذاری را CSS تغییر می‌دهد.","content_html":"<h3>هدف درس</h3><p>ul برای مجموعه‌ای است که ترتیب آیتم‌هایش اهمیت ندارد. هر گزینه باید داخل li قرار گیرد؛ ظاهر نشانه‌گذاری را CSS تغییر می‌دهد.</p><h3>نمونه و بررسی</h3><p>یک li جدید به فهرست اضافه کن و ساختار DOM را بررسی کن تا همه گزینه‌ها فرزند مستقیم منطقی ul باشند.</p><pre><code>&lt;h2&gt;ابزارهای موردنیاز&lt;/h2&gt;\n&lt;ul&gt;&lt;li&gt;ویرایشگر کد&lt;/li&gt;&lt;li&gt;مرورگر&lt;/li&gt;&lt;li&gt;تمرین روزانه&lt;/li&gt;&lt;/ul&gt;</code></pre><h3>تمرین</h3><p>فهرست پنج ابزار یا موضوع موردنیاز برای یادگیری وب بساز و مطمئن شو هر مورد li است.</p><h3>نکته مهم</h3><p>متن آیتم‌ها را مستقیم و بدون li داخل ul قرار نده.</p><h3>معیار موفقیت</h3><p>تمام گزینه‌ها داخل li باشند و فهرست نامرتب برای موارد بدون ترتیب استفاده شود.</p>","starter_code":"<h2>ابزارهای موردنیاز</h2>\n<ul><li>ویرایشگر کد</li><li>مرورگر</li><li>تمرین روزانه</li></ul>","exercise":"فهرست پنج ابزار یا موضوع موردنیاز برای یادگیری وب بساز و مطمئن شو هر مورد li است.","status":"published","sort_order":14,"estimated_minutes":25},{"id":"curriculum-324-html-15","course_id":"html","title":"فهرست مرتب ol","slug":"html-beginner-15","summary":"در این درس فهرست مرتب ol را به‌صورت عملی یاد می‌گیری. ol برای مراحل یا مواردی است که ترتیب آن‌ها مهم است. مرورگر شماره‌گذاری را مدیریت می‌کند و با ویژگی start می‌توان شماره شروع را تعیین کرد.","content_html":"<h3>هدف درس</h3><p>ol برای مراحل یا مواردی است که ترتیب آن‌ها مهم است. مرورگر شماره‌گذاری را مدیریت می‌کند و با ویژگی start می‌توان شماره شروع را تعیین کرد.</p><h3>نمونه و بررسی</h3><p>ترتیب مراحل را جابه‌جا کن و مشاهده کن شماره‌گذاری خودکار چگونه با ترتیب DOM هماهنگ می‌شود.</p><pre><code>&lt;ol&gt;\n  &lt;li&gt;فایل را بساز.&lt;/li&gt;\n  &lt;li&gt;کد HTML را بنویس.&lt;/li&gt;\n  &lt;li&gt;در مرورگر آزمایش کن.&lt;/li&gt;\n&lt;/ol&gt;</code></pre><h3>تمرین</h3><p>مراحل انتشار یک صفحه ساده را با ol بنویس. ترتیب را عوض کن و تفاوت خروجی را مشاهده کن.</p><h3>نکته مهم</h3><p>اگر ترتیب مراحل مهم نیست، ul انتخاب مناسب‌تری است.</p><h3>معیار موفقیت</h3><p>ترتیب ol با ترتیب واقعی مراحل هماهنگ باشد و شماره‌گذاری دستی در متن نوشته نشده باشد.</p>","starter_code":"<ol>\n  <li>فایل را بساز.</li>\n  <li>کد HTML را بنویس.</li>\n  <li>در مرورگر آزمایش کن.</li>\n</ol>","exercise":"مراحل انتشار یک صفحه ساده را با ol بنویس. ترتیب را عوض کن و تفاوت خروجی را مشاهده کن.","status":"published","sort_order":15,"estimated_minutes":30},{"id":"curriculum-324-html-16","course_id":"html","title":"فهرست تو در تو","slug":"html-beginner-16","summary":"در این درس فهرست تو در تو را به‌صورت عملی یاد می‌گیری. می‌توان یک فهرست را داخل li فهرست دیگر قرار داد تا رابطه گروه و زیرگروه روشن شود. فهرست تو در تو باید از نظر ساختاری داخل یک آیتم باشد.","content_html":"<h3>هدف درس</h3><p>می‌توان یک فهرست را داخل li فهرست دیگر قرار داد تا رابطه گروه و زیرگروه روشن شود. فهرست تو در تو باید از نظر ساختاری داخل یک آیتم باشد.</p><h3>نمونه و بررسی</h3><p>یک زیرگروه دیگر اضافه کن و تورفتگی ساختاری آن را داخل li والد نگه دار.</p><pre><code>&lt;ul&gt;\n  &lt;li&gt;Front-end\n    &lt;ul&gt;&lt;li&gt;HTML&lt;/li&gt;&lt;li&gt;CSS&lt;/li&gt;&lt;li&gt;JavaScript&lt;/li&gt;&lt;/ul&gt;\n  &lt;/li&gt;\n  &lt;li&gt;Back-end&lt;/li&gt;\n&lt;/ul&gt;</code></pre><h3>تمرین</h3><p>یک نقشه یادگیری وب با دو گروه و حداقل دو زیرموضوع برای هر گروه بساز.</p><h3>نکته مهم</h3><p>فهرست فرزند را داخل li والد قرار بده، نه به‌صورت هم‌سطح و نامرتبط.</p><h3>معیار موفقیت</h3><p>فهرست تو در تو از نظر DOM داخل li والد قرار گیرد و گروه‌ها قابل تشخیص باشند.</p>","starter_code":"<ul>\n  <li>Front-end\n    <ul><li>HTML</li><li>CSS</li><li>JavaScript</li></ul>\n  </li>\n  <li>Back-end</li>\n</ul>","exercise":"یک نقشه یادگیری وب با دو گروه و حداقل دو زیرموضوع برای هر گروه بساز.","status":"published","sort_order":16,"estimated_minutes":35},{"id":"curriculum-324-html-17","course_id":"html","title":"معنای div و span","slug":"html-beginner-17","summary":"در این درس معنای div و span را به‌صورت عملی یاد می‌گیری. div ظرف عمومی بلوکی و span ظرف عمومی درون‌خطی است. وقتی عنصر معنایی مناسب‌تری وجود ندارد، از آن‌ها برای گروه‌بندی و هدف‌گذاری CSS استفاده کن.","content_html":"<h3>هدف درس</h3><p>div ظرف عمومی بلوکی و span ظرف عمومی درون‌خطی است. وقتی عنصر معنایی مناسب‌تری وجود ندارد، از آن‌ها برای گروه‌بندی و هدف‌گذاری CSS استفاده کن.</p><h3>نمونه و بررسی</h3><p>کلاس level را در چند کارت تکرار کن، اما id را فقط یک بار در همان سند به کار ببر.</p><pre><code>&lt;div class=\"card\"&gt;\n  &lt;h2&gt;دوره HTML&lt;/h2&gt;\n  &lt;p&gt;سطح: &lt;span class=\"level\"&gt;مقدماتی&lt;/span&gt;&lt;/p&gt;\n&lt;/div&gt;</code></pre><h3>تمرین</h3><p>یک کارت معرفی دوره بساز و از div برای گروه‌بندی و span برای مشخص‌کردن یک عبارت درون متن استفاده کن.</p><h3>نکته مهم</h3><p>برای header، nav، main یا article از div عمومی استفاده نکن، اگر عنصر معنایی دقیق‌تر مناسب است.</p><h3>معیار موفقیت</h3><p>div و span فقط برای گروه‌بندی عمومی استفاده شوند و عنصر معنایی مناسب‌تر نادیده گرفته نشود.</p>","starter_code":"<div class=\"card\">\n  <h2>دوره HTML</h2>\n  <p>سطح: <span class=\"level\">مقدماتی</span></p>\n</div>","exercise":"یک کارت معرفی دوره بساز و از div برای گروه‌بندی و span برای مشخص‌کردن یک عبارت درون متن استفاده کن.","status":"published","sort_order":17,"estimated_minutes":20},{"id":"curriculum-324-html-18","course_id":"html","title":"ساختار معنایی header و footer","slug":"html-beginner-18","summary":"در این درس ساختار معنایی header و footer را به‌صورت عملی یاد می‌گیری. header محتوای مقدماتی یک صفحه یا بخش را گروه‌بندی می‌کند و footer اطلاعات پایانی همان محدوده را نگه می‌دارد. این عناصر جایگاه معنایی دارند، نه صرفاً ظاهر ثابت.","content_html":"<h3>هدف درس</h3><p>header محتوای مقدماتی یک صفحه یا بخش را گروه‌بندی می‌کند و footer اطلاعات پایانی همان محدوده را نگه می‌دارد. این عناصر جایگاه معنایی دارند، نه صرفاً ظاهر ثابت.</p><h3>نمونه و بررسی</h3><p>header و footer را یک‌بار برای کل صفحه و سپس برای یک article آزمایش کن تا محدوده معنایی هرکدام را تشخیص بدهی.</p><pre><code>&lt;header&gt;&lt;h1&gt;آکادمی وب&lt;/h1&gt;&lt;p&gt;مسیر یادگیری&lt;/p&gt;&lt;/header&gt;\n&lt;main&gt;&lt;p&gt;محتوای اصلی&lt;/p&gt;&lt;/main&gt;\n&lt;footer&gt;&lt;p&gt;© 2026 NEXORA FORGE&lt;/p&gt;&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>صفحه معرفی دوره را با header و footer بساز و مشخص کن هرکدام چه اطلاعاتی دارند.</p><h3>نکته مهم</h3><p>header را الزاماً فقط یک‌بار در کل سند به کار نبر؛ می‌تواند متعلق به بخش یا مقاله هم باشد.</p><h3>معیار موفقیت</h3><p>ساختار صفحه و بخش‌ها header و footer مناسب داشته باشند و محتوای اصلی در main باشد.</p>","starter_code":"<header><h1>آکادمی وب</h1><p>مسیر یادگیری</p></header>\n<main><p>محتوای اصلی</p></main>\n<footer><p>© 2026 NEXORA FORGE</p></footer>","exercise":"صفحه معرفی دوره را با header و footer بساز و مشخص کن هرکدام چه اطلاعاتی دارند.","status":"published","sort_order":18,"estimated_minutes":25},{"id":"curriculum-324-html-19","course_id":"html","title":"ناوبری با nav","slug":"html-beginner-19","summary":"در این درس ناوبری با nav را به‌صورت عملی یاد می‌گیری. nav بخش مهمی از پیوندهای ناوبری صفحه یا سایت را مشخص می‌کند. همه پیوندها لازم نیست داخل nav باشند؛ فقط مجموعه‌های اصلی ناوبری را گروه‌بندی کن.","content_html":"<h3>هدف درس</h3><p>nav بخش مهمی از پیوندهای ناوبری صفحه یا سایت را مشخص می‌کند. همه پیوندها لازم نیست داخل nav باشند؛ فقط مجموعه‌های اصلی ناوبری را گروه‌بندی کن.</p><h3>نمونه و بررسی</h3><p>برای nav نام قابل فهم تعیین کن و با صفحه‌کلید بین مقصدهای اصلی حرکت کن.</p><pre><code>&lt;nav aria-label=\"ناوبری اصلی\"&gt;\n  &lt;ul&gt;&lt;li&gt;&lt;a href=\"index.html\"&gt;خانه&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a href=\"courses.html\"&gt;دوره‌ها&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;\n&lt;/nav&gt;</code></pre><h3>تمرین</h3><p>یک نوار ناوبری با سه مقصد بساز و برای آن نام قابل فهم تعیین کن.</p><h3>نکته مهم</h3><p>nav را برای هر پیوند پراکنده یا لینک پاورقی بی‌دلیل استفاده نکن.</p><h3>معیار موفقیت</h3><p>nav فقط پیوندهای ناوبری مهم را گروه‌بندی کند و نام قابل فهم داشته باشد.</p>","starter_code":"<nav aria-label=\"ناوبری اصلی\">\n  <ul><li><a href=\"index.html\">خانه</a></li><li><a href=\"courses.html\">دوره‌ها</a></li></ul>\n</nav>","exercise":"یک نوار ناوبری با سه مقصد بساز و برای آن نام قابل فهم تعیین کن.","status":"published","sort_order":19,"estimated_minutes":30},{"id":"curriculum-324-html-20","course_id":"html","title":"محتوای اصلی با main و article","slug":"html-beginner-20","summary":"در این درس محتوای اصلی با main و article را به‌صورت عملی یاد می‌گیری. main محتوای غالب و منحصربه‌فرد صفحه را مشخص می‌کند و معمولاً در هر سند یک نمونه قابل مشاهده دارد. article محتوایی مستقل و قابل بازنشر را نمایش می‌دهد.","content_html":"<h3>هدف درس</h3><p>main محتوای غالب و منحصربه‌فرد صفحه را مشخص می‌کند و معمولاً در هر سند یک نمونه قابل مشاهده دارد. article محتوایی مستقل و قابل بازنشر را نمایش می‌دهد.</p><h3>نمونه و بررسی</h3><p>دو article مستقل درون main قرار بده و بررسی کن هر مقاله بدون وابستگی به مقاله دیگر قابل فهم باشد.</p><pre><code>&lt;main&gt;\n  &lt;article&gt;&lt;h1&gt;چرا HTML مهم است؟&lt;/h1&gt;&lt;p&gt;ساختار محتوا را توصیف می‌کند.&lt;/p&gt;&lt;/article&gt;\n&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک صفحه وبلاگ با main و دو article مستقل طراحی کن. عنوان هر مقاله را داخل همان article قرار بده.</p><h3>نکته مهم</h3><p>main را برای محتوای تکراری مانند منوی ثابت سایت به کار نبر.</p><h3>معیار موفقیت</h3><p>main محتوای اصلی صفحه را مشخص کند و articleها محتوای مستقل و قابل فهم داشته باشند.</p>","starter_code":"<main>\n  <article><h1>چرا HTML مهم است؟</h1><p>ساختار محتوا را توصیف می‌کند.</p></article>\n</main>","exercise":"یک صفحه وبلاگ با main و دو article مستقل طراحی کن. عنوان هر مقاله را داخل همان article قرار بده.","status":"published","sort_order":20,"estimated_minutes":35},{"id":"curriculum-324-html-21","course_id":"html","title":"بخش‌بندی با section و aside","slug":"html-beginner-21","summary":"در این درس بخش‌بندی با section و aside را به‌صورت عملی یاد می‌گیری. section یک بخش موضوعی با عنوان است. aside محتوای جانبی مرتبط را مشخص می‌کند. انتخاب عنصر باید بر اساس نقش محتوا باشد، نه صرفاً شکل ظاهری.","content_html":"<h3>هدف درس</h3><p>section یک بخش موضوعی با عنوان است. aside محتوای جانبی مرتبط را مشخص می‌کند. انتخاب عنصر باید بر اساس نقش محتوا باشد، نه صرفاً شکل ظاهری.</p><h3>نمونه و بررسی</h3><p>برای هر section عنوان مرتبط بساز و aside را فقط برای اطلاعات جانبی مرتبط نگه دار.</p><pre><code>&lt;main&gt;\n  &lt;section&gt;&lt;h2&gt;سرفصل دوره&lt;/h2&gt;&lt;p&gt;HTML پایه...&lt;/p&gt;&lt;/section&gt;\n  &lt;aside&gt;&lt;h2&gt;نکته&lt;/h2&gt;&lt;p&gt;تمرین روزانه را فراموش نکن.&lt;/p&gt;&lt;/aside&gt;\n&lt;/main&gt;</code></pre><h3>تمرین</h3><p>صفحه دوره‌ای بساز که دو section عنوان‌دار و یک aside شامل نکته جانبی داشته باشد.</p><h3>نکته مهم</h3><p>هر div را به‌زور section نکن؛ بخش موضوعی معمولاً باید عنوان یا مفهوم مشخص داشته باشد.</p><h3>معیار موفقیت</h3><p>sectionها موضوع مشخص و عنوان داشته باشند و aside نقش جانبی مرتبط را ایفا کند.</p>","starter_code":"<main>\n  <section><h2>سرفصل دوره</h2><p>HTML پایه...</p></section>\n  <aside><h2>نکته</h2><p>تمرین روزانه را فراموش نکن.</p></aside>\n</main>","exercise":"صفحه دوره‌ای بساز که دو section عنوان‌دار و یک aside شامل نکته جانبی داشته باشد.","status":"published","sort_order":21,"estimated_minutes":20},{"id":"curriculum-324-html-22","course_id":"html","title":"ویژگی‌های عمومی id و class","slug":"html-beginner-22","summary":"در این درس ویژگی‌های عمومی id و class را به‌صورت عملی یاد می‌گیری. id شناسه یکتا در یک سند است و class برای گروهی از عناصر قابل تکرار استفاده می‌شود. این ویژگی‌ها در CSS و JavaScript برای یافتن عناصر کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>id شناسه یکتا در یک سند است و class برای گروهی از عناصر قابل تکرار استفاده می‌شود. این ویژگی‌ها در CSS و JavaScript برای یافتن عناصر کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>با جست‌وجوی id در فایل مطمئن شو مقدار آن تکراری نیست و چند عنصر می‌توانند class یکسان داشته باشند.</p><pre><code>&lt;h2 id=\"requirements\"&gt;پیش‌نیازها&lt;/h2&gt;\n&lt;p class=\"muted\"&gt;آشنایی با کار با فایل‌ها کافی است.&lt;/p&gt;\n&lt;p class=\"muted\"&gt;مرورگر به‌روز داشته باش.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>برای یک عنوان id یکتا و برای دو پاراگراف class مشترک تعیین کن. در کل صفحه id تکراری نداشته باش.</p><h3>نکته مهم</h3><p>class می‌تواند تکرار شود؛ id در همان سند باید یکتا باشد.</p><h3>معیار موفقیت</h3><p>id در سند یکتا باشد و class بتواند برای چند عنصر مشترک استفاده شود.</p>","starter_code":"<h2 id=\"requirements\">پیش‌نیازها</h2>\n<p class=\"muted\">آشنایی با کار با فایل‌ها کافی است.</p>\n<p class=\"muted\">مرورگر به‌روز داشته باش.</p>","exercise":"برای یک عنوان id یکتا و برای دو پاراگراف class مشترک تعیین کن. در کل صفحه id تکراری نداشته باش.","status":"published","sort_order":22,"estimated_minutes":25},{"id":"curriculum-324-html-23","course_id":"html","title":"ویژگی‌های data-*","slug":"html-beginner-23","summary":"در این درس ویژگی‌های data-* را به‌صورت عملی یاد می‌گیری. ویژگی‌های data-* داده سفارشی متنی را به عنصر متصل می‌کنند. JavaScript می‌تواند آن‌ها را از dataset بخواند؛ داده حساس را در HTML قرار نده.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های data-* داده سفارشی متنی را به عنصر متصل می‌کنند. JavaScript می‌تواند آن‌ها را از dataset بخواند؛ داده حساس را در HTML قرار نده.</p><h3>نمونه و بررسی</h3><p>مقدار data-course را در ابزار توسعه مرورگر تغییر بده و تفاوت داده سفارشی با متن قابل مشاهده را توضیح بده.</p><pre><code>&lt;button type=\"button\" data-course=\"html\"&gt;مشاهده دوره HTML&lt;/button&gt;\n&lt;p data-level=\"beginner\"&gt;سطح مقدماتی&lt;/p&gt;</code></pre><h3>تمرین</h3><p>به سه کارت دوره ویژگی data-course اضافه کن و مقدار هرکدام را متفاوت قرار بده. با ابزار توسعه مرورگر مقدارها را ببین.</p><h3>نکته مهم</h3><p>data-* جایگزین پایگاه داده یا محل نگهداری رمز و اطلاعات خصوصی نیست.</p><h3>معیار موفقیت</h3><p>ویژگی‌های data-* مقدارهای غیرحساس و قابل خواندن داشته باشند و برای اطلاعات خصوصی استفاده نشوند.</p>","starter_code":"<button type=\"button\" data-course=\"html\">مشاهده دوره HTML</button>\n<p data-level=\"beginner\">سطح مقدماتی</p>","exercise":"به سه کارت دوره ویژگی data-course اضافه کن و مقدار هرکدام را متفاوت قرار بده. با ابزار توسعه مرورگر مقدارها را ببین.","status":"published","sort_order":23,"estimated_minutes":30},{"id":"curriculum-324-html-24","course_id":"html","title":"جدول و ساختار پایه","slug":"html-beginner-24","summary":"در این درس جدول و ساختار پایه را به‌صورت عملی یاد می‌گیری. table داده‌های رابطه‌ای را در ردیف و ستون نمایش می‌دهد. tr ردیف، th سلول عنوان و td سلول داده است؛ برای چیدمان صفحه از جدول استفاده نکن.","content_html":"<h3>هدف درس</h3><p>table داده‌های رابطه‌ای را در ردیف و ستون نمایش می‌دهد. tr ردیف، th سلول عنوان و td سلول داده است؛ برای چیدمان صفحه از جدول استفاده نکن.</p><h3>نمونه و بررسی</h3><p>یک ردیف و یک ستون دیگر اضافه کن و مطمئن شو هر سلول داده در td و هر سرستون در th قرار دارد.</p><pre><code>&lt;table&gt;\n  &lt;tr&gt;&lt;th&gt;درس&lt;/th&gt;&lt;th&gt;زمان&lt;/th&gt;&lt;/tr&gt;\n  &lt;tr&gt;&lt;td&gt;HTML&lt;/td&gt;&lt;td&gt;۳۰ دقیقه&lt;/td&gt;&lt;/tr&gt;\n&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول برنامه هفتگی با سه ستون روز، موضوع و زمان و دست‌کم سه ردیف داده بساز.</p><h3>نکته مهم</h3><p>برای چیدمان عمومی صفحه از table استفاده نکن؛ جدول مخصوص داده جدولی است.</p><h3>معیار موفقیت</h3><p>جدول برای داده رابطه‌ای باشد و ردیف‌ها و سلول‌ها در ساختار درست قرار بگیرند.</p>","starter_code":"<table>\n  <tr><th>درس</th><th>زمان</th></tr>\n  <tr><td>HTML</td><td>۳۰ دقیقه</td></tr>\n</table>","exercise":"جدول برنامه هفتگی با سه ستون روز، موضوع و زمان و دست‌کم سه ردیف داده بساز.","status":"published","sort_order":24,"estimated_minutes":35},{"id":"curriculum-324-html-25","course_id":"html","title":"عنوان جدول با caption و thead و tbody","slug":"html-beginner-25","summary":"در این درس عنوان جدول با caption و thead و tbody را به‌صورت عملی یاد می‌گیری. caption عنوان جدول را معرفی می‌کند. thead سرستون‌ها و tbody ردیف‌های داده را گروه‌بندی می‌کنند و به فهم ساختار کمک می‌کنند.","content_html":"<h3>هدف درس</h3><p>caption عنوان جدول را معرفی می‌کند. thead سرستون‌ها و tbody ردیف‌های داده را گروه‌بندی می‌کنند و به فهم ساختار کمک می‌کنند.</p><h3>نمونه و بررسی</h3><p>caption را تغییر بده و جدول را بدون CSS بخوان؛ سرستون‌ها باید نوع داده هر ستون را مشخص کنند.</p><pre><code>&lt;table&gt;\n  &lt;caption&gt;برنامه دوره‌ها&lt;/caption&gt;\n  &lt;thead&gt;&lt;tr&gt;&lt;th scope=\"col\"&gt;دوره&lt;/th&gt;&lt;th scope=\"col\"&gt;سطح&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n  &lt;tbody&gt;&lt;tr&gt;&lt;td&gt;HTML&lt;/td&gt;&lt;td&gt;مقدماتی&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;\n&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول برنامه درسی را با caption، thead و tbody بازنویسی کن و برای سرستون‌ها scope=\"col\" بگذار.</p><h3>نکته مهم</h3><p>عنوان جدول را با یک تیتر بیرون جدول اشتباه نگیر؛ caption بخشی از جدول است.</p><h3>معیار موفقیت</h3><p>جدول caption و سرستون‌های روشن داشته باشد و ترتیب ردیف‌ها قابل فهم باشد.</p>","starter_code":"<table>\n  <caption>برنامه دوره‌ها</caption>\n  <thead><tr><th scope=\"col\">دوره</th><th scope=\"col\">سطح</th></tr></thead>\n  <tbody><tr><td>HTML</td><td>مقدماتی</td></tr></tbody>\n</table>","exercise":"جدول برنامه درسی را با caption، thead و tbody بازنویسی کن و برای سرستون‌ها scope=\"col\" بگذار.","status":"published","sort_order":25,"estimated_minutes":20},{"id":"curriculum-324-html-26","course_id":"html","title":"فرم و عنصر form","slug":"html-beginner-26","summary":"در این درس فرم و عنصر form را به‌صورت عملی یاد می‌گیری. form مجموعه‌ای از کنترل‌ها را برای دریافت و ارسال داده گروه‌بندی می‌کند. action مقصد ارسال و method روش ارسال را تعیین می‌کند؛ پردازش واقعی به سمت سرور نیاز دارد.","content_html":"<h3>هدف درس</h3><p>form مجموعه‌ای از کنترل‌ها را برای دریافت و ارسال داده گروه‌بندی می‌کند. action مقصد ارسال و method روش ارسال را تعیین می‌کند؛ پردازش واقعی به سمت سرور نیاز دارد.</p><h3>نمونه و بررسی</h3><p>فرم را بدون CSS اجرا کن و با دکمه ارسال بررسی کن که مرورگر داده‌ها را به کدام action می‌فرستد.</p><pre><code>&lt;form action=\"/register\" method=\"post\"&gt;\n  &lt;label for=\"student-name\"&gt;نام&lt;/label&gt;\n  &lt;input id=\"student-name\" name=\"name\" type=\"text\"&gt;\n  &lt;button type=\"submit\"&gt;ارسال&lt;/button&gt;\n&lt;/form&gt;</code></pre><h3>تمرین</h3><p>یک فرم ثبت‌نام آزمایشی بساز و برای ورودی name تعیین کن. توضیح بده چرا وجود فرم به‌تنهایی ذخیره‌سازی اطلاعات را انجام نمی‌دهد.</p><h3>نکته مهم</h3><p>اطلاعات حساس را با فرم آزمایشی به مقصد ناشناس ارسال نکن.</p><h3>معیار موفقیت</h3><p>هر ورودی فرم نام و روش ارسال مناسب داشته باشد و کاربر بتواند فرم را با صفحه‌کلید تکمیل کند.</p>","starter_code":"<form action=\"/register\" method=\"post\">\n  <label for=\"student-name\">نام</label>\n  <input id=\"student-name\" name=\"name\" type=\"text\">\n  <button type=\"submit\">ارسال</button>\n</form>","exercise":"یک فرم ثبت‌نام آزمایشی بساز و برای ورودی name تعیین کن. توضیح بده چرا وجود فرم به‌تنهایی ذخیره‌سازی اطلاعات را انجام نمی‌دهد.","status":"published","sort_order":26,"estimated_minutes":25},{"id":"curriculum-324-html-27","course_id":"html","title":"label و ارتباط با ورودی","slug":"html-beginner-27","summary":"در این درس label و ارتباط با ورودی را به‌صورت عملی یاد می‌گیری. label نام قابل فهم کنترل را مشخص می‌کند. اتصال for در label به id ورودی باعث می‌شود کلیک روی برچسب نیز کنترل را فعال کند و صفحه‌خوان نام آن را بخواند.","content_html":"<h3>هدف درس</h3><p>label نام قابل فهم کنترل را مشخص می‌کند. اتصال for در label به id ورودی باعث می‌شود کلیک روی برچسب نیز کنترل را فعال کند و صفحه‌خوان نام آن را بخواند.</p><h3>نمونه و بررسی</h3><p>روی متن label کلیک کن و ببین آیا فوکوس به ورودی متناظر منتقل می‌شود؛ مقدار for باید با id یکسان باشد.</p><pre><code>&lt;label for=\"email\"&gt;ایمیل&lt;/label&gt;\n&lt;input id=\"email\" name=\"email\" type=\"email\"&gt;</code></pre><h3>تمرین</h3><p>برای نام، ایمیل و رمز سه ورودی بساز و هرکدام را با label دارای for و id متناظر متصل کن.</p><h3>نکته مهم</h3><p>placeholder جایگزین label نیست؛ پس از واردکردن متن، placeholder ناپدید می‌شود.</p><h3>معیار موفقیت</h3><p>کلیک روی label ورودی درست را فعال کند و شناسه‌های for و id دقیقاً تطابق داشته باشند.</p>","starter_code":"<label for=\"email\">ایمیل</label>\n<input id=\"email\" name=\"email\" type=\"email\">","exercise":"برای نام، ایمیل و رمز سه ورودی بساز و هرکدام را با label دارای for و id متناظر متصل کن.","status":"published","sort_order":27,"estimated_minutes":30},{"id":"curriculum-324-html-28","course_id":"html","title":"انواع ورودی input","slug":"html-beginner-28","summary":"در این درس انواع ورودی input را به‌صورت عملی یاد می‌گیری. نوع input رفتار و صفحه‌کلید مناسب را تعیین می‌کند؛ مانند email، password، number، date و checkbox. انتخاب نوع درست اعتبارسنجی اولیه و تجربه کاربری را بهتر می‌کند.","content_html":"<h3>هدف درس</h3><p>نوع input رفتار و صفحه‌کلید مناسب را تعیین می‌کند؛ مانند email، password، number، date و checkbox. انتخاب نوع درست اعتبارسنجی اولیه و تجربه کاربری را بهتر می‌کند.</p><h3>نمونه و بررسی</h3><p>هر type را جداگانه آزمایش کن و تفاوت کنترل‌های مرورگر برای email، number و date را مشاهده کن.</p><pre><code>&lt;label for=\"age\"&gt;سن&lt;/label&gt;&lt;input id=\"age\" name=\"age\" type=\"number\" min=\"10\" max=\"99\"&gt;\n&lt;label&gt;&lt;input type=\"checkbox\" name=\"agree\"&gt; قوانین را می‌پذیرم&lt;/label&gt;</code></pre><h3>تمرین</h3><p>فرمی با ورودی تاریخ تولد، ایمیل، عدد و checkbox بساز. برای هرکدام نوع مناسب انتخاب کن.</p><h3>نکته مهم</h3><p>اعتبارسنجی مرورگر جای بررسی امن داده در سرور را نمی‌گیرد.</p><h3>معیار موفقیت</h3><p>هر کنترل نوع مناسب داشته باشد و مرورگر رفتار متناسب با نوع ورودی را ارائه کند.</p>","starter_code":"<label for=\"age\">سن</label><input id=\"age\" name=\"age\" type=\"number\" min=\"10\" max=\"99\">\n<label><input type=\"checkbox\" name=\"agree\"> قوانین را می‌پذیرم</label>","exercise":"فرمی با ورودی تاریخ تولد، ایمیل، عدد و checkbox بساز. برای هرکدام نوع مناسب انتخاب کن.","status":"published","sort_order":28,"estimated_minutes":35},{"id":"curriculum-324-html-29","course_id":"html","title":"ویژگی‌های required و minlength","slug":"html-beginner-29","summary":"در این درس ویژگی‌های required و minlength را به‌صورت عملی یاد می‌گیری. required ورود مقدار را الزامی می‌کند و minlength حداقل طول متن را مشخص می‌کند. مرورگر هنگام ارسال فرم اعتبارسنجی اولیه انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>required ورود مقدار را الزامی می‌کند و minlength حداقل طول متن را مشخص می‌کند. مرورگر هنگام ارسال فرم اعتبارسنجی اولیه انجام می‌دهد.</p><h3>نمونه و بررسی</h3><p>فرم را با مقدار خالی و سپس مقدار کوتاه ارسال کن تا اعتبارسنجی بومی مرورگر را ببینی.</p><pre><code>&lt;form&gt;\n  &lt;label for=\"user\"&gt;شناسه&lt;/label&gt;\n  &lt;input id=\"user\" name=\"user\" required minlength=\"4\"&gt;\n  &lt;button&gt;بررسی&lt;/button&gt;\n&lt;/form&gt;</code></pre><h3>تمرین</h3><p>فرم ساخت شناسه‌ای بساز که خالی نباشد و حداقل چهار نویسه داشته باشد. حالت خالی و مقدار کوتاه را آزمایش کن.</p><h3>نکته مهم</h3><p>این محدودیت‌ها به‌تنهایی امنیت یا اعتبار داده در سرور را تضمین نمی‌کنند.</p><h3>معیار موفقیت</h3><p>فرم مقدار خالی یا کوتاه را مطابق محدودیت‌های تعریف‌شده رد کند و پیام مرورگر قابل مشاهده باشد.</p>","starter_code":"<form>\n  <label for=\"user\">شناسه</label>\n  <input id=\"user\" name=\"user\" required minlength=\"4\">\n  <button>بررسی</button>\n</form>","exercise":"فرم ساخت شناسه‌ای بساز که خالی نباشد و حداقل چهار نویسه داشته باشد. حالت خالی و مقدار کوتاه را آزمایش کن.","status":"published","sort_order":29,"estimated_minutes":20},{"id":"curriculum-324-html-30","course_id":"html","title":"select و option","slug":"html-beginner-30","summary":"در این درس select و option را به‌صورت عملی یاد می‌گیری. select برای انتخاب از گزینه‌های از پیش تعریف‌شده مناسب است. هر option یک انتخاب و value مقدار ارسالی آن را تعیین می‌کند.","content_html":"<h3>هدف درس</h3><p>select برای انتخاب از گزینه‌های از پیش تعریف‌شده مناسب است. هر option یک انتخاب و value مقدار ارسالی آن را تعیین می‌کند.</p><h3>نمونه و بررسی</h3><p>گزینه پیش‌فرض و گزینه انتخاب‌شده را تغییر بده و مقدار نهایی select را بررسی کن.</p><pre><code>&lt;label for=\"level\"&gt;سطح دوره&lt;/label&gt;\n&lt;select id=\"level\" name=\"level\"&gt;\n  &lt;option value=\"beginner\"&gt;مقدماتی&lt;/option&gt;\n  &lt;option value=\"intermediate\"&gt;متوسط&lt;/option&gt;\n  &lt;option value=\"advanced\"&gt;پیشرفته&lt;/option&gt;\n&lt;/select&gt;</code></pre><h3>تمرین</h3><p>یک انتخاب‌گر سطح دوره با سه گزینه بساز و value انگلیسی و متن نمایشی فارسی قرار بده.</p><h3>نکته مهم</h3><p>متن نمایشی و value می‌توانند متفاوت باشند؛ مقدار ارسالی را آگاهانه انتخاب کن.</p><h3>معیار موفقیت</h3><p>select مقدار معتبر انتخاب‌شده داشته باشد و هر option مقدار و متن روشن ارائه کند.</p>","starter_code":"<label for=\"level\">سطح دوره</label>\n<select id=\"level\" name=\"level\">\n  <option value=\"beginner\">مقدماتی</option>\n  <option value=\"intermediate\">متوسط</option>\n  <option value=\"advanced\">پیشرفته</option>\n</select>","exercise":"یک انتخاب‌گر سطح دوره با سه گزینه بساز و value انگلیسی و متن نمایشی فارسی قرار بده.","status":"published","sort_order":30,"estimated_minutes":25},{"id":"curriculum-324-html-31","course_id":"html","title":"textarea برای متن چندخطی","slug":"html-beginner-31","summary":"در این درس textarea برای متن چندخطی را به‌صورت عملی یاد می‌گیری. textarea ورودی متن چندخطی است. برخلاف input، متن آن بین تگ آغاز و پایان قرار می‌گیرد و می‌توان اندازه اولیه را با rows و cols تعیین کرد.","content_html":"<h3>هدف درس</h3><p>textarea ورودی متن چندخطی است. برخلاف input، متن آن بین تگ آغاز و پایان قرار می‌گیرد و می‌توان اندازه اولیه را با rows و cols تعیین کرد.</p><h3>نمونه و بررسی</h3><p>چند خط متن وارد کن و اندازه textarea را با rows و cols تغییر بده.</p><pre><code>&lt;label for=\"message\"&gt;پیام&lt;/label&gt;\n&lt;textarea id=\"message\" name=\"message\" rows=\"5\" maxlength=\"500\"&gt;&lt;/textarea&gt;</code></pre><h3>تمرین</h3><p>فرم بازخورد بساز که یک textarea با حداکثر ۵۰۰ نویسه داشته باشد. برچسب واضح برای آن بنویس.</p><h3>نکته مهم</h3><p>برای متن چندخطی از input type=text استفاده نکن.</p><h3>معیار موفقیت</h3><p>textarea چندخطی باشد و label قابل مشاهده و مرتبط داشته باشد.</p>","starter_code":"<label for=\"message\">پیام</label>\n<textarea id=\"message\" name=\"message\" rows=\"5\" maxlength=\"500\"></textarea>","exercise":"فرم بازخورد بساز که یک textarea با حداکثر ۵۰۰ نویسه داشته باشد. برچسب واضح برای آن بنویس.","status":"published","sort_order":31,"estimated_minutes":30},{"id":"curriculum-324-html-32","course_id":"html","title":"button و نوع دکمه","slug":"html-beginner-32","summary":"در این درس button و نوع دکمه را به‌صورت عملی یاد می‌گیری. button می‌تواند submit، reset یا button باشد. داخل فرم، نوع پیش‌فرض ممکن است submit باشد؛ تعیین type رفتار را روشن و از ارسال ناخواسته جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>button می‌تواند submit، reset یا button باشد. داخل فرم، نوع پیش‌فرض ممکن است submit باشد؛ تعیین type رفتار را روشن و از ارسال ناخواسته جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>دکمه را درون فرم با type=button و type=submit مقایسه کن تا تفاوت رفتار ارسال مشخص شود.</p><pre><code>&lt;button type=\"button\"&gt;نمایش راهنما&lt;/button&gt;\n&lt;button type=\"submit\"&gt;ثبت فرم&lt;/button&gt;\n&lt;button type=\"reset\"&gt;پاک‌کردن فرم&lt;/button&gt;</code></pre><h3>تمرین</h3><p>در یک فرم سه دکمه با نوع‌های مشخص بساز و رفتار هرکدام را در مرورگر آزمایش کن.</p><h3>نکته مهم</h3><p>دکمه‌ای که فقط قرار است JavaScript را اجرا کند باید type=\"button\" داشته باشد.</p><h3>معیار موفقیت</h3><p>دکمه عملیاتی نوع درست داشته باشد و ارسال ناخواسته فرم رخ ندهد.</p>","starter_code":"<button type=\"button\">نمایش راهنما</button>\n<button type=\"submit\">ثبت فرم</button>\n<button type=\"reset\">پاک‌کردن فرم</button>","exercise":"در یک فرم سه دکمه با نوع‌های مشخص بساز و رفتار هرکدام را در مرورگر آزمایش کن.","status":"published","sort_order":32,"estimated_minutes":35},{"id":"curriculum-324-html-33","course_id":"html","title":"audio و video","slug":"html-beginner-33","summary":"در این درس audio و video را به‌صورت عملی یاد می‌گیری. audio و video رسانه را با کنترل‌های بومی مرورگر پخش می‌کنند. برای دسترس‌پذیری و سازگاری، در صورت نیاز چند source و متن جایگزین ارائه کن.","content_html":"<h3>هدف درس</h3><p>audio و video رسانه را با کنترل‌های بومی مرورگر پخش می‌کنند. برای دسترس‌پذیری و سازگاری، در صورت نیاز چند source و متن جایگزین ارائه کن.</p><h3>نمونه و بررسی</h3><p>فایل صوتی و ویدیویی مجاز در اختیار بگذار و کنترل‌های پخش، توقف و پیام fallback را آزمایش کن.</p><pre><code>&lt;video controls width=\"480\"&gt;\n  &lt;source src=\"intro.mp4\" type=\"video/mp4\"&gt;\n  مرورگر شما از ویدیو پشتیبانی نمی‌کند.\n&lt;/video&gt;</code></pre><h3>تمرین</h3><p>یک فایل رسانه‌ای مجاز در پوشه پروژه قرار بده و با video یا audio پخش کن. controls را فعال و مسیر را بررسی کن.</p><h3>نکته مهم</h3><p>فایل رسانه را بدون توجه به مجوز استفاده دیگران کپی نکن.</p><h3>معیار موفقیت</h3><p>رسانه با کنترل‌های بومی قابل استفاده باشد و در نبود فایل پیام یا fallback مناسب ارائه شود.</p>","starter_code":"<video controls width=\"480\">\n  <source src=\"intro.mp4\" type=\"video/mp4\">\n  مرورگر شما از ویدیو پشتیبانی نمی‌کند.\n</video>","exercise":"یک فایل رسانه‌ای مجاز در پوشه پروژه قرار بده و با video یا audio پخش کن. controls را فعال و مسیر را بررسی کن.","status":"published","sort_order":33,"estimated_minutes":20},{"id":"curriculum-324-html-34","course_id":"html","title":"قرار دادن محتوای خارجی با iframe","slug":"html-beginner-34","summary":"در این درس قرار دادن محتوای خارجی با iframe را به‌صورت عملی یاد می‌گیری. iframe یک صفحه یا محتوای خارجی را در محدوده‌ای از صفحه جاسازی می‌کند. فقط منبع قابل اعتماد را وارد کن و برای آن title توصیفی بگذار.","content_html":"<h3>هدف درس</h3><p>iframe یک صفحه یا محتوای خارجی را در محدوده‌ای از صفحه جاسازی می‌کند. فقط منبع قابل اعتماد را وارد کن و برای آن title توصیفی بگذار.</p><h3>نمونه و بررسی</h3><p>آدرس iframe را با صفحه‌ای که اجازه embedding می‌دهد جایگزین کن؛ بسیاری از سایت‌ها به دلایل امنیتی داخل iframe باز نمی‌شوند.</p><pre><code>&lt;iframe src=\"https://www.example.com\" title=\"صفحه نمونه\" width=\"600\" height=\"350\" loading=\"lazy\"&gt;&lt;/iframe&gt;</code></pre><h3>تمرین</h3><p>یک محتوای آزمایشی مجاز را با iframe جاسازی کن و title توصیفی اضافه کن. محدودیت‌های نمایش سایت‌های خارجی را بررسی کن.</p><h3>نکته مهم</h3><p>همه سایت‌ها اجازه جاسازی در iframe نمی‌دهند؛ این محدودیت را با دورزدن امنیتی حل نکن.</p><h3>معیار موفقیت</h3><p>iframe فقط منبع مجاز را بارگذاری کند و عنوان توصیفی و ابعاد مناسب داشته باشد.</p>","starter_code":"<iframe src=\"https://www.example.com\" title=\"صفحه نمونه\" width=\"600\" height=\"350\" loading=\"lazy\"></iframe>","exercise":"یک محتوای آزمایشی مجاز را با iframe جاسازی کن و title توصیفی اضافه کن. محدودیت‌های نمایش سایت‌های خارجی را بررسی کن.","status":"published","sort_order":34,"estimated_minutes":25},{"id":"curriculum-324-html-35","course_id":"html","title":"نشانه‌گذاری کد و نقل‌قول","slug":"html-beginner-35","summary":"در این درس نشانه‌گذاری کد و نقل‌قول را به‌صورت عملی یاد می‌گیری. code برای قطعه کد درون‌خطی و pre برای متن از پیش قالب‌بندی‌شده مناسب است. blockquote نقل‌قول بلند از منبع دیگر را مشخص می‌کند.","content_html":"<h3>هدف درس</h3><p>code برای قطعه کد درون‌خطی و pre برای متن از پیش قالب‌بندی‌شده مناسب است. blockquote نقل‌قول بلند از منبع دیگر را مشخص می‌کند.</p><h3>نمونه و بررسی</h3><p>تفاوت code درون‌خطی و pre برای بلوک چندخطی را بررسی کن و مطمئن شو فاصله‌های کد حفظ می‌شوند.</p><pre><code>&lt;p&gt;برای تیتر از &lt;code&gt;&amp;lt;h1&amp;gt;&lt;/code&gt; استفاده می‌کنیم.&lt;/p&gt;\n&lt;pre&gt;&lt;code&gt;const name = \"NEXORA\";\nconsole.log(name);&lt;/code&gt;&lt;/pre&gt;</code></pre><h3>تمرین</h3><p>در یک درس، یک تگ HTML را با code نمایش بده و یک نمونه چندخطی را داخل pre و code قرار بده.</p><h3>نکته مهم</h3><p>کد HTML را داخل نمونه با نویسه‌های &lt; و &gt; نمایش بده تا مرورگر آن را به‌عنوان تگ اجرا نکند.</p><h3>معیار موفقیت</h3><p>کد درون‌خطی و بلوک چندخطی از نظر معنایی درست نشانه‌گذاری شوند و فاصله کد حفظ شود.</p>","starter_code":"<p>برای تیتر از <code>&lt;h1&gt;</code> استفاده می‌کنیم.</p>\n<pre><code>const name = \"NEXORA\";\nconsole.log(name);</code></pre>","exercise":"در یک درس، یک تگ HTML را با code نمایش بده و یک نمونه چندخطی را داخل pre و code قرار بده.","status":"published","sort_order":35,"estimated_minutes":30},{"id":"curriculum-324-html-36","course_id":"html","title":"پروژه پایانی: ساخت صفحه معرفی دانش‌آموز","slug":"html-beginner-36-final-project","summary":"در پروژه پایانی HTML مقدماتی، ساختار سند، عناصر معنایی، پیوندها، فهرست‌ها، تصویر، جدول و فرم را در یک صفحه واقعی ترکیب می‌کنی.","content_html":"<h3>هدف پروژه</h3><p>اکنون باید آموخته‌های HTML مقدماتی را در یک صفحه منسجم به کار ببری. این پروژه فقط تمرین نشانه‌گذاری است؛ هنوز CSS یا ذخیره‌سازی سمت سرور ندارد.</p><h3>ساختار مورد انتظار</h3><ul><li>سند کامل با doctype، lang، charset و viewport</li><li>header، nav، main، section و footer</li><li>تصویر دارای alt معنادار</li><li>فهرست مهارت‌ها و جدول دارای caption و سرستون</li><li>فرم دارای label، textarea و دکمه با type مشخص</li></ul><h3>نمونه شروع</h3><p>کد starter را در فایل index.html قرار بده. فایل تصویر را در همان پوشه بگذار یا مسیر src را متناسب با پروژه خودت تغییر بده.</p><h3>تمرین نهایی</h3><p>صفحه معرفی خودت را کامل کن. دست‌کم سه بخش ناوبری داشته باش، اطلاعات واقعی و غیرحساس وارد کن، مسیر پیوندها را آزمایش کن و همه عناصر را با معنای درست انتخاب کن.</p><h3>معیار ارزیابی</h3><ol><li>صفحه در موبایل و رایانه باز شود.</li><li>ساختار سند و ترتیب تیترها منطقی باشد.</li><li>تصویر alt مناسب داشته باشد.</li><li>هر ورودی فرم برچسب قابل مشاهده داشته باشد.</li><li>اعتبارسنج HTML خطاهای مهم را گزارش نکند.</li></ol><h3>محدودیت مهم</h3><p>فرم نمونه بدون backend اطلاعات را ذخیره یا ارسال واقعی نمی‌کند. این پروژه عمداً فقط HTML است؛ ظاهر حرفه‌ای در دوره CSS ساخته خواهد شد.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>پروفایل دانش‌آموز</title>\n</head>\n<body>\n  <header>\n    <h1>پروفایل من</h1>\n    <nav aria-label=\"ناوبری اصلی\">\n      <a href=\"#about\">درباره من</a>\n      <a href=\"#skills\">مهارت‌ها</a>\n      <a href=\"#contact\">تماس</a>\n    </nav>\n  </header>\n  <main>\n    <section id=\"about\">\n      <h2>درباره من</h2>\n      <p>من در حال یادگیری طراحی وب هستم.</p>\n      <img src=\"profile.jpg\" alt=\"تصویر پروفایل دانش‌آموز\" width=\"180\">\n    </section>\n    <section id=\"skills\">\n      <h2>مهارت‌ها</h2>\n      <ul><li>HTML</li><li>حل مسئله</li></ul>\n      <table>\n        <caption>برنامه هفتگی</caption>\n        <thead><tr><th scope=\"col\">روز</th><th scope=\"col\">موضوع</th></tr></thead>\n        <tbody><tr><td>شنبه</td><td>HTML</td></tr></tbody>\n      </table>\n    </section>\n    <section id=\"contact\">\n      <h2>تماس</h2>\n      <form>\n        <label for=\"message\">پیام</label>\n        <textarea id=\"message\" name=\"message\" rows=\"4\"></textarea>\n        <button type=\"submit\">ارسال آزمایشی</button>\n      </form>\n    </section>\n  </main>\n  <footer><p>© NEXORA FORGE</p></footer>\n</body>\n</html>","exercise":"یک صفحه معرفی دانش‌آموز با header، nav، main، سه section، تصویر دارای alt، فهرست، جدول معنایی، فرم برچسب‌دار و footer بساز. آن را در مرورگر و اعتبارسنج HTML آزمایش کن و خطاها را اصلاح کن.","status":"published","sort_order":36,"estimated_minutes":60},{"id":"curriculum-324-html-intermediate-01","course_id":"html-intermediate","title":"fieldset و legend","slug":"html-intermediate-01","summary":"fieldset و legend: گروه‌بندی معنایی کنترل‌های مرتبط در فرم‌های بزرگ.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی معنایی کنترل‌های مرتبط در فرم‌های بزرگ.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;fieldset&gt;&lt;legend&gt;اطلاعات حساب&lt;/legend&gt;&lt;label for=\"u\"&gt;شناسه&lt;/label&gt;&lt;input id=\"u\" name=\"user\"&gt;&lt;/fieldset&gt;</code></pre><h3>تمرین</h3><p>فرم تنظیمات را به گروه حساب و اعلان تقسیم کن.</p><h3>نکته فنی</h3><p>fieldset گروهی از کنترل‌های مرتبط را مشخص می‌کند و legend باید نام همان گروه را بیان کند.</p><h3>معیار موفقیت</h3><p>کنترل‌های مرتبط زیر یک fieldset قرار گیرند و legend هدف گروه را روشن کند.</p>","starter_code":"<fieldset><legend>اطلاعات حساب</legend><label for=\"u\">شناسه</label><input id=\"u\" name=\"user\"></fieldset>","exercise":"فرم تنظیمات را به گروه حساب و اعلان تقسیم کن.","status":"published","sort_order":1,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-02","course_id":"html-intermediate","title":"اعتبارسنجی pattern","slug":"html-intermediate-02","summary":"اعتبارسنجی pattern: محدودکردن قالب ورودی با عبارت منظم؛ اعتبارسنجی سرور همچنان ضروری است.","content_html":"<h3>هدف درس</h3><p>محدودکردن قالب ورودی با عبارت منظم؛ اعتبارسنجی سرور همچنان ضروری است.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input name=\"code\" pattern=\"[a-z0-9]{12}\" title=\"۱۲ حرف کوچک یا رقم\" required&gt;</code></pre><h3>تمرین</h3><p>شناسه ۱۲ نویسه‌ای بساز و حالت‌های نامعتبر را آزمایش کن.</p><h3>نکته فنی</h3><p>pattern فقط اعتبارسنجی سمت مرورگر است؛ داده دریافتی باید دوباره در سرور بررسی شود.</p><h3>معیار موفقیت</h3><p>ورودی معتبر پذیرفته و مقدار ناسازگار در مرورگر رد شود؛ محدودیت سمت سرور نیز در توضیح ذکر شود.</p>","starter_code":"<input name=\"code\" pattern=\"[a-z0-9]{12}\" title=\"۱۲ حرف کوچک یا رقم\" required>","exercise":"شناسه ۱۲ نویسه‌ای بساز و حالت‌های نامعتبر را آزمایش کن.","status":"published","sort_order":2,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-03","course_id":"html-intermediate","title":"aria-describedby","slug":"html-intermediate-03","summary":"aria-describedby: اتصال توضیح کمکی یا پیام خطا به ورودی فرم.","content_html":"<h3>هدف درس</h3><p>اتصال توضیح کمکی یا پیام خطا به ورودی فرم.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;label for=\"pw\"&gt;رمز&lt;/label&gt;&lt;input id=\"pw\" type=\"password\" aria-describedby=\"hint\"&gt;&lt;p id=\"hint\"&gt;حداقل ۱۰ نویسه&lt;/p&gt;</code></pre><h3>تمرین</h3><p>برای دو ورودی توضیح کمکی متصل کن.</p><h3>نکته فنی</h3><p>مقدار aria-describedby باید به idهای موجود و مرتبط در همان سند اشاره کند.</p><h3>معیار موفقیت</h3><p>پیام راهنما و خطا با id یکتا به ورودی درست متصل شوند.</p>","starter_code":"<label for=\"pw\">رمز</label><input id=\"pw\" type=\"password\" aria-describedby=\"hint\"><p id=\"hint\">حداقل ۱۰ نویسه</p>","exercise":"برای دو ورودی توضیح کمکی متصل کن.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-04","course_id":"html-intermediate","title":"autocomplete","slug":"html-intermediate-04","summary":"autocomplete: اعلام نوع داده مورد انتظار برای تکمیل خودکار مرورگر.","content_html":"<h3>هدف درس</h3><p>اعلام نوع داده مورد انتظار برای تکمیل خودکار مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input autocomplete=\"name\"&gt;&lt;input type=\"email\" autocomplete=\"email\"&gt;&lt;input type=\"password\" autocomplete=\"new-password\"&gt;</code></pre><h3>تمرین</h3><p>برای نام، ایمیل، شناسه و رمز token مناسب انتخاب کن.</p><h3>نکته فنی</h3><p>autocomplete از tokenهای استاندارد مانند name و email استفاده می‌کند؛ مقدار دلخواه ممکن است نادیده گرفته شود.</p><h3>معیار موفقیت</h3><p>مرورگر tokenهای autocomplete را تشخیص دهد و پیشنهاد مناسب برای فیلد نمایش دهد.</p>","starter_code":"<input autocomplete=\"name\"><input type=\"email\" autocomplete=\"email\"><input type=\"password\" autocomplete=\"new-password\">","exercise":"برای نام، ایمیل، شناسه و رمز token مناسب انتخاب کن.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-05","course_id":"html-intermediate","title":"datalist","slug":"html-intermediate-05","summary":"datalist: ارائه پیشنهاد برای input بدون محدودکردن قطعی مقدار.","content_html":"<h3>هدف درس</h3><p>ارائه پیشنهاد برای input بدون محدودکردن قطعی مقدار.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input list=\"topics\"&gt;&lt;datalist id=\"topics\"&gt;&lt;option value=\"طراحی وب\"&gt;&lt;/option&gt;&lt;option value=\"برنامه‌نویسی\"&gt;&lt;/option&gt;&lt;/datalist&gt;</code></pre><h3>تمرین</h3><p>پیشنهاد موضوع بساز و مقدار دلخواه خارج از فهرست را امتحان کن.</p><h3>نکته فنی</h3><p>datalist پیشنهاد می‌دهد اما کاربر را به گزینه‌های فهرست محدود نمی‌کند.</p><h3>معیار موفقیت</h3><p>کاربر بتواند مقدار خارج از datalist هم وارد کند و پیشنهادها همچنان قابل انتخاب باشند.</p>","starter_code":"<input list=\"topics\"><datalist id=\"topics\"><option value=\"طراحی وب\"></option><option value=\"برنامه‌نویسی\"></option></datalist>","exercise":"پیشنهاد موضوع بساز و مقدار دلخواه خارج از فهرست را امتحان کن.","status":"published","sort_order":5,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-06","course_id":"html-intermediate","title":"input فایل و accept","slug":"html-intermediate-06","summary":"input فایل و accept: پیشنهاد نوع فایل در انتخاب‌گر؛ بررسی واقعی فایل وظیفه سرور است.","content_html":"<h3>هدف درس</h3><p>پیشنهاد نوع فایل در انتخاب‌گر؛ بررسی واقعی فایل وظیفه سرور است.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input type=\"file\" accept=\"image/png,image/jpeg,image/webp\"&gt;</code></pre><h3>تمرین</h3><p>ورودی تصویر بساز و محدودیت accept را شرح بده.</p><h3>نکته فنی</h3><p>accept راهنمای انتخاب فایل است و نوع واقعی فایل را تضمین یا اعتبارسنجی نمی‌کند.</p><h3>معیار موفقیت</h3><p>انتخاب‌گر فایل نوع‌های پیشنهادی را نشان دهد و محدودیت امنیتی accept به‌درستی توضیح داده شود.</p>","starter_code":"<input type=\"file\" accept=\"image/png,image/jpeg,image/webp\">","exercise":"ورودی تصویر بساز و محدودیت accept را شرح بده.","status":"published","sort_order":6,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-07","course_id":"html-intermediate","title":"انتخاب چند فایل","slug":"html-intermediate-07","summary":"انتخاب چند فایل: multiple امکان انتخاب چند فایل را فراهم می‌کند.","content_html":"<h3>هدف درس</h3><p>multiple امکان انتخاب چند فایل را فراهم می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input type=\"file\" name=\"files\" multiple accept=\".pdf,image/*\"&gt;</code></pre><h3>تمرین</h3><p>ورودی چندفایلی و راهنمای استفاده بساز.</p><h3>نکته فنی</h3><p>multiple انتخاب چند فایل را فعال می‌کند؛ اندازه، نوع و تعداد فایل‌ها باید جداگانه کنترل شوند.</p><h3>معیار موفقیت</h3><p>چند فایل انتخاب شوند و کد تمرین تفاوت انتخاب چندگانه با اعتبارسنجی فایل را شرح دهد.</p>","starter_code":"<input type=\"file\" name=\"files\" multiple accept=\".pdf,image/*\">","exercise":"ورودی چندفایلی و راهنمای استفاده بساز.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-08","course_id":"html-intermediate","title":"readonly در برابر disabled","slug":"html-intermediate-08","summary":"readonly در برابر disabled: readonly مقدار را قفل می‌کند؛ disabled کنترل را غیرفعال و معمولاً از ارسال فرم خارج می‌کند.","content_html":"<h3>هدف درس</h3><p>readonly مقدار را قفل می‌کند؛ disabled کنترل را غیرفعال و معمولاً از ارسال فرم خارج می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input name=\"id\" value=\"ab12\" readonly&gt;&lt;input name=\"locked\" value=\"قفل\" disabled&gt;</code></pre><h3>تمرین</h3><p>رفتار ارسال مقدار این دو را مقایسه کن.</p><h3>نکته فنی</h3><p>readonly مقدار را قابل ارسال نگه می‌دارد؛ disabled معمولاً از ارسال فرم کنار گذاشته می‌شود.</p><h3>معیار موفقیت</h3><p>فیلد readonly در ارسال حضور داشته باشد و فیلد disabled به‌عنوان کنترل غیرفعال شناخته شود.</p>","starter_code":"<input name=\"id\" value=\"ab12\" readonly><input name=\"locked\" value=\"قفل\" disabled>","exercise":"رفتار ارسال مقدار این دو را مقایسه کن.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-09","course_id":"html-intermediate","title":"formaction و formmethod","slug":"html-intermediate-09","summary":"formaction و formmethod: تغییر مقصد یا روش ارسال برای یک دکمه submit خاص.","content_html":"<h3>هدف درس</h3><p>تغییر مقصد یا روش ارسال برای یک دکمه submit خاص.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;form action=\"/save\" method=\"post\"&gt;&lt;button&gt;ذخیره&lt;/button&gt;&lt;button formaction=\"/preview\" formmethod=\"get\"&gt;پیش‌نمایش&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>فرمی با دکمه‌های ذخیره و پیش‌نمایش بساز.</p><h3>نکته فنی</h3><p>formaction و formmethod می‌توانند تنظیمات action و method فرم را برای همان دکمه بازنویسی کنند.</p><h3>معیار موفقیت</h3><p>ارسال هر دکمه به مقصد و روش تعریف‌شده برای همان دکمه هدایت شود.</p>","starter_code":"<form action=\"/save\" method=\"post\"><button>ذخیره</button><button formaction=\"/preview\" formmethod=\"get\">پیش‌نمایش</button></form>","exercise":"فرمی با دکمه‌های ذخیره و پیش‌نمایش بساز.","status":"published","sort_order":9,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-10","course_id":"html-intermediate","title":"multipart/form-data","slug":"html-intermediate-10","summary":"multipart/form-data: کدگذاری لازم فرم برای ارسال فایل با درخواست POST.","content_html":"<h3>هدف درس</h3><p>کدگذاری لازم فرم برای ارسال فایل با درخواست POST.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;form action=\"/upload\" method=\"post\" enctype=\"multipart/form-data\"&gt;&lt;input type=\"file\" name=\"file\"&gt;&lt;button&gt;بارگذاری&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>فرم بارگذاری بساز و نقش enctype را توضیح بده.</p><h3>نکته فنی</h3><p>برای ارسال فایل باید enctype فرم multipart/form-data باشد و پردازش فایل در سرور انجام شود.</p><h3>معیار موفقیت</h3><p>فرم فایل را با enctype درست ارسال کند و ورودی فایل دارای name باشد.</p>","starter_code":"<form action=\"/upload\" method=\"post\" enctype=\"multipart/form-data\"><input type=\"file\" name=\"file\"><button>بارگذاری</button></form>","exercise":"فرم بارگذاری بساز و نقش enctype را توضیح بده.","status":"published","sort_order":10,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-11","course_id":"html-intermediate","title":"optgroup","slug":"html-intermediate-11","summary":"optgroup: گروه‌بندی گزینه‌های مرتبط داخل select.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی گزینه‌های مرتبط داخل select.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;select&gt;&lt;optgroup label=\"وب\"&gt;&lt;option&gt;HTML&lt;/option&gt;&lt;option&gt;CSS&lt;/option&gt;&lt;/optgroup&gt;&lt;optgroup label=\"کدنویسی\"&gt;&lt;option&gt;JavaScript&lt;/option&gt;&lt;/optgroup&gt;&lt;/select&gt;</code></pre><h3>تمرین</h3><p>گزینه‌های دوره را در گروه‌های موضوعی بچین.</p><h3>نکته فنی</h3><p>optgroup گزینه‌ها را گروه‌بندی می‌کند؛ برای هر گروه label قابل فهم تعیین کن.</p><h3>معیار موفقیت</h3><p>گزینه‌ها در گروه‌های نام‌دار دیده شوند و هر گروه عنوان معنادار داشته باشد.</p>","starter_code":"<select><optgroup label=\"وب\"><option>HTML</option><option>CSS</option></optgroup><optgroup label=\"کدنویسی\"><option>JavaScript</option></optgroup></select>","exercise":"گزینه‌های دوره را در گروه‌های موضوعی بچین.","status":"published","sort_order":11,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-12","course_id":"html-intermediate","title":"output","slug":"html-intermediate-12","summary":"output: عنصر معنایی برای نمایش نتیجه محاسبه یا عملیات.","content_html":"<h3>هدف درس</h3><p>عنصر معنایی برای نمایش نتیجه محاسبه یا عملیات.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;form oninput=\"sum.value=Number(a.value)+Number(b.value)\"&gt;&lt;input id=\"a\" type=\"number\" value=\"2\"&gt;&lt;input id=\"b\" type=\"number\" value=\"3\"&gt;&lt;output name=\"sum\" for=\"a b\"&gt;5&lt;/output&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>جمع دو ورودی را نمایش بده و نقش JavaScript را مشخص کن.</p><h3>نکته فنی</h3><p>output برای نمایش نتیجه محاسبه در فرم مناسب است و باید رابطه‌اش با ورودی‌ها مشخص شود.</p><h3>معیار موفقیت</h3><p>خروجی محاسبه در عنصر output نمایش داده شود و با ورودی‌های مرتبط باشد.</p>","starter_code":"<form oninput=\"sum.value=Number(a.value)+Number(b.value)\"><input id=\"a\" type=\"number\" value=\"2\"><input id=\"b\" type=\"number\" value=\"3\"><output name=\"sum\" for=\"a b\">5</output></form>","exercise":"جمع دو ورودی را نمایش بده و نقش JavaScript را مشخص کن.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-13","course_id":"html-intermediate","title":"progress","slug":"html-intermediate-13","summary":"progress: نمایش میزان پیشرفت یک کار در محدوده مشخص.","content_html":"<h3>هدف درس</h3><p>نمایش میزان پیشرفت یک کار در محدوده مشخص.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;progress value=\"35\" max=\"100\"&gt;35%&lt;/progress&gt;</code></pre><h3>تمرین</h3><p>نمونه progress مشخص و نامشخص بساز.</p><h3>نکته فنی</h3><p>progress میزان پیشرفت یک کار را نشان می‌دهد؛ برای مقدار نامعلوم، حالت بدون value معنای متفاوتی دارد.</p><h3>معیار موفقیت</h3><p>درصد پیشرفت با مقدار واقعی هماهنگ باشد و مقدار نامعلوم اشتباه به صفر تعبیر نشود.</p>","starter_code":"<progress value=\"35\" max=\"100\">35%</progress>","exercise":"نمونه progress مشخص و نامشخص بساز.","status":"published","sort_order":13,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-14","course_id":"html-intermediate","title":"meter","slug":"html-intermediate-14","summary":"meter: نمایش سنجه مقداری مانند ظرفیت یا امتیاز در یک بازه.","content_html":"<h3>هدف درس</h3><p>نمایش سنجه مقداری مانند ظرفیت یا امتیاز در یک بازه.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;meter min=\"0\" max=\"100\" low=\"40\" high=\"80\" optimum=\"95\" value=\"72\"&gt;72&lt;/meter&gt;</code></pre><h3>تمرین</h3><p>meter ظرفیت ذخیره‌سازی طراحی کن.</p><h3>نکته فنی</h3><p>meter مقدار را در یک بازه شناخته‌شده نشان می‌دهد و جای progress برای کار زمان‌مند نیست.</p><h3>معیار موفقیت</h3><p>meter برای سنجش یک مقدار در بازه استفاده شود و حداقل، حداکثر و مقدار مشخص باشند.</p>","starter_code":"<meter min=\"0\" max=\"100\" low=\"40\" high=\"80\" optimum=\"95\" value=\"72\">72</meter>","exercise":"meter ظرفیت ذخیره‌سازی طراحی کن.","status":"published","sort_order":14,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-15","course_id":"html-intermediate","title":"details و summary","slug":"html-intermediate-15","summary":"details و summary: ساخت بخش افشونده بومی با عنوان قابل فعال‌سازی.","content_html":"<h3>هدف درس</h3><p>ساخت بخش افشونده بومی با عنوان قابل فعال‌سازی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;details&gt;&lt;summary&gt;پیش‌نیازها&lt;/summary&gt;&lt;p&gt;آشنایی با مرورگر کافی است.&lt;/p&gt;&lt;/details&gt;</code></pre><h3>تمرین</h3><p>سه پرسش متداول با عنوان‌های روشن بساز.</p><h3>نکته فنی</h3><p>summary باید نخستین فرزند details باشد و عنوان قابل فهم بخش بازشونده را ارائه کند.</p><h3>معیار موفقیت</h3><p>بخش details باز و بسته شود و summary عنوان آن را به‌درستی نمایش دهد.</p>","starter_code":"<details><summary>پیش‌نیازها</summary><p>آشنایی با مرورگر کافی است.</p></details>","exercise":"سه پرسش متداول با عنوان‌های روشن بساز.","status":"published","sort_order":15,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-16","course_id":"html-intermediate","title":"dialog","slug":"html-intermediate-16","summary":"dialog: پنجره محاوره‌ای بومی با قابلیت بازشدن modal.","content_html":"<h3>هدف درس</h3><p>پنجره محاوره‌ای بومی با قابلیت بازشدن modal.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;dialog id=\"d\"&gt;&lt;h2&gt;راهنما&lt;/h2&gt;&lt;form method=\"dialog\"&gt;&lt;button&gt;بستن&lt;/button&gt;&lt;/form&gt;&lt;/dialog&gt;&lt;button onclick=\"d.showModal()\"&gt;نمایش&lt;/button&gt;</code></pre><h3>تمرین</h3><p>پنجره راهنما بساز و مسیر بستن و فوکوس را آزمایش کن.</p><h3>نکته فنی</h3><p>dialog را با showModal برای حالت modal باز کن تا رفتار فوکوس و لایه‌بندی بومی مرورگر فعال شود.</p><h3>معیار موفقیت</h3><p>dialog به‌صورت modal باز و با روش مناسب بسته شود و فوکوس قابل مدیریت باشد.</p>","starter_code":"<dialog id=\"d\"><h2>راهنما</h2><form method=\"dialog\"><button>بستن</button></form></dialog><button onclick=\"d.showModal()\">نمایش</button>","exercise":"پنجره راهنما بساز و مسیر بستن و فوکوس را آزمایش کن.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-17","course_id":"html-intermediate","title":"picture","slug":"html-intermediate-17","summary":"picture: انتخاب منبع تصویر بر اساس اندازه صفحه یا نوع فایل.","content_html":"<h3>هدف درس</h3><p>انتخاب منبع تصویر بر اساس اندازه صفحه یا نوع فایل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;picture&gt;&lt;source media=\"(max-width:600px)\" srcset=\"small.webp\"&gt;&lt;source type=\"image/avif\" srcset=\"banner.avif\"&gt;&lt;img src=\"banner.jpg\" alt=\"نمای پروژه\"&gt;&lt;/picture&gt;</code></pre><h3>تمرین</h3><p>نسخه موبایل و دسکتاپ تصویر معرفی کن.</p><h3>نکته فنی</h3><p>در picture ترتیب sourceها مهم است؛ مرورگر نخستین منبع سازگار را انتخاب می‌کند.</p><h3>معیار موفقیت</h3><p>تصویر مناسب با اندازه نمایشگر انتخاب شود و img دارای alt باشد.</p>","starter_code":"<picture><source media=\"(max-width:600px)\" srcset=\"small.webp\"><source type=\"image/avif\" srcset=\"banner.avif\"><img src=\"banner.jpg\" alt=\"نمای پروژه\"></picture>","exercise":"نسخه موبایل و دسکتاپ تصویر معرفی کن.","status":"published","sort_order":17,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-18","course_id":"html-intermediate","title":"srcset و sizes","slug":"html-intermediate-18","summary":"srcset و sizes: معرفی چند وضوح تصویر برای انتخاب هوشمند مرورگر.","content_html":"<h3>هدف درس</h3><p>معرفی چند وضوح تصویر برای انتخاب هوشمند مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"a800.jpg\" srcset=\"a400.jpg 400w, a800.jpg 800w, a1200.jpg 1200w\" sizes=\"(max-width:600px) 100vw,800px\" alt=\"دوره\"&gt;</code></pre><h3>تمرین</h3><p>سه فایل واقعی و عرض صحیح آن‌ها را تنظیم کن.</p><h3>نکته فنی</h3><p>srcset با sizes به مرورگر اطلاعات لازم برای انتخاب تصویر متناسب با اندازه و تراکم نمایشگر می‌دهد.</p><h3>معیار موفقیت</h3><p>مرورگر با توجه به viewport و تراکم نمایشگر منبع مناسب srcset را انتخاب کند.</p>","starter_code":"<img src=\"a800.jpg\" srcset=\"a400.jpg 400w, a800.jpg 800w, a1200.jpg 1200w\" sizes=\"(max-width:600px) 100vw,800px\" alt=\"دوره\">","exercise":"سه فایل واقعی و عرض صحیح آن‌ها را تنظیم کن.","status":"published","sort_order":18,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-19","course_id":"html-intermediate","title":"figure و figcaption","slug":"html-intermediate-19","summary":"figure و figcaption: گروه‌بندی تصویر یا نمودار مستقل با شرح مرتبط.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی تصویر یا نمودار مستقل با شرح مرتبط.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;figure&gt;&lt;img src=\"tree.png\" alt=\"درخت عناصر HTML\"&gt;&lt;figcaption&gt;شکل ۱: ساختار سند&lt;/figcaption&gt;&lt;/figure&gt;</code></pre><h3>تمرین</h3><p>برای نمودار آموزشی شرح دقیق بنویس.</p><h3>نکته فنی</h3><p>figure محتوای مستقل مانند تصویر یا نمودار را گروه‌بندی می‌کند و figcaption شرح آن است.</p><h3>معیار موفقیت</h3><p>تصویر و شرح آن در یک figure قرار گیرند و figcaption رابطه روشن داشته باشد.</p>","starter_code":"<figure><img src=\"tree.png\" alt=\"درخت عناصر HTML\"><figcaption>شکل ۱: ساختار سند</figcaption></figure>","exercise":"برای نمودار آموزشی شرح دقیق بنویس.","status":"published","sort_order":19,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-20","course_id":"html-intermediate","title":"SVG دسترس‌پذیر","slug":"html-intermediate-20","summary":"SVG دسترس‌پذیر: گرافیک برداری درون‌خطی با عنوان قابل شناسایی.","content_html":"<h3>هدف درس</h3><p>گرافیک برداری درون‌خطی با عنوان قابل شناسایی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;svg viewBox=\"0 0 100 60\" role=\"img\" aria-labelledby=\"t\"&gt;&lt;title id=\"t\"&gt;دو ستون&lt;/title&gt;&lt;rect x=\"10\" y=\"25\" width=\"20\" height=\"30\"/&gt;&lt;rect x=\"50\" y=\"10\" width=\"20\" height=\"45\"/&gt;&lt;/svg&gt;</code></pre><h3>تمرین</h3><p>SVG با دو شکل و عنوان توصیفی بساز.</p><h3>نکته فنی</h3><p>برای SVG اطلاعاتی title یا نام دسترس‌پذیر فراهم کن؛ SVG تزئینی را از درخت دسترس‌پذیری پنهان کن.</p><h3>معیار موفقیت</h3><p>SVG اطلاعاتی نام دسترس‌پذیر داشته باشد و محتوای بصری آن برای کاربر قابل فهم باشد.</p>","starter_code":"<svg viewBox=\"0 0 100 60\" role=\"img\" aria-labelledby=\"t\"><title id=\"t\">دو ستون</title><rect x=\"10\" y=\"25\" width=\"20\" height=\"30\"/><rect x=\"50\" y=\"10\" width=\"20\" height=\"45\"/></svg>","exercise":"SVG با دو شکل و عنوان توصیفی بساز.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-21","course_id":"html-intermediate","title":"noscript","slug":"html-intermediate-21","summary":"noscript: نمایش پیام جایگزین در صورت غیرفعال بودن JavaScript.","content_html":"<h3>هدف درس</h3><p>نمایش پیام جایگزین در صورت غیرفعال بودن JavaScript.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;noscript&gt;&lt;p&gt;برای این قابلیت JavaScript را فعال کن.&lt;/p&gt;&lt;/noscript&gt;</code></pre><h3>تمرین</h3><p>پیام جایگزین یک قابلیت وابسته به اسکریپت بنویس.</p><h3>نکته فنی</h3><p>noscript فقط وقتی JavaScript غیرفعال یا پشتیبانی‌نشده باشد نمایش داده می‌شود؛ محتوای اصلی را بی‌جهت به آن وابسته نکن.</p><h3>معیار موفقیت</h3><p>پیام جایگزین فقط در حالت بدون JavaScript دیده شود و محتوای اصلی همچنان قابل دسترس بماند.</p>","starter_code":"<noscript><p>برای این قابلیت JavaScript را فعال کن.</p></noscript>","exercise":"پیام جایگزین یک قابلیت وابسته به اسکریپت بنویس.","status":"published","sort_order":21,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-22","course_id":"html-intermediate","title":"loading lazy","slug":"html-intermediate-22","summary":"loading lazy: به‌تعویق‌انداختن دریافت تصویر خارج از محدوده دید.","content_html":"<h3>هدف درس</h3><p>به‌تعویق‌انداختن دریافت تصویر خارج از محدوده دید.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"gallery.jpg\" alt=\"پروژه\" width=\"800\" height=\"500\" loading=\"lazy\"&gt;</code></pre><h3>تمرین</h3><p>برای تصاویر پایین صفحه lazy و ابعاد ثابت بگذار.</p><h3>نکته فنی</h3><p>loading=lazy را برای رسانه‌های خارج از viewport به کار ببر، نه تصویر اصلی بالای صفحه.</p><h3>معیار موفقیت</h3><p>تصویر پایین صفحه تنبل بارگذاری شود و تصویر اصلی بالای صفحه بی‌دلیل تأخیر نداشته باشد.</p>","starter_code":"<img src=\"gallery.jpg\" alt=\"پروژه\" width=\"800\" height=\"500\" loading=\"lazy\">","exercise":"برای تصاویر پایین صفحه lazy و ابعاد ثابت بگذار.","status":"published","sort_order":22,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-23","course_id":"html-intermediate","title":"fetchpriority","slug":"html-intermediate-23","summary":"fetchpriority: پیشنهاد اولویت دریافت منبع مهم برای مرورگر.","content_html":"<h3>هدف درس</h3><p>پیشنهاد اولویت دریافت منبع مهم برای مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"600\" fetchpriority=\"high\"&gt;</code></pre><h3>تمرین</h3><p>برای تصویر اصلی و فرعی اولویت مناسب تعیین کن.</p><h3>نکته فنی</h3><p>fetchpriority یک hint اولویت است و نباید برای تعداد زیادی منبع high تعیین شود.</p><h3>معیار موفقیت</h3><p>اولویت بالا فقط به منبع واقعاً حیاتی داده شود و منابع دیگر اولویت عادی داشته باشند.</p>","starter_code":"<img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"600\" fetchpriority=\"high\">","exercise":"برای تصویر اصلی و فرعی اولویت مناسب تعیین کن.","status":"published","sort_order":23,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-24","course_id":"html-intermediate","title":"iframe sandbox","slug":"html-intermediate-24","summary":"iframe sandbox: محدودکردن قابلیت‌های محتوای جاسازی‌شده.","content_html":"<h3>هدف درس</h3><p>محدودکردن قابلیت‌های محتوای جاسازی‌شده.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;iframe src=\"https://example.com\" title=\"محتوای خارجی\" sandbox=\"allow-forms\" loading=\"lazy\"&gt;&lt;/iframe&gt;</code></pre><h3>تمرین</h3><p>رفتار iframe محدود را بررسی کن.</p><h3>نکته فنی</h3><p>sandbox قابلیت‌های iframe را محدود می‌کند؛ فقط tokenهای واقعاً لازم را اضافه کن.</p><h3>معیار موفقیت</h3><p>iframe فقط قابلیت‌های ضروری را دریافت کند و محتوای تعبیه‌شده در محدوده sandbox بماند.</p>","starter_code":"<iframe src=\"https://example.com\" title=\"محتوای خارجی\" sandbox=\"allow-forms\" loading=\"lazy\"></iframe>","exercise":"رفتار iframe محدود را بررسی کن.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-25","course_id":"html-intermediate","title":"defer و async","slug":"html-intermediate-25","summary":"defer و async: تفاوت اجرای اسکریپت با حفظ ترتیب و اجرای مستقل.","content_html":"<h3>هدف درس</h3><p>تفاوت اجرای اسکریپت با حفظ ترتیب و اجرای مستقل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;script src=\"app.js\" defer&gt;&lt;/script&gt;&lt;script src=\"metrics.js\" async&gt;&lt;/script&gt;</code></pre><h3>تمرین</h3><p>برای دو اسکریپت با وابستگی متفاوت ویژگی مناسب انتخاب کن.</p><h3>نکته فنی</h3><p>defer ترتیب اجرای اسکریپت‌های deferred را حفظ می‌کند؛ async ترتیب اجرا را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>اسکریپت‌های defer به ترتیب سند اجرا شوند و async مستقل از ترتیب بارگذاری عمل کند.</p>","starter_code":"<script src=\"app.js\" defer></script><script src=\"metrics.js\" async></script>","exercise":"برای دو اسکریپت با وابستگی متفاوت ویژگی مناسب انتخاب کن.","status":"published","sort_order":25,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-26","course_id":"html-intermediate","title":"JavaScript module","slug":"html-intermediate-26","summary":"JavaScript module: بارگذاری فایل به‌عنوان ماژول با scope مستقل.","content_html":"<h3>هدف درس</h3><p>بارگذاری فایل به‌عنوان ماژول با scope مستقل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;script type=\"module\" src=\"main.js\"&gt;&lt;/script&gt;</code></pre><h3>تمرین</h3><p>فایل اصلی را به ماژول app.js متصل کن.</p><h3>نکته فنی</h3><p>script type=module به‌طور پیش‌فرض deferred است و از scope ماژولی استفاده می‌کند.</p><h3>معیار موفقیت</h3><p>ماژول بدون خطای type=module بارگذاری شود و import/export در فایل ماژول معتبر باشد.</p>","starter_code":"<script type=\"module\" src=\"main.js\"></script>","exercise":"فایل اصلی را به ماژول app.js متصل کن.","status":"published","sort_order":26,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-27","course_id":"html-intermediate","title":"preconnect","slug":"html-intermediate-27","summary":"preconnect: شروع زودهنگام اتصال به مبدأ خارجی موردنیاز.","content_html":"<h3>هدف درس</h3><p>شروع زودهنگام اتصال به مبدأ خارجی موردنیاز.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;link rel=\"preconnect\" href=\"https://fonts.example.com\" crossorigin&gt;</code></pre><h3>تمرین</h3><p>برای منبع خارجی واقعی preconnect تعریف کن.</p><h3>نکته فنی</h3><p>preconnect برای originهایی مفید است که احتمالاً به‌زودی به آن‌ها اتصال برقرار می‌شود؛ از اتصال‌های اضافی بپرهیز.</p><h3>معیار موفقیت</h3><p>اتصال اولیه فقط برای origin لازم انجام شود و منبع خارجی غیرضروری اضافه نشود.</p>","starter_code":"<link rel=\"preconnect\" href=\"https://fonts.example.com\" crossorigin>","exercise":"برای منبع خارجی واقعی preconnect تعریف کن.","status":"published","sort_order":27,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-28","course_id":"html-intermediate","title":"preload","slug":"html-intermediate-28","summary":"preload: دریافت زودهنگام منبعی که صفحه به آن نیاز فوری دارد.","content_html":"<h3>هدف درس</h3><p>دریافت زودهنگام منبعی که صفحه به آن نیاز فوری دارد.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;link rel=\"preload\" href=\"/fonts/site.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;</code></pre><h3>تمرین</h3><p>فونت پروژه را با as و type درست preload کن.</p><h3>نکته فنی</h3><p>preload برای منبع ضروری همین صفحه است؛ نوع و crossorigin باید با درخواست واقعی هماهنگ باشد.</p><h3>معیار موفقیت</h3><p>منبع preload واقعاً در همان صفحه مصرف شود و نوع و crossorigin با فایل هماهنگ باشد.</p>","starter_code":"<link rel=\"preload\" href=\"/fonts/site.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>","exercise":"فونت پروژه را با as و type درست preload کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-29","course_id":"html-intermediate","title":"skip link","slug":"html-intermediate-29","summary":"skip link: پرش مستقیم کاربران صفحه‌کلید به محتوای اصلی.","content_html":"<h3>هدف درس</h3><p>پرش مستقیم کاربران صفحه‌کلید به محتوای اصلی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;a href=\"#main\"&gt;رفتن به محتوا&lt;/a&gt;&lt;nav&gt;...&lt;/nav&gt;&lt;main id=\"main\" tabindex=\"-1\"&gt;...&lt;/main&gt;</code></pre><h3>تمرین</h3><p>لینک پرش بساز و فوکوس مقصد را بررسی کن.</p><h3>نکته فنی</h3><p>skip link باید به مقصدی با id معتبر برسد و هنگام فعال‌سازی با صفحه‌کلید قابل استفاده باشد.</p><h3>معیار موفقیت</h3><p>پیوند پرش به محتوا با صفحه‌کلید کار کند و مقصد main قابل تمرکز باشد.</p>","starter_code":"<a href=\"#main\">رفتن به محتوا</a><nav>...</nav><main id=\"main\" tabindex=\"-1\">...</main>","exercise":"لینک پرش بساز و فوکوس مقصد را بررسی کن.","status":"published","sort_order":29,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-30","course_id":"html-intermediate","title":"tabindex","slug":"html-intermediate-30","summary":"tabindex: کنترل فوکوس برنامه‌ای با مقدار منفی یک یا ترتیب طبیعی با صفر.","content_html":"<h3>هدف درس</h3><p>کنترل فوکوس برنامه‌ای با مقدار منفی یک یا ترتیب طبیعی با صفر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;h2 id=\"result\" tabindex=\"-1\"&gt;نتیجه&lt;/h2&gt;&lt;button&gt;ادامه&lt;/button&gt;</code></pre><h3>تمرین</h3><p>برای مقصد لینک پرش tabindex منفی یک بگذار.</p><h3>نکته فنی</h3><p>tabindex مثبت ترتیب طبیعی فوکوس را مختل می‌کند؛ برای ترتیب عادی از صفر یا بدون tabindex استفاده کن.</p><h3>معیار موفقیت</h3><p>ترتیب Tab طبیعی و قابل پیش‌بینی باشد و tabindex مثبت غیرضروری وجود نداشته باشد.</p>","starter_code":"<h2 id=\"result\" tabindex=\"-1\">نتیجه</h2><button>ادامه</button>","exercise":"برای مقصد لینک پرش tabindex منفی یک بگذار.","status":"published","sort_order":30,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-31","course_id":"html-intermediate","title":"inert و hidden","slug":"html-intermediate-31","summary":"inert و hidden: inert تعامل زیردرخت را می‌بندد؛ hidden محتوا را از نمایش معمول پنهان می‌کند.","content_html":"<h3>هدف درس</h3><p>inert تعامل زیردرخت را می‌بندد؛ hidden محتوا را از نمایش معمول پنهان می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;section hidden&gt;پنل مخفی&lt;/section&gt;&lt;div inert&gt;&lt;button&gt;غیرفعال&lt;/button&gt;&lt;/div&gt;</code></pre><h3>تمرین</h3><p>تفاوت نمایش و تعامل را آزمایش کن.</p><h3>نکته فنی</h3><p>inert تعامل و فوکوس زیرشاخه را غیرفعال می‌کند؛ hidden عنصر را از نمایش عادی حذف می‌کند.</p><h3>معیار موفقیت</h3><p>بخش inert قابل تعامل نباشد و بخش hidden در صفحه نمایش داده نشود.</p>","starter_code":"<section hidden>پنل مخفی</section><div inert><button>غیرفعال</button></div>","exercise":"تفاوت نمایش و تعامل را آزمایش کن.","status":"published","sort_order":31,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-32","course_id":"html-intermediate","title":"aria-live","slug":"html-intermediate-32","summary":"aria-live: اعلام تغییرات ناحیه پویا به فناوری‌های کمکی.","content_html":"<h3>هدف درس</h3><p>اعلام تغییرات ناحیه پویا به فناوری‌های کمکی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;p id=\"status\" aria-live=\"polite\" aria-atomic=\"true\"&gt;آماده&lt;/p&gt;&lt;button onclick=\"status.textContent='ذخیره شد'\"&gt;ذخیره&lt;/button&gt;</code></pre><h3>تمرین</h3><p>ناحیه وضعیت پویا بساز و تغییر متن را آزمایش کن.</p><h3>نکته فنی</h3><p>aria-live را فقط برای پیام‌های واقعاً پویا به کار ببر تا صفحه‌خوان با اعلان‌های پی‌درپی آزار نبیند.</p><h3>معیار موفقیت</h3><p>پیام پویا یک بار و با متن مناسب به صفحه‌خوان اعلام شود.</p>","starter_code":"<p id=\"status\" aria-live=\"polite\" aria-atomic=\"true\">آماده</p><button onclick=\"status.textContent='ذخیره شد'\">ذخیره</button>","exercise":"ناحیه وضعیت پویا بساز و تغییر متن را آزمایش کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-33","course_id":"html-intermediate","title":"rowspan و colspan","slug":"html-intermediate-33","summary":"rowspan و colspan: گسترش سلول جدول در چند ردیف یا ستون.","content_html":"<h3>هدف درس</h3><p>گسترش سلول جدول در چند ردیف یا ستون.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th rowspan=\"2\"&gt;نام&lt;/th&gt;&lt;th colspan=\"2\"&gt;نمره&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th&gt;HTML&lt;/th&gt;&lt;th&gt;CSS&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;سارا&lt;/td&gt;&lt;td&gt;90&lt;/td&gt;&lt;td&gt;85&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول چندسطحی بساز و سلول‌های منطقی را بشمار.</p><h3>نکته فنی</h3><p>rowspan و colspan ساختار جدول را پیچیده می‌کنند؛ برای جدول‌های پیچیده ارتباط سرستون‌ها را صریح کن.</p><h3>معیار موفقیت</h3><p>سلول‌های ادغام‌شده در جدول درست نمایش داده شوند و رابطه سرستون‌ها قابل تشخیص باشد.</p>","starter_code":"<table><tr><th rowspan=\"2\">نام</th><th colspan=\"2\">نمره</th></tr><tr><th>HTML</th><th>CSS</th></tr><tr><td>سارا</td><td>90</td><td>85</td></tr></table>","exercise":"جدول چندسطحی بساز و سلول‌های منطقی را بشمار.","status":"published","sort_order":33,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-34","course_id":"html-intermediate","title":"headers در جدول","slug":"html-intermediate-34","summary":"headers در جدول: ارتباط صریح سلول داده با سرستون‌ها در جدول پیچیده.","content_html":"<h3>هدف درس</h3><p>ارتباط صریح سلول داده با سرستون‌ها در جدول پیچیده.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th id=\"student\"&gt;دانش‌آموز&lt;/th&gt;&lt;th id=\"html\"&gt;HTML&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td headers=\"student\"&gt;علی&lt;/td&gt;&lt;td headers=\"html\"&gt;88&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول نمره با id و headers بساز.</p><h3>نکته فنی</h3><p>headers باید به id سرستون‌های مرتبط اشاره کند؛ مقدارها با فاصله از هم جدا می‌شوند.</p><h3>معیار موفقیت</h3><p>هر سلول داده در جدول پیچیده به سرستون‌های مربوط با headers وصل شود.</p>","starter_code":"<table><tr><th id=\"student\">دانش‌آموز</th><th id=\"html\">HTML</th></tr><tr><td headers=\"student\">علی</td><td headers=\"html\">88</td></tr></table>","exercise":"جدول نمره با id و headers بساز.","status":"published","sort_order":34,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-35","course_id":"html-intermediate","title":"time و datetime","slug":"html-intermediate-35","summary":"time و datetime: ارائه تاریخ ماشین‌خوان در کنار متن نمایشی.","content_html":"<h3>هدف درس</h3><p>ارائه تاریخ ماشین‌خوان در کنار متن نمایشی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;time datetime=\"2026-11-07\"&gt;۷ نوامبر ۲۰۲۶&lt;/time&gt;</code></pre><h3>تمرین</h3><p>تاریخ و ساعت رویداد را با datetime معتبر نمایش بده.</p><h3>نکته فنی</h3><p>time باید datetime ماشین‌خوان معتبر داشته باشد و متن داخل عنصر می‌تواند قالب محلی داشته باشد.</p><h3>معیار موفقیت</h3><p>تاریخ برای ماشین با datetime قابل خواندن و برای انسان با متن محلی نمایش داده شود.</p>","starter_code":"<time datetime=\"2026-11-07\">۷ نوامبر ۲۰۲۶</time>","exercise":"تاریخ و ساعت رویداد را با datetime معتبر نمایش بده.","status":"published","sort_order":35,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-36","course_id":"html-intermediate","title":"پروژه پایانی داشبورد آموزشی","slug":"html-intermediate-36","summary":"پروژه پایانی داشبورد آموزشی: ترکیب فرم گروه‌بندی‌شده، progress، details، تصویر واکنش‌گرا و اعلان وضعیت در یک رابط.","content_html":"<h3>هدف درس</h3><p>ترکیب فرم گروه‌بندی‌شده، progress، details، تصویر واکنش‌گرا و اعلان وضعیت در یک رابط.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;!doctype html&gt;&lt;html lang=\"fa\" dir=\"rtl\"&gt;&lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"&gt;&lt;title&gt;داشبورد دوره&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;a href=\"#main\"&gt;رفتن به محتوا&lt;/a&gt;&lt;header&gt;&lt;h1&gt;داشبورد دوره&lt;/h1&gt;&lt;/header&gt;&lt;main id=\"main\" tabindex=\"-1\"&gt;&lt;section&gt;&lt;h2&gt;پیشرفت&lt;/h2&gt;&lt;progress value=\"6\" max=\"10\"&gt;60%&lt;/progress&gt;&lt;/section&gt;&lt;form&gt;&lt;fieldset&gt;&lt;legend&gt;مسیر آموزشی&lt;/legend&gt;&lt;select&gt;&lt;optgroup label=\"وب\"&gt;&lt;option&gt;HTML&lt;/option&gt;&lt;option&gt;CSS&lt;/option&gt;&lt;/optgroup&gt;&lt;/select&gt;&lt;/fieldset&gt;&lt;button&gt;ثبت آزمایشی&lt;/button&gt;&lt;/form&gt;&lt;details&gt;&lt;summary&gt;راهنما&lt;/summary&gt;&lt;p&gt;درس بعدی را باز کن.&lt;/p&gt;&lt;/details&gt;&lt;p aria-live=\"polite\"&gt;آماده&lt;/p&gt;&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;</code></pre><h3>تمرین</h3><p>داشبوردی با skip link، progress، fieldset، optgroup، details، picture، جدول چندسطحی و aria-live بساز و با صفحه‌کلید و اعتبارسنج HTML بررسی کن.</p><h3>نکته فنی</h3><p>داشبورد نمونه فقط ساختار HTML را نشان می‌دهد؛ داده پویا، احراز هویت و ذخیره‌سازی به لایه‌های دیگر نیاز دارند.</p><h3>معیار موفقیت</h3><p>داشبورد ساختار معنایی، جدول و فرم درست داشته باشد و محدودیت نبود backend مشخص باشد.</p>","starter_code":"<!doctype html><html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>داشبورد دوره</title></head><body><a href=\"#main\">رفتن به محتوا</a><header><h1>داشبورد دوره</h1></header><main id=\"main\" tabindex=\"-1\"><section><h2>پیشرفت</h2><progress value=\"6\" max=\"10\">60%</progress></section><form><fieldset><legend>مسیر آموزشی</legend><select><optgroup label=\"وب\"><option>HTML</option><option>CSS</option></optgroup></select></fieldset><button>ثبت آزمایشی</button></form><details><summary>راهنما</summary><p>درس بعدی را باز کن.</p></details><p aria-live=\"polite\">آماده</p></main></body></html>","exercise":"داشبوردی با skip link، progress، fieldset، optgroup، details، picture، جدول چندسطحی و aria-live بساز و با صفحه‌کلید و اعتبارسنج HTML بررسی کن.","status":"published","sort_order":36,"estimated_minutes":75},{"id":"curriculum-324-html-advanced-01","course_id":"html-advanced","title":"طراحی معماری معنایی برای صفحات چندبخشی","slug":"html-advanced-01","summary":"یک صفحه بزرگ باید با بخش‌های معنایی روشن، ترتیب منطقی و روابط قابل فهم ساخته شود؛ این معماری هم پیمایش را آسان می‌کند و هم نگهداری را. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>یک صفحه بزرگ باید با بخش‌های معنایی روشن، ترتیب منطقی و روابط قابل فهم ساخته شود؛ این معماری هم پیمایش را آسان می‌کند و هم نگهداری را.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;header&gt;برند&lt;/header&gt;&lt;nav aria-label=\"راهنمای اصلی\"&gt;&lt;a href=\"#guide\"&gt;راهنما&lt;/a&gt;&lt;/nav&gt;&lt;main id=\"guide\"&gt;&lt;article&gt;&lt;h1&gt;راهنمای محصول&lt;/h1&gt;&lt;section aria-labelledby=\"install\"&gt;&lt;h2 id=\"install\"&gt;نصب&lt;/h2&gt;&lt;p&gt;مراحل نصب محصول.&lt;/p&gt;&lt;/section&gt;&lt;/article&gt;&lt;aside aria-label=\"مطالب مرتبط\"&gt;پیوندهای مرتبط&lt;/aside&gt;&lt;/main&gt;&lt;footer&gt;پایان صفحه&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>یک صفحه مستندات با header، nav، main، article، دو section و footer بساز؛ ترتیب را طوری بچین که با خاموش بودن CSS هم قابل فهم باشد.</p><h3>نکته فنی</h3><p>عنصرهای معنایی را به‌خاطر ظاهر انتخاب نکن؛ هر عنصر باید نقش محتوایی واقعی داشته باشد.</p><h3>معیار موفقیت</h3><p>صفحه با landmarkهای درست و بدون چند main هم‌زمان ساخته شده باشد.</p>","starter_code":"<header>برند</header><nav aria-label=\"راهنمای اصلی\"><a href=\"#guide\">راهنما</a></nav><main id=\"guide\"><article><h1>راهنمای محصول</h1><section aria-labelledby=\"install\"><h2 id=\"install\">نصب</h2><p>مراحل نصب محصول.</p></section></article><aside aria-label=\"مطالب مرتبط\">پیوندهای مرتبط</aside></main><footer>پایان صفحه</footer>","exercise":"یک صفحه مستندات با header، nav، main، article، دو section و footer بساز؛ ترتیب را طوری بچین که با خاموش بودن CSS هم قابل فهم باشد.","status":"published","sort_order":1,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-02","course_id":"html-advanced","title":"مدل‌سازی landmarkهای صفحه و ناحیه‌های مستقل","slug":"html-advanced-02","summary":"Landmarkها نقاط پرش اصلی صفحه‌اند. برای ناحیه‌های تکراری یا چندگانه باید نام قابل فهم تعیین کنی تا صفحه‌خوان بتواند آن‌ها را از هم جدا کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Landmarkها نقاط پرش اصلی صفحه‌اند. برای ناحیه‌های تکراری یا چندگانه باید نام قابل فهم تعیین کنی تا صفحه‌خوان بتواند آن‌ها را از هم جدا کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;nav aria-label=\"ناوبری اصلی\"&gt;...&lt;/nav&gt;&lt;nav aria-label=\"مسیر صفحه\"&gt;...&lt;/nav&gt;&lt;main&gt;...&lt;/main&gt;&lt;aside aria-label=\"فیلتر نتایج\"&gt;...&lt;/aside&gt;</code></pre><h3>تمرین</h3><p>سه nav مستقل برای منوی اصلی، مسیر راهنما و صفحه‌بندی بساز و برای هرکدام نام دقیق و غیرتکراری قرار بده.</p><h3>نکته فنی</h3><p>برای landmarkهای هم‌نوع، نام‌گذاری مبهم مثل «منو» کافی نیست.</p><h3>معیار موفقیت</h3><p>هر ناحیه با نامش از ناحیه‌های دیگر قابل تشخیص باشد.</p>","starter_code":"<nav aria-label=\"ناوبری اصلی\">...</nav><nav aria-label=\"مسیر صفحه\">...</nav><main>...</main><aside aria-label=\"فیلتر نتایج\">...</aside>","exercise":"سه nav مستقل برای منوی اصلی، مسیر راهنما و صفحه‌بندی بساز و برای هرکدام نام دقیق و غیرتکراری قرار بده.","status":"published","sort_order":2,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-03","course_id":"html-advanced","title":"نام‌گذاری دسترس‌پذیر با name و role و value","slug":"html-advanced-03","summary":"دسترس‌پذیری فقط متن جایگزین نیست؛ کنترل باید نام، نقش و مقدار قابل تشخیص داشته باشد. عنصر بومی معمولاً این اطلاعات را بهتر از نقش‌سازی دستی فراهم می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>دسترس‌پذیری فقط متن جایگزین نیست؛ کنترل باید نام، نقش و مقدار قابل تشخیص داشته باشد. عنصر بومی معمولاً این اطلاعات را بهتر از نقش‌سازی دستی فراهم می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;label for=\"volume\"&gt;بلندی صدا&lt;/label&gt;&lt;input id=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"40\"&gt;&lt;button type=\"button\" aria-pressed=\"false\"&gt;زیرنویس&lt;/button&gt;</code></pre><h3>تمرین</h3><p>یک کنترل تنظیم صدا و دکمه روشن/خاموش زیرنویس بساز؛ نام قابل مشاهده و وضعیت دکمه را درست نمایش بده.</p><h3>نکته فنی</h3><p>روی div نقش دکمه نگذار وقتی می‌توانی button واقعی استفاده کنی.</p><h3>معیار موفقیت</h3><p>نام کنترل‌ها واضح باشد و وضعیت toggle با aria-pressed هماهنگ تغییر کند.</p>","starter_code":"<label for=\"volume\">بلندی صدا</label><input id=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"40\"><button type=\"button\" aria-pressed=\"false\">زیرنویس</button>","exercise":"یک کنترل تنظیم صدا و دکمه روشن/خاموش زیرنویس بساز؛ نام قابل مشاهده و وضعیت دکمه را درست نمایش بده.","status":"published","sort_order":3,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-04","course_id":"html-advanced","title":"ساخت جدول داده‌های پیچیده با scope و id","slug":"html-advanced-04","summary":"در جدول پیچیده، scope به مرورگر می‌گوید سرستون به کدام محور مربوط است؛ برای ارتباط‌های پیچیده‌تر از id و headers استفاده می‌شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در جدول پیچیده، scope به مرورگر می‌گوید سرستون به کدام محور مربوط است؛ برای ارتباط‌های پیچیده‌تر از id و headers استفاده می‌شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;table&gt;&lt;caption&gt;فروش ماهانه&lt;/caption&gt;&lt;tr&gt;&lt;th scope=\"col\"&gt;ماه&lt;/th&gt;&lt;th scope=\"col\"&gt;فروش&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th scope=\"row\"&gt;مهر&lt;/th&gt;&lt;td&gt;120&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدولی برای گزارش سه منطقه و دو فصل بساز؛ سرستون‌های ردیف و ستون را مشخص کن و caption بنویس.</p><h3>نکته فنی</h3><p>جدول را برای چیدمان صفحه استفاده نکن؛ فقط داده‌های جدولی.</p><h3>معیار موفقیت</h3><p>هر سلول داده سرستون مرتبط و قابل تشخیص داشته باشد.</p>","starter_code":"<table><caption>فروش ماهانه</caption><tr><th scope=\"col\">ماه</th><th scope=\"col\">فروش</th></tr><tr><th scope=\"row\">مهر</th><td>120</td></tr></table>","exercise":"جدولی برای گزارش سه منطقه و دو فصل بساز؛ سرستون‌های ردیف و ستون را مشخص کن و caption بنویس.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-05","course_id":"html-advanced","title":"پیوند دادن سرستون‌های چندسطحی جدول","slug":"html-advanced-05","summary":"وقتی سرستون‌ها چند سطح دارند، headers می‌تواند رابطه دقیق سلول داده با چند سرستون را روشن کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>وقتی سرستون‌ها چند سطح دارند، headers می‌تواند رابطه دقیق سلول داده با چند سرستون را روشن کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th id=\"year\" colspan=\"2\"&gt;۱۴۰۵&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th id=\"q1\"&gt;سه‌ماهه اول&lt;/th&gt;&lt;th id=\"q2\"&gt;سه‌ماهه دوم&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th id=\"sales\"&gt;فروش&lt;/th&gt;&lt;td headers=\"year q1 sales\"&gt;۸۰&lt;/td&gt;&lt;td headers=\"year q2 sales\"&gt;۹۵&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>یک جدول با گروه‌بندی سال، فصل و شاخص بساز و برای سلول داده headers دقیق تعریف کن.</p><h3>نکته فنی</h3><p>مقدار headers باید به id سرستون‌های موجود اشاره کند.</p><h3>معیار موفقیت</h3><p>تمام شناسه‌ها یکتا و ارجاع‌ها معتبر باشند.</p>","starter_code":"<table><tr><th id=\"year\" colspan=\"2\">۱۴۰۵</th></tr><tr><th id=\"q1\">سه‌ماهه اول</th><th id=\"q2\">سه‌ماهه دوم</th></tr><tr><th id=\"sales\">فروش</th><td headers=\"year q1 sales\">۸۰</td><td headers=\"year q2 sales\">۹۵</td></tr></table>","exercise":"یک جدول با گروه‌بندی سال، فصل و شاخص بساز و برای سلول داده headers دقیق تعریف کن.","status":"published","sort_order":5,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-06","course_id":"html-advanced","title":"الگوی توضیح خطا برای فرم‌های بزرگ","slug":"html-advanced-06","summary":"در فرم‌های طولانی، خطا باید هم کنار فیلد و هم در خلاصه‌ای قابل پیمایش ارائه شود؛ توضیح خطا باید به ورودی مرتبط باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در فرم‌های طولانی، خطا باید هم کنار فیلد و هم در خلاصه‌ای قابل پیمایش ارائه شود؛ توضیح خطا باید به ورودی مرتبط باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;label for=\"email\"&gt;ایمیل کاری&lt;/label&gt;&lt;input id=\"email\" type=\"email\" aria-describedby=\"email-help email-error\"&gt;&lt;p id=\"email-help\"&gt;برای دریافت رسید استفاده می‌شود.&lt;/p&gt;&lt;p id=\"email-error\"&gt;نشانی واردشده معتبر نیست.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>فرم ثبت‌نام سه فیلدی بساز که برای هر فیلد راهنما و پیام خطای جداگانه داشته باشد و با aria-describedby متصل شوند.</p><h3>نکته فنی</h3><p>فقط رنگ قرمز برای اعلام خطا کافی نیست.</p><h3>معیار موفقیت</h3><p>هر پیام خطا متنی، مرتبط و قابل دسترسی باشد.</p>","starter_code":"<label for=\"email\">ایمیل کاری</label><input id=\"email\" type=\"email\" aria-describedby=\"email-help email-error\"><p id=\"email-help\">برای دریافت رسید استفاده می‌شود.</p><p id=\"email-error\">نشانی واردشده معتبر نیست.</p>","exercise":"فرم ثبت‌نام سه فیلدی بساز که برای هر فیلد راهنما و پیام خطای جداگانه داشته باشد و با aria-describedby متصل شوند.","status":"published","sort_order":6,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-07","course_id":"html-advanced","title":"اعتبارسنجی گروهی و نمایش خلاصه خطاها","slug":"html-advanced-07","summary":"برای فرم‌های بزرگ، خلاصه خطاها کاربر را به اولین ورودی نامعتبر هدایت می‌کند؛ لینک‌ها باید به id واقعی فیلدها بروند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>برای فرم‌های بزرگ، خلاصه خطاها کاربر را به اولین ورودی نامعتبر هدایت می‌کند؛ لینک‌ها باید به id واقعی فیلدها بروند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;section aria-labelledby=\"errors\"&gt;&lt;h2 id=\"errors\"&gt;موارد نیازمند اصلاح&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;a href=\"#user-email\"&gt;ایمیل را بررسی کن&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;label for=\"user-email\"&gt;ایمیل&lt;/label&gt;&lt;input id=\"user-email\" type=\"email\"&gt;</code></pre><h3>تمرین</h3><p>یک فرم پنج فیلدی طراحی کن و خلاصه خطاها را با پیوند به فیلدهای دارای مشکل نمایش بده.</p><h3>نکته فنی</h3><p>خلاصه خطا باید بعد از اعتبارسنجی به‌روزرسانی شود؛ HTML تنها منطق پویا را اجرا نمی‌کند.</p><h3>معیار موفقیت</h3><p>هر پیوند خطا به فیلد متناظر برسد و پیام مشخص داشته باشد.</p>","starter_code":"<section aria-labelledby=\"errors\"><h2 id=\"errors\">موارد نیازمند اصلاح</h2><ul><li><a href=\"#user-email\">ایمیل را بررسی کن</a></li></ul></section><label for=\"user-email\">ایمیل</label><input id=\"user-email\" type=\"email\">","exercise":"یک فرم پنج فیلدی طراحی کن و خلاصه خطاها را با پیوند به فیلدهای دارای مشکل نمایش بده.","status":"published","sort_order":7,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-08","course_id":"html-advanced","title":"ساخت کنترل سفارشی متصل به فرم","slug":"html-advanced-08","summary":"فرم‌های سفارشی می‌توانند با ElementInternals به چرخه فرم مرورگر وصل شوند؛ این API به JavaScript و custom element نیاز دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>فرم‌های سفارشی می‌توانند با ElementInternals به چرخه فرم مرورگر وصل شوند؛ این API به JavaScript و custom element نیاز دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>class XCode extends HTMLElement{static formAssociated=true;#internals=this.attachInternals();connectedCallback(){this.#internals.setFormValue(this.getAttribute('value')||'');}}customElements.define('x-code',XCode);</code></pre><h3>تمرین</h3><p>نمونه را در فایل JavaScript کنار HTML اجرا کن؛ یک custom element فرم‌پذیر بساز و توضیح بده چرا تعریف آن فقط با HTML ممکن نیست.</p><h3>نکته فنی</h3><p>form-associated custom elements قابلیت پیشرفته مرورگر است و باید پشتیبانی هدف بررسی شود.</p><h3>معیار موفقیت</h3><p>عنصر سفارشی مقدار را به فرم ارسال کند و محدودیت پشتیبانی مستند شود.</p>","starter_code":"class XCode extends HTMLElement{static formAssociated=true;#internals=this.attachInternals();connectedCallback(){this.#internals.setFormValue(this.getAttribute('value')||'');}}customElements.define('x-code',XCode);","exercise":"نمونه را در فایل JavaScript کنار HTML اجرا کن؛ یک custom element فرم‌پذیر بساز و توضیح بده چرا تعریف آن فقط با HTML ممکن نیست.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-09","course_id":"html-advanced","title":"مدیریت چرخه فوکوس در رابط‌های modal","slug":"html-advanced-09","summary":"در پنجره modal باید فوکوس داخل پنجره بماند، با Escape بسته شود و پس از بسته‌شدن به کنترل آغازگر برگردد؛ dialog بومی بسیاری از این رفتارها را فراهم می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در پنجره modal باید فوکوس داخل پنجره بماند، با Escape بسته شود و پس از بسته‌شدن به کنترل آغازگر برگردد؛ dialog بومی بسیاری از این رفتارها را فراهم می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;button id=\"open-dialog\" type=\"button\"&gt;باز کردن&lt;/button&gt;\n&lt;dialog id=\"confirm-dialog\"&gt;\n  &lt;p&gt;ادامه می‌دهی؟&lt;/p&gt;\n  &lt;button id=\"close-dialog\" type=\"button\"&gt;بستن&lt;/button&gt;\n&lt;/dialog&gt;\n&lt;script&gt;\n  const dialog = document.querySelector(\"#confirm-dialog\");\n  const openButton = document.querySelector(\"#open-dialog\");\n  const closeButton = document.querySelector(\"#close-dialog\");\n  openButton.addEventListener(\"click\", () =&gt; dialog.showModal());\n  closeButton.addEventListener(\"click\", () =&gt; dialog.close());\n&lt;/script&gt;</code></pre><h3>تمرین</h3><p>پنجره تأیید بساز؛ بازگشت فوکوس به دکمه آغازگر و رفتار Escape را در مرورگر آزمایش کن.</p><h3>نکته فنی</h3><p>dialog را با display:block شبیه‌سازی نکن؛ حالت modal واقعی تفاوت دارد.</p><h3>معیار موفقیت</h3><p>فوکوس هنگام بازشدن مدیریت شود و پس از بستن به آغازگر بازگردد.</p>","starter_code":"<button id=\"open-dialog\" type=\"button\">باز کردن</button>\n<dialog id=\"confirm-dialog\">\n  <p>ادامه می‌دهی؟</p>\n  <button id=\"close-dialog\" type=\"button\">بستن</button>\n</dialog>\n<script>\n  const dialog = document.querySelector(\"#confirm-dialog\");\n  const openButton = document.querySelector(\"#open-dialog\");\n  const closeButton = document.querySelector(\"#close-dialog\");\n  openButton.addEventListener(\"click\", () => dialog.showModal());\n  closeButton.addEventListener(\"click\", () => dialog.close());\n</script>","exercise":"پنجره تأیید بساز؛ بازگشت فوکوس به دکمه آغازگر و رفتار Escape را در مرورگر آزمایش کن.","status":"published","sort_order":9,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-10","course_id":"html-advanced","title":"الگوی تعاملی popover با دسترس‌پذیری","slug":"html-advanced-10","summary":"Popover برای محتوای موقت مناسب است، اما trigger باید نام و وضعیت روشن داشته باشد و محتوای آن نباید مسیر اصلی کاربر را قطع کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Popover برای محتوای موقت مناسب است، اما trigger باید نام و وضعیت روشن داشته باشد و محتوای آن نباید مسیر اصلی کاربر را قطع کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;button popovertarget=\"help\" aria-label=\"نمایش راهنما\"&gt;راهنما&lt;/button&gt;&lt;div id=\"help\" popover&gt;&lt;p&gt;راهنمای کوتاه این بخش&lt;/p&gt;&lt;/div&gt;</code></pre><h3>تمرین</h3><p>برای سه فیلد حساس راهنمای popover بساز و مشخص کن کدام محتوا باید همیشه روی صفحه بماند.</p><h3>نکته فنی</h3><p>popover جایگزین dialog برای تأییدهای مهم یا جریان چندمرحله‌ای نیست.</p><h3>معیار موفقیت</h3><p>باز و بسته شدن با trigger بومی کار کند و محتوا قابل پیمایش باشد.</p>","starter_code":"<button popovertarget=\"help\" aria-label=\"نمایش راهنما\">راهنما</button><div id=\"help\" popover><p>راهنمای کوتاه این بخش</p></div>","exercise":"برای سه فیلد حساس راهنمای popover بساز و مشخص کن کدام محتوا باید همیشه روی صفحه بماند.","status":"published","sort_order":10,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-11","course_id":"html-advanced","title":"ساخت مؤلفه‌های تکرارپذیر با template","slug":"html-advanced-11","summary":"template محتوای غیرفعال و قابل تکثیر نگه می‌دارد؛ محتوای آن تا زمان clone و درج در سند نمایش داده نمی‌شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>template محتوای غیرفعال و قابل تکثیر نگه می‌دارد؛ محتوای آن تا زمان clone و درج در سند نمایش داده نمی‌شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;template id=\"card-template\"&gt;\n  &lt;article class=\"card\"&gt;\n    &lt;h2&gt;&lt;/h2&gt;\n    &lt;p&gt;&lt;/p&gt;\n  &lt;/article&gt;\n&lt;/template&gt;\n&lt;div id=\"items\"&gt;&lt;/div&gt;\n&lt;script&gt;\n  const template = document.querySelector(\"#card-template\");\n  const itemsContainer = document.querySelector(\"#items\");\n  const card = template.content.cloneNode(true);\n  card.querySelector(\"h2\").textContent = \"درس HTML\";\n  card.querySelector(\"p\").textContent = \"ساختار سند\";\n  itemsContainer.append(card);\n&lt;/script&gt;</code></pre><h3>تمرین</h3><p>قالب کارت درس بساز و با JavaScript دو نسخه با داده‌های متفاوت تولید کن؛ داده را با textContent وارد کن.</p><h3>نکته فنی</h3><p>محتوای کاربر را با innerHTML وارد قالب نکن مگر پاک‌سازی معتبر انجام شده باشد.</p><h3>معیار موفقیت</h3><p>قالب اولیه در صفحه دیده نشود و کارت‌های clone شده درست نمایش یابند.</p>","starter_code":"<template id=\"card-template\">\n  <article class=\"card\">\n    <h2></h2>\n    <p></p>\n  </article>\n</template>\n<div id=\"items\"></div>\n<script>\n  const template = document.querySelector(\"#card-template\");\n  const itemsContainer = document.querySelector(\"#items\");\n  const card = template.content.cloneNode(true);\n  card.querySelector(\"h2\").textContent = \"درس HTML\";\n  card.querySelector(\"p\").textContent = \"ساختار سند\";\n  itemsContainer.append(card);\n</script>","exercise":"قالب کارت درس بساز و با JavaScript دو نسخه با داده‌های متفاوت تولید کن؛ داده را با textContent وارد کن.","status":"published","sort_order":11,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-12","course_id":"html-advanced","title":"ترکیب Web Components با slot","slug":"html-advanced-12","summary":"slot نقطه درج محتوا در Web Component است؛ نام slot باید با ویژگی slot در محتوای فرزند هماهنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>slot نقطه درج محتوا در Web Component است؛ نام slot باید با ویژگی slot در محتوای فرزند هماهنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;template id=\"card-template\"&gt;\n  &lt;article&gt;\n    &lt;h2&gt;&lt;slot name=\"name\"&gt;بدون نام&lt;/slot&gt;&lt;/h2&gt;\n    &lt;slot&gt;&lt;/slot&gt;\n  &lt;/article&gt;\n&lt;/template&gt;\n&lt;user-card&gt;\n  &lt;span slot=\"name\"&gt;سارا&lt;/span&gt;\n  &lt;p&gt;دانش‌آموز HTML&lt;/p&gt;\n&lt;/user-card&gt;\n&lt;script&gt;\n  class UserCard extends HTMLElement {\n    connectedCallback() {\n      if (this.shadowRoot) return;\n      const template = document.querySelector(\"#card-template\");\n      this.attachShadow({mode: \"open\"}).append(template.content.cloneNode(true));\n    }\n  }\n  customElements.define(\"user-card\", UserCard);\n&lt;/script&gt;</code></pre><h3>تمرین</h3><p>ساختار یک کارت با slot نام‌دار و slot پیش‌فرض طراحی کن و حالت محتوای جایگزین را توضیح بده.</p><h3>نکته فنی</h3><p>slot به‌تنهایی کامپوننت را فعال نمی‌کند؛ به custom element و shadow DOM نیاز است.</p><h3>معیار موفقیت</h3><p>محتوای نام‌دار و پیش‌فرض در جای درست قرار بگیرند.</p>","starter_code":"<template id=\"card-template\">\n  <article>\n    <h2><slot name=\"name\">بدون نام</slot></h2>\n    <slot></slot>\n  </article>\n</template>\n<user-card>\n  <span slot=\"name\">سارا</span>\n  <p>دانش‌آموز HTML</p>\n</user-card>\n<script>\n  class UserCard extends HTMLElement {\n    connectedCallback() {\n      if (this.shadowRoot) return;\n      const template = document.querySelector(\"#card-template\");\n      this.attachShadow({mode: \"open\"}).append(template.content.cloneNode(true));\n    }\n  }\n  customElements.define(\"user-card\", UserCard);\n</script>","exercise":"ساختار یک کارت با slot نام‌دار و slot پیش‌فرض طراحی کن و حالت محتوای جایگزین را توضیح بده.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-13","course_id":"html-advanced","title":"تعریف قرارداد HTML برای custom elements","slug":"html-advanced-13","summary":"custom element باید نام دارای خط تیره داشته باشد و رفتار آن با چرخه عمر اتصال و جداشدن هماهنگ شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>custom element باید نام دارای خط تیره داشته باشد و رفتار آن با چرخه عمر اتصال و جداشدن هماهنگ شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>class LessonBadge extends HTMLElement{connectedCallback(){this.textContent=this.getAttribute('level')||'درس';}}customElements.define('lesson-badge',LessonBadge);</code></pre><h3>تمرین</h3><p>یک عنصر lesson-badge تعریف کن که ویژگی level را بخواند؛ رفتار آن را هنگام حذف و افزودن دوباره بررسی کن.</p><h3>نکته فنی</h3><p>نام‌های رزروشده یا بدون خط تیره برای custom element معتبر نیستند.</p><h3>معیار موفقیت</h3><p>عنصر بدون خطای ثبت تعریف شود و ویژگی level را نمایش دهد.</p>","starter_code":"class LessonBadge extends HTMLElement{connectedCallback(){this.textContent=this.getAttribute('level')||'درس';}}customElements.define('lesson-badge',LessonBadge);","exercise":"یک عنصر lesson-badge تعریف کن که ویژگی level را بخواند؛ رفتار آن را هنگام حذف و افزودن دوباره بررسی کن.","status":"published","sort_order":13,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-14","course_id":"html-advanced","title":"ساختاردهی داده‌های ساخت‌یافته با JSON-LD","slug":"html-advanced-14","summary":"JSON-LD داده ساخت‌یافته را از محتوای نمایشی جدا می‌کند؛ داده باید دقیقاً با محتوای قابل مشاهده صفحه هماهنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>JSON-LD داده ساخت‌یافته را از محتوای نمایشی جدا می‌کند؛ داده باید دقیقاً با محتوای قابل مشاهده صفحه هماهنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;script type=\"application/ld+json\"&gt;{\"@context\":\"https://schema.org\",\"@type\":\"Course\",\"name\":\"آموزش HTML پیشرفته\",\"description\":\"ساخت صفحات استاندارد\"}&lt;/script&gt;</code></pre><h3>تمرین</h3><p>برای صفحه یک دوره واقعی JSON-LD از نوع Course بساز و فقط اطلاعاتی را وارد کن که روی صفحه هم وجود دارد.</p><h3>نکته فنی</h3><p>داده ساخت‌یافته تضمین‌کننده نمایش نتیجه ویژه در جست‌وجو نیست.</p><h3>معیار موفقیت</h3><p>JSON معتبر باشد و ادعای نادرست یا محتوای پنهان نداشته باشد.</p>","starter_code":"<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"Course\",\"name\":\"آموزش HTML پیشرفته\",\"description\":\"ساخت صفحات استاندارد\"}</script>","exercise":"برای صفحه یک دوره واقعی JSON-LD از نوع Course بساز و فقط اطلاعاتی را وارد کن که روی صفحه هم وجود دارد.","status":"published","sort_order":14,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-15","course_id":"html-advanced","title":"مدیریت canonical و نسخه‌های تکراری صفحه","slug":"html-advanced-15","summary":"canonical نسخه ترجیحی یک محتوای تکراری را معرفی می‌کند؛ نشانی باید مطلق و به نسخه واقعی و قابل دسترس اشاره کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>canonical نسخه ترجیحی یک محتوای تکراری را معرفی می‌کند؛ نشانی باید مطلق و به نسخه واقعی و قابل دسترس اشاره کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"canonical\" href=\"https://example.com/academy/html-advanced\"&gt;</code></pre><h3>تمرین</h3><p>برای صفحه‌ای که با پارامترهای مرتب‌سازی باز می‌شود canonical تعریف کن و توضیح بده چه زمانی نباید به صفحه دیگری اشاره کند.</p><h3>نکته فنی</h3><p>canonical ابزار حل همه مشکلات duplicate content نیست و باید با redirect و نقشه سایت سازگار باشد.</p><h3>معیار موفقیت</h3><p>فقط یک canonical معتبر و همسو با URL اصلی وجود داشته باشد.</p>","starter_code":"<link rel=\"canonical\" href=\"https://example.com/academy/html-advanced\">","exercise":"برای صفحه‌ای که با پارامترهای مرتب‌سازی باز می‌شود canonical تعریف کن و توضیح بده چه زمانی نباید به صفحه دیگری اشاره کند.","status":"published","sort_order":15,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-16","course_id":"html-advanced","title":"چندزبانه‌سازی فنی با hreflang","slug":"html-advanced-16","summary":"hreflang نسخه‌های زبانی هم‌ارز را به موتور جست‌وجو معرفی می‌کند؛ پیوندها باید متقابل و کد زبان/منطقه معتبر باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>hreflang نسخه‌های زبانی هم‌ارز را به موتور جست‌وجو معرفی می‌کند؛ پیوندها باید متقابل و کد زبان/منطقه معتبر باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"alternate\" hreflang=\"fa\" href=\"https://example.com/fa/course\"&gt;&lt;link rel=\"alternate\" hreflang=\"en\" href=\"https://example.com/en/course\"&gt;&lt;link rel=\"alternate\" hreflang=\"x-default\" href=\"https://example.com/course\"&gt;</code></pre><h3>تمرین</h3><p>برای نسخه فارسی و انگلیسی یک مقاله، hreflang متقابل و x-default بساز و خطای URL نامتقارن را پیدا کن.</p><h3>نکته فنی</h3><p>hreflang زبان صفحه را عوض نمی‌کند؛ lang سند نیز باید درست باشد.</p><h3>معیار موفقیت</h3><p>هر نسخه به نسخه‌های هم‌ارز اشاره کند و URLها واقعی باشند.</p>","starter_code":"<link rel=\"alternate\" hreflang=\"fa\" href=\"https://example.com/fa/course\"><link rel=\"alternate\" hreflang=\"en\" href=\"https://example.com/en/course\"><link rel=\"alternate\" hreflang=\"x-default\" href=\"https://example.com/course\">","exercise":"برای نسخه فارسی و انگلیسی یک مقاله، hreflang متقابل و x-default بساز و خطای URL نامتقارن را پیدا کن.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-17","course_id":"html-advanced","title":"بهینه‌سازی اشتراک‌گذاری با Open Graph","slug":"html-advanced-17","summary":"Open Graph عنوان، توضیح و تصویر اشتراک‌گذاری را کنترل می‌کند؛ تصویر باید قابل دسترس و متناسب با محتوای همان صفحه باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Open Graph عنوان، توضیح و تصویر اشتراک‌گذاری را کنترل می‌کند؛ تصویر باید قابل دسترس و متناسب با محتوای همان صفحه باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta property=\"og:type\" content=\"article\"&gt;&lt;meta property=\"og:title\" content=\"HTML پیشرفته\"&gt;&lt;meta property=\"og:description\" content=\"ساخت صفحات وب استاندارد\"&gt;&lt;meta property=\"og:image\" content=\"https://example.com/images/html.jpg\"&gt;&lt;meta property=\"og:url\" content=\"https://example.com/html\"&gt;</code></pre><h3>تمرین</h3><p>برای یک درس، مجموعه Open Graph کامل بنویس و تفاوت آن را با meta description توضیح بده.</p><h3>نکته فنی</h3><p>اطلاعات Open Graph جایگزین title و description عادی نیست.</p><h3>معیار موفقیت</h3><p>عنوان، URL و تصویر با محتوای صفحه همخوان باشند.</p>","starter_code":"<meta property=\"og:type\" content=\"article\"><meta property=\"og:title\" content=\"HTML پیشرفته\"><meta property=\"og:description\" content=\"ساخت صفحات وب استاندارد\"><meta property=\"og:image\" content=\"https://example.com/images/html.jpg\"><meta property=\"og:url\" content=\"https://example.com/html\">","exercise":"برای یک درس، مجموعه Open Graph کامل بنویس و تفاوت آن را با meta description توضیح بده.","status":"published","sort_order":17,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-18","course_id":"html-advanced","title":"کنترل نمایه‌سازی با robots metadata","slug":"html-advanced-18","summary":"robots meta دستورهای نمایه‌سازی را برای خزنده‌ها اعلام می‌کند؛ این دستور دسترسی امنیتی ایجاد نمی‌کند و محرمانگی محتوا را تضمین نمی‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>robots meta دستورهای نمایه‌سازی را برای خزنده‌ها اعلام می‌کند؛ این دستور دسترسی امنیتی ایجاد نمی‌کند و محرمانگی محتوا را تضمین نمی‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta name=\"robots\" content=\"noindex,follow\"&gt;</code></pre><h3>تمرین</h3><p>برای صفحه ورود خصوصی دستور مناسب بنویس و توضیح بده چرا اطلاعات حساس نباید صرفاً با noindex محافظت شوند.</p><h3>نکته فنی</h3><p>برای محتوای محرمانه احراز هویت و کنترل دسترسی لازم است؛ robots.txt نیز ابزار امنیتی نیست.</p><h3>معیار موفقیت</h3><p>محدودیت نمایه‌سازی درست باشد و هیچ داده محرمانه‌ای در HTML عمومی قرار نگیرد.</p>","starter_code":"<meta name=\"robots\" content=\"noindex,follow\">","exercise":"برای صفحه ورود خصوصی دستور مناسب بنویس و توضیح بده چرا اطلاعات حساس نباید صرفاً با noindex محافظت شوند.","status":"published","sort_order":18,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-19","course_id":"html-advanced","title":"امن‌سازی پیوندهای خروجی و پنجره جدید","slug":"html-advanced-19","summary":"لینک‌های بازشونده در تب جدید باید رفتارشان برای کاربر روشن باشد؛ rel مناسب از دسترسی صفحه مقصد به window.opener جلوگیری می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>لینک‌های بازشونده در تب جدید باید رفتارشان برای کاربر روشن باشد؛ rel مناسب از دسترسی صفحه مقصد به window.opener جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\"&gt;منبع خارجی (در زبانه جدید)&lt;/a&gt;</code></pre><h3>تمرین</h3><p>سه لینک خارجی بساز؛ یکی در همان تب و دو مورد در تب جدید با توضیح قابل فهم برای کاربر.</p><h3>نکته فنی</h3><p>target blank بدون توضیح ممکن است کاربر را سردرگم کند؛ noopener را صریح بنویس.</p><h3>معیار موفقیت</h3><p>رفتار لینک اعلام شده و opener در دسترس صفحه مقصد نباشد.</p>","starter_code":"<a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\">منبع خارجی (در زبانه جدید)</a>","exercise":"سه لینک خارجی بساز؛ یکی در همان تب و دو مورد در تب جدید با توضیح قابل فهم برای کاربر.","status":"published","sort_order":19,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-20","course_id":"html-advanced","title":"سیاست امنیت محتوا و محدودیت‌های meta CSP","slug":"html-advanced-20","summary":"meta CSP فقط زیرمجموعه‌ای از سیاست امنیت محتوا را اعمال می‌کند و نسبت به هدر HTTP محدودیت دارد؛ سیاست سخت‌گیرانه باید در سرور تنظیم شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>meta CSP فقط زیرمجموعه‌ای از سیاست امنیت محتوا را اعمال می‌کند و نسبت به هدر HTTP محدودیت دارد؛ سیاست سخت‌گیرانه باید در سرور تنظیم شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'\"&gt;</code></pre><h3>تمرین</h3><p>یک سیاست آزمایشی برای صفحه ایستا بنویس و مشخص کن چرا هدر HTTP برای سیاست نهایی ترجیح دارد.</p><h3>نکته فنی</h3><p>CSP را بدون آزمون منابع لازم فعال نکن؛ ممکن است اسکریپت‌ها و سبک‌های معتبر را مسدود کند.</p><h3>معیار موفقیت</h3><p>منابع مجاز محدود باشند و محدودیت meta CSP به‌درستی توضیح داده شود.</p>","starter_code":"<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'\">","exercise":"یک سیاست آزمایشی برای صفحه ایستا بنویس و مشخص کن چرا هدر HTTP برای سیاست نهایی ترجیح دارد.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-21","course_id":"html-advanced","title":"طراحی بارگذاری واکنشی رسانه‌های سنگین","slug":"html-advanced-21","summary":"رسانه واکنشی باید برای اندازه‌های مختلف فایل مناسب انتخاب کند؛ picture برای art direction و source type کاربرد دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>رسانه واکنشی باید برای اندازه‌های مختلف فایل مناسب انتخاب کند؛ picture برای art direction و source type کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;picture&gt;&lt;source media=\"(max-width: 600px)\" srcset=\"small.webp\"&gt;&lt;source type=\"image/avif\" srcset=\"hero.avif\"&gt;&lt;img src=\"hero.jpg\" alt=\"نمای داشبورد آموزشی\" width=\"1200\" height=\"600\"&gt;&lt;/picture&gt;</code></pre><h3>تمرین</h3><p>برای تصویر قهرمان نسخه موبایل و دسکتاپ تعریف کن و fallback تصویری معتبر قرار بده.</p><h3>نکته فنی</h3><p>ابعاد را مشخص کن تا جابه‌جایی چیدمان کاهش یابد؛ alt را با محتوای واقعی هماهنگ کن.</p><h3>معیار موفقیت</h3><p>در مرورگرهای فاقد فرمت جدید، fallback نمایش داده شود.</p>","starter_code":"<picture><source media=\"(max-width: 600px)\" srcset=\"small.webp\"><source type=\"image/avif\" srcset=\"hero.avif\"><img src=\"hero.jpg\" alt=\"نمای داشبورد آموزشی\" width=\"1200\" height=\"600\"></picture>","exercise":"برای تصویر قهرمان نسخه موبایل و دسکتاپ تعریف کن و fallback تصویری معتبر قرار بده.","status":"published","sort_order":21,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-22","course_id":"html-advanced","title":"راهبرد preload و prefetch برای مسیرهای واقعی","slug":"html-advanced-22","summary":"preload برای منبعی است که همین صفحه قطعاً به‌زودی نیاز دارد؛ prefetch برای ناوبری احتمالی آینده است و مصرف شبکه دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>preload برای منبعی است که همین صفحه قطعاً به‌زودی نیاز دارد؛ prefetch برای ناوبری احتمالی آینده است و مصرف شبکه دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"preload\" href=\"/fonts/academy.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;&lt;link rel=\"prefetch\" href=\"/next-lesson.html\"&gt;</code></pre><h3>تمرین</h3><p>برای فونت ضروری preload و برای صفحه بعدی prefetch تعریف کن؛ هزینه بارگذاری بی‌مورد را بررسی کن.</p><h3>نکته فنی</h3><p>preload زیاد رقابت منابع را بالا می‌برد و می‌تواند عملکرد را بدتر کند.</p><h3>معیار موفقیت</h3><p>فقط منابع حیاتی preload شوند و نوع و crossorigin درست باشد.</p>","starter_code":"<link rel=\"preload\" href=\"/fonts/academy.woff2\" as=\"font\" type=\"font/woff2\" crossorigin><link rel=\"prefetch\" href=\"/next-lesson.html\">","exercise":"برای فونت ضروری preload و برای صفحه بعدی prefetch تعریف کن؛ هزینه بارگذاری بی‌مورد را بررسی کن.","status":"published","sort_order":22,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-23","course_id":"html-advanced","title":"مدیریت crossorigin در منابع خارجی","slug":"html-advanced-23","summary":"منابع cross-origin ممکن است به CORS نیاز داشته باشند؛ مقدار crossorigin باید با نوع منبع و پاسخ سرور سازگار باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>منابع cross-origin ممکن است به CORS نیاز داشته باشند؛ مقدار crossorigin باید با نوع منبع و پاسخ سرور سازگار باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"preload\" href=\"https://cdn.example.com/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;&lt;img src=\"https://cdn.example.com/chart.png\" alt=\"نمودار فروش\" crossorigin=\"anonymous\"&gt;</code></pre><h3>تمرین</h3><p>یک فونت و تصویر CDN تعریف کن؛ بررسی کن سرور چه هدر CORS لازم دارد و چه زمانی درخواست مسدود می‌شود.</p><h3>نکته فنی</h3><p>افزودن crossorigin به‌تنهایی مجوز سرور ایجاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>درخواست با هدرهای مجاز پاسخ بگیرد و رفتار خطا توضیح داده شود.</p>","starter_code":"<link rel=\"preload\" href=\"https://cdn.example.com/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin><img src=\"https://cdn.example.com/chart.png\" alt=\"نمودار فروش\" crossorigin=\"anonymous\">","exercise":"یک فونت و تصویر CDN تعریف کن؛ بررسی کن سرور چه هدر CORS لازم دارد و چه زمانی درخواست مسدود می‌شود.","status":"published","sort_order":23,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-24","course_id":"html-advanced","title":"پخش ویدیوی آموزشی با track و caption","slug":"html-advanced-24","summary":"عنصر track زیرنویس و توضیح صوتی را به ویدیو متصل می‌کند؛ kind و srclang و label باید با فایل هماهنگ باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>عنصر track زیرنویس و توضیح صوتی را به ویدیو متصل می‌کند؛ kind و srclang و label باید با فایل هماهنگ باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;video controls preload=\"metadata\" poster=\"cover.jpg\"&gt;&lt;source src=\"lesson.mp4\" type=\"video/mp4\"&gt;&lt;track kind=\"captions\" src=\"fa.vtt\" srclang=\"fa\" label=\"فارسی\" default&gt;&lt;/video&gt;</code></pre><h3>تمرین</h3><p>برای ویدیوی آموزشی زیرنویس فارسی و انگلیسی اضافه کن و فایل WebVTT معتبر بساز.</p><h3>نکته فنی</h3><p>زیرنویس باید گفتار و صداهای مهم را پوشش دهد؛ صرف متن خودکار بررسی‌نشده کافی نیست.</p><h3>معیار موفقیت</h3><p>کاربر بتواند زیرنویس را انتخاب کند و زمان‌بندی VTT معتبر باشد.</p>","starter_code":"<video controls preload=\"metadata\" poster=\"cover.jpg\"><source src=\"lesson.mp4\" type=\"video/mp4\"><track kind=\"captions\" src=\"fa.vtt\" srclang=\"fa\" label=\"فارسی\" default></video>","exercise":"برای ویدیوی آموزشی زیرنویس فارسی و انگلیسی اضافه کن و فایل WebVTT معتبر بساز.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-25","course_id":"html-advanced","title":"دسترسی‌پذیری رسانه با توضیح و transcript","slug":"html-advanced-25","summary":"رسانه آموزشی باید برای افراد ناشنوا، کم‌شنوا و کسانی که صدا ندارند جایگزین متنی فراهم کند؛ transcript محتوای گفتار و اطلاعات دیداری ضروری را پوشش می‌دهد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>رسانه آموزشی باید برای افراد ناشنوا، کم‌شنوا و کسانی که صدا ندارند جایگزین متنی فراهم کند؛ transcript محتوای گفتار و اطلاعات دیداری ضروری را پوشش می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;figure&gt;&lt;video controls&gt;&lt;source src=\"lesson.mp4\" type=\"video/mp4\"&gt;&lt;/video&gt;&lt;figcaption&gt;آموزش ساخت فرم&lt;/figcaption&gt;&lt;/figure&gt;&lt;a href=\"lesson-transcript.html\"&gt;خواندن متن کامل ویدیو&lt;/a&gt;</code></pre><h3>تمرین</h3><p>برای یک ویدیوی کوتاه caption و transcript جداگانه تهیه کن و تفاوت کاربرد آن‌ها را شرح بده.</p><h3>نکته فنی</h3><p>figcaption عنوان رسانه است و جایگزین زیرنویس یا transcript نیست.</p><h3>معیار موفقیت</h3><p>محتوای صوتی و دیداری مهم بدون نیاز به پخش ویدیو قابل دریافت باشد.</p>","starter_code":"<figure><video controls><source src=\"lesson.mp4\" type=\"video/mp4\"></video><figcaption>آموزش ساخت فرم</figcaption></figure><a href=\"lesson-transcript.html\">خواندن متن کامل ویدیو</a>","exercise":"برای یک ویدیوی کوتاه caption و transcript جداگانه تهیه کن و تفاوت کاربرد آن‌ها را شرح بده.","status":"published","sort_order":25,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-26","course_id":"html-advanced","title":"طراحی تجربه چاپ با ساختار معنایی","slug":"html-advanced-26","summary":"ساختار چاپ باید ترتیب خواندن و اطلاعات ضروری را حفظ کند؛ کنترل‌های تعاملی غیرضروری نباید در نسخه چاپی غالب باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ساختار چاپ باید ترتیب خواندن و اطلاعات ضروری را حفظ کند؛ کنترل‌های تعاملی غیرضروری نباید در نسخه چاپی غالب باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;article&gt;&lt;h1&gt;گزارش دوره&lt;/h1&gt;&lt;p&gt;خلاصه پیشرفت دانش‌آموز&lt;/p&gt;&lt;a href=\"/details\"&gt;جزئیات آنلاین&lt;/a&gt;&lt;/article&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک گزارش قابل چاپ طراحی کن؛ مشخص کن کدام داده‌ها باید در چاپ باقی بمانند و کدام کنترل‌ها فقط برای صفحه‌اند.</p><h3>نکته فنی</h3><p>قواعد چاپ عمدتاً در CSS @media print هستند؛ HTML باید معنای محتوا را درست ارائه کند.</p><h3>معیار موفقیت</h3><p>بدون کنترل‌های تعاملی نیز گزارش چاپی قابل فهم باشد.</p>","starter_code":"<main><article><h1>گزارش دوره</h1><p>خلاصه پیشرفت دانش‌آموز</p><a href=\"/details\">جزئیات آنلاین</a></article></main>","exercise":"یک گزارش قابل چاپ طراحی کن؛ مشخص کن کدام داده‌ها باید در چاپ باقی بمانند و کدام کنترل‌ها فقط برای صفحه‌اند.","status":"published","sort_order":26,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-27","course_id":"html-advanced","title":"بهبود سازگاری با زبان و نویسه‌های ترکیبی","slug":"html-advanced-27","summary":"زبان‌های ترکیبی، نام‌ها و متن‌های با جهت متفاوت نیازمند نشانه‌گذاری دقیق‌اند؛ bdi متن با جهت ناشناخته را ایزوله می‌کند و bdo جهت را به‌زور تغییر می‌دهد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>زبان‌های ترکیبی، نام‌ها و متن‌های با جهت متفاوت نیازمند نشانه‌گذاری دقیق‌اند؛ bdi متن با جهت ناشناخته را ایزوله می‌کند و bdo جهت را به‌زور تغییر می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;p&gt;شناسه کاربر: &lt;bdi&gt;user_علی_27&lt;/bdi&gt;&lt;/p&gt;&lt;p&gt;کد: &lt;bdi&gt;AB-1209&lt;/bdi&gt;&lt;/p&gt;</code></pre><h3>تمرین</h3><p>در یک فهرست فارسی، نام کاربری لاتین و کدهای ترکیبی قرار بده و از bdi در جای درست استفاده کن.</p><h3>نکته فنی</h3><p>bdo را برای اصلاح عمومی متن به کار نبر؛ جهت واقعی محتوا را حفظ کن.</p><h3>معیار موفقیت</h3><p>ترکیب فارسی و لاتین بدون به‌هم‌ریختگی نمایش داده شود.</p>","starter_code":"<p>شناسه کاربر: <bdi>user_علی_27</bdi></p><p>کد: <bdi>AB-1209</bdi></p>","exercise":"در یک فهرست فارسی، نام کاربری لاتین و کدهای ترکیبی قرار بده و از bdi در جای درست استفاده کن.","status":"published","sort_order":27,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-28","course_id":"html-advanced","title":"ساختاردهی محتوای زمان‌مند و داده‌های ماشین‌خوان","slug":"html-advanced-28","summary":"داده زمان باید هم برای انسان و هم ماشین خوانا باشد؛ time با datetime مقدار استاندارد قابل پردازش ارائه می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>داده زمان باید هم برای انسان و هم ماشین خوانا باشد؛ time با datetime مقدار استاندارد قابل پردازش ارائه می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;time datetime=\"2026-11-07T18:30:00+04:30\"&gt;۷ نوامبر ۲۰۲۶، ساعت ۱۸:۳۰&lt;/time&gt;</code></pre><h3>تمرین</h3><p>برای تاریخ انتشار، مهلت تحویل و مدت یک رویداد از time با datetime معتبر استفاده کن.</p><h3>نکته فنی</h3><p>متن نمایشی و مقدار machine-readable باید به یک زمان اشاره کنند.</p><h3>معیار موفقیت</h3><p>مقدار datetime معتبر و با متن قابل مشاهده سازگار باشد.</p>","starter_code":"<time datetime=\"2026-11-07T18:30:00+04:30\">۷ نوامبر ۲۰۲۶، ساعت ۱۸:۳۰</time>","exercise":"برای تاریخ انتشار، مهلت تحویل و مدت یک رویداد از time با datetime معتبر استفاده کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-29","course_id":"html-advanced","title":"ارتقای تدریجی قابلیت‌ها بدون وابستگی اجباری","slug":"html-advanced-29","summary":"Progressive enhancement یعنی محتوای اصلی بدون قابلیت‌های اضافی هم در دسترس باشد؛ قابلیت‌های پیشرفته پس از آن افزوده می‌شوند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Progressive enhancement یعنی محتوای اصلی بدون قابلیت‌های اضافی هم در دسترس باشد؛ قابلیت‌های پیشرفته پس از آن افزوده می‌شوند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;form action=\"/search\" method=\"get\"&gt;&lt;label for=\"q\"&gt;جست‌وجو&lt;/label&gt;&lt;input id=\"q\" name=\"q\"&gt;&lt;button&gt;جست‌وجو&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>یک جست‌وجوی ساده بساز که بدون JavaScript نیز با GET کار کند؛ سپس قابلیت پیشنهاد زنده را به‌عنوان افزونه طراحی کن.</p><h3>نکته فنی</h3><p>از ابتدا عملکرد اصلی را به JavaScript وابسته نکن.</p><h3>معیار موفقیت</h3><p>عملکرد پایه با خاموش بودن JavaScript قابل استفاده باشد.</p>","starter_code":"<form action=\"/search\" method=\"get\"><label for=\"q\">جست‌وجو</label><input id=\"q\" name=\"q\"><button>جست‌وجو</button></form>","exercise":"یک جست‌وجوی ساده بساز که بدون JavaScript نیز با GET کار کند؛ سپس قابلیت پیشنهاد زنده را به‌عنوان افزونه طراحی کن.","status":"published","sort_order":29,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-30","course_id":"html-advanced","title":"طراحی HTML مقاوم در برابر محتوای ناقص","slug":"html-advanced-30","summary":"HTML مقاوم باید در برابر داده ناقص همچنان قابل فهم بماند؛ fallback و محتوای جایگزین بخشی از طراحی است. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>HTML مقاوم باید در برابر داده ناقص همچنان قابل فهم بماند؛ fallback و محتوای جایگزین بخشی از طراحی است.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;picture&gt;&lt;source srcset=\"diagram.webp\" type=\"image/webp\"&gt;&lt;img src=\"diagram.png\" alt=\"نمودار مراحل ثبت‌نام\"&gt;&lt;/picture&gt;&lt;noscript&gt;&lt;p&gt;برای امکانات تعاملی، JavaScript را فعال کن؛ محتوای اصلی در دسترس است.&lt;/p&gt;&lt;/noscript&gt;</code></pre><h3>تمرین</h3><p>یک صفحه آموزشی طراحی کن که تصویر فرمت جدید یا اسکریپت آن بارگیری نشد، پیام و محتوای اصلی همچنان قابل استفاده باشد.</p><h3>نکته فنی</h3><p>noscript جایگزین طراحی کامل بدون JavaScript نیست؛ فقط پیام/محتوای جایگزین ارائه می‌کند.</p><h3>معیار موفقیت</h3><p>شکست یک منبع، کل محتوای آموزشی را غیرقابل استفاده نکند.</p>","starter_code":"<picture><source srcset=\"diagram.webp\" type=\"image/webp\"><img src=\"diagram.png\" alt=\"نمودار مراحل ثبت‌نام\"></picture><noscript><p>برای امکانات تعاملی، JavaScript را فعال کن؛ محتوای اصلی در دسترس است.</p></noscript>","exercise":"یک صفحه آموزشی طراحی کن که تصویر فرمت جدید یا اسکریپت آن بارگیری نشد، پیام و محتوای اصلی همچنان قابل استفاده باشد.","status":"published","sort_order":30,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-31","course_id":"html-advanced","title":"ارزیابی ساختار با اعتبارسنجی و درخت دسترس‌پذیری","slug":"html-advanced-31","summary":"اعتبارسنجی HTML خطاهای ساختاری را پیدا می‌کند؛ درخت دسترس‌پذیری نشان می‌دهد فناوری کمکی چه نام و نقشی دریافت می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی HTML خطاهای ساختاری را پیدا می‌کند؛ درخت دسترس‌پذیری نشان می‌دهد فناوری کمکی چه نام و نقشی دریافت می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;ثبت‌نام&lt;/h1&gt;&lt;form&gt;&lt;label for=\"name\"&gt;نام&lt;/label&gt;&lt;input id=\"name\" name=\"name\" required&gt;&lt;button&gt;ارسال&lt;/button&gt;&lt;/form&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک صفحه را با validator بررسی کن، سپس در ابزار توسعه‌دهنده درخت دسترس‌پذیری را باز کن و سه ایراد را مستند کن.</p><h3>نکته فنی</h3><p>validator به‌تنهایی کیفیت دسترس‌پذیری یا تجربه کاربری را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>خطاهای معتبر رفع شوند و نقش و نام کنترل‌ها در accessibility tree دیده شود.</p>","starter_code":"<main><h1>ثبت‌نام</h1><form><label for=\"name\">نام</label><input id=\"name\" name=\"name\" required><button>ارسال</button></form></main>","exercise":"یک صفحه را با validator بررسی کن، سپس در ابزار توسعه‌دهنده درخت دسترس‌پذیری را باز کن و سه ایراد را مستند کن.","status":"published","sort_order":31,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-32","course_id":"html-advanced","title":"ممیزی صفحه برای خزنده و کاربر صفحه‌خوان","slug":"html-advanced-32","summary":"ممیزی حرفه‌ای باید ترتیب headingها، landmarkها، نام کنترل‌ها، متن جایگزین و پیوندهای تکراری را بررسی کند؛ ارزیابی خودکار کافی نیست. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ممیزی حرفه‌ای باید ترتیب headingها، landmarkها، نام کنترل‌ها، متن جایگزین و پیوندهای تکراری را بررسی کند؛ ارزیابی خودکار کافی نیست.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;دوره‌ها&lt;/h1&gt;&lt;section aria-labelledby=\"popular\"&gt;&lt;h2 id=\"popular\"&gt;محبوب&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;a href=\"/html\"&gt;دوره HTML&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>برای صفحه‌ای با چند بخش، یک چک‌لیست ممیزی بساز و با صفحه‌خوان یا پیمایش صفحه‌کلید موارد را دستی بررسی کن.</p><h3>نکته فنی</h3><p>امتیاز ابزار خودکار معادل دسترس‌پذیری کامل نیست.</p><h3>معیار موفقیت</h3><p>حداقل یک آزمون خودکار و یک آزمون دستی مستند شود.</p>","starter_code":"<main><h1>دوره‌ها</h1><section aria-labelledby=\"popular\"><h2 id=\"popular\">محبوب</h2><ul><li><a href=\"/html\">دوره HTML</a></li></ul></section></main>","exercise":"برای صفحه‌ای با چند بخش، یک چک‌لیست ممیزی بساز و با صفحه‌خوان یا پیمایش صفحه‌کلید موارد را دستی بررسی کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-33","course_id":"html-advanced","title":"طراحی صفحه خطا و وضعیت‌های خالی","slug":"html-advanced-33","summary":"صفحه وضعیت خالی و خطا باید دلیل و مسیر اقدام بعدی را روشن کند؛ پیام نباید فقط یک کد یا رنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>صفحه وضعیت خالی و خطا باید دلیل و مسیر اقدام بعدی را روشن کند؛ پیام نباید فقط یک کد یا رنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;دوره‌ای پیدا نشد&lt;/h1&gt;&lt;p&gt;این دوره هنوز منتشر نشده است.&lt;/p&gt;&lt;a href=\"/courses\"&gt;مشاهده همه دوره‌ها&lt;/a&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>برای حالت خالی، خطای ۴۰۴ و خطای بارگیری سه صفحه مجزا بساز و برای هرکدام مسیر بازیابی تعریف کن.</p><h3>نکته فنی</h3><p>خطای سرور را به‌عنوان نبودن محتوا نمایش نده؛ وضعیت‌ها معنای متفاوت دارند.</p><h3>معیار موفقیت</h3><p>کاربر دلیل وضعیت و اقدام بعدی را بفهمد.</p>","starter_code":"<main><h1>دوره‌ای پیدا نشد</h1><p>این دوره هنوز منتشر نشده است.</p><a href=\"/courses\">مشاهده همه دوره‌ها</a></main>","exercise":"برای حالت خالی، خطای ۴۰۴ و خطای بارگیری سه صفحه مجزا بساز و برای هرکدام مسیر بازیابی تعریف کن.","status":"published","sort_order":33,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-34","course_id":"html-advanced","title":"ساخت الگوی ناوبری عمیق برای سایت چندصفحه‌ای","slug":"html-advanced-34","summary":"ناوبری عمیق در سایت چندصفحه‌ای باید مسیر فعلی، بخش‌های اصلی و پیوندهای بازگشت را مشخص کند؛ ساختار باید در همه صفحات سازگار بماند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ناوبری عمیق در سایت چندصفحه‌ای باید مسیر فعلی، بخش‌های اصلی و پیوندهای بازگشت را مشخص کند؛ ساختار باید در همه صفحات سازگار بماند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;nav aria-label=\"مسیر صفحه\"&gt;&lt;ol&gt;&lt;li&gt;&lt;a href=\"/\"&gt;خانه&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a href=\"/academy\"&gt;آکادمی&lt;/a&gt;&lt;/li&gt;&lt;li aria-current=\"page\"&gt;HTML پیشرفته&lt;/li&gt;&lt;/ol&gt;&lt;/nav&gt;</code></pre><h3>تمرین</h3><p>برای سه صفحه تو‌در‌تو breadcrumb بساز و aria-current را فقط روی صفحه جاری قرار بده.</p><h3>نکته فنی</h3><p>breadcrumb جایگزین منوی اصلی نیست و نباید مسیر ساختگی نشان دهد.</p><h3>معیار موفقیت</h3><p>مسیر واقعی صفحه و وضعیت جاری برای فناوری کمکی مشخص باشد.</p>","starter_code":"<nav aria-label=\"مسیر صفحه\"><ol><li><a href=\"/\">خانه</a></li><li><a href=\"/academy\">آکادمی</a></li><li aria-current=\"page\">HTML پیشرفته</li></ol></nav>","exercise":"برای سه صفحه تو‌در‌تو breadcrumb بساز و aria-current را فقط روی صفحه جاری قرار بده.","status":"published","sort_order":34,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-35","course_id":"html-advanced","title":"پروژه نهایی: وب‌سایت مستندات چندزبانه","slug":"html-advanced-35","summary":"پروژه نهایی باید چند صفحه واقعی، ناوبری یکپارچه، metadata یکتا، ساختار معنایی، رسانه دسترس‌پذیر و fallback داشته باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>پروژه نهایی باید چند صفحه واقعی، ناوبری یکپارچه، metadata یکتا، ساختار معنایی، رسانه دسترس‌پذیر و fallback داشته باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;header&gt;&lt;a href=\"/\"&gt;آکادمی NEXORA FORGE&lt;/a&gt;&lt;nav aria-label=\"اصلی\"&gt;&lt;a href=\"/courses\"&gt;دوره‌ها&lt;/a&gt;&lt;/nav&gt;&lt;/header&gt;&lt;main&gt;&lt;article&gt;&lt;h1&gt;HTML پیشرفته&lt;/h1&gt;&lt;p&gt;مسیر یادگیری استاندارد وب&lt;/p&gt;&lt;/article&gt;&lt;/main&gt;&lt;footer&gt;© NEXORA FORGE&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>یک وب‌سایت مستندات سه‌صفحه‌ای بساز: خانه، فهرست دوره‌ها و صفحه درس. برای هر صفحه عنوان، توضیح، canonical، breadcrumb و ساختار معنایی مستقل قرار بده.</p><h3>نکته فنی</h3><p>کپی‌کردن یک metadata ثابت برای همه صفحات خطاست؛ هر URL باید اطلاعات متناسب خودش را داشته باشد.</p><h3>معیار موفقیت</h3><p>هر سه صفحه با پیوندهای واقعی، عنوان یکتا، دسترس‌پذیری پایه و HTML معتبر کار کنند.</p>","starter_code":"<header><a href=\"/\">آکادمی NEXORA FORGE</a><nav aria-label=\"اصلی\"><a href=\"/courses\">دوره‌ها</a></nav></header><main><article><h1>HTML پیشرفته</h1><p>مسیر یادگیری استاندارد وب</p></article></main><footer>© NEXORA FORGE</footer>","exercise":"یک وب‌سایت مستندات سه‌صفحه‌ای بساز: خانه، فهرست دوره‌ها و صفحه درس. برای هر صفحه عنوان، توضیح، canonical، breadcrumb و ساختار معنایی مستقل قرار بده.","status":"published","sort_order":35,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-36","course_id":"html-advanced","title":"ارزیابی نهایی استاندارد، امنیت و کیفیت HTML","slug":"html-advanced-36","summary":"در ارزیابی نهایی باید صحت استاندارد، امنیت، سازگاری، دسترس‌پذیری و عملکرد را جداگانه بررسی کنی و شواهد آزمون را ثبت کنی. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در ارزیابی نهایی باید صحت استاندارد، امنیت، سازگاری، دسترس‌پذیری و عملکرد را جداگانه بررسی کنی و شواهد آزمون را ثبت کنی.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;گزارش ممیزی HTML&lt;/h1&gt;&lt;ol&gt;&lt;li&gt;اعتبارسنجی ساختار&lt;/li&gt;&lt;li&gt;آزمون صفحه‌کلید&lt;/li&gt;&lt;li&gt;بررسی metadata&lt;/li&gt;&lt;li&gt;بررسی منابع خارجی&lt;/li&gt;&lt;/ol&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>پروژه نهایی را با یک جدول ممیزی ارزیابی کن؛ برای هر ایراد، شدت، اثر، روش بازتولید و اصلاح را بنویس.</p><h3>نکته فنی</h3><p>عبارت «بدون خطا» را بدون آزمون مستند استفاده نکن.</p><h3>معیار موفقیت</h3><p>گزارش شامل نتیجه آزمون، ایرادهای باقی‌مانده و محدودیت‌های بررسی باشد.</p>","starter_code":"<main><h1>گزارش ممیزی HTML</h1><ol><li>اعتبارسنجی ساختار</li><li>آزمون صفحه‌کلید</li><li>بررسی metadata</li><li>بررسی منابع خارجی</li></ol></main>","exercise":"پروژه نهایی را با یک جدول ممیزی ارزیابی کن؛ برای هر ایراد، شدت، اثر، روش بازتولید و اصلاح را بنویس.","status":"published","sort_order":36,"estimated_minutes":40},{"id":"curriculum-324-css-01","course_id":"css","title":"CSS چیست و چه نقشی در ظاهر وب دارد","slug":"css-beginner-01","summary":"CSS ظاهر و چیدمان عناصر HTML را کنترل می‌کند؛ محتوا و ساختار را از ظاهر جدا نگه می‌دارد.","content_html":"<h3>هدف درس</h3><p>CSS ظاهر و چیدمان عناصر HTML را کنترل می‌کند؛ محتوا و ساختار را از ظاهر جدا نگه می‌دارد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>body { font-family: sans-serif; color: #222; } h1 { color: #174ea6; }</code></pre><h3>تمرین</h3><p>برای یک مقاله، رنگ متن و عنوان را جدا کن و توضیح بده چرا ساختار HTML را با CSS جایگزین نمی‌کنی.</p><h3>نکته فنی</h3><p>CSS ظاهر را کنترل می‌کند؛ ساختار و معنای محتوا باید در HTML باقی بماند.</p><h3>معیار موفقیت</h3><p>با تغییر CSS رنگ و قلم عوض شوند، اما متن و ساختار HTML بدون تغییر باقی بمانند.</p>","starter_code":"body { font-family: sans-serif; color: #222; } h1 { color: #174ea6; }","exercise":"برای یک مقاله، رنگ متن و عنوان را جدا کن و توضیح بده چرا ساختار HTML را با CSS جایگزین نمی‌کنی.","status":"published","sort_order":1,"estimated_minutes":25},{"id":"curriculum-324-css-02","course_id":"css","title":"اتصال فایل CSS خارجی به صفحه","slug":"css-beginner-02","summary":"فایل خارجی باعث استفاده مجدد از یک مجموعه سبک در چند صفحه می‌شود.","content_html":"<h3>هدف درس</h3><p>فایل خارجی باعث استفاده مجدد از یک مجموعه سبک در چند صفحه می‌شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>&lt;link rel=\"stylesheet\" href=\"style.css\"&gt;</code></pre><h3>تمرین</h3><p>دو صفحه بساز که هر دو از style.css مشترک استفاده کنند و تغییر یک قانون را در هر دو ببین.</p><h3>نکته فنی</h3><p>مسیر href نسبت به فایل HTML محاسبه می‌شود و نام فایل و حروف بزرگ و کوچک را دقیق بررسی کن.</p><h3>معیار موفقیت</h3><p>فایل style.css بارگذاری شود و تغییر یک قانون در مرورگر روی عنصر هدف دیده شود.</p>","starter_code":"<link rel=\"stylesheet\" href=\"style.css\">","exercise":"دو صفحه بساز که هر دو از style.css مشترک استفاده کنند و تغییر یک قانون را در هر دو ببین.","status":"published","sort_order":2,"estimated_minutes":25},{"id":"curriculum-324-css-03","course_id":"css","title":"ساختار قانون و اعلان‌های CSS","slug":"css-beginner-03","summary":"هر قانون از انتخابگر و یک یا چند اعلان property:value تشکیل می‌شود.","content_html":"<h3>هدف درس</h3><p>هر قانون از انتخابگر و یک یا چند اعلان property:value تشکیل می‌شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.notice { color: #333; background: #f2f4f7; padding: 12px; }</code></pre><h3>تمرین</h3><p>برای یک هشدار سه اعلان متفاوت بنویس و نام انتخابگر، ویژگی و مقدار را مشخص کن.</p><h3>نکته فنی</h3><p>هر قانون از انتخابگر و بلوک اعلان‌ها تشکیل می‌شود؛ هر اعلان باید property و value معتبر داشته باشد.</p><h3>معیار موفقیت</h3><p>قانون انتخابگر و اعلان معتبر داشته باشد و مقدار property در DevTools اعمال شود.</p>","starter_code":".notice { color: #333; background: #f2f4f7; padding: 12px; }","exercise":"برای یک هشدار سه اعلان متفاوت بنویس و نام انتخابگر، ویژگی و مقدار را مشخص کن.","status":"published","sort_order":3,"estimated_minutes":25},{"id":"curriculum-324-css-04","course_id":"css","title":"انتخابگر نوع و محدوده اثر آن","slug":"css-beginner-04","summary":"انتخابگر نوع تمام عناصر هم‌نام در محدوده سند را هدف می‌گیرد.","content_html":"<h3>هدف درس</h3><p>انتخابگر نوع تمام عناصر هم‌نام در محدوده سند را هدف می‌گیرد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>p { color: #334155; }</code></pre><h3>تمرین</h3><p>سه پاراگراف را با انتخابگر p سبک بده و نتیجه را در صفحه ببین.</p><h3>نکته فنی</h3><p>انتخابگر نوع روی همه عناصر همان نوع اثر می‌گذارد؛ دامنه آن را با ساختار HTML بسنج.</p><h3>معیار موفقیت</h3><p>فقط پاراگراف‌ها هدف قرار گیرند و عناصر دیگر ناخواسته تغییر نکنند.</p>","starter_code":"p { color: #334155; }","exercise":"سه پاراگراف را با انتخابگر p سبک بده و نتیجه را در صفحه ببین.","status":"published","sort_order":4,"estimated_minutes":25},{"id":"curriculum-324-css-05","course_id":"css","title":"کلاس‌ها و شناسه‌ها در انتخابگرها","slug":"css-beginner-05","summary":"کلاس برای گروهی از عناصر و شناسه برای یک عنصر یکتا مناسب است.","content_html":"<h3>هدف درس</h3><p>کلاس برای گروهی از عناصر و شناسه برای یک عنصر یکتا مناسب است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.important { color: #b42318; } #page-title { font-size: 2rem; }</code></pre><h3>تمرین</h3><p>برای دو پیام از یک کلاس و برای عنوان اصلی یک شناسه استفاده کن؛ شناسه را تکرار نکن.</p><h3>نکته فنی</h3><p>کلاس برای گروه عناصر قابل تکرار است؛ id در یک سند باید یکتا بماند.</p><h3>معیار موفقیت</h3><p>کلاس روی چند عنصر اثر کند و id فقط عنصر یکتای موردنظر را انتخاب کند.</p>","starter_code":".important { color: #b42318; } #page-title { font-size: 2rem; }","exercise":"برای دو پیام از یک کلاس و برای عنوان اصلی یک شناسه استفاده کن؛ شناسه را تکرار نکن.","status":"published","sort_order":5,"estimated_minutes":25},{"id":"curriculum-324-css-06","course_id":"css","title":"ترکیب انتخابگرها و گروه‌بندی","slug":"css-beginner-06","summary":"با گروه‌بندی می‌توان یک مجموعه اعلان را به چند انتخابگر اعمال کرد.","content_html":"<h3>هدف درس</h3><p>با گروه‌بندی می‌توان یک مجموعه اعلان را به چند انتخابگر اعمال کرد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>h1, h2, p { margin-block: 0 1rem; }</code></pre><h3>تمرین</h3><p>یک قانون را به h1 و h2 بده و سپس تفاوتشان را با قانون جداگانه تنظیم کن.</p><h3>نکته فنی</h3><p>ویرگول انتخابگرها را گروه‌بندی می‌کند؛ فاصله یا combinatorها معنای دیگری دارند.</p><h3>معیار موفقیت</h3><p>هر سه انتخابگر گروهی یک مجموعه قوانین مشترک بگیرند و جداگانه نیز قابل تشخیص باشند.</p>","starter_code":"h1, h2, p { margin-block: 0 1rem; }","exercise":"یک قانون را به h1 و h2 بده و سپس تفاوتشان را با قانون جداگانه تنظیم کن.","status":"published","sort_order":6,"estimated_minutes":25},{"id":"curriculum-324-css-07","course_id":"css","title":"رنگ‌ها با HEX و RGB","slug":"css-beginner-07","summary":"HEX و RGB دو روش رایج نمایش رنگ در CSS هستند.","content_html":"<h3>هدف درس</h3><p>HEX و RGB دو روش رایج نمایش رنگ در CSS هستند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.swatch { color: #2563eb; background: rgb(219 234 254); }</code></pre><h3>تمرین</h3><p>سه نمونه رنگ با HEX و RGB بساز و کنتراست متن را مقایسه کن.</p><h3>نکته فنی</h3><p>HEX و RGB دو نمایش رنگ‌اند؛ برای کنتراست متن و پس‌زمینه جداگانه بررسی انجام بده.</p><h3>معیار موفقیت</h3><p>هر دو قالب رنگ در مرورگر معتبر باشند و متن روی پس‌زمینه خوانا بماند.</p>","starter_code":".swatch { color: #2563eb; background: rgb(219 234 254); }","exercise":"سه نمونه رنگ با HEX و RGB بساز و کنتراست متن را مقایسه کن.","status":"published","sort_order":7,"estimated_minutes":25},{"id":"curriculum-324-css-08","course_id":"css","title":"رنگ پس‌زمینه و لایه‌های ساده","slug":"css-beginner-08","summary":"پس‌زمینه می‌تواند رنگی باشد و سطح بصری بخش را مشخص کند.","content_html":"<h3>هدف درس</h3><p>پس‌زمینه می‌تواند رنگی باشد و سطح بصری بخش را مشخص کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.hero { background-color: #eef2ff; }</code></pre><h3>تمرین</h3><p>برای بخش معرفی رنگ پس‌زمینه تعیین کن و مطمئن شو متن خوانا می‌ماند.</p><h3>نکته فنی</h3><p>background-color فقط سطح عنصر را رنگ می‌کند و به‌تنهایی تصویر یا گرادیان ایجاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>پس‌زمینه عنصر هدف تغییر کند و رنگ متن مستقل از آن قابل کنترل باشد.</p>","starter_code":".hero { background-color: #eef2ff; }","exercise":"برای بخش معرفی رنگ پس‌زمینه تعیین کن و مطمئن شو متن خوانا می‌ماند.","status":"published","sort_order":8,"estimated_minutes":25},{"id":"curriculum-324-css-09","course_id":"css","title":"واحدهای px و درصد","slug":"css-beginner-09","summary":"px واحد ثابت CSS و درصد واحدی وابسته به اندازه مرجع است.","content_html":"<h3>هدف درس</h3><p>px واحد ثابت CSS و درصد واحدی وابسته به اندازه مرجع است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.box { width: 80%; padding: 12px; }</code></pre><h3>تمرین</h3><p>عرض یک جعبه را با px و درصد تعریف کن و تغییر اندازه پنجره را مقایسه کن.</p><h3>نکته فنی</h3><p>درصد معمولاً نسبت به اندازه مرجع والد محاسبه می‌شود؛ px واحد ثابت CSS است.</p><h3>معیار موفقیت</h3><p>با تغییر عرض والد، مقدار درصدی تغییر کند اما padding پیکسلی ثابت بماند.</p>","starter_code":".box { width: 80%; padding: 12px; }","exercise":"عرض یک جعبه را با px و درصد تعریف کن و تغییر اندازه پنجره را مقایسه کن.","status":"published","sort_order":9,"estimated_minutes":25},{"id":"curriculum-324-css-10","course_id":"css","title":"واحدهای em و rem","slug":"css-beginner-10","summary":"em نسبت به اندازه قلم زمینه و rem نسبت به اندازه قلم ریشه محاسبه می‌شود.","content_html":"<h3>هدف درس</h3><p>em نسبت به اندازه قلم زمینه و rem نسبت به اندازه قلم ریشه محاسبه می‌شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.text { font-size: 1rem; margin-bottom: 1.5em; }</code></pre><h3>تمرین</h3><p>اندازه قلم ریشه را تغییر بده و اثر rem و em را روی دو عنصر تو در تو بررسی کن.</p><h3>نکته فنی</h3><p>em به اندازه قلم زمینه وابسته است و rem به اندازه قلم عنصر ریشه وابسته می‌ماند.</p><h3>معیار موفقیت</h3><p>تغییر اندازه قلم ریشه روی rem اثر بگذارد و وابستگی em به زمینه قابل مشاهده باشد.</p>","starter_code":".text { font-size: 1rem; margin-bottom: 1.5em; }","exercise":"اندازه قلم ریشه را تغییر بده و اثر rem و em را روی دو عنصر تو در تو بررسی کن.","status":"published","sort_order":10,"estimated_minutes":25},{"id":"curriculum-324-css-11","course_id":"css","title":"اندازه و وزن قلم","slug":"css-beginner-11","summary":"font-size اندازه قلم و font-weight ضخامت ظاهری آن را تعیین می‌کند.","content_html":"<h3>هدف درس</h3><p>font-size اندازه قلم و font-weight ضخامت ظاهری آن را تعیین می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>h1 { font-size: 2rem; font-weight: 700; }</code></pre><h3>تمرین</h3><p>عنوان، زیرعنوان و متن معمولی با سه اندازه و وزن متفاوت بساز.</p><h3>نکته فنی</h3><p>font-size اندازه متن و font-weight ضخامت را کنترل می‌کند؛ وزن موجود در فایل فونت را هم بررسی کن.</p><h3>معیار موفقیت</h3><p>عنوان در اندازه و وزن موردنظر نمایش داده شود و وزن ناموجود به‌درستی fallback شود.</p>","starter_code":"h1 { font-size: 2rem; font-weight: 700; }","exercise":"عنوان، زیرعنوان و متن معمولی با سه اندازه و وزن متفاوت بساز.","status":"published","sort_order":11,"estimated_minutes":25},{"id":"curriculum-324-css-12","course_id":"css","title":"فونت فارسی و زنجیره جایگزین","slug":"css-beginner-12","summary":"فونت فارسی باید خوانا باشد و در نبود فونت اول، گزینه‌های جایگزین وجود داشته باشند.","content_html":"<h3>هدف درس</h3><p>فونت فارسی باید خوانا باشد و در نبود فونت اول، گزینه‌های جایگزین وجود داشته باشند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>body { font-family: Tahoma, Arial, sans-serif; }</code></pre><h3>تمرین</h3><p>یک فونت فارسی و دو fallback تعیین کن؛ صفحه را با حذف فونت اول آزمایش کن.</p><h3>نکته فنی</h3><p>فونت‌های جایگزین باید glyphهای فارسی را پوشش دهند تا متن به شکل مربع نمایش داده نشود.</p><h3>معیار موفقیت</h3><p>متن فارسی با فونت اصلی یا جایگزین خوانا باشد و glyph مفقود نمایش داده نشود.</p>","starter_code":"body { font-family: Tahoma, Arial, sans-serif; }","exercise":"یک فونت فارسی و دو fallback تعیین کن؛ صفحه را با حذف فونت اول آزمایش کن.","status":"published","sort_order":12,"estimated_minutes":25},{"id":"curriculum-324-css-13","course_id":"css","title":"تراز متن و line-height","slug":"css-beginner-13","summary":"text-align تراز افقی متن و line-height فاصله خطوط را کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>text-align تراز افقی متن و line-height فاصله خطوط را کنترل می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>p { text-align: start; line-height: 1.8; }</code></pre><h3>تمرین</h3><p>یک پاراگراف فارسی بساز و text-align و line-height را تغییر بده.</p><h3>نکته فنی</h3><p>برای متن چندزبانه از start و end استفاده کن تا جهت نوشتار تعیین‌کننده تراز باشد.</p><h3>معیار موفقیت</h3><p>متن در جهت نوشتار درست تراز شود و line-height خوانایی سطرها را حفظ کند.</p>","starter_code":"p { text-align: start; line-height: 1.8; }","exercise":"یک پاراگراف فارسی بساز و text-align و line-height را تغییر بده.","status":"published","sort_order":13,"estimated_minutes":25},{"id":"curriculum-324-css-14","course_id":"css","title":"فاصله داخلی با padding","slug":"css-beginner-14","summary":"padding فضای میان محتوا و مرز عنصر است.","content_html":"<h3>هدف درس</h3><p>padding فضای میان محتوا و مرز عنصر است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.card { padding: 20px 16px; }</code></pre><h3>تمرین</h3><p>برای یک کارت padding متفاوت در چهار جهت تعریف کن و فضای داخل آن را بررسی کن.</p><h3>نکته فنی</h3><p>padding فضای داخل border است و در اندازه نهایی عنصر، همراه با box model محاسبه می‌شود.</p><h3>معیار موفقیت</h3><p>فاصله داخلی کارت قابل مشاهده باشد و محتوای آن از border فاصله بگیرد.</p>","starter_code":".card { padding: 20px 16px; }","exercise":"برای یک کارت padding متفاوت در چهار جهت تعریف کن و فضای داخل آن را بررسی کن.","status":"published","sort_order":14,"estimated_minutes":25},{"id":"curriculum-324-css-15","course_id":"css","title":"فاصله بیرونی با margin","slug":"css-beginner-15","summary":"margin فاصله بیرونی عنصر نسبت به عناصر اطراف را تنظیم می‌کند.","content_html":"<h3>هدف درس</h3><p>margin فاصله بیرونی عنصر نسبت به عناصر اطراف را تنظیم می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.section { margin: 24px auto; }</code></pre><h3>تمرین</h3><p>فاصله دو بخش را با margin تنظیم کن و تفاوت آن را با padding نشان بده.</p><h3>نکته فنی</h3><p>margin فضای بیرون border است و در بعضی چیدمان‌های block می‌تواند collapse شود.</p><h3>معیار موفقیت</h3><p>عنصر از همسایه‌ها فاصله بگیرد و رفتار margin در چیدمان توضیح داده شود.</p>","starter_code":".section { margin: 24px auto; }","exercise":"فاصله دو بخش را با margin تنظیم کن و تفاوت آن را با padding نشان بده.","status":"published","sort_order":15,"estimated_minutes":25},{"id":"curriculum-324-css-16","course_id":"css","title":"مرزها و ضخامت و سبک آن‌ها","slug":"css-beginner-16","summary":"border مرز پیرامون جعبه را با ضخامت و سبک مشخص می‌کند.","content_html":"<h3>هدف درس</h3><p>border مرز پیرامون جعبه را با ضخامت و سبک مشخص می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.panel { border: 1px solid #cbd5e1; }</code></pre><h3>تمرین</h3><p>برای یک پنل border پیوسته و برای ورودی border باریک تعریف کن.</p><h3>نکته فنی</h3><p>border برای نمایش به width و style نیاز دارد؛ فقط تعیین رنگ کافی نیست.</p><h3>معیار موفقیت</h3><p>مرز با ضخامت و سبک مشخص دیده شود و رنگ آن با پس‌زمینه کنتراست کافی داشته باشد.</p>","starter_code":".panel { border: 1px solid #cbd5e1; }","exercise":"برای یک پنل border پیوسته و برای ورودی border باریک تعریف کن.","status":"published","sort_order":16,"estimated_minutes":25},{"id":"curriculum-324-css-17","course_id":"css","title":"مدل جعبه‌ای در محاسبه اندازه","slug":"css-beginner-17","summary":"محتوا، padding، border و margin چهار بخش مدل جعبه‌ای‌اند.","content_html":"<h3>هدف درس</h3><p>محتوا، padding، border و margin چهار بخش مدل جعبه‌ای‌اند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.box { width: 200px; padding: 20px; border: 5px solid; }</code></pre><h3>تمرین</h3><p>عرض نهایی یک جعبه را با محاسبه content-box به دست بیاور.</p><h3>نکته فنی</h3><p>عرض نهایی در content-box شامل محتواست و padding و border به آن افزوده می‌شوند.</p><h3>معیار موفقیت</h3><p>اندازه واقعی عنصر با جمع content، padding و border محاسبه شود.</p>","starter_code":".box { width: 200px; padding: 20px; border: 5px solid; }","exercise":"عرض نهایی یک جعبه را با محاسبه content-box به دست بیاور.","status":"published","sort_order":17,"estimated_minutes":25},{"id":"curriculum-324-css-18","course_id":"css","title":"box-sizing و اندازه قابل پیش‌بینی","slug":"css-beginner-18","summary":"border-box باعث می‌شود عرض تعیین‌شده padding و border را نیز در بر بگیرد.","content_html":"<h3>هدف درس</h3><p>border-box باعث می‌شود عرض تعیین‌شده padding و border را نیز در بر بگیرد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>* { box-sizing: border-box; }</code></pre><h3>تمرین</h3><p>دو جعبه با عرض یکسان بساز؛ یکی content-box و دیگری border-box باشد.</p><h3>نکته فنی</h3><p>border-box باعث می‌شود width شامل padding و border باشد و محاسبه layout قابل پیش‌بینی‌تر شود.</p><h3>معیار موفقیت</h3><p>افزودن padding اندازه بیرونی تعیین‌شده را از مقدار width بزرگ‌تر نکند.</p>","starter_code":"* { box-sizing: border-box; }","exercise":"دو جعبه با عرض یکسان بساز؛ یکی content-box و دیگری border-box باشد.","status":"published","sort_order":18,"estimated_minutes":25},{"id":"curriculum-324-css-19","course_id":"css","title":"عرض و ارتفاع و محدودیت اندازه","slug":"css-beginner-19","summary":"width و height اندازه را تعیین می‌کنند و max/min محدودیت ایجاد می‌کنند.","content_html":"<h3>هدف درس</h3><p>width و height اندازه را تعیین می‌کنند و max/min محدودیت ایجاد می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.content { width: 100%; max-width: 720px; min-height: 120px; }</code></pre><h3>تمرین</h3><p>برای یک محتوا width، max-width و min-height تعیین کن و در صفحه کوچک آزمایش کن.</p><h3>نکته فنی</h3><p>max-width و min-height محدودیت می‌سازند؛ ارتفاع ثابت را برای محتوای متغیر با احتیاط انتخاب کن.</p><h3>معیار موفقیت</h3><p>عنصر در عرض‌های متفاوت از محدودیت‌های min و max پیروی کند.</p>","starter_code":".content { width: 100%; max-width: 720px; min-height: 120px; }","exercise":"برای یک محتوا width، max-width و min-height تعیین کن و در صفحه کوچک آزمایش کن.","status":"published","sort_order":19,"estimated_minutes":25},{"id":"curriculum-324-css-20","course_id":"css","title":"رفتار block و inline","slug":"css-beginner-20","summary":"block معمولاً خط جدید می‌گیرد و inline در جریان متن باقی می‌ماند.","content_html":"<h3>هدف درس</h3><p>block معمولاً خط جدید می‌گیرد و inline در جریان متن باقی می‌ماند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.label { display: inline; } .article { display: block; }</code></pre><h3>تمرین</h3><p>یک span و یک div را کنار متن قرار بده و تفاوت رفتارشان را ببین.</p><h3>نکته فنی</h3><p>عنصر inline مانند block عرض و ارتفاع دلخواه را به همان شکل نمی‌پذیرد؛ رفتار جریان را بشناس.</p><h3>معیار موفقیت</h3><p>عنصر block خط جدید بگیرد و عنصر inline در جریان متن باقی بماند.</p>","starter_code":".label { display: inline; } .article { display: block; }","exercise":"یک span و یک div را کنار متن قرار بده و تفاوت رفتارشان را ببین.","status":"published","sort_order":20,"estimated_minutes":25},{"id":"curriculum-324-css-21","course_id":"css","title":"کنترل نمایش با display","slug":"css-beginner-21","summary":"display نوع جعبه و نحوه مشارکت عنصر در چیدمان را مشخص می‌کند.","content_html":"<h3>هدف درس</h3><p>display نوع جعبه و نحوه مشارکت عنصر در چیدمان را مشخص می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.hidden { display: none; }</code></pre><h3>تمرین</h3><p>یک عنصر را با display:none پنهان کن و تفاوت آن را با visibility:hidden بررسی کن.</p><h3>نکته فنی</h3><p>display:none عنصر را از layout و درخت دسترس‌پذیری حذف می‌کند؛ برای مخفی‌سازی بصری روش دیگری لازم است.</p><h3>معیار موفقیت</h3><p>عنصر hidden در layout فضا نگیرد و تفاوت آن با visibility توضیح داده شود.</p>","starter_code":".hidden { display: none; }","exercise":"یک عنصر را با display:none پنهان کن و تفاوت آن را با visibility:hidden بررسی کن.","status":"published","sort_order":21,"estimated_minutes":25},{"id":"curriculum-324-css-22","course_id":"css","title":"موقعیت‌دهی relative","slug":"css-beginner-22","summary":"relative عنصر را نسبت به جای اصلی خودش جابه‌جا می‌کند و جای اصلی حفظ می‌شود.","content_html":"<h3>هدف درس</h3><p>relative عنصر را نسبت به جای اصلی خودش جابه‌جا می‌کند و جای اصلی حفظ می‌شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.badge { position: relative; top: 4px; }</code></pre><h3>تمرین</h3><p>یک نشان کوچک را با relative کمی جابه‌جا کن و جای اصلی آن را مقایسه کن.</p><h3>نکته فنی</h3><p>position:relative عنصر را در جریان نگه می‌دارد و مبنای موقعیت‌دهی فرزندان absolute می‌تواند باشد.</p><h3>معیار موفقیت</h3><p>عنصر با offset جابه‌جا شود اما جای اصلی آن در جریان حفظ شود.</p>","starter_code":".badge { position: relative; top: 4px; }","exercise":"یک نشان کوچک را با relative کمی جابه‌جا کن و جای اصلی آن را مقایسه کن.","status":"published","sort_order":22,"estimated_minutes":25},{"id":"curriculum-324-css-23","course_id":"css","title":"موقعیت‌دهی absolute در والد","slug":"css-beginner-23","summary":"absolute عنصر را نسبت به نزدیک‌ترین والد موقعیت‌دار جای‌گذاری می‌کند.","content_html":"<h3>هدف درس</h3><p>absolute عنصر را نسبت به نزدیک‌ترین والد موقعیت‌دار جای‌گذاری می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.card { position: relative; } .card__tag { position: absolute; inset-block-start: 8px; inset-inline-end: 8px; }</code></pre><h3>تمرین</h3><p>یک برچسب گوشه کارت بساز؛ والد را relative و برچسب را absolute قرار بده.</p><h3>نکته فنی</h3><p>والد مناسب باید موقعیت‌دهی شده باشد تا عنصر absolute نسبت به مرجع مورد انتظار قرار گیرد.</p><h3>معیار موفقیت</h3><p>برچسب در گوشه کارت قرار گیرد و با تغییر اندازه والد از مرجع درست پیروی کند.</p>","starter_code":".card { position: relative; } .card__tag { position: absolute; inset-block-start: 8px; inset-inline-end: 8px; }","exercise":"یک برچسب گوشه کارت بساز؛ والد را relative و برچسب را absolute قرار بده.","status":"published","sort_order":23,"estimated_minutes":25},{"id":"curriculum-324-css-24","course_id":"css","title":"موقعیت ثابت و چسبان","slug":"css-beginner-24","summary":"fixed نسبت به viewport و sticky با رسیدن به آستانه در جریان پیمایش می‌چسبد.","content_html":"<h3>هدف درس</h3><p>fixed نسبت به viewport و sticky با رسیدن به آستانه در جریان پیمایش می‌چسبد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.fixed-bar {\n  position: fixed;\n  inset-block-start: 0;\n  inset-inline: 0;\n  z-index: 10;\n}\n.sticky-notice {\n  position: sticky;\n  top: 0;\n}</code></pre><h3>تمرین</h3><p>نوار بالای صفحه را sticky کن و رفتار آن را هنگام پیمایش بررسی کن.</p><h3>نکته فنی</h3><p>fixed از جریان عادی خارج می‌شود و نسبت به viewport موقعیت می‌گیرد؛ برای جلوگیری از پوشاندن محتوا باید فضای لازم رزرو شود. sticky در محدوده پیمایش والد می‌چسبد.</p><h3>معیار موفقیت</h3><p>نوار fixed نسبت به viewport ثابت بماند و نوار sticky فقط هنگام رسیدن به آستانه در محدوده والد بچسبد.</p>","starter_code":".fixed-bar {\n  position: fixed;\n  inset-block-start: 0;\n  inset-inline: 0;\n  z-index: 10;\n}\n.sticky-notice {\n  position: sticky;\n  top: 0;\n}","exercise":"نوار بالای صفحه را sticky کن و رفتار آن را هنگام پیمایش بررسی کن.","status":"published","sort_order":24,"estimated_minutes":25},{"id":"curriculum-324-css-25","course_id":"css","title":"لایه‌بندی با z-index","slug":"css-beginner-25","summary":"z-index ترتیب روی‌هم‌افتادن جعبه‌ها را در زمینه‌های لایه‌بندی کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>z-index ترتیب روی‌هم‌افتادن جعبه‌ها را در زمینه‌های لایه‌بندی کنترل می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.menu { position: relative; z-index: 2; }</code></pre><h3>تمرین</h3><p>دو عنصر هم‌پوشان بساز و z-index را تغییر بده؛ stacking context را فقط در حد مشاهده ثبت کن.</p><h3>نکته فنی</h3><p>z-index فقط در چارچوب stacking context مربوط اثر می‌کند؛ عدد بزرگ همیشه از همه لایه‌ها بالاتر نیست.</p><h3>معیار موفقیت</h3><p>لایه منو در stacking context مورد انتظار نمایش داده شود و ترتیب لایه‌ها آزمایش شود.</p>","starter_code":".menu { position: relative; z-index: 2; }","exercise":"دو عنصر هم‌پوشان بساز و z-index را تغییر بده؛ stacking context را فقط در حد مشاهده ثبت کن.","status":"published","sort_order":25,"estimated_minutes":25},{"id":"curriculum-324-css-26","course_id":"css","title":"حالت‌های hover و focus","slug":"css-beginner-26","summary":"hover برای اشاره‌گر و focus برای عنصر دارای تمرکز صفحه‌کلید کاربرد دارد.","content_html":"<h3>هدف درس</h3><p>hover برای اشاره‌گر و focus برای عنصر دارای تمرکز صفحه‌کلید کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>a:hover { text-decoration: underline; } button:focus { outline: 3px solid #2563eb; }</code></pre><h3>تمرین</h3><p>برای لینک hover و برای دکمه focus واضح بساز؛ با Tab آزمایش کن.</p><h3>نکته فنی</h3><p>برای دسترسی صفحه‌کلید focus-visible را هم در نظر بگیر و نشانگر فوکوس را حذف نکن.</p><h3>معیار موفقیت</h3><p>حالت hover با ماوس و focus با صفحه‌کلید قابل تشخیص باشد.</p>","starter_code":"a:hover { text-decoration: underline; } button:focus { outline: 3px solid #2563eb; }","exercise":"برای لینک hover و برای دکمه focus واضح بساز؛ با Tab آزمایش کن.","status":"published","sort_order":26,"estimated_minutes":25},{"id":"curriculum-324-css-27","course_id":"css","title":"شبه‌عنصرهای before و after","slug":"css-beginner-27","summary":"شبه‌عنصرها امکان افزودن تزئینات بدون افزودن عنصر HTML را می‌دهند.","content_html":"<h3>هدف درس</h3><p>شبه‌عنصرها امکان افزودن تزئینات بدون افزودن عنصر HTML را می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.link::after { content: \" ↗\"; }</code></pre><h3>تمرین</h3><p>با ::before یک نشان تزئینی اضافه کن و محتوای ضروری را داخل شبه‌عنصر نگذار.</p><h3>نکته فنی</h3><p>محتوای شبه‌عنصر برای تزئین مناسب است و نباید اطلاعات ضروری را فقط در content قرار دهد.</p><h3>معیار موفقیت</h3><p>شبه‌عنصر نشانه تزئینی بسازد و حذف آن اطلاعات ضروری را از بین نبرد.</p>","starter_code":".link::after { content: \" ↗\"; }","exercise":"با ::before یک نشان تزئینی اضافه کن و محتوای ضروری را داخل شبه‌عنصر نگذار.","status":"published","sort_order":27,"estimated_minutes":25},{"id":"curriculum-324-css-28","course_id":"css","title":"طراحی پیوند و دکمه قابل استفاده","slug":"css-beginner-28","summary":"پیوند و دکمه باید ظاهر قابل تشخیص و حالت تمرکز واضح داشته باشند.","content_html":"<h3>هدف درس</h3><p>پیوند و دکمه باید ظاهر قابل تشخیص و حالت تمرکز واضح داشته باشند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>a { color: #174ea6; } button { padding: 10px 16px; cursor: pointer; }</code></pre><h3>تمرین</h3><p>یک پیوند و یک دکمه بساز؛ هرکدام را برای کاربرد درست و حالت focus سبک بده.</p><h3>نکته فنی</h3><p>پیوند و دکمه نقش متفاوت دارند؛ پیوند ناوبری می‌کند و دکمه عملی را اجرا می‌کند.</p><h3>معیار موفقیت</h3><p>پیوند مقصد واقعی داشته باشد و دکمه رفتار عملیاتی مشخص و قابل فوکوس داشته باشد.</p>","starter_code":"a { color: #174ea6; } button { padding: 10px 16px; cursor: pointer; }","exercise":"یک پیوند و یک دکمه بساز؛ هرکدام را برای کاربرد درست و حالت focus سبک بده.","status":"published","sort_order":28,"estimated_minutes":25},{"id":"curriculum-324-css-29","course_id":"css","title":"ساخت کارت اطلاعاتی","slug":"css-beginner-29","summary":"کارت یک الگوی بصری برای گروه‌بندی عنوان، توضیح و اقدام مرتبط است.","content_html":"<h3>هدف درس</h3><p>کارت یک الگوی بصری برای گروه‌بندی عنوان، توضیح و اقدام مرتبط است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.card { border: 1px solid #ddd; padding: 16px; border-radius: 12px; }</code></pre><h3>تمرین</h3><p>کارت شامل عنوان، متن و پیوند بساز و فاصله‌های داخلی آن را منظم کن.</p><h3>نکته فنی</h3><p>کارت باید ترتیب محتوا و فاصله‌ها را با HTML معنایی حفظ کند؛ CSS فقط ظاهر آن را می‌سازد.</p><h3>معیار موفقیت</h3><p>کارت مرز، فاصله و گوشه مناسب داشته باشد و ساختار محتوا در HTML باقی بماند.</p>","starter_code":".card { border: 1px solid #ddd; padding: 16px; border-radius: 12px; }","exercise":"کارت شامل عنوان، متن و پیوند بساز و فاصله‌های داخلی آن را منظم کن.","status":"published","sort_order":29,"estimated_minutes":25},{"id":"curriculum-324-css-30","course_id":"css","title":"چیدمان یک‌بعدی با Flexbox","slug":"css-beginner-30","summary":"Flexbox برای چیدمان یک‌بعدی در محور اصلی و متقاطع طراحی شده است.","content_html":"<h3>هدف درس</h3><p>Flexbox برای چیدمان یک‌بعدی در محور اصلی و متقاطع طراحی شده است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.toolbar { display: flex; align-items: center; justify-content: space-between; }</code></pre><h3>تمرین</h3><p>سه گزینه را با Flexbox در یک ردیف بچین و تراز عمودی را تنظیم کن.</p><h3>نکته فنی</h3><p>Flexbox برای توزیع یک‌بعدی آیتم‌ها مناسب است؛ جهت محور اصلی را با flex-direction تعیین کن.</p><h3>معیار موفقیت</h3><p>آیتم‌ها در محور اصلی مرتب و در محور متقاطع تراز شوند.</p>","starter_code":".toolbar { display: flex; align-items: center; justify-content: space-between; }","exercise":"سه گزینه را با Flexbox در یک ردیف بچین و تراز عمودی را تنظیم کن.","status":"published","sort_order":30,"estimated_minutes":25},{"id":"curriculum-324-css-31","course_id":"css","title":"فاصله‌گذاری با gap","slug":"css-beginner-31","summary":"gap فاصله میان فرزندان یک چیدمان flex یا grid را تعیین می‌کند.","content_html":"<h3>هدف درس</h3><p>gap فاصله میان فرزندان یک چیدمان flex یا grid را تعیین می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.items { display: flex; gap: 12px; }</code></pre><h3>تمرین</h3><p>فاصله میان کارت‌ها را با gap تغییر بده و از marginهای پراکنده پرهیز کن.</p><h3>نکته فنی</h3><p>gap فاصله بین آیتم‌ها را می‌سازد و از marginهای پراکنده برای فاصله‌گذاری ساده‌تر است.</p><h3>معیار موفقیت</h3><p>فاصله بین آیتم‌ها با gap ایجاد شود و margin اضافی ناخواسته باقی نماند.</p>","starter_code":".items { display: flex; gap: 12px; }","exercise":"فاصله میان کارت‌ها را با gap تغییر بده و از marginهای پراکنده پرهیز کن.","status":"published","sort_order":31,"estimated_minutes":25},{"id":"curriculum-324-css-32","course_id":"css","title":"ساخت ستون‌های ساده با Grid","slug":"css-beginner-32","summary":"Grid شبکه‌ای دوبعدی برای ردیف‌ها و ستون‌ها ایجاد می‌کند.","content_html":"<h3>هدف درس</h3><p>Grid شبکه‌ای دوبعدی برای ردیف‌ها و ستون‌ها ایجاد می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.columns { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }</code></pre><h3>تمرین</h3><p>یک شبکه دو ستونی بساز و اندازه ستون‌ها را تغییر بده.</p><h3>نکته فنی</h3><p>Grid برای چیدمان دوبعدی مناسب است؛ برای جلوگیری از سرریز ستون‌ها minmax(0,1fr) را بشناس.</p><h3>معیار موفقیت</h3><p>دو ستون در صفحه عریض دیده شوند و اندازه محتوا باعث سرریز ستون نشود.</p>","starter_code":".columns { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }","exercise":"یک شبکه دو ستونی بساز و اندازه ستون‌ها را تغییر بده.","status":"published","sort_order":32,"estimated_minutes":25},{"id":"curriculum-324-css-33","course_id":"css","title":"Media Query برای اندازه صفحه","slug":"css-beginner-33","summary":"Media Query قوانین را بر اساس ویژگی‌های محیط مانند عرض viewport فعال می‌کند.","content_html":"<h3>هدف درس</h3><p>Media Query قوانین را بر اساس ویژگی‌های محیط مانند عرض viewport فعال می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>@media (max-width: 600px) { .columns { grid-template-columns: 1fr; } }</code></pre><h3>تمرین</h3><p>در عرض کمتر از 600 پیکسل ستون‌ها را به یک ستون تبدیل کن.</p><h3>نکته فنی</h3><p>Media Query شرطی بر ویژگی viewport است؛ breakpoint را بر اساس شکست محتوا انتخاب کن نه مدل گوشی.</p><h3>معیار موفقیت</h3><p>در عرض کمتر از breakpoint ستون‌ها به چیدمان تک‌ستونه تبدیل شوند.</p>","starter_code":"@media (max-width: 600px) { .columns { grid-template-columns: 1fr; } }","exercise":"در عرض کمتر از 600 پیکسل ستون‌ها را به یک ستون تبدیل کن.","status":"published","sort_order":33,"estimated_minutes":25},{"id":"curriculum-324-css-34","course_id":"css","title":"طراحی mobile-first","slug":"css-beginner-34","summary":"mobile-first یعنی ابتدا سبک پایه برای صفحه کوچک و سپس گسترش برای نمایشگر بزرگ‌تر.","content_html":"<h3>هدف درس</h3><p>mobile-first یعنی ابتدا سبک پایه برای صفحه کوچک و سپس گسترش برای نمایشگر بزرگ‌تر.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.container { width: min(100% - 2rem, 1100px); margin-inline: auto; }</code></pre><h3>تمرین</h3><p>محتوا را با عرض منعطف و حاشیه خودکار در مرکز نگه دار.</p><h3>نکته فنی</h3><p>در mobile-first ابتدا سبک پایه برای صفحه کوچک نوشته می‌شود و سپس با min-width گسترش می‌یابد.</p><h3>معیار موفقیت</h3><p>صفحه ابتدا برای موبایل قابل استفاده باشد و در عرض بزرگ‌تر محدودیت منطقی داشته باشد.</p>","starter_code":".container { width: min(100% - 2rem, 1100px); margin-inline: auto; }","exercise":"محتوا را با عرض منعطف و حاشیه خودکار در مرکز نگه دار.","status":"published","sort_order":34,"estimated_minutes":25},{"id":"curriculum-324-css-35","course_id":"css","title":"سایه و گوشه‌های نرم","slug":"css-beginner-35","summary":"box-shadow عمق بصری ایجاد می‌کند و border-radius گوشه‌ها را گرد می‌کند.","content_html":"<h3>هدف درس</h3><p>box-shadow عمق بصری ایجاد می‌کند و border-radius گوشه‌ها را گرد می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.card { box-shadow: 0 4px 14px rgb(15 23 42 / 10%); border-radius: 14px; }</code></pre><h3>تمرین</h3><p>به کارت سایه ملایم و گوشه گرد بده؛ خوانایی و کنتراست را حفظ کن.</p><h3>نکته فنی</h3><p>box-shadow در خوانایی و کنتراست اثر دارد؛ سایه نباید تنها نشانه مرز یا وضعیت باشد.</p><h3>معیار موفقیت</h3><p>سایه و گوشه کارت دیده شوند و مرز کارت بدون اتکا به سایه هم قابل تشخیص باشد.</p>","starter_code":".card { box-shadow: 0 4px 14px rgb(15 23 42 / 10%); border-radius: 14px; }","exercise":"به کارت سایه ملایم و گوشه گرد بده؛ خوانایی و کنتراست را حفظ کن.","status":"published","sort_order":35,"estimated_minutes":25},{"id":"curriculum-324-css-36","course_id":"css","title":"پروژه نهایی کارت واکنش‌گرا","slug":"css-beginner-36","summary":"در پروژه نهایی مفاهیم پایه برای ساخت یک کارت واکنش‌گرا ترکیب می‌شوند.","content_html":"<h3>هدف درس</h3><p>در پروژه نهایی مفاهیم پایه برای ساخت یک کارت واکنش‌گرا ترکیب می‌شوند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل style.css قرار بده و آن را به صفحه HTML متصل کن. سپس مقادیر را تغییر بده و اثر را بررسی کن.</p><pre><code>.card { width: min(100% - 2rem, 420px); margin: 2rem auto; padding: 1.25rem; border: 1px solid #dbe2ea; border-radius: 1rem; } .card h2 { margin-top: 0; } .card a { display: inline-block; padding: .6rem 1rem; background: #174ea6; color: white; border-radius: .5rem; } @media (min-width: 700px) { .card { padding: 2rem; } }</code></pre><h3>تمرین</h3><p>کارت نهایی را در عرض 360، 768 و 1200 پیکسل بررسی و ایرادهای overflow را رفع کن.</p><h3>نکته فنی</h3><p>پروژه نهایی باید در عرض‌های مختلف آزمایش شود و محتوای کارت نباید باعث overflow افقی شود.</p><h3>معیار موفقیت</h3><p>کارت در موبایل و دسکتاپ بدون overflow افقی و با فاصله‌گذاری خوانا نمایش داده شود.</p>","starter_code":".card { width: min(100% - 2rem, 420px); margin: 2rem auto; padding: 1.25rem; border: 1px solid #dbe2ea; border-radius: 1rem; } .card h2 { margin-top: 0; } .card a { display: inline-block; padding: .6rem 1rem; background: #174ea6; color: white; border-radius: .5rem; } @media (min-width: 700px) { .card { padding: 2rem; } }","exercise":"کارت نهایی را در عرض 360، 768 و 1200 پیکسل بررسی و ایرادهای overflow را رفع کن.","status":"published","sort_order":36,"estimated_minutes":25},{"id":"curriculum-324-css-intermediate-01","course_id":"css-intermediate","title":"معماری CSS با لایه‌های آبشاری","slug":"css-intermediate-01","summary":"لایه‌های آبشاری ترتیب اولویت گروه‌های قانون را مستقل از specificity کنترل می‌کنند؛ برای معماری بزرگ، لایه‌ها از انباشتن انتخابگرهای سنگین قابل نگهداری‌ترند.","content_html":"<h3>هدف درس</h3><p>لایه‌های آبشاری ترتیب اولویت گروه‌های قانون را مستقل از specificity کنترل می‌کنند؛ برای معماری بزرگ، لایه‌ها از انباشتن انتخابگرهای سنگین قابل نگهداری‌ترند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@layer reset, base, components, utilities;\n@layer base { h1 { margin: 0; color: #1f2937; } }\n@layer components { .notice { padding: 1rem; border: 1px solid; } }\n@layer utilities { .text-center { text-align: center; } }</code></pre><h3>تمرین</h3><p>یک فایل CSS با چهار لایه بساز و یک قانون متعارض را در دو لایه قرار بده؛ نتیجه را با ترتیب لایه‌ها توضیح بده.</p><h3>نکته فنی</h3><p>ترتیب لایه‌ها برای قواعد مهم است؛ specificity به‌تنهایی برنده را تعیین نمی‌کند.</p><h3>معیار موفقیت</h3><p>قواعد در لایه درست قرار بگیرند و اثر ترتیب لایه‌ها مستند شود.</p>","starter_code":"@layer reset, base, components, utilities;\n@layer base { h1 { margin: 0; color: #1f2937; } }\n@layer components { .notice { padding: 1rem; border: 1px solid; } }\n@layer utilities { .text-center { text-align: center; } }","exercise":"یک فایل CSS با چهار لایه بساز و یک قانون متعارض را در دو لایه قرار بده؛ نتیجه را با ترتیب لایه‌ها توضیح بده.","status":"published","sort_order":1,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-02","course_id":"css-intermediate","title":"محدودسازی دامنه سبک‌ها با @scope","slug":"css-intermediate-02","summary":"@scope دامنه اثر انتخابگرها را به یک زیر درخت محدود می‌کند و از نشت سبک مؤلفه‌ها به بخش‌های دیگر می‌کاهد.","content_html":"<h3>هدف درس</h3><p>@scope دامنه اثر انتخابگرها را به یک زیر درخت محدود می‌کند و از نشت سبک مؤلفه‌ها به بخش‌های دیگر می‌کاهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@scope (.profile-card) {\n  h2 { color: #174ea6; }\n  a { text-decoration-thickness: .12em; }\n}</code></pre><h3>تمرین</h3><p>دو کارت با کلاس‌های متفاوت بساز؛ سبک scoped را فقط به کارت پروفایل محدود کن و تفاوت را آزمایش کن.</p><h3>نکته فنی</h3><p>@scope جایگزین کامل معماری مؤلفه یا Shadow DOM نیست؛ پشتیبانی مرورگر را بررسی کن.</p><h3>معیار موفقیت</h3><p>سبک‌های داخل scope بیرون از دامنه اثر نگذارند.</p>","starter_code":"@scope (.profile-card) {\n  h2 { color: #174ea6; }\n  a { text-decoration-thickness: .12em; }\n}","exercise":"دو کارت با کلاس‌های متفاوت بساز؛ سبک scoped را فقط به کارت پروفایل محدود کن و تفاوت را آزمایش کن.","status":"published","sort_order":2,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-03","course_id":"css-intermediate","title":"CSS Nesting و ساختار تو‌در‌تو","slug":"css-intermediate-03","summary":"CSS Nesting اجازه می‌دهد قواعد مرتبط درون انتخابگر والد نوشته شوند و ساختار مؤلفه خواناتر شود.","content_html":"<h3>هدف درس</h3><p>CSS Nesting اجازه می‌دهد قواعد مرتبط درون انتخابگر والد نوشته شوند و ساختار مؤلفه خواناتر شود.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.menu {\n  color: #222;\n  &amp; a { color: inherit; }\n  &amp;:hover { background: #eef2ff; }\n}</code></pre><h3>تمرین</h3><p>یک کارت با حالت hover و پیوند داخلی بساز؛ نسخه nested و نسخه تخت را مقایسه کن.</p><h3>نکته فنی</h3><p>در nesting از & برای رابطه دقیق استفاده کن و از تو‌در‌تویی عمیق بپرهیز.</p><h3>معیار موفقیت</h3><p>نسخه nested همان نتیجه مورد انتظار را بدهد و خوانا بماند.</p>","starter_code":".menu {\n  color: #222;\n  & a { color: inherit; }\n  &:hover { background: #eef2ff; }\n}","exercise":"یک کارت با حالت hover و پیوند داخلی بساز؛ نسخه nested و نسخه تخت را مقایسه کن.","status":"published","sort_order":3,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-04","course_id":"css-intermediate","title":"انتخابگرهای پیشرفته :is و :where","slug":"css-intermediate-04","summary":":is و :where چند انتخابگر را گروه‌بندی می‌کنند؛ :where specificity صفر دارد و برای پایه‌های قابل بازنویسی مناسب است.","content_html":"<h3>هدف درس</h3><p>:is و :where چند انتخابگر را گروه‌بندی می‌کنند؛ :where specificity صفر دارد و برای پایه‌های قابل بازنویسی مناسب است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:where(header, footer) a { color: #174ea6; }\n:is(h1, h2, h3).title { font-family: sans-serif; }</code></pre><h3>تمرین</h3><p>یک گروه قانون پایه با :where بساز و آن را با یک کلاس ساده بازنویسی کن؛ specificity دو روش را مقایسه کن.</p><h3>نکته فنی</h3><p>:is specificity بیشترین آرگومان را می‌گیرد؛ :where همیشه صفر است.</p><h3>معیار موفقیت</h3><p>بتوانی علت برنده‌شدن قانون را با specificity توضیح بدهی.</p>","starter_code":":where(header, footer) a { color: #174ea6; }\n:is(h1, h2, h3).title { font-family: sans-serif; }","exercise":"یک گروه قانون پایه با :where بساز و آن را با یک کلاس ساده بازنویسی کن؛ specificity دو روش را مقایسه کن.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-05","course_id":"css-intermediate","title":"انتخابگر رابطه‌ای :has","slug":"css-intermediate-05","summary":":has انتخابگر والد‌مانند است و می‌تواند بر اساس وجود فرزند یا همسایه، ظاهر عنصر را تغییر دهد.","content_html":"<h3>هدف درس</h3><p>:has انتخابگر والد‌مانند است و می‌تواند بر اساس وجود فرزند یا همسایه، ظاهر عنصر را تغییر دهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.field:has(input:invalid) { border-inline-start: 4px solid #b42318; }\n.card:has(&gt; img) { display: grid; }</code></pre><h3>تمرین</h3><p>کارت دارای تصویر و کارت بدون تصویر بساز؛ فقط کارت دارای تصویر را سبک بده و حالت ورودی نامعتبر را هم آزمایش کن.</p><h3>نکته فنی</h3><p>:has را با انتخابگرهای محدود و دقیق به کار ببر؛ برای فهرست‌های بسیار بزرگ اثر عملکرد را بسنج.</p><h3>معیار موفقیت</h3><p>قانون فقط در حالت وجود فرزند موردنظر فعال شود.</p>","starter_code":".field:has(input:invalid) { border-inline-start: 4px solid #b42318; }\n.card:has(> img) { display: grid; }","exercise":"کارت دارای تصویر و کارت بدون تصویر بساز؛ فقط کارت دارای تصویر را سبک بده و حالت ورودی نامعتبر را هم آزمایش کن.","status":"published","sort_order":5,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-06","course_id":"css-intermediate","title":"انتخابگرهای ساختاری با nth-child of","slug":"css-intermediate-06","summary":"nth-child می‌تواند با بخش of فقط میان فرزندانی که با انتخابگر مشخص تطبیق دارند شمارش کند.","content_html":"<h3>هدف درس</h3><p>nth-child می‌تواند با بخش of فقط میان فرزندانی که با انتخابگر مشخص تطبیق دارند شمارش کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.list &gt; :nth-child(odd of .item) { background: #f1f5f9; }\n.list &gt; :nth-child(3n of li.active) { font-weight: 700; }</code></pre><h3>تمرین</h3><p>فهرستی از item و تبلیغ بساز و سومین عضو فعال را بدون شمردن تبلیغ‌ها هدف بگیر.</p><h3>نکته فنی</h3><p>تفاوت nth-child با nth-of-type و فیلتر of را دقیق بررسی کن.</p><h3>معیار موفقیت</h3><p>فقط عضو مطابق موقعیت فیلترشده انتخاب شود.</p>","starter_code":".list > :nth-child(odd of .item) { background: #f1f5f9; }\n.list > :nth-child(3n of li.active) { font-weight: 700; }","exercise":"فهرستی از item و تبلیغ بساز و سومین عضو فعال را بدون شمردن تبلیغ‌ها هدف بگیر.","status":"published","sort_order":6,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-07","course_id":"css-intermediate","title":"انتخابگر ویژگی با تطبیق دقیق","slug":"css-intermediate-07","summary":"انتخابگر ویژگی می‌تواند وجود، برابری، شروع، پایان یا شامل‌شدن یک رشته را بررسی کند.","content_html":"<h3>هدف درس</h3><p>انتخابگر ویژگی می‌تواند وجود، برابری، شروع، پایان یا شامل‌شدن یک رشته را بررسی کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>a[href^=\"https://\"] { text-decoration: underline; }\ninput[aria-invalid=\"true\"] { border-color: #b42318; }\nimg[alt=\"\"] { outline: 1px dashed #999; }</code></pre><h3>تمرین</h3><p>برای پیوند خارجی، ورودی نامعتبر و فایل PDF سه انتخابگر ویژگی بنویس.</p><h3>نکته فنی</h3><p>تطبیق رشته‌ای به مقدار واقعی attribute وابسته است و جای اعتبارسنجی معنایی را نمی‌گیرد.</p><h3>معیار موفقیت</h3><p>هر انتخابگر فقط عنصرهای موردنظر را هدف بگیرد.</p>","starter_code":"a[href^=\"https://\"] { text-decoration: underline; }\ninput[aria-invalid=\"true\"] { border-color: #b42318; }\nimg[alt=\"\"] { outline: 1px dashed #999; }","exercise":"برای پیوند خارجی، ورودی نامعتبر و فایل PDF سه انتخابگر ویژگی بنویس.","status":"published","sort_order":7,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-08","course_id":"css-intermediate","title":"ویژگی‌های منطقی برای چیدمان چندجهته","slug":"css-intermediate-08","summary":"ویژگی‌های منطقی مانند margin-inline و padding-block با جهت نوشتار و writing mode سازگارند و نیاز به چپ/راست ثابت را کاهش می‌دهند.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های منطقی مانند margin-inline و padding-block با جهت نوشتار و writing mode سازگارند و نیاز به چپ/راست ثابت را کاهش می‌دهند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.panel { padding-block: 1rem; padding-inline: 1.5rem; border-inline-start: 4px solid #2563eb; }\n.title { margin-block-end: .75rem; }</code></pre><h3>تمرین</h3><p>یک مؤلفه فارسی و انگلیسی بساز؛ با تغییر dir بررسی کن فاصله‌ها و مرز منطقی درست جابه‌جا شوند.</p><h3>نکته فنی</h3><p>برای رابط‌های چندزبانه از left و right ثابت فقط وقتی واقعاً لازم است استفاده کن.</p><h3>معیار موفقیت</h3><p>با تغییر جهت، چیدمان بدون بازنویسی قوانین درست بماند.</p>","starter_code":".panel { padding-block: 1rem; padding-inline: 1.5rem; border-inline-start: 4px solid #2563eb; }\n.title { margin-block-end: .75rem; }","exercise":"یک مؤلفه فارسی و انگلیسی بساز؛ با تغییر dir بررسی کن فاصله‌ها و مرز منطقی درست جابه‌جا شوند.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-09","course_id":"css-intermediate","title":"مدیریت writing-mode و متن عمودی","slug":"css-intermediate-09","summary":"writing-mode جهت جریان متن و محورهای نوشتاری را تغییر می‌دهد؛ ویژگی‌های منطقی در کنار آن رفتار سازگارتر دارند.","content_html":"<h3>هدف درس</h3><p>writing-mode جهت جریان متن و محورهای نوشتاری را تغییر می‌دهد؛ ویژگی‌های منطقی در کنار آن رفتار سازگارتر دارند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.vertical-label { writing-mode: vertical-rl; text-orientation: mixed; }\n.caption { writing-mode: horizontal-tb; }</code></pre><h3>تمرین</h3><p>یک برچسب عمودی کنار کارت بساز و متن فارسی و لاتین را آزمایش کن.</p><h3>نکته فنی</h3><p>writing-mode صرفاً چرخاندن جعبه نیست؛ جریان و محورهای چیدمان را تغییر می‌دهد.</p><h3>معیار موفقیت</h3><p>متن عمودی خوانا باشد و محتوای اصلی همچنان در جریان منطقی قرار گیرد.</p>","starter_code":".vertical-label { writing-mode: vertical-rl; text-orientation: mixed; }\n.caption { writing-mode: horizontal-tb; }","exercise":"یک برچسب عمودی کنار کارت بساز و متن فارسی و لاتین را آزمایش کن.","status":"published","sort_order":9,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-10","course_id":"css-intermediate","title":"تعریف قرارداد طراحی با custom properties","slug":"css-intermediate-10","summary":"custom properties قراردادهای طراحی را در یک نقطه متمرکز می‌کنند و با var در اجزای مختلف مصرف می‌شوند.","content_html":"<h3>هدف درس</h3><p>custom properties قراردادهای طراحی را در یک نقطه متمرکز می‌کنند و با var در اجزای مختلف مصرف می‌شوند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --color-brand: #174ea6; --space-card: 1.25rem; --radius-card: .8rem; }\n.card { color: var(--color-brand); padding: var(--space-card); border-radius: var(--radius-card); }</code></pre><h3>تمرین</h3><p>برای رنگ، فاصله و شعاع گوشه‌ها توکن تعریف کن و سه مؤلفه را فقط با توکن‌ها سبک بده.</p><h3>نکته فنی</h3><p>نام متغیر باید معنایی باشد؛ مقدار ثابت تکراری را بی‌هدف به متغیر تبدیل نکن.</p><h3>معیار موفقیت</h3><p>تغییر یک توکن، همه مؤلفه‌های وابسته را هماهنگ به‌روزرسانی کند.</p>","starter_code":":root { --color-brand: #174ea6; --space-card: 1.25rem; --radius-card: .8rem; }\n.card { color: var(--color-brand); padding: var(--space-card); border-radius: var(--radius-card); }","exercise":"برای رنگ، فاصله و شعاع گوشه‌ها توکن تعریف کن و سه مؤلفه را فقط با توکن‌ها سبک بده.","status":"published","sort_order":10,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-11","course_id":"css-intermediate","title":"ثبت نوع متغیر با @property","slug":"css-intermediate-11","summary":"@property نوع و رفتار custom property را ثبت می‌کند؛ این کار می‌تواند مقدار اولیه و قابلیت انیمیشن نوع‌دار را مشخص کند.","content_html":"<h3>هدف درس</h3><p>@property نوع و رفتار custom property را ثبت می‌کند؛ این کار می‌تواند مقدار اولیه و قابلیت انیمیشن نوع‌دار را مشخص کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@property --progress {\n  syntax: \"&lt;percentage&gt;\";\n  inherits: false;\n  initial-value: 0%;\n}\n.bar { width: var(--progress); }</code></pre><h3>تمرین</h3><p>یک متغیر درصدی ثبت کن و مقدار نامعتبر را آزمایش کن؛ تفاوت آن را با custom property ثبت‌نشده توضیح بده.</p><h3>نکته فنی</h3><p>syntax و initial-value باید با هم سازگار باشند و پشتیبانی مرورگر بررسی شود.</p><h3>معیار موفقیت</h3><p>مقدار متغیر مطابق نوع ثبت‌شده پردازش شود.</p>","starter_code":"@property --progress {\n  syntax: \"<percentage>\";\n  inherits: false;\n  initial-value: 0%;\n}\n.bar { width: var(--progress); }","exercise":"یک متغیر درصدی ثبت کن و مقدار نامعتبر را آزمایش کن؛ تفاوت آن را با custom property ثبت‌نشده توضیح بده.","status":"published","sort_order":11,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-12","course_id":"css-intermediate","title":"ساخت تم پویا با متغیرهای وابسته","slug":"css-intermediate-12","summary":"تم پویا با تغییر مجموعه توکن‌ها ساخته می‌شود؛ بهتر است رنگ معنایی مانند surface و text تعریف شود نه رنگ وابسته به نام مؤلفه.","content_html":"<h3>هدف درس</h3><p>تم پویا با تغییر مجموعه توکن‌ها ساخته می‌شود؛ بهتر است رنگ معنایی مانند surface و text تعریف شود نه رنگ وابسته به نام مؤلفه.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --surface: white; --text: #172033; }\n[data-theme=\"dark\"] { --surface: #172033; --text: #f8fafc; }\nbody { background: var(--surface); color: var(--text); }</code></pre><h3>تمرین</h3><p>تم روشن و تاریک بساز و سه مؤلفه را با توکن‌های معنایی هماهنگ کن.</p><h3>نکته فنی</h3><p>کنتراست هر تم باید جداگانه بررسی شود؛ وارونه‌کردن رنگ‌ها به‌تنهایی کافی نیست.</p><h3>معیار موفقیت</h3><p>هر دو تم خوانا باشند و تغییر data-theme ظاهر همه مؤلفه‌ها را تغییر دهد.</p>","starter_code":":root { --surface: white; --text: #172033; }\n[data-theme=\"dark\"] { --surface: #172033; --text: #f8fafc; }\nbody { background: var(--surface); color: var(--text); }","exercise":"تم روشن و تاریک بساز و سه مؤلفه را با توکن‌های معنایی هماهنگ کن.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-13","course_id":"css-intermediate","title":"رنگ‌های مدرن با oklch و color-mix","slug":"css-intermediate-13","summary":"OKLCH رنگ را با روشنایی، کروما و فام توصیف می‌کند و color-mix امکان ترکیب رنگ در فضای مشخص را می‌دهد.","content_html":"<h3>هدف درس</h3><p>OKLCH رنگ را با روشنایی، کروما و فام توصیف می‌کند و color-mix امکان ترکیب رنگ در فضای مشخص را می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --brand: oklch(55% .18 250); }\n.button { background: var(--brand); }\n.button:hover { background: color-mix(in oklch, var(--brand), black 12%); }</code></pre><h3>تمرین</h3><p>یک رنگ برند در OKLCH تعریف کن و برای hover با color-mix نسخه تیره‌تر بساز؛ تفاوت ادراکی را مشاهده کن.</p><h3>نکته فنی</h3><p>نمایشگر و مرورگر ممکن است gamut متفاوت داشته باشند؛ خروجی نهایی را روی دستگاه واقعی بررسی کن.</p><h3>معیار موفقیت</h3><p>رنگ پایه و حالت hover هماهنگ و خوانا باشند.</p>","starter_code":":root { --brand: oklch(55% .18 250); }\n.button { background: var(--brand); }\n.button:hover { background: color-mix(in oklch, var(--brand), black 12%); }","exercise":"یک رنگ برند در OKLCH تعریف کن و برای hover با color-mix نسخه تیره‌تر بساز؛ تفاوت ادراکی را مشاهده کن.","status":"published","sort_order":13,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-14","course_id":"css-intermediate","title":"شفافیت و ترکیب رنگ‌های نسبی","slug":"css-intermediate-14","summary":"رنگ‌های نسبی می‌توانند از یک رنگ پایه کانال‌ها را استخراج و تغییر دهند؛ برای ساخت طیف منسجم مفیدند.","content_html":"<h3>هدف درس</h3><p>رنگ‌های نسبی می‌توانند از یک رنگ پایه کانال‌ها را استخراج و تغییر دهند؛ برای ساخت طیف منسجم مفیدند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --brand: oklch(60% .16 250); }\n.badge { background: oklch(from var(--brand) calc(l + .25) c h); color: oklch(from var(--brand) .2 .02 h); }</code></pre><h3>تمرین</h3><p>از یک رنگ پایه، نسخه روشن و تیره بساز و کنتراست متن روی هرکدام را بررسی کن.</p><h3>نکته فنی</h3><p>نحو رنگ نسبی جدید است؛ برای پروژه واقعی fallback و پشتیبانی مرورگر را بررسی کن.</p><h3>معیار موفقیت</h3><p>نسخه‌های رنگی از رنگ پایه مشتق شوند و کنتراست مناسب داشته باشند.</p>","starter_code":":root { --brand: oklch(60% .16 250); }\n.badge { background: oklch(from var(--brand) calc(l + .25) c h); color: oklch(from var(--brand) .2 .02 h); }","exercise":"از یک رنگ پایه، نسخه روشن و تیره بساز و کنتراست متن روی هرکدام را بررسی کن.","status":"published","sort_order":14,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-15","course_id":"css-intermediate","title":"مدیریت gamut و رنگ نمایشگر","slug":"css-intermediate-15","summary":"رنگ خارج از gamut نمایشگر ممکن است نگاشت شود؛ انتخاب فضای رنگ و fallback روی خروجی نهایی اثر دارد.","content_html":"<h3>هدف درس</h3><p>رنگ خارج از gamut نمایشگر ممکن است نگاشت شود؛ انتخاب فضای رنگ و fallback روی خروجی نهایی اثر دارد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>:root { --brand-fallback: #2563eb; --brand-wide: color(display-p3 0.1 0.35 0.9); }\n.button { background: var(--brand-fallback); background: var(--brand-wide); }</code></pre><h3>تمرین</h3><p>یک رنگ fallback و یک رنگ wide-gamut تعریف کن و با ابزار توسعه‌دهنده بررسی کن کدام مرورگر کدام مقدار را می‌پذیرد.</p><h3>نکته فنی</h3><p>رنگ گسترده‌تر تضمین نمی‌کند همه نمایشگرها آن را یکسان نشان دهند.</p><h3>معیار موفقیت</h3><p>در مرورگر فاقد پشتیبانی، fallback معتبر باقی بماند.</p>","starter_code":":root { --brand-fallback: #2563eb; --brand-wide: color(display-p3 0.1 0.35 0.9); }\n.button { background: var(--brand-fallback); background: var(--brand-wide); }","exercise":"یک رنگ fallback و یک رنگ wide-gamut تعریف کن و با ابزار توسعه‌دهنده بررسی کن کدام مرورگر کدام مقدار را می‌پذیرد.","status":"published","sort_order":15,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-16","course_id":"css-intermediate","title":"ماسک‌کردن لایه‌ها با mask","slug":"css-intermediate-16","summary":"mask با کانال آلفا یا روشنایی بخش‌هایی از عنصر را آشکار یا پنهان می‌کند و برای جلوه‌های تصویری کاربرد دارد.","content_html":"<h3>هدف درس</h3><p>mask با کانال آلفا یا روشنایی بخش‌هایی از عنصر را آشکار یا پنهان می‌کند و برای جلوه‌های تصویری کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.avatar { mask-image: linear-gradient(to bottom, black 70%, transparent); }\n.logo { -webkit-mask-image: url(\"shape.svg\"); mask-image: url(\"shape.svg\"); }</code></pre><h3>تمرین</h3><p>تصویری را با ماسک گرادیانی محو کن و نسخه بدون mask را به‌عنوان fallback نگه دار.</p><h3>نکته فنی</h3><p>محتوای ضروری را فقط با ماسک یا تصویر پس‌زمینه منتقل نکن.</p><h3>معیار موفقیت</h3><p>تصویر در حالت پشتیبانی و عدم پشتیبانی قابل فهم باقی بماند.</p>","starter_code":".avatar { mask-image: linear-gradient(to bottom, black 70%, transparent); }\n.logo { -webkit-mask-image: url(\"shape.svg\"); mask-image: url(\"shape.svg\"); }","exercise":"تصویری را با ماسک گرادیانی محو کن و نسخه بدون mask را به‌عنوان fallback نگه دار.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-17","course_id":"css-intermediate","title":"برش شکل‌ها با clip-path","slug":"css-intermediate-17","summary":"clip-path ناحیه قابل مشاهده عنصر را به شکل مشخص محدود می‌کند و برای ساخت قاب‌های هندسی مفید است.","content_html":"<h3>هدف درس</h3><p>clip-path ناحیه قابل مشاهده عنصر را به شکل مشخص محدود می‌کند و برای ساخت قاب‌های هندسی مفید است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.thumbnail { clip-path: polygon(0 0, 100% 0, 88% 100%, 0 100%); }\n.avatar { clip-path: circle(48%); }</code></pre><h3>تمرین</h3><p>یک تصویر کارت را با polygon برش بده و نسخه دایره‌ای بساز؛ متن جایگزین و اندازه تصویر را حفظ کن.</p><h3>نکته فنی</h3><p>clip-path فقط نمایش را برش می‌دهد؛ فضای چیدمان عنصر همچنان مستطیلی است.</p><h3>معیار موفقیت</h3><p>برش بصری بدون حذف اطلاعات ضروری انجام شود.</p>","starter_code":".thumbnail { clip-path: polygon(0 0, 100% 0, 88% 100%, 0 100%); }\n.avatar { clip-path: circle(48%); }","exercise":"یک تصویر کارت را با polygon برش بده و نسخه دایره‌ای بساز؛ متن جایگزین و اندازه تصویر را حفظ کن.","status":"published","sort_order":17,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-18","course_id":"css-intermediate","title":"ترکیب لایه‌ها با blend modes","slug":"css-intermediate-18","summary":"blend modes نحوه ترکیب رنگ یک لایه با زمینه را تعیین می‌کنند و باید با پس‌زمینه واقعی آزمایش شوند.","content_html":"<h3>هدف درس</h3><p>blend modes نحوه ترکیب رنگ یک لایه با زمینه را تعیین می‌کنند و باید با پس‌زمینه واقعی آزمایش شوند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.hero { background: linear-gradient(#102a43aa,#102a43aa), url(\"hero.jpg\") center/cover; background-blend-mode: multiply; }\n.icon { mix-blend-mode: screen; }</code></pre><h3>تمرین</h3><p>یک تصویر قهرمان با overlay بساز و تفاوت background-blend-mode و mix-blend-mode را بررسی کن.</p><h3>نکته فنی</h3><p>ترکیب رنگ می‌تواند کنتراست متن را کاهش دهد؛ خوانایی را آزمایش کن.</p><h3>معیار موفقیت</h3><p>متن روی تصویر در حالت‌های مختلف همچنان خوانا بماند.</p>","starter_code":".hero { background: linear-gradient(#102a43aa,#102a43aa), url(\"hero.jpg\") center/cover; background-blend-mode: multiply; }\n.icon { mix-blend-mode: screen; }","exercise":"یک تصویر قهرمان با overlay بساز و تفاوت background-blend-mode و mix-blend-mode را بررسی کن.","status":"published","sort_order":18,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-19","course_id":"css-intermediate","title":"ساخت شکل‌های متنی با CSS Shapes","slug":"css-intermediate-19","summary":"CSS Shapes اجازه می‌دهد متن پیرامون شکل شناور جریان یابد؛ این روش برای چیدمان تحریریه‌ای کاربرد دارد.","content_html":"<h3>هدف درس</h3><p>CSS Shapes اجازه می‌دهد متن پیرامون شکل شناور جریان یابد؛ این روش برای چیدمان تحریریه‌ای کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.portrait { float: inline-start; width: 9rem; aspect-ratio: 1; shape-outside: circle(50%); clip-path: circle(50%); margin-inline-end: 1rem; }</code></pre><h3>تمرین</h3><p>متن مقاله را پیرامون تصویر دایره‌ای جاری کن و تفاوت shape-outside با clip-path را توضیح بده.</p><h3>نکته فنی</h3><p>shape-outside معمولاً به عنصر شناور نیاز دارد و جایگزین Grid/Flex برای چیدمان عمومی نیست.</p><h3>معیار موفقیت</h3><p>متن در اطراف شکل جریان یابد و در عرض کم به‌هم نریزد.</p>","starter_code":".portrait { float: inline-start; width: 9rem; aspect-ratio: 1; shape-outside: circle(50%); clip-path: circle(50%); margin-inline-end: 1rem; }","exercise":"متن مقاله را پیرامون تصویر دایره‌ای جاری کن و تفاوت shape-outside با clip-path را توضیح بده.","status":"published","sort_order":19,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-20","course_id":"css-intermediate","title":"پیمایش مرحله‌ای با scroll-snap","slug":"css-intermediate-20","summary":"scroll-snap موقعیت توقف پیمایش را به نقاط مشخص محدود می‌کند و برای گالری افقی یا مراحل مناسب است.","content_html":"<h3>هدف درس</h3><p>scroll-snap موقعیت توقف پیمایش را به نقاط مشخص محدود می‌کند و برای گالری افقی یا مراحل مناسب است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.gallery { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; }\n.gallery &gt; article { flex: 0 0 85%; scroll-snap-align: start; }</code></pre><h3>تمرین</h3><p>گالری سه‌کارتی بساز که هر کارت در ابتدای ناحیه دید متوقف شود؛ پیمایش لمسی و صفحه‌کلید را بررسی کن.</p><h3>نکته فنی</h3><p>scroll snap نباید کنترل پیمایش آزاد یا دسترسی به محتوای میانی را مختل کند.</p><h3>معیار موفقیت</h3><p>هر کارت قابل دسترسی باشد و توقف پیمایش آزاردهنده نباشد.</p>","starter_code":".gallery { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; }\n.gallery > article { flex: 0 0 85%; scroll-snap-align: start; }","exercise":"گالری سه‌کارتی بساز که هر کارت در ابتدای ناحیه دید متوقف شود؛ پیمایش لمسی و صفحه‌کلید را بررسی کن.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-21","course_id":"css-intermediate","title":"کنترل رفتار پیمایش با scroll-behavior و overscroll","slug":"css-intermediate-21","summary":"scroll-behavior کنترل پیمایش نرم و overscroll-behavior کنترل زنجیره انتقال پیمایش به والد را فراهم می‌کند.","content_html":"<h3>هدف درس</h3><p>scroll-behavior کنترل پیمایش نرم و overscroll-behavior کنترل زنجیره انتقال پیمایش به والد را فراهم می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>html { scroll-behavior: smooth; }\n.modal-list { overflow: auto; overscroll-behavior: contain; }</code></pre><h3>تمرین</h3><p>یک پنجره فهرست بلند بساز و بررسی کن هنگام رسیدن به انتهای آن صفحه پشت پنجره ناخواسته حرکت نکند.</p><h3>نکته فنی</h3><p>برای کاربرانی که حرکت کمتر می‌خواهند باید رفتار نرم را محدود یا غیرفعال کرد.</p><h3>معیار موفقیت</h3><p>پیمایش داخلی کنترل شود و مسیر خروج از محتوا مسدود نشود.</p>","starter_code":"html { scroll-behavior: smooth; }\n.modal-list { overflow: auto; overscroll-behavior: contain; }","exercise":"یک پنجره فهرست بلند بساز و بررسی کن هنگام رسیدن به انتهای آن صفحه پشت پنجره ناخواسته حرکت نکند.","status":"published","sort_order":21,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-22","course_id":"css-intermediate","title":"انیمیشن مبتنی بر پیمایش","slug":"css-intermediate-22","summary":"scroll-driven animations پیشرفت انیمیشن را به موقعیت پیمایش متصل می‌کنند؛ برای شاخص پیشرفت خواندن کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>scroll-driven animations پیشرفت انیمیشن را به موقعیت پیمایش متصل می‌کنند؛ برای شاخص پیشرفت خواندن کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@keyframes reading { from { transform: scaleX(0); } to { transform: scaleX(1); } }\n.progress { transform-origin: left; animation: reading linear; animation-timeline: scroll(root block); }</code></pre><h3>تمرین</h3><p>نوار پیشرفت خواندن بساز و در مرورگر پشتیبان حرکت آن را با پیمایش هماهنگ کن؛ fallback ساده ارائه بده.</p><h3>نکته فنی</h3><p>این قابلیت هنوز در همه محیط‌ها یکسان نیست و نباید اطلاعات حیاتی را فقط با آن منتقل کرد.</p><h3>معیار موفقیت</h3><p>نوار در مرورگر پشتیبان با پیمایش پیش برود و در سایر مرورگرها محتوا سالم بماند.</p>","starter_code":"@keyframes reading { from { transform: scaleX(0); } to { transform: scaleX(1); } }\n.progress { transform-origin: left; animation: reading linear; animation-timeline: scroll(root block); }","exercise":"نوار پیشرفت خواندن بساز و در مرورگر پشتیبان حرکت آن را با پیمایش هماهنگ کن؛ fallback ساده ارائه بده.","status":"published","sort_order":22,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-23","course_id":"css-intermediate","title":"موقعیت‌دهی لنگری با anchor positioning","slug":"css-intermediate-23","summary":"anchor positioning می‌تواند یک عنصر را نسبت به عنصر لنگر جای دهد بدون آنکه والد موقعیت‌دار مشترک لازم باشد؛ پشتیبانی مرورگر مهم است.","content_html":"<h3>هدف درس</h3><p>anchor positioning می‌تواند یک عنصر را نسبت به عنصر لنگر جای دهد بدون آنکه والد موقعیت‌دار مشترک لازم باشد؛ پشتیبانی مرورگر مهم است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.trigger { anchor-name: --help-anchor; }\n.tip { position: absolute; position-anchor: --help-anchor; position-area: block-end; }</code></pre><h3>تمرین</h3><p>راهنمایی را نسبت به دکمه لنگر قرار بده و در viewport کوچک احتمال بیرون‌زدن آن را بررسی کن.</p><h3>نکته فنی</h3><p>Anchor positioning قابلیت نوظهور است؛ برای تولید، fallback و پشتیبانی هدف را بسنج.</p><h3>معیار موفقیت</h3><p>راهنما در جای درست قرار بگیرد و مسیر جایگزین وجود داشته باشد.</p>","starter_code":".trigger { anchor-name: --help-anchor; }\n.tip { position: absolute; position-anchor: --help-anchor; position-area: block-end; }","exercise":"راهنمایی را نسبت به دکمه لنگر قرار بده و در viewport کوچک احتمال بیرون‌زدن آن را بررسی کن.","status":"published","sort_order":23,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-24","course_id":"css-intermediate","title":"زیرشبکه‌بندی با subgrid","slug":"css-intermediate-24","summary":"subgrid اجازه می‌دهد ردیف یا ستون فرزند، خطوط شبکه والد را به ارث ببرد؛ برای هم‌ترازی کارت‌های چندردیفه مفید است.","content_html":"<h3>هدف درس</h3><p>subgrid اجازه می‌دهد ردیف یا ستون فرزند، خطوط شبکه والد را به ارث ببرد؛ برای هم‌ترازی کارت‌های چندردیفه مفید است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.catalog {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  grid-template-rows: repeat(3, auto);\n}\n.card {\n  display: grid;\n  grid-row: span 3;\n  grid-template-rows: subgrid;\n}</code></pre><h3>تمرین</h3><p>سه کارت با عنوان، توضیح و دکمه بساز؛ با subgrid دکمه‌ها را در یک خط هم‌تراز کن.</p><h3>نکته فنی</h3><p>برای subgrid در محور ردیف، عنصر والد باید ردیف‌هایی برای به‌ارث‌رسیدن تعریف کند؛ در این نمونه هر کارت سه ردیف مشترک را می‌گیرد.</p><h3>معیار موفقیت</h3><p>عنوان، توضیح و دکمه کارت‌ها روی خطوط ردیف مشترک هم‌تراز شوند و در مرورگر بدون subgrid fallback قابل استفاده بماند.</p>","starter_code":".catalog {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  grid-template-rows: repeat(3, auto);\n}\n.card {\n  display: grid;\n  grid-row: span 3;\n  grid-template-rows: subgrid;\n}","exercise":"سه کارت با عنوان، توضیح و دکمه بساز؛ با subgrid دکمه‌ها را در یک خط هم‌تراز کن.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-25","course_id":"css-intermediate","title":"بهینه‌سازی رندر با containment","slug":"css-intermediate-25","summary":"contain به مرورگر مرز اثر layout، paint یا size را اعلام می‌کند و می‌تواند هزینه بازچینی بخش‌های مستقل را کاهش دهد.","content_html":"<h3>هدف درس</h3><p>contain به مرورگر مرز اثر layout، paint یا size را اعلام می‌کند و می‌تواند هزینه بازچینی بخش‌های مستقل را کاهش دهد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.widget { contain: layout paint; }\n.isolated-panel { contain: content; }</code></pre><h3>تمرین</h3><p>یک ویجت مستقل بساز و با ابزار توسعه‌دهنده تغییرات رندر را بررسی کن؛ اثر contain را روی overflow بسنج.</p><h3>نکته فنی</h3><p>contain ممکن است containing block و clipping ایجاد کند؛ بی‌دلیل روی کل صفحه اعمال نکن.</p><h3>معیار موفقیت</h3><p>ویجت مستقل بماند و محتوای لازم بریده یا جابه‌جا نشود.</p>","starter_code":".widget { contain: layout paint; }\n.isolated-panel { contain: content; }","exercise":"یک ویجت مستقل بساز و با ابزار توسعه‌دهنده تغییرات رندر را بررسی کن؛ اثر contain را روی overflow بسنج.","status":"published","sort_order":25,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-26","course_id":"css-intermediate","title":"نمایش محتوای دور از دید با content-visibility","slug":"css-intermediate-26","summary":"content-visibility می‌تواند رندر محتوای دور از دید را به تعویق بیندازد؛ contain-intrinsic-size فضای تقریبی آن را حفظ می‌کند.","content_html":"<h3>هدف درس</h3><p>content-visibility می‌تواند رندر محتوای دور از دید را به تعویق بیندازد؛ contain-intrinsic-size فضای تقریبی آن را حفظ می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.lesson-section { content-visibility: auto; contain-intrinsic-size: auto 32rem; }</code></pre><h3>تمرین</h3><p>برای صفحه بلند درس‌ها از content-visibility استفاده کن و پرش چیدمان هنگام پیمایش را اندازه‌گیری کن.</p><h3>نکته فنی</h3><p>این ویژگی جای lazy loading تصویر را نمی‌گیرد و اندازه ذاتی تقریبی باید منطقی باشد.</p><h3>معیار موفقیت</h3><p>بخش خارج از دید سبک‌تر رندر شود و پرش شدید چیدمان رخ ندهد.</p>","starter_code":".lesson-section { content-visibility: auto; contain-intrinsic-size: auto 32rem; }","exercise":"برای صفحه بلند درس‌ها از content-visibility استفاده کن و پرش چیدمان هنگام پیمایش را اندازه‌گیری کن.","status":"published","sort_order":26,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-27","course_id":"css-intermediate","title":"فونت متغیر و محورهای سفارشی","slug":"css-intermediate-27","summary":"فونت متغیر چند محور مانند وزن و عرض را در یک فایل ارائه می‌کند؛ محورهای سفارشی با font-variation-settings قابل کنترل‌اند.","content_html":"<h3>هدف درس</h3><p>فونت متغیر چند محور مانند وزن و عرض را در یک فایل ارائه می‌کند؛ محورهای سفارشی با font-variation-settings قابل کنترل‌اند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@font-face { font-family: AcademyVF; src: url(\"academy-variable.woff2\") format(\"woff2\"); font-weight: 100 900; }\n.title { font-family: AcademyVF, sans-serif; font-weight: 650; font-stretch: 95%; }</code></pre><h3>تمرین</h3><p>یک فونت متغیر دارای دامنه وزن تعریف کن و وزن‌های مختلف را مقایسه کن؛ اگر فایل واقعی نداری نام آن را نمونه نگه دار.</p><h3>نکته فنی</h3><p>دامنه font-weight باید با قابلیت واقعی فایل فونت هماهنگ باشد.</p><h3>معیار موفقیت</h3><p>مرورگر فایل را بارگیری کند و وزن‌های درخواستی به‌درستی نمایش داده شوند.</p>","starter_code":"@font-face { font-family: AcademyVF; src: url(\"academy-variable.woff2\") format(\"woff2\"); font-weight: 100 900; }\n.title { font-family: AcademyVF, sans-serif; font-weight: 650; font-stretch: 95%; }","exercise":"یک فونت متغیر دارای دامنه وزن تعریف کن و وزن‌های مختلف را مقایسه کن؛ اگر فایل واقعی نداری نام آن را نمونه نگه دار.","status":"published","sort_order":27,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-28","course_id":"css-intermediate","title":"بارگذاری فونت با font-face و font-display","slug":"css-intermediate-28","summary":"@font-face فونت محلی را ثبت می‌کند و font-display رفتار متن هنگام بارگیری فونت را کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>@font-face فونت محلی را ثبت می‌کند و font-display رفتار متن هنگام بارگیری فونت را کنترل می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@font-face { font-family: Academy; src: url(\"academy.woff2\") format(\"woff2\"); font-display: swap; }\nbody { font-family: Academy, sans-serif; }</code></pre><h3>تمرین</h3><p>فونت فارسی را با swap تعریف کن و رفتار متن پیش و پس از بارگیری را بررسی کن.</p><h3>نکته فنی</h3><p>فرمت و مجوز استفاده از فونت را بررسی کن؛ فایل بزرگ می‌تواند بارگذاری را کند کند.</p><h3>معیار موفقیت</h3><p>متن هنگام بارگیری پنهان نماند و fallback خوانا باشد.</p>","starter_code":"@font-face { font-family: Academy; src: url(\"academy.woff2\") format(\"woff2\"); font-display: swap; }\nbody { font-family: Academy, sans-serif; }","exercise":"فونت فارسی را با swap تعریف کن و رفتار متن پیش و پس از بارگیری را بررسی کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-29","course_id":"css-intermediate","title":"شمارنده‌های خودکار با CSS counters","slug":"css-intermediate-29","summary":"CSS counters شمارنده‌های خودکار برای شماره‌گذاری فصل‌ها و بخش‌ها می‌سازند و بدون تغییر متن HTML خروجی شماره‌دار ارائه می‌کنند.","content_html":"<h3>هدف درس</h3><p>CSS counters شمارنده‌های خودکار برای شماره‌گذاری فصل‌ها و بخش‌ها می‌سازند و بدون تغییر متن HTML خروجی شماره‌دار ارائه می‌کنند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.chapter { counter-reset: section; }\n.chapter h2 { counter-increment: section; }\n.chapter h2::before { content: counter(section) \". \"; }</code></pre><h3>تمرین</h3><p>فهرست فصل‌ها بساز و هر h2 را شماره‌گذاری کن؛ ترتیب و reset شمارنده را بررسی کن.</p><h3>نکته فنی</h3><p>شمارنده تزئینی نباید تنها منبع اطلاعات ضروری باشد؛ متن و ساختار واقعی را حفظ کن.</p><h3>معیار موفقیت</h3><p>شماره‌ها در هر فصل از ابتدا شروع شوند.</p>","starter_code":".chapter { counter-reset: section; }\n.chapter h2 { counter-increment: section; }\n.chapter h2::before { content: counter(section) \". \"; }","exercise":"فهرست فصل‌ها بساز و هر h2 را شماره‌گذاری کن؛ ترتیب و reset شمارنده را بررسی کن.","status":"published","sort_order":29,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-30","course_id":"css-intermediate","title":"قواعد چاپ حرفه‌ای با page و break","slug":"css-intermediate-30","summary":"قواعد چاپ با @page اندازه و حاشیه صفحه را تنظیم می‌کنند و break کنترل شکست صفحه را برعهده دارد.","content_html":"<h3>هدف درس</h3><p>قواعد چاپ با @page اندازه و حاشیه صفحه را تنظیم می‌کنند و break کنترل شکست صفحه را برعهده دارد.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@page { size: A4; margin: 18mm; }\n.report-section { break-inside: avoid; }\n.no-print { display: none; }</code></pre><h3>تمرین</h3><p>گزارش چندبخشی بساز و نسخه چاپی A4 را پیش‌نمایش بگیر؛ شکست ناخواسته عنوان و جدول را اصلاح کن.</p><h3>نکته فنی</h3><p>پشتیبانی ویژگی‌های چاپ میان مرورگرها و چاپگرها متفاوت است.</p><h3>معیار موفقیت</h3><p>نسخه چاپی خوانا باشد و بخش‌های مهم بی‌دلیل نصف نشوند.</p>","starter_code":"@page { size: A4; margin: 18mm; }\n.report-section { break-inside: avoid; }\n.no-print { display: none; }","exercise":"گزارش چندبخشی بساز و نسخه چاپی A4 را پیش‌نمایش بگیر؛ شکست ناخواسته عنوان و جدول را اصلاح کن.","status":"published","sort_order":30,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-31","course_id":"css-intermediate","title":"افزایش تدریجی با @supports","slug":"css-intermediate-31","summary":"@supports امکان فعال‌کردن سبک پیشرفته فقط در مرورگری را می‌دهد که ویژگی لازم را می‌شناسد؛ پایه باید قبل از آن تعریف شود.","content_html":"<h3>هدف درس</h3><p>@supports امکان فعال‌کردن سبک پیشرفته فقط در مرورگری را می‌دهد که ویژگی لازم را می‌شناسد؛ پایه باید قبل از آن تعریف شود.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.card { display: block; }\n@supports (display: grid) { .card-list { display: grid; grid-template-columns: repeat(2, 1fr); } }</code></pre><h3>تمرین</h3><p>یک fallback ساده و یک چیدمان پیشرفته تعریف کن؛ با ابزار توسعه‌دهنده پشتیبانی ویژگی را بررسی کن.</p><h3>نکته فنی</h3><p>@supports پشتیبانی نحوی را می‌سنجد، نه کیفیت یا رفتار کامل ویژگی را.</p><h3>معیار موفقیت</h3><p>در نبود پشتیبانی، صفحه همچنان قابل استفاده باشد.</p>","starter_code":".card { display: block; }\n@supports (display: grid) { .card-list { display: grid; grid-template-columns: repeat(2, 1fr); } }","exercise":"یک fallback ساده و یک چیدمان پیشرفته تعریف کن؛ با ابزار توسعه‌دهنده پشتیبانی ویژگی را بررسی کن.","status":"published","sort_order":31,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-32","course_id":"css-intermediate","title":"استایل‌دهی بر اساس ویژگی والد با style queries","slug":"css-intermediate-32","summary":"Style Queries می‌توانند سبک فرزند را بر اساس custom property والد انتخاب کنند؛ این الگو برای مؤلفه‌های قابل تنظیم مفید است.","content_html":"<h3>هدف درس</h3><p>Style Queries می‌توانند سبک فرزند را بر اساس custom property والد انتخاب کنند؛ این الگو برای مؤلفه‌های قابل تنظیم مفید است.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@container style(--density: compact) {\n  .item { padding-block: .35rem; }\n}\n.list { --density: compact; }</code></pre><h3>تمرین</h3><p>یک فهرست با حالت compact و comfortable بساز و style query را برای فاصله داخلی اعمال کن.</p><h3>نکته فنی</h3><p>Style Queries نسبتاً جدیدند؛ fallback کلاس‌محور برای مرورگرهای هدف فراهم کن.</p><h3>معیار موفقیت</h3><p>هر حالت در مرورگر پشتیبان درست و در مرورگر دیگر قابل استفاده باشد.</p>","starter_code":"@container style(--density: compact) {\n  .item { padding-block: .35rem; }\n}\n.list { --density: compact; }","exercise":"یک فهرست با حالت compact و comfortable بساز و style query را برای فاصله داخلی اعمال کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-33","course_id":"css-intermediate","title":"انیمیشن ورود با @starting-style","slug":"css-intermediate-33","summary":"@starting-style سبک آغازین عنصر تازه‌وارد یا تازه قابل نمایش را تعریف می‌کند تا transition از حالت اولیه اجرا شود.","content_html":"<h3>هدف درس</h3><p>@starting-style سبک آغازین عنصر تازه‌وارد یا تازه قابل نمایش را تعریف می‌کند تا transition از حالت اولیه اجرا شود.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.toast { opacity: 1; transform: translateY(0); transition: opacity .2s, transform .2s; }\n@starting-style { .toast { opacity: 0; transform: translateY(12px); } }</code></pre><h3>تمرین</h3><p>برای پیام وضعیت که به DOM افزوده می‌شود ورود نرم بساز و حالت کاهش حرکت را هم اضافه کن.</p><h3>نکته فنی</h3><p>انیمیشن نباید مانع دسترسی به پیام یا باعث حرکت آزاردهنده شود.</p><h3>معیار موفقیت</h3><p>پیام در مرورگر پشتیبان نرم ظاهر شود و حالت پایه نیز درست باشد.</p>","starter_code":".toast { opacity: 1; transform: translateY(0); transition: opacity .2s, transform .2s; }\n@starting-style { .toast { opacity: 0; transform: translateY(12px); } }","exercise":"برای پیام وضعیت که به DOM افزوده می‌شود ورود نرم بساز و حالت کاهش حرکت را هم اضافه کن.","status":"published","sort_order":33,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-34","course_id":"css-intermediate","title":"تعویض نما با View Transitions CSS","slug":"css-intermediate-34","summary":"View Transitions API تغییر نما را میان دو وضعیت صفحه هموار می‌کند؛ CSS نام‌گذاری عناصر و انیمیشن گذار را تعریف می‌کند.","content_html":"<h3>هدف درس</h3><p>View Transitions API تغییر نما را میان دو وضعیت صفحه هموار می‌کند؛ CSS نام‌گذاری عناصر و انیمیشن گذار را تعریف می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>::view-transition-old(root) { animation: fade-out .18s ease-in; }\n::view-transition-new(root) { animation: fade-in .22s ease-out; }\n@keyframes fade-out { to { opacity: 0; } }\n@keyframes fade-in { from { opacity: 0; } }</code></pre><h3>تمرین</h3><p>برای تغییر محتوای یک صفحه آزمایشی view transition تعریف کن و مسیر بدون پشتیبانی را هم بررسی کن.</p><h3>نکته فنی</h3><p>API به فراخوانی JavaScript و شرایط مرورگر نیاز دارد؛ CSS به‌تنهایی انتقال را آغاز نمی‌کند.</p><h3>معیار موفقیت</h3><p>محتوا بدون API نیز قابل استفاده باشد و حرکت با تنظیمات کاربر سازگار شود.</p>","starter_code":"::view-transition-old(root) { animation: fade-out .18s ease-in; }\n::view-transition-new(root) { animation: fade-in .22s ease-out; }\n@keyframes fade-out { to { opacity: 0; } }\n@keyframes fade-in { from { opacity: 0; } }","exercise":"برای تغییر محتوای یک صفحه آزمایشی view transition تعریف کن و مسیر بدون پشتیبانی را هم بررسی کن.","status":"published","sort_order":34,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-35","course_id":"css-intermediate","title":"طراحی مؤلفه‌های مقاوم با fallback","slug":"css-intermediate-35","summary":"مؤلفه مقاوم باید fallback، حالت پشتیبانی و عدم پشتیبانی را از ابتدا در نظر بگیرد و از ویژگی‌های آزمایشی به‌عنوان تنها مسیر استفاده نکند.","content_html":"<h3>هدف درس</h3><p>مؤلفه مقاوم باید fallback، حالت پشتیبانی و عدم پشتیبانی را از ابتدا در نظر بگیرد و از ویژگی‌های آزمایشی به‌عنوان تنها مسیر استفاده نکند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>.panel { display: block; }\n@supports (display: grid) { .panel { display: grid; grid-template-columns: 1fr 2fr; gap: 1rem; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; } }</code></pre><h3>تمرین</h3><p>یک مؤلفه بساز که در مرورگر بدون Grid و با تنظیم reduced motion همچنان کار کند؛ دو حالت را مستند کن.</p><h3>نکته فنی</h3><p>fallback باید تجربه قابل استفاده بدهد، نه صرفاً ظاهر ناقص.</p><h3>معیار موفقیت</h3><p>مؤلفه در حالت پایه، پشتیبانی پیشرفته و کاهش حرکت قابل استفاده باشد.</p>","starter_code":".panel { display: block; }\n@supports (display: grid) { .panel { display: grid; grid-template-columns: 1fr 2fr; gap: 1rem; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; } }","exercise":"یک مؤلفه بساز که در مرورگر بدون Grid و با تنظیم reduced motion همچنان کار کند؛ دو حالت را مستند کن.","status":"published","sort_order":35,"estimated_minutes":40},{"id":"curriculum-324-css-intermediate-36","course_id":"css-intermediate","title":"پروژه نهایی: سیستم طراحی چندتمی","slug":"css-intermediate-36","summary":"سیستم طراحی چندتمی باید توکن‌های معنایی، لایه‌های آبشاری، مؤلفه‌های قابل تنظیم و fallback داشته باشد؛ ساختار باید توسعه‌پذیر بماند.","content_html":"<h3>هدف درس</h3><p>سیستم طراحی چندتمی باید توکن‌های معنایی، لایه‌های آبشاری، مؤلفه‌های قابل تنظیم و fallback داشته باشد؛ ساختار باید توسعه‌پذیر بماند.</p><h3>نمونه و بررسی</h3><p>نمونه را در فایل CSS قرار بده و در صفحه آزمایشی اجرا کن. قابلیت‌های نوظهور را در مرورگر هدف بررسی کن.</p><pre><code>@layer tokens, base, components, utilities;\n@layer tokens { :root { --surface: #fff; --text: #182230; --brand: #174ea6; } [data-theme=\"dark\"] { --surface: #182230; --text: #f8fafc; } }\n@layer base { body { background: var(--surface); color: var(--text); } }\n@layer components { .button { background: var(--brand); color: white; padding: .75rem 1rem; border-radius: .6rem; } }</code></pre><h3>تمرین</h3><p>یک سیستم طراحی کوچک با تم روشن/تاریک، سه مؤلفه، توکن فاصله و رنگ و لایه‌های آبشاری بساز؛ سپس ممیزی کنتراست و fallback انجام بده.</p><h3>نکته فنی</h3><p>از انباشتن selectorهای پرقدرت و !important برای حل معماری ضعیف پرهیز کن.</p><h3>معیار موفقیت</h3><p>تم‌ها هماهنگ باشند، قوانین قابل نگهداری باشند و fallback و محدودیت مرورگر مستند شود.</p>","starter_code":"@layer tokens, base, components, utilities;\n@layer tokens { :root { --surface: #fff; --text: #182230; --brand: #174ea6; } [data-theme=\"dark\"] { --surface: #182230; --text: #f8fafc; } }\n@layer base { body { background: var(--surface); color: var(--text); } }\n@layer components { .button { background: var(--brand); color: white; padding: .75rem 1rem; border-radius: .6rem; } }","exercise":"یک سیستم طراحی کوچک با تم روشن/تاریک، سه مؤلفه، توکن فاصله و رنگ و لایه‌های آبشاری بساز؛ سپس ممیزی کنتراست و fallback انجام بده.","status":"published","sort_order":36,"estimated_minutes":40},{"id":"curriculum-324-css-advanced-01","course_id":"css-advanced","title":"قرارداد معماری CSS در تیم‌های بزرگ","slug":"css-advanced-01","summary":"ساختار چندتیمی باید مرز مالکیت فایل، مؤلفه و مسئولیت تغییر را روشن کند تا سبک‌ها به هم نشت نکنند.","content_html":"<h3>هدف درس</h3><p>ساختار چندتیمی باید مرز مالکیت فایل، مؤلفه و مسئولیت تغییر را روشن کند تا سبک‌ها به هم نشت نکنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>/* entry.css */\n@import url(\"./reset.css\");\n@import url(\"./tokens.css\");\n@import url(\"./shell.css\");\n@import url(\"./features/catalog.css\");</code></pre><h3>تمرین عملی</h3><p>برای یک فروشگاه، پوشه‌ها، مالک هر بخش و روش بازبینی تغییرات CSS را در README تعریف کن.</p><h3>نکته فنی</h3><p>وابستگی دوری میان فایل‌ها و importهای پراکنده معماری را شکننده می‌کنند.</p><h3>معیار موفقیت</h3><p>هر قانون سبک جای مشخص و مالک مشخص داشته باشد.</p>","starter_code":"/* entry.css */\n@import url(\"./reset.css\");\n@import url(\"./tokens.css\");\n@import url(\"./shell.css\");\n@import url(\"./features/catalog.css\");","exercise":"برای یک فروشگاه، پوشه‌ها، مالک هر بخش و روش بازبینی تغییرات CSS را در README تعریف کن.","status":"published","sort_order":1,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-02","course_id":"css-advanced","title":"نام‌گذاری BEM در سامانه مؤلفه‌ای","slug":"css-advanced-02","summary":"BEM با الگوی block، element و modifier نام کلاس‌ها را مستقل و قابل پیش‌بینی می‌کند.","content_html":"<h3>هدف درس</h3><p>BEM با الگوی block، element و modifier نام کلاس‌ها را مستقل و قابل پیش‌بینی می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.course-card {}\n.course-card__title {}\n.course-card__meta {}\n.course-card--featured {}\n.course-card__button--disabled {}</code></pre><h3>تمرین عملی</h3><p>یک کارت دوره را با BEM نام‌گذاری کن و حالت عادی، برجسته و غیرفعال را پیاده کن.</p><h3>نکته فنی</h3><p>نام‌گذاری باید نقش مؤلفه را نشان دهد، نه محل فعلی آن در صفحه.</p><h3>معیار موفقیت</h3><p>با جابه‌جایی کارت در DOM، کلاس‌ها همچنان معنی‌دار بمانند.</p>","starter_code":".course-card {}\n.course-card__title {}\n.course-card__meta {}\n.course-card--featured {}\n.course-card__button--disabled {}","exercise":"یک کارت دوره را با BEM نام‌گذاری کن و حالت عادی، برجسته و غیرفعال را پیاده کن.","status":"published","sort_order":2,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-03","course_id":"css-advanced","title":"ایزوله‌سازی فایل با CSS Modules","slug":"css-advanced-03","summary":"CSS Modules نام کلاس‌ها را در زمان build محلی می‌کند و برخورد نام میان مؤلفه‌ها را کاهش می‌دهد.","content_html":"<h3>هدف درس</h3><p>CSS Modules نام کلاس‌ها را در زمان build محلی می‌کند و برخورد نام میان مؤلفه‌ها را کاهش می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>/* Card.module.css */\n.title { font-weight: 700; }\n.featured { border: 2px solid royalblue; }\n/* در ابزار build: styles.title */</code></pre><h3>تمرین عملی</h3><p>دو مؤلفه با کلاس هم‌نام بساز و توضیح بده CSS Modules چگونه دامنه نام را جدا می‌کند.</p><h3>نکته فنی</h3><p>این قابلیت به زنجیره build نیاز دارد و CSS خام مرورگر آن را اجرا نمی‌کند.</p><h3>معیار موفقیت</h3><p>کلاس‌های محلی بدون تداخل بین دو مؤلفه تولید شوند.</p>","starter_code":"/* Card.module.css */\n.title { font-weight: 700; }\n.featured { border: 2px solid royalblue; }\n/* در ابزار build: styles.title */","exercise":"دو مؤلفه با کلاس هم‌نام بساز و توضیح بده CSS Modules چگونه دامنه نام را جدا می‌کند.","status":"published","sort_order":3,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-04","course_id":"css-advanced","title":"مرزبندی استایل در Shadow DOM","slug":"css-advanced-04","summary":"Shadow DOM سبک‌های داخلی مؤلفه را از صفحه میزبان جدا می‌کند و برای اجزای قابل استفاده مجدد مناسب است.","content_html":"<h3>هدف درس</h3><p>Shadow DOM سبک‌های داخلی مؤلفه را از صفحه میزبان جدا می‌کند و برای اجزای قابل استفاده مجدد مناسب است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>:host { display:block; color:var(--widget-text,#222); }\n:host([compact]) { padding:.5rem; }\n.title { font:inherit; }</code></pre><h3>تمرین عملی</h3><p>برای یک مؤلفه سفارشی، تعیین کن چه سبک‌هایی باید داخلی بمانند و چه تنظیماتی به میزبان واگذار شوند.</p><h3>نکته فنی</h3><p>Shadow DOM مرز واقعی‌تری از نام‌گذاری کلاس‌ها ایجاد می‌کند، اما API ظاهری آن باید محدود باشد.</p><h3>معیار موفقیت</h3><p>تغییر CSS میزبان نتواند ناخواسته ساختار داخلی را خراب کند.</p>","starter_code":":host { display:block; color:var(--widget-text,#222); }\n:host([compact]) { padding:.5rem; }\n.title { font:inherit; }","exercise":"برای یک مؤلفه سفارشی، تعیین کن چه سبک‌هایی باید داخلی بمانند و چه تنظیماتی به میزبان واگذار شوند.","status":"published","sort_order":4,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-05","course_id":"css-advanced","title":"انتشار API ظاهری با ::part","slug":"css-advanced-05","summary":"::part فقط بخش‌هایی را هدف می‌گیرد که مؤلفه عمداً برای سفارشی‌سازی بیرونی منتشر کرده است.","content_html":"<h3>هدف درس</h3><p>::part فقط بخش‌هایی را هدف می‌گیرد که مؤلفه عمداً برای سفارشی‌سازی بیرونی منتشر کرده است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>/* داخل shadow root: عنصر دارای part=\"surface title\" */\nproduct-card::part(surface) { border-radius: 1rem; }\nproduct-card::part(title) { color: navy; }</code></pre><h3>تمرین عملی</h3><p>برای کارت محصول دو part عمومی تعریف کن و قرارداد استفاده از آن‌ها را بنویس.</p><h3>نکته فنی</h3><p>تمام جزئیات داخلی را به part تبدیل نکن؛ API کوچک پایدارتر است.</p><h3>معیار موفقیت</h3><p>میزبان فقط بخش‌های مستندشده را سفارشی کند.</p>","starter_code":"/* داخل shadow root: عنصر دارای part=\"surface title\" */\nproduct-card::part(surface) { border-radius: 1rem; }\nproduct-card::part(title) { color: navy; }","exercise":"برای کارت محصول دو part عمومی تعریف کن و قرارداد استفاده از آن‌ها را بنویس.","status":"published","sort_order":5,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-06","course_id":"css-advanced","title":"جای‌گذاری کنترل‌شده محتوا با slot","slug":"css-advanced-06","summary":"slot و ::slotted برای دریافت محتوای میزبان در Shadow DOM هستند و قواعد هدف‌گیری محدودی دارند.","content_html":"<h3>هدف درس</h3><p>slot و ::slotted برای دریافت محتوای میزبان در Shadow DOM هستند و قواعد هدف‌گیری محدودی دارند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>/* در قالب مؤلفه */\n&lt;slot name=\"summary\"&gt;&lt;/slot&gt;\n/* در سبک داخلی */\n::slotted([slot=\"summary\"]) { margin-block: .5rem; }</code></pre><h3>تمرین عملی</h3><p>یک کارت با slot عنوان و خلاصه طراحی کن و محدودیت استایل‌دهی عناصر slot شده را آزمایش کن.</p><h3>نکته فنی</h3><p>::slotted جایگزین انتخابگر عمومی برای همه نوادگان محتوای اسلات‌شده نیست.</p><h3>معیار موفقیت</h3><p>محتوای میزبان در محل درست نمایش داده شود و محدودیت‌ها مستند باشند.</p>","starter_code":"/* در قالب مؤلفه */\n<slot name=\"summary\"></slot>\n/* در سبک داخلی */\n::slotted([slot=\"summary\"]) { margin-block: .5rem; }","exercise":"یک کارت با slot عنوان و خلاصه طراحی کن و محدودیت استایل‌دهی عناصر slot شده را آزمایش کن.","status":"published","sort_order":6,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-07","course_id":"css-advanced","title":"Container Queries مبتنی بر اندازه","slug":"css-advanced-07","summary":"Size container query مؤلفه را با اندازه والدش تطبیق می‌دهد و برای کارت‌های قابل استفاده در ستون‌های مختلف مفید است.","content_html":"<h3>هدف درس</h3><p>Size container query مؤلفه را با اندازه والدش تطبیق می‌دهد و برای کارت‌های قابل استفاده در ستون‌های مختلف مفید است.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.product-panel { container: product / inline-size; }\n.product-card { display:grid; gap:1rem; }\n@container product (min-width:42rem) { .product-card { grid-template-columns:9rem 1fr; } }</code></pre><h3>تمرین عملی</h3><p>کارت واحدی بساز که در ظرف باریک عمودی و در ظرف عریض دو ستونه شود.</p><h3>نکته فنی</h3><p>عرض viewport همیشه نماینده فضای واقعی مؤلفه نیست؛ اندازه ظرف را مبنا بگیر.</p><h3>معیار موفقیت</h3><p>یک کارت بدون media query سراسری در دو والد متفاوت درست نمایش داده شود.</p>","starter_code":".product-panel { container: product / inline-size; }\n.product-card { display:grid; gap:1rem; }\n@container product (min-width:42rem) { .product-card { grid-template-columns:9rem 1fr; } }","exercise":"کارت واحدی بساز که در ظرف باریک عمودی و در ظرف عریض دو ستونه شود.","status":"published","sort_order":7,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-08","course_id":"css-advanced","title":"مقیاس‌بندی مؤلفه با واحدهای cqi و cqb","slug":"css-advanced-08","summary":"واحدهای container نسبت به محورهای ظرف query محاسبه می‌شوند و برای مقیاس داخلی اجزا کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>واحدهای container نسبت به محورهای ظرف query محاسبه می‌شوند و برای مقیاس داخلی اجزا کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.hero { container-type:inline-size; }\n.hero h2 { font-size:clamp(1.4rem,6cqi,4rem); }\n.hero p { padding-block:3cqb; }</code></pre><h3>تمرین عملی</h3><p>بنر را در دو ظرف با اندازه متفاوت قرار بده و مقیاس عنوان و فاصله را بررسی کن.</p><h3>نکته فنی</h3><p>در نبود ظرف مناسب، fallback واحدهای container را در مرورگر هدف آزمایش کن.</p><h3>معیار موفقیت</h3><p>عنوان با فضای مؤلفه رشد کند اما از حد خوانایی خارج نشود.</p>","starter_code":".hero { container-type:inline-size; }\n.hero h2 { font-size:clamp(1.4rem,6cqi,4rem); }\n.hero p { padding-block:3cqb; }","exercise":"بنر را در دو ظرف با اندازه متفاوت قرار بده و مقیاس عنوان و فاصله را بررسی کن.","status":"published","sort_order":8,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-09","course_id":"css-advanced","title":"واکنش به وضعیت پیمایش با scroll-state","slug":"css-advanced-09","summary":"Scroll-state container queries می‌توانند به وضعیت‌هایی مانند sticky واکنش نشان دهند؛ پشتیبانی مرورگر هنوز باید بررسی شود.","content_html":"<h3>هدف درس</h3><p>Scroll-state container queries می‌توانند به وضعیت‌هایی مانند sticky واکنش نشان دهند؛ پشتیبانی مرورگر هنوز باید بررسی شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.header-wrap { container-type:scroll-state; }\n@container scroll-state(stuck:top) { .site-header { box-shadow:0 2px 12px #0002; } }</code></pre><h3>تمرین عملی</h3><p>هدر sticky بساز و نسخه پایه بدون این قابلیت را نیز قابل استفاده نگه دار.</p><h3>نکته فنی</h3><p>ویژگی آزمایشی نباید تنها راه انتقال اطلاعات مهم باشد.</p><h3>معیار موفقیت</h3><p>در مرورگر فاقد پشتیبانی، هدر همچنان خوانا و کاربردی بماند.</p>","starter_code":".header-wrap { container-type:scroll-state; }\n@container scroll-state(stuck:top) { .site-header { box-shadow:0 2px 12px #0002; } }","exercise":"هدر sticky بساز و نسخه پایه بدون این قابلیت را نیز قابل استفاده نگه دار.","status":"published","sort_order":9,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-10","course_id":"css-advanced","title":"تطبیق رابط با viewport segments نمایشگر تاشو","slug":"css-advanced-10","summary":"ویژگی‌های viewport segment اطلاعات بخش‌های مجزای نمایشگر را فراهم می‌کنند و برای رابط‌های دوپنلی مفیدند.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های viewport segment اطلاعات بخش‌های مجزای نمایشگر را فراهم می‌کنند و برای رابط‌های دوپنلی مفیدند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@media (horizontal-viewport-segments:2) {\n .split-app { display:grid; grid-template-columns:1fr 1fr; }\n}\n.pane { min-width:0; }</code></pre><h3>تمرین عملی</h3><p>طرح دوپنلی بساز و برای گوشی معمولی نسخه تک‌ستونه ارائه بده.</p><h3>نکته فنی</h3><p>وجود دو بخش نمایشگر را فرض نکن؛ fallback دستگاه عادی ضروری است.</p><h3>معیار موفقیت</h3><p>محتوا روی نمایشگر معمولی و تاشو قابل استفاده بماند.</p>","starter_code":"@media (horizontal-viewport-segments:2) {\n .split-app { display:grid; grid-template-columns:1fr 1fr; }\n}\n.pane { min-width:0; }","exercise":"طرح دوپنلی بساز و برای گوشی معمولی نسخه تک‌ستونه ارائه بده.","status":"published","sort_order":10,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-11","course_id":"css-advanced","title":"ساخت مقیاس تایپوگرافی سیال","slug":"css-advanced-11","summary":"مقیاس مرحله‌ای با clamp اندازه متن را بین حدود کنترل‌شده تغییر می‌دهد و سلسله‌مراتب را حفظ می‌کند.","content_html":"<h3>هدف درس</h3><p>مقیاس مرحله‌ای با clamp اندازه متن را بین حدود کنترل‌شده تغییر می‌دهد و سلسله‌مراتب را حفظ می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>:root { --step-0:clamp(1rem,.92rem + .35vw,1.15rem); --step-1:clamp(1.25rem,1.1rem + .8vw,1.8rem); --step-2:clamp(1.6rem,1.3rem + 1.5vw,2.6rem); }\nbody { font-size:var(--step-0); }\nh1 { font-size:var(--step-2); }</code></pre><h3>تمرین عملی</h3><p>برای مقاله سه سطح تیتر و متن تعریف کن و در عرض‌های 320، 768 و 1440 بررسی کن.</p><h3>نکته فنی</h3><p>اندازه متن را همراه طول خط و line-height ارزیابی کن.</p><h3>معیار موفقیت</h3><p>سلسله‌مراتب متن در عرض‌های مختلف حفظ شود و متن قابل خواندن بماند.</p>","starter_code":":root { --step-0:clamp(1rem,.92rem + .35vw,1.15rem); --step-1:clamp(1.25rem,1.1rem + .8vw,1.8rem); --step-2:clamp(1.6rem,1.3rem + 1.5vw,2.6rem); }\nbody { font-size:var(--step-0); }\nh1 { font-size:var(--step-2); }","exercise":"برای مقاله سه سطح تیتر و متن تعریف کن و در عرض‌های 320، 768 و 1440 بررسی کن.","status":"published","sort_order":11,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-12","course_id":"css-advanced","title":"اندازه‌گذاری ذاتی با min-content و max-content","slug":"css-advanced-12","summary":"مقادیر ذاتی اندازه را از محتوای واقعی می‌گیرند و برای کنترل فضای حداقل و حداکثر مفیدند.","content_html":"<h3>هدف درس</h3><p>مقادیر ذاتی اندازه را از محتوای واقعی می‌گیرند و برای کنترل فضای حداقل و حداکثر مفیدند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.label { inline-size:min-content; }\n.body { min-inline-size:0; }\n.code { max-inline-size:max-content; overflow-wrap:anywhere; }</code></pre><h3>تمرین عملی</h3><p>ردیف نتیجه جست‌وجو با عنوان بلند و کد طولانی بساز و رفتار اندازه‌گذاری را آزمایش کن.</p><h3>نکته فنی</h3><p>max-content ممکن است در ظرف باریک overflow بسازد؛ محدودیت والد را در نظر بگیر.</p><h3>معیار موفقیت</h3><p>عنوان و کد در فضای محدود بیرون‌زدگی نداشته باشند.</p>","starter_code":".label { inline-size:min-content; }\n.body { min-inline-size:0; }\n.code { max-inline-size:max-content; overflow-wrap:anywhere; }","exercise":"ردیف نتیجه جست‌وجو با عنوان بلند و کد طولانی بساز و رفتار اندازه‌گذاری را آزمایش کن.","status":"published","sort_order":12,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-13","course_id":"css-advanced","title":"اندازه‌گذاری تطبیقی با fit-content","slug":"css-advanced-13","summary":"fit-content اندازه محتوا را با فضای موجود و سقف تعیین‌شده ترکیب می‌کند.","content_html":"<h3>هدف درس</h3><p>fit-content اندازه محتوا را با فضای موجود و سقف تعیین‌شده ترکیب می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.sidebar {\n  inline-size: fit-content;\n  max-inline-size: 18rem;\n}\n.dialog {\n  inline-size: min(92vw, 42rem);\n}\n.media {\n  max-block-size: min(70vh, 38rem);\n}</code></pre><h3>تمرین عملی</h3><p>پنل تنظیمات با متن کوتاه و طولانی بساز و رفتار عرض آن را مقایسه کن.</p><h3>نکته فنی</h3><p>در ویژگی inline-size از keyword یعنی fit-content استفاده کن؛ تابع fit-content(length) برای track sizing در Grid به کار می‌رود، نه به‌عنوان مقدار عمومی inline-size.</p><h3>معیار موفقیت</h3><p>پنل با اندازه ذاتی محتوا رشد کند اما از سقف ۱۸rem فراتر نرود؛ متن طولانی نیز بدون برش مدیریت شود.</p>","starter_code":".sidebar {\n  inline-size: fit-content;\n  max-inline-size: 18rem;\n}\n.dialog {\n  inline-size: min(92vw, 42rem);\n}\n.media {\n  max-block-size: min(70vh, 38rem);\n}","exercise":"پنل تنظیمات با متن کوتاه و طولانی بساز و رفتار عرض آن را مقایسه کن.","status":"published","sort_order":13,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-14","course_id":"css-advanced","title":"کنترل trackهای ضمنی در CSS Grid","slug":"css-advanced-14","summary":"Grid برای آیتم‌های اضافه track ضمنی می‌سازد و auto-rows رفتار این ردیف‌ها را تعیین می‌کند.","content_html":"<h3>هدف درس</h3><p>Grid برای آیتم‌های اضافه track ضمنی می‌سازد و auto-rows رفتار این ردیف‌ها را تعیین می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.board { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); grid-auto-rows:minmax(8rem,auto); }\n.board &gt; :nth-child(n+7) { border-style:dashed; }</code></pre><h3>تمرین عملی</h3><p>شبکه‌ای بساز که تعداد کارت‌هایش از پیش مشخص نیست و کارت هشتم و نهم را اضافه کن.</p><h3>نکته فنی</h3><p>trackهای ضمنی را صریح مدیریت کن تا محتوای تازه اندازه غیرمنتظره نسازد.</p><h3>معیار موفقیت</h3><p>با افزایش تعداد آیتم‌ها شبکه بدون overflow گسترش یابد.</p>","starter_code":".board { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); grid-auto-rows:minmax(8rem,auto); }\n.board > :nth-child(n+7) { border-style:dashed; }","exercise":"شبکه‌ای بساز که تعداد کارت‌هایش از پیش مشخص نیست و کارت هشتم و نهم را اضافه کن.","status":"published","sort_order":14,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-15","course_id":"css-advanced","title":"جریان dense و ترتیب منطقی محتوا","slug":"css-advanced-15","summary":"dense حفره‌های بصری Grid را پر می‌کند اما ممکن است ترتیب دیداری را از ترتیب DOM جدا کند.","content_html":"<h3>هدف درس</h3><p>dense حفره‌های بصری Grid را پر می‌کند اما ممکن است ترتیب دیداری را از ترتیب DOM جدا کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.gallery { display:grid; grid-template-columns:repeat(4,1fr); grid-auto-flow:row dense; }\n.featured { grid-column:span 2; grid-row:span 2; }</code></pre><h3>تمرین عملی</h3><p>گالری بساز و ترتیب DOM، ترتیب دیداری و حرکت با Tab را مقایسه کن.</p><h3>نکته فنی</h3><p>چیدمان فشرده نباید ترتیب خواندن و پیمایش صفحه‌کلید را گمراه کند.</p><h3>معیار موفقیت</h3><p>ترتیب منطقی محتوا حفظ شود و چیدمان بصری قابل فهم باشد.</p>","starter_code":".gallery { display:grid; grid-template-columns:repeat(4,1fr); grid-auto-flow:row dense; }\n.featured { grid-column:span 2; grid-row:span 2; }","exercise":"گالری بساز و ترتیب DOM، ترتیب دیداری و حرکت با Tab را مقایسه کن.","status":"published","sort_order":15,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-16","course_id":"css-advanced","title":"نقشه‌بندی صفحه با grid-template-areas","slug":"css-advanced-16","summary":"نام‌گذاری نواحی Grid ساختار کلان صفحه را خوانا می‌کند و تغییر layout را ساده‌تر می‌سازد.","content_html":"<h3>هدف درس</h3><p>نام‌گذاری نواحی Grid ساختار کلان صفحه را خوانا می‌کند و تغییر layout را ساده‌تر می‌سازد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.workspace { display:grid; grid-template:\"head head\" auto \"nav main\" 1fr \"foot foot\" auto / 16rem minmax(0,1fr); }\n.header { grid-area:head; } .nav { grid-area:nav; } .main { grid-area:main; } .footer { grid-area:foot; }</code></pre><h3>تمرین عملی</h3><p>داشبوردی با چهار ناحیه بساز و چیدمان موبایل را تغییر بده؛ ترتیب DOM را منطقی نگه دار.</p><h3>نکته فنی</h3><p>جابجایی بصری جایگزین ترتیب معنایی HTML نیست.</p><h3>معیار موفقیت</h3><p>نواحی در موبایل و دسکتاپ درست چیده شوند و ترتیب خواندن معنادار باشد.</p>","starter_code":".workspace { display:grid; grid-template:\"head head\" auto \"nav main\" 1fr \"foot foot\" auto / 16rem minmax(0,1fr); }\n.header { grid-area:head; } .nav { grid-area:nav; } .main { grid-area:main; } .footer { grid-area:foot; }","exercise":"داشبوردی با چهار ناحیه بساز و چیدمان موبایل را تغییر بده؛ ترتیب DOM را منطقی نگه دار.","status":"published","sort_order":16,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-17","course_id":"css-advanced","title":"مدیریت ارتفاع موبایل با dvh و svh","slug":"css-advanced-17","summary":"واحدهای viewport پویا تفاوت نوار مرورگر موبایل را مدیریت می‌کنند و برای پوسته تمام‌قد مهم‌اند.","content_html":"<h3>هدف درس</h3><p>واحدهای viewport پویا تفاوت نوار مرورگر موبایل را مدیریت می‌کنند و برای پوسته تمام‌قد مهم‌اند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.app-shell { min-block-size:100vh; }\n@supports (min-block-size:100dvh) { .app-shell { min-block-size:100dvh; } }\n.panel { min-block-size:100svh; }</code></pre><h3>تمرین عملی</h3><p>صفحه تمام‌قد موبایل بساز و تغییر ارتفاع هنگام ظاهر شدن نوار مرورگر را آزمایش کن.</p><h3>نکته فنی</h3><p>100vh در برخی مرورگرهای موبایل ممکن است با نوارهای مرورگر تفاوت داشته باشد.</p><h3>معیار موفقیت</h3><p>دکمه پایینی زیر نوار مرورگر پنهان نشود.</p>","starter_code":".app-shell { min-block-size:100vh; }\n@supports (min-block-size:100dvh) { .app-shell { min-block-size:100dvh; } }\n.panel { min-block-size:100svh; }","exercise":"صفحه تمام‌قد موبایل بساز و تغییر ارتفاع هنگام ظاهر شدن نوار مرورگر را آزمایش کن.","status":"published","sort_order":17,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-18","course_id":"css-advanced","title":"محافظت از بریدگی نمایشگر با safe-area","slug":"css-advanced-18","summary":"safe-area-inset فاصله امن برای بریدگی و گوشه‌های نمایشگر را فراهم می‌کند.","content_html":"<h3>هدف درس</h3><p>safe-area-inset فاصله امن برای بریدگی و گوشه‌های نمایشگر را فراهم می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.mobile-bar { padding:.75rem 1rem; }\n.mobile-bar { padding-inline:max(1rem,env(safe-area-inset-left)); padding-block-end:max(.75rem,env(safe-area-inset-bottom)); }</code></pre><h3>تمرین عملی</h3><p>نوار پایینی ثابت بساز و آن را روی دستگاه دارای بریدگی آزمایش کن.</p><h3>نکته فنی</h3><p>مقدار safe area جایگزین فاصله پایه طراحی نیست.</p><h3>معیار موفقیت</h3><p>هیچ کنترل مهمی زیر بریدگی یا نوار سیستم قرار نگیرد.</p>","starter_code":".mobile-bar { padding:.75rem 1rem; }\n.mobile-bar { padding-inline:max(1rem,env(safe-area-inset-left)); padding-block-end:max(.75rem,env(safe-area-inset-bottom)); }","exercise":"نوار پایینی ثابت بساز و آن را روی دستگاه دارای بریدگی آزمایش کن.","status":"published","sort_order":18,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-19","course_id":"css-advanced","title":"قاب‌بندی رسانه با aspect-ratio و object-position","slug":"css-advanced-19","summary":"نسبت تصویر قاب رسانه را پایدار می‌کند و object-position نقطه کانونی برش را کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>نسبت تصویر قاب رسانه را پایدار می‌کند و object-position نقطه کانونی برش را کنترل می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.cover { aspect-ratio:16/9; overflow:hidden; }\n.cover img { width:100%; height:100%; object-fit:cover; object-position:50% 30%; }\n.avatar { aspect-ratio:1; border-radius:50%; }</code></pre><h3>تمرین عملی</h3><p>سه تصویر با نسبت متفاوت را در کارت قرار بده و نقطه کانونی هرکدام را تنظیم کن.</p><h3>نکته فنی</h3><p>cover بخشی از تصویر را حذف می‌کند؛ برش محتوای معنادار را بررسی کن.</p><h3>معیار موفقیت</h3><p>کارت‌ها هم‌اندازه باشند و سوژه اصلی حفظ شود.</p>","starter_code":".cover { aspect-ratio:16/9; overflow:hidden; }\n.cover img { width:100%; height:100%; object-fit:cover; object-position:50% 30%; }\n.avatar { aspect-ratio:1; border-radius:50%; }","exercise":"سه تصویر با نسبت متفاوت را در کارت قرار بده و نقطه کانونی هرکدام را تنظیم کن.","status":"published","sort_order":19,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-20","course_id":"css-advanced","title":"دسترس‌پذیری رنگ در forced-colors","slug":"css-advanced-20","summary":"در حالت رنگ اجباری سیستم باید از رنگ‌های سیستمی و نشانه‌های غیررنگی استفاده شود.","content_html":"<h3>هدف درس</h3><p>در حالت رنگ اجباری سیستم باید از رنگ‌های سیستمی و نشانه‌های غیررنگی استفاده شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.button { border:2px solid transparent; }\n@media (forced-colors:active) { .button { color:ButtonText; background:ButtonFace; border-color:ButtonText; } .selected { outline:2px solid Highlight; } }</code></pre><h3>تمرین عملی</h3><p>فرمی با وضعیت انتخاب و خطا بساز و در حالت forced-colors بررسی کن.</p><h3>نکته فنی</h3><p>با forced-color-adjust بی‌دلیل کنترل رنگ سیستم را خنثی نکن.</p><h3>معیار موفقیت</h3><p>متن، مرز و وضعیت انتخاب در حالت کنتراست اجباری قابل تشخیص باشند.</p>","starter_code":".button { border:2px solid transparent; }\n@media (forced-colors:active) { .button { color:ButtonText; background:ButtonFace; border-color:ButtonText; } .selected { outline:2px solid Highlight; } }","exercise":"فرمی با وضعیت انتخاب و خطا بساز و در حالت forced-colors بررسی کن.","status":"published","sort_order":20,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-21","course_id":"css-advanced","title":"افزایش خوانایی با prefers-contrast","slug":"css-advanced-21","summary":"prefers-contrast ترجیح کنتراست کاربر را گزارش می‌کند و می‌تواند متن و مرزها را تقویت کند.","content_html":"<h3>هدف درس</h3><p>prefers-contrast ترجیح کنتراست کاربر را گزارش می‌کند و می‌تواند متن و مرزها را تقویت کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.card { border:1px solid #9aa4b2; }\n@media (prefers-contrast:more) { .card { border-width:2px; } .muted { color:#263244; } }</code></pre><h3>تمرین عملی</h3><p>برای کارت‌ها و متن کم‌رنگ حالت کنتراست بالا بساز و آزمایش کن.</p><h3>نکته فنی</h3><p>تغییر ظاهری باید خوانایی واقعی را افزایش دهد، نه فقط ضخامت تزئینی را.</p><h3>معیار موفقیت</h3><p>اطلاعات ثانویه نیز در حالت کنتراست بالا خوانا باشند.</p>","starter_code":".card { border:1px solid #9aa4b2; }\n@media (prefers-contrast:more) { .card { border-width:2px; } .muted { color:#263244; } }","exercise":"برای کارت‌ها و متن کم‌رنگ حالت کنتراست بالا بساز و آزمایش کن.","status":"published","sort_order":21,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-22","course_id":"css-advanced","title":"طراحی ورودی چندگانه با pointer و hover","slug":"css-advanced-22","summary":"pointer و hover قابلیت ورودی را گزارش می‌کنند و باید برای بهبود تعامل استفاده شوند.","content_html":"<h3>هدف درس</h3><p>pointer و hover قابلیت ورودی را گزارش می‌کنند و باید برای بهبود تعامل استفاده شوند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.action { min-block-size:2.75rem; }\n@media (hover:hover) and (pointer:fine) { .action:hover { transform:translateY(-1px); } }\n@media (pointer:coarse) { .action { padding-inline:1.1rem; } }</code></pre><h3>تمرین عملی</h3><p>منویی بساز که با لمس، ماوس و صفحه‌کلید کامل کار کند و hover فقط افزوده باشد.</p><h3>نکته فنی</h3><p>دستگاه‌های ترکیبی ممکن است بیش از یک نوع ورودی داشته باشند.</p><h3>معیار موفقیت</h3><p>هیچ عملکرد ضروری فقط با hover در دسترس نباشد.</p>","starter_code":".action { min-block-size:2.75rem; }\n@media (hover:hover) and (pointer:fine) { .action:hover { transform:translateY(-1px); } }\n@media (pointer:coarse) { .action { padding-inline:1.1rem; } }","exercise":"منویی بساز که با لمس، ماوس و صفحه‌کلید کامل کار کند و hover فقط افزوده باشد.","status":"published","sort_order":22,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-23","course_id":"css-advanced","title":"ترکیب چند انیمیشن با animation-composition","slug":"css-advanced-23","summary":"این ویژگی تعیین می‌کند انیمیشن‌های هم‌زمان روی یک ویژگی چگونه ترکیب شوند.","content_html":"<h3>هدف درس</h3><p>این ویژگی تعیین می‌کند انیمیشن‌های هم‌زمان روی یک ویژگی چگونه ترکیب شوند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@keyframes drift { to { transform:translateX(1rem); } }\n@keyframes pulse { to { transform:scale(1.08); } }\n.icon { animation:drift 2s alternate infinite,pulse 1s alternate infinite; animation-composition:add; }</code></pre><h3>تمرین عملی</h3><p>دو انیمیشن روی transform بساز و رفتار replace و add را مقایسه کن.</p><h3>نکته فنی</h3><p>ترکیب چند transform ممکن است حرکت ناخواسته ایجاد کند؛ نتیجه را اندازه‌گیری کن.</p><h3>معیار موفقیت</h3><p>هر انیمیشن اثر قابل پیش‌بینی داشته باشد و حرکت اضافی کنترل شود.</p>","starter_code":"@keyframes drift { to { transform:translateX(1rem); } }\n@keyframes pulse { to { transform:scale(1.08); } }\n.icon { animation:drift 2s alternate infinite,pulse 1s alternate infinite; animation-composition:add; }","exercise":"دو انیمیشن روی transform بساز و رفتار replace و add را مقایسه کن.","status":"published","sort_order":23,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-24","course_id":"css-advanced","title":"کنترل گذار ویژگی‌های گسسته","slug":"css-advanced-24","summary":"transition-behavior می‌تواند برخی تغییرهای گسسته مانند display را در گذار مشارکت دهد.","content_html":"<h3>هدف درس</h3><p>transition-behavior می‌تواند برخی تغییرهای گسسته مانند display را در گذار مشارکت دهد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.panel { display:none; opacity:0; transition:opacity .2s,display .2s allow-discrete; }\n.panel.open { display:block; opacity:1; }\n@starting-style { .panel.open { opacity:0; } }</code></pre><h3>تمرین عملی</h3><p>پنل بازشو بساز و دسترسی فوکوس و صفحه‌خوان را در حالت بسته بررسی کن.</p><h3>نکته فنی</h3><p>مخفی‌سازی بصری به‌تنهایی برای حذف از ترتیب فوکوس کافی نیست؛ وضعیت تعاملی را نیز مدیریت کن.</p><h3>معیار موفقیت</h3><p>پنل درست باز و بسته شود و محتوای بسته قابل فوکوس نباشد.</p>","starter_code":".panel { display:none; opacity:0; transition:opacity .2s,display .2s allow-discrete; }\n.panel.open { display:block; opacity:1; }\n@starting-style { .panel.open { opacity:0; } }","exercise":"پنل بازشو بساز و دسترسی فوکوس و صفحه‌خوان را در حالت بسته بررسی کن.","status":"published","sort_order":24,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-25","course_id":"css-advanced","title":"انیمیشن سازگار با prefers-reduced-motion","slug":"css-advanced-25","summary":"کاهش حرکت باید افکت‌های غیرضروری را حذف کند و بازخورد وضعیت را نگه دارد.","content_html":"<h3>هدف درس</h3><p>کاهش حرکت باید افکت‌های غیرضروری را حذف کند و بازخورد وضعیت را نگه دارد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.card { transition:transform .25s ease,opacity .25s ease; }\n@media (prefers-reduced-motion:reduce) { .card { transition:opacity .12s linear; } .parallax { transform:none !important; } }</code></pre><h3>تمرین عملی</h3><p>برای صفحه دارای parallax نسخه کاهش حرکت طراحی و با تنظیم سیستم آزمایش کن.</p><h3>نکته فنی</h3><p>خاموش کردن تمام بازخوردها می‌تواند تغییر وضعیت را مبهم کند؛ جایگزین ساده ارائه بده.</p><h3>معیار موفقیت</h3><p>کاربر همچنان تغییر وضعیت را واضح تشخیص دهد.</p>","starter_code":".card { transition:transform .25s ease,opacity .25s ease; }\n@media (prefers-reduced-motion:reduce) { .card { transition:opacity .12s linear; } .parallax { transform:none !important; } }","exercise":"برای صفحه دارای parallax نسخه کاهش حرکت طراحی و با تنظیم سیستم آزمایش کن.","status":"published","sort_order":25,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-26","course_id":"css-advanced","title":"شکست خطوط هوشمند با text-wrap","slug":"css-advanced-26","summary":"text-wrap balance و pretty شکست خطوط را برای تیتر و بدنه بهبود می‌دهند؛ hyphenation باید زبان‌محور باشد.","content_html":"<h3>هدف درس</h3><p>text-wrap balance و pretty شکست خطوط را برای تیتر و بدنه بهبود می‌دهند؛ hyphenation باید زبان‌محور باشد.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.article-title { text-wrap:balance; }\n.article-body { text-wrap:pretty; hyphens:auto; }\n[lang=\"fa\"] { hyphens:manual; }</code></pre><h3>تمرین عملی</h3><p>تیتر و پاراگراف فارسی و انگلیسی را در چند عرض آزمایش کن.</p><h3>نکته فنی</h3><p>کیفیت hyphenation میان زبان‌ها متفاوت است؛ برای فارسی خط تیره خودکار را بدون آزمون فعال نکن.</p><h3>معیار موفقیت</h3><p>تیتر متوازن و پاراگراف بدون شکست عجیب نمایش داده شود.</p>","starter_code":".article-title { text-wrap:balance; }\n.article-body { text-wrap:pretty; hyphens:auto; }\n[lang=\"fa\"] { hyphens:manual; }","exercise":"تیتر و پاراگراف فارسی و انگلیسی را در چند عرض آزمایش کن.","status":"published","sort_order":26,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-27","course_id":"css-advanced","title":"تنظیم ویژگی‌های OpenType برای داده و کد","slug":"css-advanced-27","summary":"ویژگی‌های قلم مانند kerning و اعداد جدولی می‌توانند تراز داده‌ها و خوانایی کد را بهبود دهند.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های قلم مانند kerning و اعداد جدولی می‌توانند تراز داده‌ها و خوانایی کد را بهبود دهند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.data { font-kerning:normal; font-variant-numeric:tabular-nums; }\n.code { font-variant-ligatures:none; }</code></pre><h3>تمرین عملی</h3><p>جدول قیمت و قطعه‌کد بساز؛ اعداد را هم‌تراز و ligature کد را خاموش کن.</p><h3>نکته فنی</h3><p>ابتدا ویژگی‌های سطح بالاتر font-variant را ترجیح بده و تنظیمات سطح پایین را فقط در صورت نیاز به کار ببر.</p><h3>معیار موفقیت</h3><p>اعداد ستون‌ها هم‌تراز و کد بدون اتصال حروف ناخواسته باشد.</p>","starter_code":".data { font-kerning:normal; font-variant-numeric:tabular-nums; }\n.code { font-variant-ligatures:none; }","exercise":"جدول قیمت و قطعه‌کد بساز؛ اعداد را هم‌تراز و ligature کد را خاموش کن.","status":"published","sort_order":27,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-28","course_id":"css-advanced","title":"نوشتار عمودی و نشانه‌گذاری آویخته","slug":"css-advanced-28","summary":"writing-mode و hanging-punctuation برای متن‌های عمودی و نشانه‌گذاری خاص کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>writing-mode و hanging-punctuation برای متن‌های عمودی و نشانه‌گذاری خاص کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.vertical-label { writing-mode:vertical-rl; text-orientation:mixed; }\n.quote { hanging-punctuation:first; }</code></pre><h3>تمرین عملی</h3><p>برچسب عمودی تزئینی بساز و ترتیب خواندن صفحه را بررسی کن.</p><h3>نکته فنی</h3><p>پشتیبانی ویژگی‌های نشانه‌گذاری میان مرورگرها متفاوت است.</p><h3>معیار موفقیت</h3><p>متن اصلی در ترتیب منطقی بماند و برچسب خوانا باشد.</p>","starter_code":".vertical-label { writing-mode:vertical-rl; text-orientation:mixed; }\n.quote { hanging-punctuation:first; }","exercise":"برچسب عمودی تزئینی بساز و ترتیب خواندن صفحه را بررسی کن.","status":"published","sort_order":28,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-29","course_id":"css-advanced","title":"صفحه‌بندی چاپ با widows و orphans","slug":"css-advanced-29","summary":"قواعد paged media شکست صفحه و خطوط تنها در ابتدا و انتهای صفحه را کنترل می‌کنند.","content_html":"<h3>هدف درس</h3><p>قواعد paged media شکست صفحه و خطوط تنها در ابتدا و انتهای صفحه را کنترل می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@media print { .toolbar { display:none !important; } h2 { break-after:avoid-page; } p { orphans:3; widows:3; } a { color:inherit; text-decoration:underline; } }</code></pre><h3>تمرین عملی</h3><p>گزارش چندصفحه‌ای بساز و تیترهای جداافتاده را در پیش‌نمایش چاپ اصلاح کن.</p><h3>نکته فنی</h3><p>چاپگرها و مرورگرها ممکن است رفتار متفاوتی داشته باشند؛ خروجی واقعی را ببین.</p><h3>معیار موفقیت</h3><p>گزارش بدون ابزارهای تعاملی و با تیترهای همراه محتوا خوانا باشد.</p>","starter_code":"@media print { .toolbar { display:none !important; } h2 { break-after:avoid-page; } p { orphans:3; widows:3; } a { color:inherit; text-decoration:underline; } }","exercise":"گزارش چندصفحه‌ای بساز و تیترهای جداافتاده را در پیش‌نمایش چاپ اصلاح کن.","status":"published","sort_order":29,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-30","course_id":"css-advanced","title":"هماهنگی color-scheme با کنترل‌های بومی","slug":"css-advanced-30","summary":"color-scheme اعلام می‌کند کنترل‌های بومی مرورگر با چه طرح رنگی سازگارند.","content_html":"<h3>هدف درس</h3><p>color-scheme اعلام می‌کند کنترل‌های بومی مرورگر با چه طرح رنگی سازگارند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>:root { color-scheme:light dark; }\n.light { color-scheme:light; }\n.dark { color-scheme:dark; }\ninput,select { accent-color:var(--brand,#2457a6); }</code></pre><h3>تمرین عملی</h3><p>فرم ورود با تم روشن و تاریک بساز و کنترل‌های بومی را در هر دو حالت بررسی کن.</p><h3>نکته فنی</h3><p>اعلام color-scheme به‌تنهایی رنگ‌های سفارشی و کنتراست متن را اصلاح نمی‌کند.</p><h3>معیار موفقیت</h3><p>کنترل‌ها با پس‌زمینه هماهنگ و خوانا باشند.</p>","starter_code":":root { color-scheme:light dark; }\n.light { color-scheme:light; }\n.dark { color-scheme:dark; }\ninput,select { accent-color:var(--brand,#2457a6); }","exercise":"فرم ورود با تم روشن و تاریک بساز و کنترل‌های بومی را در هر دو حالت بررسی کن.","status":"published","sort_order":30,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-31","course_id":"css-advanced","title":"فوکوس چندلایه با focus-visible و focus-within","slug":"css-advanced-31","summary":"این شبه‌کلاس‌ها فوکوس صفحه‌کلید و ظرف دارای عنصر متمرکز را واضح می‌کنند.","content_html":"<h3>هدف درس</h3><p>این شبه‌کلاس‌ها فوکوس صفحه‌کلید و ظرف دارای عنصر متمرکز را واضح می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.field:focus-within { border-color:var(--brand); box-shadow:0 0 0 3px #2457a633; }\n:where(button,a,input):focus-visible { outline:3px solid #e08a00; outline-offset:3px; }</code></pre><h3>تمرین عملی</h3><p>فرم بساز و با Tab و ماوس آزمایش کن؛ فوکوس را بدون جایگزین حذف نکن.</p><h3>نکته فنی</h3><p>outline قابل مشاهده برای کاربر صفحه‌کلید ضروری است.</p><h3>معیار موفقیت</h3><p>محل فوکوس در تمام مراحل قابل تشخیص باشد.</p>","starter_code":".field:focus-within { border-color:var(--brand); box-shadow:0 0 0 3px #2457a633; }\n:where(button,a,input):focus-visible { outline:3px solid #e08a00; outline-offset:3px; }","exercise":"فرم بساز و با Tab و ماوس آزمایش کن؛ فوکوس را بدون جایگزین حذف نکن.","status":"published","sort_order":31,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-32","course_id":"css-advanced","title":"مدیریت stacking context در لایه‌ها","slug":"css-advanced-32","summary":"stacking context ترتیب z-index را در محدوده‌های مستقل نگه می‌دارد و برخی ویژگی‌ها آن را ایجاد می‌کنند.","content_html":"<h3>هدف درس</h3><p>stacking context ترتیب z-index را در محدوده‌های مستقل نگه می‌دارد و برخی ویژگی‌ها آن را ایجاد می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.app { isolation:isolate; }\n.modal-layer { position:fixed; inset:0; z-index:100; }\n.toast-layer { position:fixed; inset:0; z-index:200; pointer-events:none; }\n.toast { pointer-events:auto; }</code></pre><h3>تمرین عملی</h3><p>modal و toast بساز و دلیل ترتیب نمایش را با بررسی context والد پیدا کن.</p><h3>نکته فنی</h3><p>z-index بسیار بزرگ مشکل context والد را حل نمی‌کند.</p><h3>معیار موفقیت</h3><p>لایه‌ها در ترتیب مورد انتظار باشند و کلیک‌ها درست مدیریت شوند.</p>","starter_code":".app { isolation:isolate; }\n.modal-layer { position:fixed; inset:0; z-index:100; }\n.toast-layer { position:fixed; inset:0; z-index:200; pointer-events:none; }\n.toast { pointer-events:auto; }","exercise":"modal و toast بساز و دلیل ترتیب نمایش را با بررسی context والد پیدا کن.","status":"published","sort_order":32,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-33","course_id":"css-advanced","title":"پیشگیری از جابه‌جایی چیدمان با رزرو فضا","slug":"css-advanced-33","summary":"رزرو ابعاد تصویر و محتوای دیررس از layout shift جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>رزرو ابعاد تصویر و محتوای دیررس از layout shift جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.article-image { display:block; width:100%; aspect-ratio:3/2; object-fit:cover; }\n.ad-slot { min-block-size:18rem; }\n.avatar { width:3rem; aspect-ratio:1; }</code></pre><h3>تمرین عملی</h3><p>صفحه خبری را با و بدون فضای رزروشده بارگذاری و تفاوت جابه‌جایی را مقایسه کن.</p><h3>نکته فنی</h3><p>فضای رزروشده را با اندازه واقعی محتوا هماهنگ کن تا فضای خالی بی‌دلیل نسازی.</p><h3>معیار موفقیت</h3><p>بارگذاری رسانه باعث پرش محسوس متن و کنترل‌ها نشود.</p>","starter_code":".article-image { display:block; width:100%; aspect-ratio:3/2; object-fit:cover; }\n.ad-slot { min-block-size:18rem; }\n.avatar { width:3rem; aspect-ratio:1; }","exercise":"صفحه خبری را با و بدون فضای رزروشده بارگذاری و تفاوت جابه‌جایی را مقایسه کن.","status":"published","sort_order":33,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-34","course_id":"css-advanced","title":"اندازه‌گیری هزینه CSS در DevTools","slug":"css-advanced-34","summary":"بهینه‌سازی CSS باید بر اساس Performance و Coverage باشد، نه باورهای کلی درباره selectorها.","content_html":"<h3>هدف درس</h3><p>بهینه‌سازی CSS باید بر اساس Performance و Coverage باشد، نه باورهای کلی درباره selectorها.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>/* selector آزمایشی برای مقایسه */\n.page .catalog .item .title strong { color:#182230; }\n.catalog-title { color:#182230; }</code></pre><h3>تمرین عملی</h3><p>دو نسخه selector را با داده Performance و Coverage مقایسه و نتیجه را ثبت کن.</p><h3>نکته فنی</h3><p>هزینه واقعی به DOM، تعداد عناصر و دفعات تغییر style وابسته است.</p><h3>معیار موفقیت</h3><p>پیشنهاد بهینه‌سازی با داده قبل و بعد مستند شود.</p>","starter_code":"/* selector آزمایشی برای مقایسه */\n.page .catalog .item .title strong { color:#182230; }\n.catalog-title { color:#182230; }","exercise":"دو نسخه selector را با داده Performance و Coverage مقایسه و نتیجه را ثبت کن.","status":"published","sort_order":34,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-35","course_id":"css-advanced","title":"راهبرد fallback برای قابلیت‌های نوظهور","slug":"css-advanced-35","summary":"نسخه پایه باید مستقل کار کند و قابلیت جدید فقط به‌عنوان ارتقا فعال شود.","content_html":"<h3>هدف درس</h3><p>نسخه پایه باید مستقل کار کند و قابلیت جدید فقط به‌عنوان ارتقا فعال شود.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>.panel { display:block; }\n@supports (container-type:inline-size) { .panel { container-type:inline-size; } @container (min-width:36rem) { .panel__body { columns:2; } } }</code></pre><h3>تمرین عملی</h3><p>برای یک ویژگی تازه نسخه پایه، شرط پشتیبانی و روش آزمون مرورگر را مستند کن.</p><h3>نکته فنی</h3><p>@supports پشتیبانی نحوی را می‌سنجد، نه نبود باگ در پیاده‌سازی.</p><h3>معیار موفقیت</h3><p>محتوا در مرورگر قدیمی قابل استفاده و در مرورگر جدید بهبود یافته باشد.</p>","starter_code":".panel { display:block; }\n@supports (container-type:inline-size) { .panel { container-type:inline-size; } @container (min-width:36rem) { .panel__body { columns:2; } } }","exercise":"برای یک ویژگی تازه نسخه پایه، شرط پشتیبانی و روش آزمون مرورگر را مستند کن.","status":"published","sort_order":35,"estimated_minutes":45},{"id":"curriculum-324-css-advanced-36","course_id":"css-advanced","title":"پروژه نهایی: داشبورد تولیدی و واکنش‌گرا","slug":"css-advanced-36","summary":"پروژه نهایی معماری مؤلفه، اندازه‌گذاری پیشرفته، ورودی‌های چندگانه، دسترس‌پذیری و fallback را ترکیب می‌کند.","content_html":"<h3>هدف درس</h3><p>پروژه نهایی معماری مؤلفه، اندازه‌گذاری پیشرفته، ورودی‌های چندگانه، دسترس‌پذیری و fallback را ترکیب می‌کند.</p><h3>نمونه و بررسی</h3><p>کد را در فایل CSS آزمایشی قرار بده و در مرورگر اجرا کن. سپس اندازه صفحه و وضعیت‌های تعاملی را تغییر بده.</p><pre><code>@layer reset,tokens,layout,components,utilities;\n@layer tokens { :root { --space:1rem; --surface:#fff; --ink:#182230; --brand:#2457a6; } }\n@layer layout { .dashboard { display:grid; grid-template-columns:16rem minmax(0,1fr); min-block-size:100dvh; } }\n@layer components { .metric { container-type:inline-size; padding:var(--space); background:var(--surface); color:var(--ink); border:1px solid #ccd3dc; border-radius:1rem; } }\n@media (max-width:48rem) { .dashboard { grid-template-columns:1fr; } }</code></pre><h3>تمرین عملی</h3><p>داشبورد آموزشی با نوار کناری، کارت آمار، جدول و فرم جست‌وجو بساز؛ موبایل، صفحه‌کلید، reduced motion و forced colors را آزمایش کن.</p><h3>نکته فنی</h3><p>ویژگی‌های جدید را فقط وقتی نگه دار که در نسخه پایه نیز مسیر استفاده روشن باشد.</p><h3>معیار موفقیت</h3><p>داشبورد در موبایل و دسکتاپ، با صفحه‌کلید و تنظیمات دسترس‌پذیری کار کند.</p>","starter_code":"@layer reset,tokens,layout,components,utilities;\n@layer tokens { :root { --space:1rem; --surface:#fff; --ink:#182230; --brand:#2457a6; } }\n@layer layout { .dashboard { display:grid; grid-template-columns:16rem minmax(0,1fr); min-block-size:100dvh; } }\n@layer components { .metric { container-type:inline-size; padding:var(--space); background:var(--surface); color:var(--ink); border:1px solid #ccd3dc; border-radius:1rem; } }\n@media (max-width:48rem) { .dashboard { grid-template-columns:1fr; } }","exercise":"داشبورد آموزشی با نوار کناری، کارت آمار، جدول و فرم جست‌وجو بساز؛ موبایل، صفحه‌کلید، reduced motion و forced colors را آزمایش کن.","status":"published","sort_order":36,"estimated_minutes":45},{"id":"curriculum-324-javascript-01","course_id":"javascript","title":"اجرای JavaScript در مرورگر","slug":"javascript-beginner-01","summary":"مرورگر کد JavaScript را اجرا می‌کند و کنسول محل مشاهده خروجی و خطاهای اولیه است.","content_html":"<h3>هدف درس</h3><p>مرورگر کد JavaScript را اجرا می‌کند و کنسول محل مشاهده خروجی و خطاهای اولیه است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(\"سلام از JavaScript\");\nconsole.log(\"NEXORA FORGE\");</code></pre><h3>تمرین عملی</h3><p>دو پیام تازه چاپ کن و ترتیب نمایش آن‌ها را توضیح بده.</p><h3>نکته فنی</h3><p>console.log خروجی را در کنسول نشان می‌دهد، نه داخل صفحه وب.</p><h3>معیار موفقیت</h3><p>دو پیام به ترتیب در Console دیده شوند و محل اجرای کد را نشان بدهی.</p>","starter_code":"console.log(\"سلام از JavaScript\");\nconsole.log(\"NEXORA FORGE\");","exercise":"دو پیام تازه چاپ کن و ترتیب نمایش آن‌ها را توضیح بده.","status":"published","sort_order":1,"estimated_minutes":25},{"id":"curriculum-324-javascript-02","course_id":"javascript","title":"اتصال فایل خارجی با defer","slug":"javascript-beginner-02","summary":"فایل JavaScript را جداگانه نگه دار و با script متصل کن؛ defer اجرای آن را تا پایان تحلیل HTML عقب می‌اندازد.","content_html":"<h3>هدف درس</h3><p>فایل JavaScript را جداگانه نگه دار و با script متصل کن؛ defer اجرای آن را تا پایان تحلیل HTML عقب می‌اندازد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>// در head سند:\n// &lt;script src=\"app.js\" defer&gt;&lt;/script&gt;\nconsole.log(\"app.js اجرا شد\");</code></pre><h3>تمرین عملی</h3><p>فایل app.js بساز، آن را با defer متصل کن و پیام اختصاصی نمایش بده.</p><h3>نکته فنی</h3><p>defer برای اسکریپت خارجی مناسب است؛ async ترتیب اجرای فایل‌ها را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>فایل app.js بدون خطای مسیر بارگذاری شود و پیام آن دیده شود.</p>","starter_code":"// در head سند:\n// <script src=\"app.js\" defer></script>\nconsole.log(\"app.js اجرا شد\");","exercise":"فایل app.js بساز، آن را با defer متصل کن و پیام اختصاصی نمایش بده.","status":"published","sort_order":2,"estimated_minutes":25},{"id":"curriculum-324-javascript-03","course_id":"javascript","title":"نخستین دستورها","slug":"javascript-beginner-03","summary":"دستورهای JavaScript به ترتیب اجرا می‌شوند. نوشتن هر دستور در خط جدا خواندن کد را آسان می‌کند.","content_html":"<h3>هدف درس</h3><p>دستورهای JavaScript به ترتیب اجرا می‌شوند. نوشتن هر دستور در خط جدا خواندن کد را آسان می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(\"نام پروژه\");\nconsole.log(\"NEXORA FORGE\");\nconsole.log(\"نسخه آزمایشی 1\");</code></pre><h3>تمرین عملی</h3><p>سه دستور برای نام، هدف و نسخه پروژه بنویس.</p><h3>نکته فنی</h3><p>هر دستور را جداگانه اجرا کن تا ترتیب و محل خطا مشخص باشد.</p><h3>معیار موفقیت</h3><p>سه پیام دقیقاً به ترتیب نوشته‌شده نمایش داده شوند.</p>","starter_code":"console.log(\"نام پروژه\");\nconsole.log(\"NEXORA FORGE\");\nconsole.log(\"نسخه آزمایشی 1\");","exercise":"سه دستور برای نام، هدف و نسخه پروژه بنویس.","status":"published","sort_order":3,"estimated_minutes":25},{"id":"curriculum-324-javascript-04","course_id":"javascript","title":"کنسول و پیام‌های تشخیصی","slug":"javascript-beginner-04","summary":"کنسول برای مشاهده مقدارها و خطاهاست. log، warn و error پیام‌ها را با سطح متفاوت نمایش می‌دهند.","content_html":"<h3>هدف درس</h3><p>کنسول برای مشاهده مقدارها و خطاهاست. log، warn و error پیام‌ها را با سطح متفاوت نمایش می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(\"اطلاعات\");\nconsole.warn(\"هشدار آزمایشی\");\nconsole.error(\"خطای نمونه\");</code></pre><h3>تمرین عملی</h3><p>سه نوع پیام بساز و تفاوت نمایش آن‌ها را در DevTools بررسی کن.</p><h3>نکته فنی</h3><p>console.error پیام خطا را نمایش می‌دهد اما به‌تنهایی اجرای برنامه را متوقف نمی‌کند.</p><h3>معیار موفقیت</h3><p>تفاوت ظاهر و کاربرد log، warn و error را توضیح بدهی.</p>","starter_code":"console.log(\"اطلاعات\");\nconsole.warn(\"هشدار آزمایشی\");\nconsole.error(\"خطای نمونه\");","exercise":"سه نوع پیام بساز و تفاوت نمایش آن‌ها را در DevTools بررسی کن.","status":"published","sort_order":4,"estimated_minutes":25},{"id":"curriculum-324-javascript-05","course_id":"javascript","title":"متغیرها با let و const","slug":"javascript-beginner-05","summary":"const برای متغیری است که دوباره انتساب نمی‌گیرد و let برای مقداری است که تغییر می‌کند.","content_html":"<h3>هدف درس</h3><p>const برای متغیری است که دوباره انتساب نمی‌گیرد و let برای مقداری است که تغییر می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const academy = \"NEXORA FORGE\";\nlet completed = 0;\ncompleted = completed + 1;\nconsole.log(academy, completed);</code></pre><h3>تمرین عملی</h3><p>نام آکادمی را با const و شمارنده درس را با let تعریف و سه بار افزایش بده.</p><h3>نکته فنی</h3><p>const انتساب دوباره را محدود می‌کند، نه تغییر محتوای شیء یا آرایه را.</p><h3>معیار موفقیت</h3><p>مقدار academy ثابت بماند و شمارنده با let افزایش پیدا کند.</p>","starter_code":"const academy = \"NEXORA FORGE\";\nlet completed = 0;\ncompleted = completed + 1;\nconsole.log(academy, completed);","exercise":"نام آکادمی را با const و شمارنده درس را با let تعریف و سه بار افزایش بده.","status":"published","sort_order":5,"estimated_minutes":25},{"id":"curriculum-324-javascript-06","course_id":"javascript","title":"نام‌گذاری متغیرها","slug":"javascript-beginner-06","summary":"نام متغیر باید معتبر و معنادار باشد. JavaScript به بزرگی و کوچکی حروف حساس است.","content_html":"<h3>هدف درس</h3><p>نام متغیر باید معتبر و معنادار باشد. JavaScript به بزرگی و کوچکی حروف حساس است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const studentName = \"سارا\";\nconst lessonCount = 12;\nconst isActive = true;\nconsole.log(studentName, lessonCount, isActive);</code></pre><h3>تمرین عملی</h3><p>نام‌های a و x را با نام‌های روشن و معنادار جایگزین کن.</p><h3>نکته فنی</h3><p>JavaScript به بزرگی و کوچکی حروف حساس است و نام‌های رزروشده قابل استفاده نیستند.</p><h3>معیار موفقیت</h3><p>نام‌ها معتبر باشند و از روی هر نام نقش متغیر مشخص شود.</p>","starter_code":"const studentName = \"سارا\";\nconst lessonCount = 12;\nconst isActive = true;\nconsole.log(studentName, lessonCount, isActive);","exercise":"نام‌های a و x را با نام‌های روشن و معنادار جایگزین کن.","status":"published","sort_order":6,"estimated_minutes":25},{"id":"curriculum-324-javascript-07","course_id":"javascript","title":"رشته‌ها و طول متن","slug":"javascript-beginner-07","summary":"رشته برای نگهداری متن است. typeof نوع داده را نشان می‌دهد و length طول رشته را گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>رشته برای نگهداری متن است. typeof نوع داده را نشان می‌دهد و length طول رشته را گزارش می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const student = \"مینا\";\nconst course = 'JavaScript';\nconsole.log(typeof student, student.length);\nconsole.log(course.length);</code></pre><h3>تمرین عملی</h3><p>نام و عنوان دوره را ذخیره کن و نوع و طول هر دو را چاپ کن.</p><h3>نکته فنی</h3><p>length تعداد واحدهای UTF-16 را می‌شمارد و همیشه برابر نویسه‌های دیداری نیست.</p><h3>معیار موفقیت</h3><p>نوع هر مقدار string باشد و طول آن درست از length خوانده شود.</p>","starter_code":"const student = \"مینا\";\nconst course = 'JavaScript';\nconsole.log(typeof student, student.length);\nconsole.log(course.length);","exercise":"نام و عنوان دوره را ذخیره کن و نوع و طول هر دو را چاپ کن.","status":"published","sort_order":7,"estimated_minutes":25},{"id":"curriculum-324-javascript-08","course_id":"javascript","title":"عدد و محاسبات پایه","slug":"javascript-beginner-08","summary":"نوع Number برای عدد صحیح و اعشاری استفاده می‌شود. عملگرهای ریاضی محاسبات پایه را انجام می‌دهند.","content_html":"<h3>هدف درس</h3><p>نوع Number برای عدد صحیح و اعشاری استفاده می‌شود. عملگرهای ریاضی محاسبات پایه را انجام می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const price = 125;\nconst count = 3;\nconsole.log(price * count);\nconsole.log(17 % 5);</code></pre><h3>تمرین عملی</h3><p>هزینه چهار قلم را محاسبه کن و باقیمانده تقسیم ۲۳ بر ۴ را چاپ کن.</p><h3>نکته فنی</h3><p>عملگر % باقیمانده تقسیم را می‌دهد؛ در محاسبات اعشاری محدودیت دقت Number را در نظر بگیر.</p><h3>معیار موفقیت</h3><p>ضرب و باقیمانده با محاسبه دستی برابر باشند.</p>","starter_code":"const price = 125;\nconst count = 3;\nconsole.log(price * count);\nconsole.log(17 % 5);","exercise":"هزینه چهار قلم را محاسبه کن و باقیمانده تقسیم ۲۳ بر ۴ را چاپ کن.","status":"published","sort_order":8,"estimated_minutes":25},{"id":"curriculum-324-javascript-09","course_id":"javascript","title":"تبدیل نوع داده","slug":"javascript-beginner-09","summary":"Number و String تبدیل صریح انجام می‌دهند. ورودی نامعتبر باید بررسی شود تا محاسبه اشتباه انجام نشود.","content_html":"<h3>هدف درس</h3><p>Number و String تبدیل صریح انجام می‌دهند. ورودی نامعتبر باید بررسی شود تا محاسبه اشتباه انجام نشود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const raw = \"17\";\nconst score = Number(raw);\nconsole.log(score + 3);\nconsole.log(String(score));\nconsole.log(Number.isNaN(Number(\"هفده\")));</code></pre><h3>تمرین عملی</h3><p>ورودی عددی و غیرعددی را تبدیل کن و ورودی نامعتبر را تشخیص بده.</p><h3>نکته فنی</h3><p>Number رشته خالی را صفر می‌کند؛ ورودی را قبل از تبدیل بررسی کن.</p><h3>معیار موفقیت</h3><p>ورودی عددی به number و ورودی نامعتبر به‌درستی شناسایی شود.</p>","starter_code":"const raw = \"17\";\nconst score = Number(raw);\nconsole.log(score + 3);\nconsole.log(String(score));\nconsole.log(Number.isNaN(Number(\"هفده\")));","exercise":"ورودی عددی و غیرعددی را تبدیل کن و ورودی نامعتبر را تشخیص بده.","status":"published","sort_order":9,"estimated_minutes":25},{"id":"curriculum-324-javascript-10","course_id":"javascript","title":"عملگرهای مقایسه","slug":"javascript-beginner-10","summary":"عملگرهای مقایسه نتیجه Boolean می‌دهند. === هم مقدار و هم نوع را می‌سنجد.","content_html":"<h3>هدف درس</h3><p>عملگرهای مقایسه نتیجه Boolean می‌دهند. === هم مقدار و هم نوع را می‌سنجد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>console.log(10 === \"10\");\nconsole.log(10 !== 8);\nconsole.log(15 &gt;= 12);\nconsole.log(7 &lt; 3);</code></pre><h3>تمرین عملی</h3><p>نمره را با چند حد مقایسه کن و نتیجه عبارت‌ها را پیش از اجرا پیش‌بینی کن.</p><h3>نکته فنی</h3><p>=== و !== از تبدیل ضمنی نوع جلوگیری می‌کنند و معمولاً انتخاب امن‌تری هستند.</p><h3>معیار موفقیت</h3><p>نتیجه هر چهار مقایسه را پیش از اجرا درست پیش‌بینی کنی.</p>","starter_code":"console.log(10 === \"10\");\nconsole.log(10 !== 8);\nconsole.log(15 >= 12);\nconsole.log(7 < 3);","exercise":"نمره را با چند حد مقایسه کن و نتیجه عبارت‌ها را پیش از اجرا پیش‌بینی کن.","status":"published","sort_order":10,"estimated_minutes":25},{"id":"curriculum-324-javascript-11","course_id":"javascript","title":"عملگرهای منطقی","slug":"javascript-beginner-11","summary":"&&، || و ! برای ترکیب شرط‌ها یا معکوس کردن نتیجه منطقی استفاده می‌شوند.","content_html":"<h3>هدف درس</h3><p>&&، || و ! برای ترکیب شرط‌ها یا معکوس کردن نتیجه منطقی استفاده می‌شوند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const loggedIn = true;\nconst active = false;\nconsole.log(loggedIn &amp;&amp; active);\nconsole.log(loggedIn || active);\nconsole.log(!active);</code></pre><h3>تمرین عملی</h3><p>شرط دسترسی به درس را با ورود و فعال بودن حساب بساز.</p><h3>نکته فنی</h3><p>&& و || از ارزیابی کوتاه‌شونده استفاده می‌کنند؛ سمت راست ممکن است اجرا نشود.</p><h3>معیار موفقیت</h3><p>شرط دسترسی فقط وقتی true شود که هر دو وضعیت لازم برقرار باشند.</p>","starter_code":"const loggedIn = true;\nconst active = false;\nconsole.log(loggedIn && active);\nconsole.log(loggedIn || active);\nconsole.log(!active);","exercise":"شرط دسترسی به درس را با ورود و فعال بودن حساب بساز.","status":"published","sort_order":11,"estimated_minutes":25},{"id":"curriculum-324-javascript-12","course_id":"javascript","title":"شرط if","slug":"javascript-beginner-12","summary":"if یک بلوک کد را فقط زمانی اجرا می‌کند که شرط درست باشد.","content_html":"<h3>هدف درس</h3><p>if یک بلوک کد را فقط زمانی اجرا می‌کند که شرط درست باشد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const score = 82;\nif (score &gt;= 60) {\n  console.log(\"قبول شدی\");\n}</code></pre><h3>تمرین عملی</h3><p>اگر حداقل پنج درس تکمیل شده بود پیام پیشرفت چاپ کن.</p><h3>نکته فنی</h3><p>شرط را داخل پرانتز و بدنه را داخل آکولاد قرار بده؛ مرزهای شرط را آزمایش کن.</p><h3>معیار موفقیت</h3><p>نمره کمتر از ۶۰ پیام رد و نمره ۶۰ یا بیشتر پیام قبولی بدهد.</p>","starter_code":"const score = 82;\nif (score >= 60) {\n  console.log(\"قبول شدی\");\n}","exercise":"اگر حداقل پنج درس تکمیل شده بود پیام پیشرفت چاپ کن.","status":"published","sort_order":12,"estimated_minutes":25},{"id":"curriculum-324-javascript-13","course_id":"javascript","title":"مسیر جایگزین else","slug":"javascript-beginner-13","summary":"else زمانی اجرا می‌شود که شرط if درست نباشد و دو مسیر تصمیم‌گیری را پوشش می‌دهد.","content_html":"<h3>هدف درس</h3><p>else زمانی اجرا می‌شود که شرط if درست نباشد و دو مسیر تصمیم‌گیری را پوشش می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const balance = 40;\nif (balance &gt;= 50) {\n  console.log(\"اعتبار کافی است\");\n} else {\n  console.log(\"اعتبار کافی نیست\");\n}</code></pre><h3>تمرین عملی</h3><p>برای اعتبار حساب دو پیام متفاوت بنویس و هر دو مسیر را آزمایش کن.</p><h3>نکته فنی</h3><p>else شرط مستقلی ندارد و فقط زمانی اجرا می‌شود که if متناظر false باشد.</p><h3>معیار موفقیت</h3><p>هر دو مسیر با تغییر موجودی اجرا شوند و پیام درست نمایش داده شود.</p>","starter_code":"const balance = 40;\nif (balance >= 50) {\n  console.log(\"اعتبار کافی است\");\n} else {\n  console.log(\"اعتبار کافی نیست\");\n}","exercise":"برای اعتبار حساب دو پیام متفاوت بنویس و هر دو مسیر را آزمایش کن.","status":"published","sort_order":13,"estimated_minutes":25},{"id":"curriculum-324-javascript-14","course_id":"javascript","title":"چند حالت با else if","slug":"javascript-beginner-14","summary":"زنجیره else if چند بازه را بررسی می‌کند. ترتیب شرط‌ها مهم است و شرط خاص باید پیش از شرط عمومی قرار گیرد.","content_html":"<h3>هدف درس</h3><p>زنجیره else if چند بازه را بررسی می‌کند. ترتیب شرط‌ها مهم است و شرط خاص باید پیش از شرط عمومی قرار گیرد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const score = 76;\nif (score &gt;= 90) console.log(\"عالی\");\nelse if (score &gt;= 70) console.log(\"خوب\");\nelse if (score &gt;= 50) console.log(\"نیازمند تمرین\");\nelse console.log(\"شروع دوباره\");</code></pre><h3>تمرین عملی</h3><p>رده‌بندی چهارسطحی بساز و مرزهای ۴۹، ۵۰، ۶۹، ۷۰ و ۹۰ را آزمایش کن.</p><h3>نکته فنی</h3><p>پس از اولین شرط درست، بقیه شاخه‌های else if بررسی نمی‌شوند.</p><h3>معیار موفقیت</h3><p>نمره‌های مرزی ۴۹، ۵۰، ۶۹، ۷۰ و ۹۰ در دسته صحیح قرار بگیرند.</p>","starter_code":"const score = 76;\nif (score >= 90) console.log(\"عالی\");\nelse if (score >= 70) console.log(\"خوب\");\nelse if (score >= 50) console.log(\"نیازمند تمرین\");\nelse console.log(\"شروع دوباره\");","exercise":"رده‌بندی چهارسطحی بساز و مرزهای ۴۹، ۵۰، ۶۹، ۷۰ و ۹۰ را آزمایش کن.","status":"published","sort_order":14,"estimated_minutes":25},{"id":"curriculum-324-javascript-15","course_id":"javascript","title":"انتخاب حالت با switch","slug":"javascript-beginner-15","summary":"switch برای انتخاب بین مقدارهای مشخص مناسب است. break مانع ادامه ناخواسته به case بعدی می‌شود.","content_html":"<h3>هدف درس</h3><p>switch برای انتخاب بین مقدارهای مشخص مناسب است. break مانع ادامه ناخواسته به case بعدی می‌شود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const level = \"intermediate\";\nswitch (level) {\n case \"beginner\": console.log(\"مقدماتی\"); break;\n case \"intermediate\": console.log(\"متوسط\"); break;\n case \"advanced\": console.log(\"پیشرفته\"); break;\n default: console.log(\"ناشناخته\");\n}</code></pre><h3>تمرین عملی</h3><p>برای سه وضعیت سفارش و یک مقدار ناشناخته switch بنویس.</p><h3>نکته فنی</h3><p>switch با تطبیق سخت‌گیرانه کار می‌کند؛ break از fall-through ناخواسته جلوگیری می‌کند.</p><h3>معیار موفقیت</h3><p>سه case و مسیر default خروجی متناسب با مقدار داشته باشند.</p>","starter_code":"const level = \"intermediate\";\nswitch (level) {\n case \"beginner\": console.log(\"مقدماتی\"); break;\n case \"intermediate\": console.log(\"متوسط\"); break;\n case \"advanced\": console.log(\"پیشرفته\"); break;\n default: console.log(\"ناشناخته\");\n}","exercise":"برای سه وضعیت سفارش و یک مقدار ناشناخته switch بنویس.","status":"published","sort_order":15,"estimated_minutes":25},{"id":"curriculum-324-javascript-16","course_id":"javascript","title":"حلقه for","slug":"javascript-beginner-16","summary":"for برای تکرار تعداد مشخصی از دفعات مناسب است. مقدار آغاز، شرط ادامه و تغییر شمارنده در یک ساختار قرار دارند.","content_html":"<h3>هدف درس</h3><p>for برای تکرار تعداد مشخصی از دفعات مناسب است. مقدار آغاز، شرط ادامه و تغییر شمارنده در یک ساختار قرار دارند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>for (let lesson = 1; lesson &lt;= 5; lesson++) {\n  console.log(\"درس\", lesson);\n}</code></pre><h3>تمرین عملی</h3><p>شماره درس‌های ۱ تا ۱۰ را چاپ کن و سپس فقط عددهای زوج را نمایش بده.</p><h3>نکته فنی</h3><p>شرط پایان را دقیق انتخاب کن؛ خطای یک‌واحدی می‌تواند یک دور اضافه یا کمتر ایجاد کند.</p><h3>معیار موفقیت</h3><p>شماره‌های ۱ تا ۵ دقیقاً یک بار چاپ شوند.</p>","starter_code":"for (let lesson = 1; lesson <= 5; lesson++) {\n  console.log(\"درس\", lesson);\n}","exercise":"شماره درس‌های ۱ تا ۱۰ را چاپ کن و سپس فقط عددهای زوج را نمایش بده.","status":"published","sort_order":16,"estimated_minutes":25},{"id":"curriculum-324-javascript-17","course_id":"javascript","title":"حلقه while","slug":"javascript-beginner-17","summary":"while پیش از اجرای بدنه شرط را می‌سنجد؛ تغییر متغیر کنترل برای توقف حلقه ضروری است.","content_html":"<h3>هدف درس</h3><p>while پیش از اجرای بدنه شرط را می‌سنجد؛ تغییر متغیر کنترل برای توقف حلقه ضروری است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>let attempts = 0;\nwhile (attempts &lt; 3) {\n  console.log(\"تلاش\", attempts + 1);\n  attempts++;\n}</code></pre><h3>تمرین عملی</h3><p>شمارش معکوس از پنج تا یک را با while انجام بده.</p><h3>نکته فنی</h3><p>اگر متغیر کنترل تغییر نکند، حلقه while ممکن است بی‌نهایت شود.</p><h3>معیار موفقیت</h3><p>حلقه پس از سه تلاش متوقف شود و شمارنده افزایش یافته باشد.</p>","starter_code":"let attempts = 0;\nwhile (attempts < 3) {\n  console.log(\"تلاش\", attempts + 1);\n  attempts++;\n}","exercise":"شمارش معکوس از پنج تا یک را با while انجام بده.","status":"published","sort_order":17,"estimated_minutes":25},{"id":"curriculum-324-javascript-18","course_id":"javascript","title":"ساخت آرایه و اندیس","slug":"javascript-beginner-18","summary":"آرایه مجموعه‌ای مرتب از مقدارهاست و اندیس آن از صفر آغاز می‌شود. length تعداد عناصر را می‌دهد.","content_html":"<h3>هدف درس</h3><p>آرایه مجموعه‌ای مرتب از مقدارهاست و اندیس آن از صفر آغاز می‌شود. length تعداد عناصر را می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const courses = [\"HTML\", \"CSS\", \"JavaScript\"];\nconsole.log(courses[0]);\nconsole.log(courses[2]);\nconsole.log(courses.length);</code></pre><h3>تمرین عملی</h3><p>آرایه‌ای از پنج درس بساز و اولین، سومین و آخرین مقدار را چاپ کن.</p><h3>نکته فنی</h3><p>اندیس آرایه از صفر آغاز می‌شود؛ اندیس خارج از محدوده معمولاً undefined می‌دهد.</p><h3>معیار موفقیت</h3><p>اولین، سومین و آخرین درس درست نمایش داده شوند.</p>","starter_code":"const courses = [\"HTML\", \"CSS\", \"JavaScript\"];\nconsole.log(courses[0]);\nconsole.log(courses[2]);\nconsole.log(courses.length);","exercise":"آرایه‌ای از پنج درس بساز و اولین، سومین و آخرین مقدار را چاپ کن.","status":"published","sort_order":18,"estimated_minutes":25},{"id":"curriculum-324-javascript-19","course_id":"javascript","title":"افزودن و حذف از آرایه","slug":"javascript-beginner-19","summary":"push عنصر را به انتهای آرایه اضافه و pop آخرین عنصر را حذف می‌کند. هر دو آرایه اصلی را تغییر می‌دهند.","content_html":"<h3>هدف درس</h3><p>push عنصر را به انتهای آرایه اضافه و pop آخرین عنصر را حذف می‌کند. هر دو آرایه اصلی را تغییر می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const tasks = [\"مطالعه\", \"تمرین\"];\ntasks.push(\"مرور\");\nconst removed = tasks.pop();\nconsole.log(tasks, removed);</code></pre><h3>تمرین عملی</h3><p>سه کار اضافه کن، آخرین کار را حذف و مقدار حذف‌شده را چاپ کن.</p><h3>نکته فنی</h3><p>push و pop آرایه اصلی را تغییر می‌دهند؛ مقدار pop آخرین عنصر حذف‌شده است.</p><h3>معیار موفقیت</h3><p>عنصر جدید به انتها اضافه و مقدار حذف‌شده درست گزارش شود.</p>","starter_code":"const tasks = [\"مطالعه\", \"تمرین\"];\ntasks.push(\"مرور\");\nconst removed = tasks.pop();\nconsole.log(tasks, removed);","exercise":"سه کار اضافه کن، آخرین کار را حذف و مقدار حذف‌شده را چاپ کن.","status":"published","sort_order":19,"estimated_minutes":25},{"id":"curriculum-324-javascript-20","course_id":"javascript","title":"تعریف و فراخوانی تابع","slug":"javascript-beginner-20","summary":"تابع مجموعه‌ای از دستورهای قابل استفاده مجدد است. تعریف تابع آن را اجرا نمی‌کند و برای اجرا باید فراخوانی شود.","content_html":"<h3>هدف درس</h3><p>تابع مجموعه‌ای از دستورهای قابل استفاده مجدد است. تعریف تابع آن را اجرا نمی‌کند و برای اجرا باید فراخوانی شود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function showWelcome() {\n  console.log(\"به آکادمی خوش آمدی\");\n}\nshowWelcome();\nshowWelcome();</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که نام آکادمی را چاپ کند و آن را دو بار فراخوانی کن.</p><h3>نکته فنی</h3><p>تعریف تابع و فراخوانی آن دو مرحله جدا هستند؛ تابع تا زمان فراخوانی اجرا نمی‌شود.</p><h3>معیار موفقیت</h3><p>پیام خوش‌آمدگویی در هر دو فراخوانی نمایش داده شود.</p>","starter_code":"function showWelcome() {\n  console.log(\"به آکادمی خوش آمدی\");\n}\nshowWelcome();\nshowWelcome();","exercise":"تابعی بساز که نام آکادمی را چاپ کند و آن را دو بار فراخوانی کن.","status":"published","sort_order":20,"estimated_minutes":25},{"id":"curriculum-324-javascript-21","course_id":"javascript","title":"پارامتر و آرگومان","slug":"javascript-beginner-21","summary":"پارامتر نام ورودی در تعریف تابع و آرگومان مقدار واقعی هنگام فراخوانی است. می‌توان پارامتر مقدار پیش‌فرض داشت.","content_html":"<h3>هدف درس</h3><p>پارامتر نام ورودی در تعریف تابع و آرگومان مقدار واقعی هنگام فراخوانی است. می‌توان پارامتر مقدار پیش‌فرض داشت.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function welcome(name = \"دانش‌آموز\") {\n  console.log(`سلام ${name}`);\n}\nwelcome(\"نورا\");\nwelcome();</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که نام دوره و زبان را بگیرد؛ زبان پیش‌فرض فارسی باشد.</p><h3>نکته فنی</h3><p>پارامتر در تعریف تابع می‌آید و آرگومان هنگام فراخوانی ارسال می‌شود؛ null مقدار پیش‌فرض را فعال نمی‌کند.</p><h3>معیار موفقیت</h3><p>تابع هم با نام ارسال‌شده و هم با مقدار پیش‌فرض پیام درست بسازد.</p>","starter_code":"function welcome(name = \"دانش‌آموز\") {\n  console.log(`سلام ${name}`);\n}\nwelcome(\"نورا\");\nwelcome();","exercise":"تابعی بساز که نام دوره و زبان را بگیرد؛ زبان پیش‌فرض فارسی باشد.","status":"published","sort_order":21,"estimated_minutes":25},{"id":"curriculum-324-javascript-22","course_id":"javascript","title":"بازگرداندن نتیجه با return","slug":"javascript-beginner-22","summary":"return اجرای تابع را پایان می‌دهد و مقدار را به محل فراخوانی برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>return اجرای تابع را پایان می‌دهد و مقدار را به محل فراخوانی برمی‌گرداند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function calculateTotal(price, count) {\n  return price * count;\n}\nconst total = calculateTotal(120, 3);\nconsole.log(total);</code></pre><h3>تمرین عملی</h3><p>تابعی بنویس که میانگین دو نمره را برگرداند و بیرون تابع چاپ کند.</p><h3>نکته فنی</h3><p>تابعی که return ندارد در پایان undefined برمی‌گرداند؛ کد پس از return در همان مسیر اجرا نمی‌شود.</p><h3>معیار موفقیت</h3><p>میانگین تابع به‌صورت مقدار قابل استفاده در بیرون برگردد.</p>","starter_code":"function calculateTotal(price, count) {\n  return price * count;\n}\nconst total = calculateTotal(120, 3);\nconsole.log(total);","exercise":"تابعی بنویس که میانگین دو نمره را برگرداند و بیرون تابع چاپ کند.","status":"published","sort_order":22,"estimated_minutes":25},{"id":"curriculum-324-javascript-23","course_id":"javascript","title":"محدوده دسترسی متغیرها","slug":"javascript-beginner-23","summary":"متغیرهای let و const در محدوده بلوک خود قابل دسترسی‌اند. متغیر محلی تابع بیرون از تابع دیده نمی‌شود.","content_html":"<h3>هدف درس</h3><p>متغیرهای let و const در محدوده بلوک خود قابل دسترسی‌اند. متغیر محلی تابع بیرون از تابع دیده نمی‌شود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const academy = \"NEXORA\";\nfunction showCourse() {\n  const course = \"JavaScript\";\n  console.log(academy, course);\n}\nshowCourse();</code></pre><h3>تمرین عملی</h3><p>متغیری داخل تابع و متغیری بیرون آن بساز و دسترسی مجاز و غیرمجاز را بررسی کن.</p><h3>نکته فنی</h3><p>متغیرهای let و const دارای block scope هستند؛ دسترسی خارج از محدوده خطا می‌دهد.</p><h3>معیار موفقیت</h3><p>بتوانی توضیح بدهی چرا academy در تابع قابل دسترسی است اما course بیرون آن نیست.</p>","starter_code":"const academy = \"NEXORA\";\nfunction showCourse() {\n  const course = \"JavaScript\";\n  console.log(academy, course);\n}\nshowCourse();","exercise":"متغیری داخل تابع و متغیری بیرون آن بساز و دسترسی مجاز و غیرمجاز را بررسی کن.","status":"published","sort_order":23,"estimated_minutes":25},{"id":"curriculum-324-javascript-24","course_id":"javascript","title":"رشته قالبی","slug":"javascript-beginner-24","summary":"Template literal با backtick نوشته می‌شود و با ${} مقدار متغیر را در متن قرار می‌دهد.","content_html":"<h3>هدف درس</h3><p>Template literal با backtick نوشته می‌شود و با ${} مقدار متغیر را در متن قرار می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const student = \"سارا\";\nconst completed = 12;\nconst message = `سلام ${student}؛ ${completed} درس را تمام کرده‌ای.`;\nconsole.log(message);</code></pre><h3>تمرین عملی</h3><p>پیامی شامل نام دانش‌آموز، نام دوره و تعداد درس‌های باقی‌مانده بساز.</p><h3>نکته فنی</h3><p>داخل ${} می‌توان عبارت JavaScript قرار داد؛ backtick امکان متن چندخطی نیز می‌دهد.</p><h3>معیار موفقیت</h3><p>پیام نهایی نام و تعداد درس را بدون چسباندن رشته‌های متعدد نشان دهد.</p>","starter_code":"const student = \"سارا\";\nconst completed = 12;\nconst message = `سلام ${student}؛ ${completed} درس را تمام کرده‌ای.`;\nconsole.log(message);","exercise":"پیامی شامل نام دانش‌آموز، نام دوره و تعداد درس‌های باقی‌مانده بساز.","status":"published","sort_order":24,"estimated_minutes":25},{"id":"curriculum-324-javascript-25","course_id":"javascript","title":"پاک‌سازی و جست‌وجوی رشته","slug":"javascript-beginner-25","summary":"trim، toLowerCase، includes و slice برای پاک‌سازی، جست‌وجو و استخراج بخشی از متن کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>trim، toLowerCase، includes و slice برای پاک‌سازی، جست‌وجو و استخراج بخشی از متن کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const entered = \"  NEXORA-FORGE  \";\nconst clean = entered.trim().toLowerCase();\nconsole.log(clean.includes(\"forge\"));\nconsole.log(clean.slice(0, 6));</code></pre><h3>تمرین عملی</h3><p>شناسه را پاک‌سازی کن، وجود forge را بررسی و پیشوند آن را جدا کن.</p><h3>نکته فنی</h3><p>slice اندیس پایان را شامل نمی‌کند؛ trim و toLowerCase رشته تازه برمی‌گردانند.</p><h3>معیار موفقیت</h3><p>شناسه بدون فاصله و با حروف کوچک باشد و جست‌وجوی forge نتیجه درست بدهد.</p>","starter_code":"const entered = \"  NEXORA-FORGE  \";\nconst clean = entered.trim().toLowerCase();\nconsole.log(clean.includes(\"forge\"));\nconsole.log(clean.slice(0, 6));","exercise":"شناسه را پاک‌سازی کن، وجود forge را بررسی و پیشوند آن را جدا کن.","status":"published","sort_order":25,"estimated_minutes":25},{"id":"curriculum-324-javascript-26","course_id":"javascript","title":"ساخت شیء و ویژگی‌ها","slug":"javascript-beginner-26","summary":"شیء مجموعه‌ای از ویژگی‌های نام‌دار است و برای نگهداری اطلاعات مرتبط مانند نام و سطح مناسب است.","content_html":"<h3>هدف درس</h3><p>شیء مجموعه‌ای از ویژگی‌های نام‌دار است و برای نگهداری اطلاعات مرتبط مانند نام و سطح مناسب است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const student = {\n  name: \"سارا\",\n  level: \"beginner\",\n  active: true\n};\nconsole.log(student.name, student.level);</code></pre><h3>تمرین عملی</h3><p>شیئی برای دوره بساز که title، level و lessonCount داشته باشد.</p><h3>نکته فنی</h3><p>ویژگی‌ها با نقطه و براکت قابل دسترسی‌اند؛ ویژگی ناموجود معمولاً undefined است.</p><h3>معیار موفقیت</h3><p>سه ویژگی title، level و lessonCount درست ذخیره و خوانده شوند.</p>","starter_code":"const student = {\n  name: \"سارا\",\n  level: \"beginner\",\n  active: true\n};\nconsole.log(student.name, student.level);","exercise":"شیئی برای دوره بساز که title، level و lessonCount داشته باشد.","status":"published","sort_order":26,"estimated_minutes":25},{"id":"curriculum-324-javascript-27","course_id":"javascript","title":"انتخاب عنصر از DOM","slug":"javascript-beginner-27","summary":"DOM نمای درختی عناصر صفحه است. querySelector نخستین عنصری را که با انتخابگر CSS تطبیق دارد برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>DOM نمای درختی عناصر صفحه است. querySelector نخستین عنصری را که با انتخابگر CSS تطبیق دارد برمی‌گرداند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const status = document.querySelector(\"#status\");\nconsole.log(status);</code></pre><h3>تمرین عملی</h3><p>در HTML یک عنصر با id مشخص بساز و با querySelector انتخابش کن؛ نبودن عنصر را هم بررسی کن.</p><h3>نکته فنی</h3><p>querySelector نخستین تطبیق را برمی‌گرداند و در صورت نبودن عنصر null می‌دهد.</p><h3>معیار موفقیت</h3><p>عنصر هدف انتخاب شود و نبودن آن باعث دسترسی ناامن به null نشود.</p>","starter_code":"const status = document.querySelector(\"#status\");\nconsole.log(status);","exercise":"در HTML یک عنصر با id مشخص بساز و با querySelector انتخابش کن؛ نبودن عنصر را هم بررسی کن.","status":"published","sort_order":27,"estimated_minutes":25},{"id":"curriculum-324-javascript-28","course_id":"javascript","title":"تغییر متن با textContent","slug":"javascript-beginner-28","summary":"پس از انتخاب عنصر DOM می‌توان متن آن را با textContent تغییر داد. این ویژگی متن را به‌صورت متن ساده قرار می‌دهد.","content_html":"<h3>هدف درس</h3><p>پس از انتخاب عنصر DOM می‌توان متن آن را با textContent تغییر داد. این ویژگی متن را به‌صورت متن ساده قرار می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const message = document.querySelector(\"#message\");\nif (message) {\n  message.textContent = \"پیشرفت ذخیره شد\";\n}</code></pre><h3>تمرین عملی</h3><p>متن پیام وضعیت را تغییر بده و حالت نبودن عنصر را مدیریت کن.</p><h3>نکته فنی</h3><p>textContent متن را به‌عنوان HTML تفسیر نمی‌کند و برای نمایش متن کاربر مناسب‌تر است.</p><h3>معیار موفقیت</h3><p>متن عنصر تغییر کند و رشته واردشده به‌صورت متن عادی باقی بماند.</p>","starter_code":"const message = document.querySelector(\"#message\");\nif (message) {\n  message.textContent = \"پیشرفت ذخیره شد\";\n}","exercise":"متن پیام وضعیت را تغییر بده و حالت نبودن عنصر را مدیریت کن.","status":"published","sort_order":28,"estimated_minutes":25},{"id":"curriculum-324-javascript-29","course_id":"javascript","title":"رویداد کلیک","slug":"javascript-beginner-29","summary":"addEventListener تابعی را به رویدادی مانند click متصل می‌کند تا برنامه به کنش کاربر پاسخ دهد.","content_html":"<h3>هدف درس</h3><p>addEventListener تابعی را به رویدادی مانند click متصل می‌کند تا برنامه به کنش کاربر پاسخ دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const button = document.querySelector(\"#counter-button\");\nlet count = 0;\nbutton?.addEventListener(\"click\", () =&gt; {\n  count++;\n  console.log(count);\n});</code></pre><h3>تمرین عملی</h3><p>دکمه‌ای بساز که با هر کلیک شمارنده را افزایش دهد و مقدار را روی صفحه نشان دهد.</p><h3>نکته فنی</h3><p>شنونده رویداد را یک بار ثبت کن؛ ثبت چندباره می‌تواند باعث اجرای چندباره تابع شود.</p><h3>معیار موفقیت</h3><p>هر کلیک فقط یک واحد به شمارنده اضافه کند.</p>","starter_code":"const button = document.querySelector(\"#counter-button\");\nlet count = 0;\nbutton?.addEventListener(\"click\", () => {\n  count++;\n  console.log(count);\n});","exercise":"دکمه‌ای بساز که با هر کلیک شمارنده را افزایش دهد و مقدار را روی صفحه نشان دهد.","status":"published","sort_order":29,"estimated_minutes":25},{"id":"curriculum-324-javascript-30","course_id":"javascript","title":"خواندن مقدار ورودی","slug":"javascript-beginner-30","summary":"مقدار input از ویژگی value خوانده می‌شود و معمولاً از نوع رشته است؛ حتی اگر input عددی باشد.","content_html":"<h3>هدف درس</h3><p>مقدار input از ویژگی value خوانده می‌شود و معمولاً از نوع رشته است؛ حتی اگر input عددی باشد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const nameInput = document.querySelector(\"#student-name\");\nconst enteredName = nameInput?.value.trim();\nconsole.log(enteredName);</code></pre><h3>تمرین عملی</h3><p>فیلد نام بساز، مقدارش را بخوان و فاصله‌های ابتدا و انتهای آن را حذف کن.</p><h3>نکته فنی</h3><p>value معمولاً رشته است؛ برای محاسبه عددی باید تبدیل و اعتبارسنجی انجام شود.</p><h3>معیار موفقیت</h3><p>فاصله‌های ابتدا و انتهای نام حذف و مقدار درست خوانده شود.</p>","starter_code":"const nameInput = document.querySelector(\"#student-name\");\nconst enteredName = nameInput?.value.trim();\nconsole.log(enteredName);","exercise":"فیلد نام بساز، مقدارش را بخوان و فاصله‌های ابتدا و انتهای آن را حذف کن.","status":"published","sort_order":30,"estimated_minutes":25},{"id":"curriculum-324-javascript-31","course_id":"javascript","title":"مدیریت ارسال فرم","slug":"javascript-beginner-31","summary":"رویداد submit هنگام ارسال فرم رخ می‌دهد. preventDefault از بارگذاری دوباره صفحه در فرم آزمایشی جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>رویداد submit هنگام ارسال فرم رخ می‌دهد. preventDefault از بارگذاری دوباره صفحه در فرم آزمایشی جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const form = document.querySelector(\"#register-form\");\nform?.addEventListener(\"submit\", (event) =&gt; {\n  event.preventDefault();\n  console.log(\"فرم دریافت شد\");\n});</code></pre><h3>تمرین عملی</h3><p>فرمی با نام و شناسه بساز؛ هنگام ارسال، بارگذاری مجدد را متوقف و مقدارها را بررسی کن.</p><h3>نکته فنی</h3><p>preventDefault فقط رفتار پیش‌فرض مرورگر را متوقف می‌کند و داده را خودکار به سرور نمی‌فرستد.</p><h3>معیار موفقیت</h3><p>فرم بدون بارگذاری مجدد مدیریت و مقدار فیلدها خوانده شوند.</p>","starter_code":"const form = document.querySelector(\"#register-form\");\nform?.addEventListener(\"submit\", (event) => {\n  event.preventDefault();\n  console.log(\"فرم دریافت شد\");\n});","exercise":"فرمی با نام و شناسه بساز؛ هنگام ارسال، بارگذاری مجدد را متوقف و مقدارها را بررسی کن.","status":"published","sort_order":31,"estimated_minutes":25},{"id":"curriculum-324-javascript-32","course_id":"javascript","title":"اعتبارسنجی ساده ورودی","slug":"javascript-beginner-32","summary":"اعتبارسنجی سمت مرورگر خطاهای ساده را پیش از ارسال نشان می‌دهد اما جای اعتبارسنجی سرور را نمی‌گیرد.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی سمت مرورگر خطاهای ساده را پیش از ارسال نشان می‌دهد اما جای اعتبارسنجی سرور را نمی‌گیرد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function validateName(value) {\n  const name = value.trim();\n  return name.length &gt;= 2;\n}\nconsole.log(validateName(\"علی\"));\nconsole.log(validateName(\" \"));</code></pre><h3>تمرین عملی</h3><p>تابعی بنویس که نام خالی یا کوتاه‌تر از دو نویسه را رد کند.</p><h3>نکته فنی</h3><p>اعتبارسنجی سمت مرورگر قابل دور زدن است؛ سرور باید داده را دوباره بررسی کند.</p><h3>معیار موفقیت</h3><p>نام معتبر true و نام خالی یا کوتاه false برگرداند.</p>","starter_code":"function validateName(value) {\n  const name = value.trim();\n  return name.length >= 2;\n}\nconsole.log(validateName(\"علی\"));\nconsole.log(validateName(\" \"));","exercise":"تابعی بنویس که نام خالی یا کوتاه‌تر از دو نویسه را رد کند.","status":"published","sort_order":32,"estimated_minutes":25},{"id":"curriculum-324-javascript-33","course_id":"javascript","title":"ذخیره داده در localStorage","slug":"javascript-beginner-33","summary":"localStorage داده متنی را بین بارگذاری‌های صفحه نگه می‌دارد. مقدارهای غیرمتنی باید پیش از ذخیره به رشته تبدیل شوند.","content_html":"<h3>هدف درس</h3><p>localStorage داده متنی را بین بارگذاری‌های صفحه نگه می‌دارد. مقدارهای غیرمتنی باید پیش از ذخیره به رشته تبدیل شوند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>localStorage.setItem(\"academy-theme\", \"dark\");\nconst savedTheme = localStorage.getItem(\"academy-theme\");\nconsole.log(savedTheme);</code></pre><h3>تمرین عملی</h3><p>نام نمایشی کاربر را ذخیره کن، صفحه را دوباره بارگذاری و مقدار را بخوان.</p><h3>نکته فنی</h3><p>localStorage فقط رشته ذخیره می‌کند و برای رمز عبور یا داده حساس مناسب نیست.</p><h3>معیار موفقیت</h3><p>مقدار ذخیره‌شده پس از بارگذاری مجدد صفحه قابل بازیابی باشد.</p>","starter_code":"localStorage.setItem(\"academy-theme\", \"dark\");\nconst savedTheme = localStorage.getItem(\"academy-theme\");\nconsole.log(savedTheme);","exercise":"نام نمایشی کاربر را ذخیره کن، صفحه را دوباره بارگذاری و مقدار را بخوان.","status":"published","sort_order":33,"estimated_minutes":25},{"id":"curriculum-324-javascript-34","course_id":"javascript","title":"تبدیل داده با JSON","slug":"javascript-beginner-34","summary":"JSON قالب متنی تبادل داده است. stringify شیء را به متن و parse متن معتبر را به مقدار JavaScript تبدیل می‌کند.","content_html":"<h3>هدف درس</h3><p>JSON قالب متنی تبادل داده است. stringify شیء را به متن و parse متن معتبر را به مقدار JavaScript تبدیل می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const profile = { name: \"سارا\", completed: 8 };\nconst text = JSON.stringify(profile);\nconst restored = JSON.parse(text);\nconsole.log(text, restored.name);</code></pre><h3>تمرین عملی</h3><p>شیء پروفایل را به JSON تبدیل کن، دوباره parse و یکی از ویژگی‌ها را چاپ کن.</p><h3>نکته فنی</h3><p>JSON.parse برای متن نامعتبر خطا می‌دهد؛ در برنامه واقعی آن را با try/catch مدیریت کن.</p><h3>معیار موفقیت</h3><p>شیء بازیابی‌شده ویژگی name و completed را با مقدار اولیه حفظ کند.</p>","starter_code":"const profile = { name: \"سارا\", completed: 8 };\nconst text = JSON.stringify(profile);\nconst restored = JSON.parse(text);\nconsole.log(text, restored.name);","exercise":"شیء پروفایل را به JSON تبدیل کن، دوباره parse و یکی از ویژگی‌ها را چاپ کن.","status":"published","sort_order":34,"estimated_minutes":25},{"id":"curriculum-324-javascript-35","course_id":"javascript","title":"اشکال‌زدایی و breakpoint","slug":"javascript-beginner-35","summary":"breakpoint اجرای برنامه را در یک خط متوقف می‌کند تا بتوانی مقدار متغیرها و مسیر اجرا را در DevTools بررسی کنی.","content_html":"<h3>هدف درس</h3><p>breakpoint اجرای برنامه را در یک خط متوقف می‌کند تا بتوانی مقدار متغیرها و مسیر اجرا را در DevTools بررسی کنی.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const price = 120;\nconst quantity = 3;\nconst total = price * quantity;\nconsole.log(total);</code></pre><h3>تمرین عملی</h3><p>روی خط محاسبه breakpoint بگذار و مقدار price، quantity و total را هنگام توقف ببین.</p><h3>نکته فنی</h3><p>breakpoint را پس از بررسی بردار و پیام‌های آزمایشی غیرضروری را پاک کن.</p><h3>معیار موفقیت</h3><p>بتوانی مقدارهای price، quantity و total را هنگام توقف مشاهده و خطا را ردیابی کنی.</p>","starter_code":"const price = 120;\nconst quantity = 3;\nconst total = price * quantity;\nconsole.log(total);","exercise":"روی خط محاسبه breakpoint بگذار و مقدار price، quantity و total را هنگام توقف ببین.","status":"published","sort_order":35,"estimated_minutes":25},{"id":"curriculum-324-javascript-36","course_id":"javascript","title":"پروژه نهایی: داشبورد پیشرفت","slug":"javascript-beginner-36","summary":"در پروژه پایانی آرایه، شیء، تابع، حلقه، شرط و DOM را ترکیب می‌کنی. برنامه تعداد درس‌های تکمیل‌شده و درصد پیشرفت را محاسبه و نمایش می‌دهد.","content_html":"<h3>هدف درس</h3><p>در پروژه پایانی آرایه، شیء، تابع، حلقه، شرط و DOM را ترکیب می‌کنی. برنامه تعداد درس‌های تکمیل‌شده و درصد پیشرفت را محاسبه و نمایش می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const lessons = [\n { title: \"متغیرها\", done: true },\n { title: \"شرط‌ها\", done: true },\n { title: \"حلقه‌ها\", done: false },\n { title: \"توابع\", done: false }\n];\nfunction getProgress(items) {\n let completed = 0;\n for (const item of items) if (item.done) completed++;\n const percent = items.length ? Math.round(completed / items.length * 100) : 0;\n return { completed, total: items.length, percent };\n}\nconst report = getProgress(lessons);\nconst output = document.querySelector(\"#progress\");\nif (output) output.textContent = `${report.completed}/${report.total} (${report.percent}%)`;</code></pre><h3>تمرین عملی</h3><p>پروژه را با شش درس توسعه بده و حالت آرایه خالی، همه تکمیل‌شده و هیچ‌کدام تکمیل‌نشده را آزمایش کن؛ دکمه‌ای برای تغییر وضعیت یک درس اضافه کن.</p><h3>نکته فنی</h3><p>آرایه خالی را مدیریت کن تا تقسیم بر صفر رخ ندهد؛ داده، منطق و نمایش را از هم جدا نگه دار.</p><h3>معیار موفقیت</h3><p>داشبورد برای آرایه خالی، همه تکمیل‌شده و هیچ‌کدام تکمیل‌نشده درصد درست از صفر تا صد نشان دهد.</p>","starter_code":"const lessons = [\n { title: \"متغیرها\", done: true },\n { title: \"شرط‌ها\", done: true },\n { title: \"حلقه‌ها\", done: false },\n { title: \"توابع\", done: false }\n];\nfunction getProgress(items) {\n let completed = 0;\n for (const item of items) if (item.done) completed++;\n const percent = items.length ? Math.round(completed / items.length * 100) : 0;\n return { completed, total: items.length, percent };\n}\nconst report = getProgress(lessons);\nconst output = document.querySelector(\"#progress\");\nif (output) output.textContent = `${report.completed}/${report.total} (${report.percent}%)`;","exercise":"پروژه را با شش درس توسعه بده و حالت آرایه خالی، همه تکمیل‌شده و هیچ‌کدام تکمیل‌نشده را آزمایش کن؛ دکمه‌ای برای تغییر وضعیت یک درس اضافه کن.","status":"published","sort_order":36,"estimated_minutes":60},{"id":"curriculum-324-javascript-intermediate-01","course_id":"javascript-intermediate","title":"عبارت تابعی و تفاوت آن با اعلان تابع","slug":"javascript-intermediate-01","summary":"تابع را می‌توان در یک متغیر ذخیره کرد. عبارت تابعی تا زمان رسیدن اجرا به تعریف آن قابل استفاده نیست؛ این تفاوت در ترتیب بارگذاری اهمیت دارد.","content_html":"<h3>هدف درس</h3><p>زمان تعریف و قابل‌دسترسی شدن تابع را در عبارت تابعی بشناس.</p><h3>نمونه و بررسی</h3><p>قبل از خط تعریف، تابع را فراخوانی نکن و تفاوت آن را با function declaration آزمایش کن.</p><pre><code>const formatName = function (name) {\n  return name.trim().toUpperCase();\n};\nconsole.log(formatName(\"sara\"));</code></pre><h3>تمرین عملی</h3><p>یک تابع اعتبارسنجی ایمیل را به‌صورت عبارت تابعی در const ذخیره کن و پس از تعریف فراخوانی کن.</p><h3>نکته فنی</h3><p>عبارت تابعی معمولاً hoist نمی‌شود؛ متغیر const پیش از مقداردهی قابل استفاده نیست.</p><h3>معیار موفقیت</h3><p>تابع پس از تعریف اجرا شود و ورودی را طبق انتظار قالب‌بندی کند.</p>","starter_code":"const formatName = function (name) {\n  return name.trim().toUpperCase();\n};\nconsole.log(formatName(\"sara\"));","exercise":"یک تابع اعتبارسنجی ایمیل را به‌صورت عبارت تابعی در const ذخیره کن و پس از تعریف فراخوانی کن.","status":"published","sort_order":1,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-02","course_id":"javascript-intermediate","title":"قرارداد callback","slug":"javascript-intermediate-02","summary":"Callback تابعی است که به تابع دیگری داده می‌شود تا در زمان مشخص اجرا شود. قرارداد ورودی و خروجی آن باید روشن باشد.","content_html":"<h3>هدف درس</h3><p>تابع را به‌عنوان ورودی به تابع دیگر ارسال کن.</p><h3>نمونه و بررسی</h3><p>مشخص کن callback چه آرگومان‌هایی دریافت می‌کند و چند بار اجرا می‌شود.</p><pre><code>function processName(name, onReady) {\n  const clean = name.trim();\n  onReady(clean);\n}\nprocessName(\"  NEXORA  \", value =&gt; console.log(value));</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که فهرست نام‌ها را بگیرد و پس از پاک‌سازی هر نام، callback را با نتیجه صدا بزند.</p><h3>نکته فنی</h3><p>callback باید تابع باشد؛ ارسال مقدار غیرتابع هنگام فراخوانی خطا ایجاد می‌کند.</p><h3>معیار موفقیت</h3><p>callback دقیقاً یک بار برای هر نام و با مقدار پاک‌سازی‌شده اجرا شود.</p>","starter_code":"function processName(name, onReady) {\n  const clean = name.trim();\n  onReady(clean);\n}\nprocessName(\"  NEXORA  \", value => console.log(value));","exercise":"تابعی بساز که فهرست نام‌ها را بگیرد و پس از پاک‌سازی هر نام، callback را با نتیجه صدا بزند.","status":"published","sort_order":2,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-03","course_id":"javascript-intermediate","title":"توابع مرتبه‌بالا","slug":"javascript-intermediate-03","summary":"تابع مرتبه‌بالا تابعی است که تابع می‌گیرد یا تابع برمی‌گرداند. این الگو برای ساخت رفتارهای قابل ترکیب مفید است.","content_html":"<h3>هدف درس</h3><p>تابعی بنویس که تابع دیگری تولید کند.</p><h3>نمونه و بررسی</h3><p>ورودی و خروجی تابع تولیدشده را مشخص کن.</p><pre><code>function makeMultiplier(factor) {\n  return number =&gt; number * factor;\n}\nconst double = makeMultiplier(2);\nconsole.log(double(9));</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که ضریب تخفیف را دریافت کند و تابع محاسبه قیمت نهایی برگرداند.</p><h3>نکته فنی</h3><p>تابع بازگشتی می‌تواند به متغیرهای محدوده بیرونی دسترسی داشته باشد.</p><h3>معیار موفقیت</h3><p>تابع تولیدشده با چند ورودی نتیجه صحیح بدهد.</p>","starter_code":"function makeMultiplier(factor) {\n  return number => number * factor;\n}\nconst double = makeMultiplier(2);\nconsole.log(double(9));","exercise":"تابعی بساز که ضریب تخفیف را دریافت کند و تابع محاسبه قیمت نهایی برگرداند.","status":"published","sort_order":3,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-04","course_id":"javascript-intermediate","title":"تابع خالص و اثر جانبی","slug":"javascript-intermediate-04","summary":"تابع خالص با ورودی یکسان خروجی یکسان می‌دهد و بیرون از خود را تغییر نمی‌دهد. اثر جانبی مانند تغییر DOM یا نوشتن در storage باید آگاهانه مدیریت شود.","content_html":"<h3>هدف درس</h3><p>منطق محاسبه را از عملیات جانبی جدا کن.</p><h3>نمونه و بررسی</h3><p>داده مورد نیاز را به پارامتر بده و نتیجه را return کن.</p><pre><code>function addTax(price, rate) {\n  return price * (1 + rate);\n}\nconsole.log(addTax(100, 0.1));</code></pre><h3>تمرین عملی</h3><p>یک تابع محاسبه امتیاز را از بخش نمایش پیام جدا کن و بررسی کن تابع محاسبه وضعیت بیرونی را تغییر ندهد.</p><h3>نکته فنی</h3><p>تابع خالص تست واحد و استفاده مجدد را ساده‌تر می‌کند.</p><h3>معیار موفقیت</h3><p>دو بار اجرای تابع با ورودی یکسان نتیجه یکسان بدهد و متغیر بیرونی تغییر نکند.</p>","starter_code":"function addTax(price, rate) {\n  return price * (1 + rate);\n}\nconsole.log(addTax(100, 0.1));","exercise":"یک تابع محاسبه امتیاز را از بخش نمایش پیام جدا کن و بررسی کن تابع محاسبه وضعیت بیرونی را تغییر ندهد.","status":"published","sort_order":4,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-05","course_id":"javascript-intermediate","title":"Closure و حفظ وضعیت","slug":"javascript-intermediate-05","summary":"Closure زمانی شکل می‌گیرد که تابع به متغیرهای محدوده بیرونی خود حتی پس از پایان اجرای آن محدوده دسترسی داشته باشد.","content_html":"<h3>هدف درس</h3><p>وضعیت خصوصی را با تابع بازگشتی نگه دار.</p><h3>نمونه و بررسی</h3><p>متغیر count را بیرون از تابع بازگشتی در دسترس مستقیم قرار نده.</p><pre><code>function createCounter() {\n  let count = 0;\n  return () =&gt; ++count;\n}\nconst next = createCounter();\nconsole.log(next(), next(), next());</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که شمارنده خصوصی برای هر دانش‌آموز ایجاد کند؛ دو شمارنده مستقل بساز.</p><h3>نکته فنی</h3><p>هر بار اجرای تابع سازنده، محیط closure جداگانه ایجاد می‌کند.</p><h3>معیار موفقیت</h3><p>دو شمارنده مستقل باشند و مقدار یکی روی دیگری اثر نگذارد.</p>","starter_code":"function createCounter() {\n  let count = 0;\n  return () => ++count;\n}\nconst next = createCounter();\nconsole.log(next(), next(), next());","exercise":"تابعی بساز که شمارنده خصوصی برای هر دانش‌آموز ایجاد کند؛ دو شمارنده مستقل بساز.","status":"published","sort_order":5,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-06","course_id":"javascript-intermediate","title":"بازگشت تابعی و recursion","slug":"javascript-intermediate-06","summary":"در recursion تابع خودش را با مسئله کوچک‌تر فراخوانی می‌کند. شرط پایه برای جلوگیری از فراخوانی بی‌پایان ضروری است.","content_html":"<h3>هدف درس</h3><p>مسئله را به زیرمسئله کوچک‌تر تقسیم کن.</p><h3>نمونه و بررسی</h3><p>شرط پایه را پیش از فراخوانی دوباره بنویس.</p><pre><code>function factorial(n) {\n  if (n &lt;= 1) return 1;\n  return n * factorial(n - 1);\n}\nconsole.log(factorial(5));</code></pre><h3>تمرین عملی</h3><p>تابع بازگشتی برای جمع اعداد از یک تا n بنویس و ورودی صفر را هم مدیریت کن.</p><h3>نکته فنی</h3><p>عمق زیاد recursion ممکن است به خطای stack overflow منجر شود.</p><h3>معیار موفقیت</h3><p>برای ورودی صفر، یک و چند مقدار بزرگ نتیجه درست و توقف قطعی داشته باشی.</p>","starter_code":"function factorial(n) {\n  if (n <= 1) return 1;\n  return n * factorial(n - 1);\n}\nconsole.log(factorial(5));","exercise":"تابع بازگشتی برای جمع اعداد از یک تا n بنویس و ورودی صفر را هم مدیریت کن.","status":"published","sort_order":6,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-07","course_id":"javascript-intermediate","title":"تبدیل مجموعه با map","slug":"javascript-intermediate-07","summary":"map از هر عنصر آرایه یک مقدار جدید می‌سازد و آرایه تازه‌ای با همان تعداد عضو برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>برای هر عضو آرایه یک مقدار تبدیل‌شده تولید کن.</p><h3>نمونه و بررسی</h3><p>تابع callback را بدون تغییر آرایه اصلی بنویس.</p><pre><code>const prices = [100, 250, 400];\nconst withTax = prices.map(price =&gt; price * 1.1);\nconsole.log(withTax, prices);</code></pre><h3>تمرین عملی</h3><p>آرایه‌ای از مدت زمان درس‌ها را به متن‌هایی مانند «۲۰ دقیقه» تبدیل کن.</p><h3>نکته فنی</h3><p>اگر هدف فقط اجرای اثر جانبی است، map انتخاب مناسبی نیست.</p><h3>معیار موفقیت</h3><p>آرایه خروجی هم‌اندازه ورودی باشد و آرایه اولیه تغییر نکند.</p>","starter_code":"const prices = [100, 250, 400];\nconst withTax = prices.map(price => price * 1.1);\nconsole.log(withTax, prices);","exercise":"آرایه‌ای از مدت زمان درس‌ها را به متن‌هایی مانند «۲۰ دقیقه» تبدیل کن.","status":"published","sort_order":7,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-08","course_id":"javascript-intermediate","title":"فیلتر شرطی با filter","slug":"javascript-intermediate-08","summary":"filter فقط عناصری را نگه می‌دارد که تابع شرط برای آن‌ها true برگرداند و آرایه جدید می‌سازد.","content_html":"<h3>هدف درس</h3><p>از یک آرایه زیرمجموعه مطابق شرط بساز.</p><h3>نمونه و بررسی</h3><p>شرط را در تابع کوتاه و قابل فهم بنویس.</p><pre><code>const scores = [42, 78, 91, 55, 66];\nconst passed = scores.filter(score =&gt; score &gt;= 60);\nconsole.log(passed);</code></pre><h3>تمرین عملی</h3><p>فهرست دوره‌ها را بر اساس published بودن فیلتر کن و آرایه اصلی را دست‌نخورده نگه دار.</p><h3>نکته فنی</h3><p>filter عضوها را تغییر نمی‌دهد، اما ارجاع به اشیای درون آرایه همچنان مشترک است.</p><h3>معیار موفقیت</h3><p>فقط عضوهای واجد شرط در خروجی باشند.</p>","starter_code":"const scores = [42, 78, 91, 55, 66];\nconst passed = scores.filter(score => score >= 60);\nconsole.log(passed);","exercise":"فهرست دوره‌ها را بر اساس published بودن فیلتر کن و آرایه اصلی را دست‌نخورده نگه دار.","status":"published","sort_order":8,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-09","course_id":"javascript-intermediate","title":"تجمیع داده با reduce","slug":"javascript-intermediate-09","summary":"reduce عناصر آرایه را به یک مقدار نهایی مانند عدد، شیء یا آرایه تجمیع می‌کند. مقدار اولیه accumulator اهمیت دارد.","content_html":"<h3>هدف درس</h3><p>چند مقدار را به یک نتیجه خلاصه تبدیل کن.</p><h3>نمونه و بررسی</h3><p>مقدار اولیه accumulator را صریح تعیین کن.</p><pre><code>const minutes = [12, 18, 25];\nconst total = minutes.reduce((sum, item) =&gt; sum + item, 0);\nconsole.log(total);</code></pre><h3>تمرین عملی</h3><p>تعداد درس‌های تکمیل‌شده را از آرایه‌ای از اشیا با reduce محاسبه کن.</p><h3>نکته فنی</h3><p>reduce روی آرایه خالی بدون مقدار اولیه خطا می‌دهد.</p><h3>معیار موفقیت</h3><p>جمع و شمارش با داده آزمایشی و آرایه خالی درست مدیریت شود.</p>","starter_code":"const minutes = [12, 18, 25];\nconst total = minutes.reduce((sum, item) => sum + item, 0);\nconsole.log(total);","exercise":"تعداد درس‌های تکمیل‌شده را از آرایه‌ای از اشیا با reduce محاسبه کن.","status":"published","sort_order":9,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-10","course_id":"javascript-intermediate","title":"جست‌وجو با find و findIndex","slug":"javascript-intermediate-10","summary":"find نخستین عضو مطابق شرط را برمی‌گرداند؛ findIndex موقعیت آن را می‌دهد. اگر موردی یافت نشود، به‌ترتیب undefined و ‎-1 برمی‌گردند.","content_html":"<h3>هدف درس</h3><p>مورد مشخصی را در آرایه پیدا کن.</p><h3>نمونه و بررسی</h3><p>حالت پیدا نشدن را قبل از استفاده از ویژگی‌های نتیجه بررسی کن.</p><pre><code>const users = [{id: 4, name: \"آوا\"}, {id: 7, name: \"نیما\"}];\nconst user = users.find(item =&gt; item.id === 7);\nconst index = users.findIndex(item =&gt; item.id === 7);\nconsole.log(user, index);</code></pre><h3>تمرین عملی</h3><p>دانش‌آموز را با شناسه یکتا پیدا کن و موقعیت او را نیز گزارش بده.</p><h3>نکته فنی</h3><p>find فقط نخستین تطبیق را برمی‌گرداند.</p><h3>معیار موفقیت</h3><p>شناسه موجود پیدا شود و شناسه ناموجود بدون خطا مدیریت شود.</p>","starter_code":"const users = [{id: 4, name: \"آوا\"}, {id: 7, name: \"نیما\"}];\nconst user = users.find(item => item.id === 7);\nconst index = users.findIndex(item => item.id === 7);\nconsole.log(user, index);","exercise":"دانش‌آموز را با شناسه یکتا پیدا کن و موقعیت او را نیز گزارش بده.","status":"published","sort_order":10,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-11","course_id":"javascript-intermediate","title":"مرتب‌سازی پایدار با comparator","slug":"javascript-intermediate-11","summary":"sort آرایه را درجا تغییر می‌دهد. برای عددها comparator لازم است تا مرتب‌سازی عددی به‌جای لغوی انجام شود.","content_html":"<h3>هدف درس</h3><p>ترتیب آرایه را با تابع مقایسه سفارشی تعیین کن.</p><h3>نمونه و بررسی</h3><p>برای ترتیب نزولی b - a و برای صعودی a - b را بررسی کن.</p><pre><code>const scores = [8, 100, 23, 4];\nconst sorted = [...scores].sort((a, b) =&gt; a - b);\nconsole.log(sorted, scores);</code></pre><h3>تمرین عملی</h3><p>فهرست دانش‌آموزان را بر اساس امتیاز نزولی مرتب کن و ترتیب آرایه اصلی را حفظ کن.</p><h3>نکته فنی</h3><p>sort آرایه اصلی را تغییر می‌دهد؛ پیش از آن کپی بساز.</p><h3>معیار موفقیت</h3><p>خروجی عددی درست مرتب شود و ورودی بدون تغییر بماند.</p>","starter_code":"const scores = [8, 100, 23, 4];\nconst sorted = [...scores].sort((a, b) => a - b);\nconsole.log(sorted, scores);","exercise":"فهرست دانش‌آموزان را بر اساس امتیاز نزولی مرتب کن و ترتیب آرایه اصلی را حفظ کن.","status":"published","sort_order":11,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-12","course_id":"javascript-intermediate","title":"تخت‌کردن آرایه‌های تو در تو","slug":"javascript-intermediate-12","summary":"flat یک سطح از آرایه‌های تو در تو را تخت می‌کند و flatMap ابتدا map و سپس تخت‌سازی یک‌سطحی انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>ساختار آرایه تو در تو را به خروجی تخت تبدیل کن.</p><h3>نمونه و بررسی</h3><p>عمق تخت‌سازی flat را متناسب با ساختار انتخاب کن.</p><pre><code>const groups = [[\"HTML\", \"CSS\"], [\"JS\"]];\nconsole.log(groups.flat());\nconst tags = [\"js\", \"css\"].flatMap(tag =&gt; [tag, tag.toUpperCase()]);\nconsole.log(tags);</code></pre><h3>تمرین عملی</h3><p>فهرست گروه‌های آموزشی را به یک فهرست واحد تبدیل و برای هر برچسب نسخه کوچک و بزرگ بساز.</p><h3>نکته فنی</h3><p>flat بدون آرگومان فقط یک سطح را تخت می‌کند.</p><h3>معیار موفقیت</h3><p>همه اعضای مورد انتظار در ترتیب درست قرار بگیرند.</p>","starter_code":"const groups = [[\"HTML\", \"CSS\"], [\"JS\"]];\nconsole.log(groups.flat());\nconst tags = [\"js\", \"css\"].flatMap(tag => [tag, tag.toUpperCase()]);\nconsole.log(tags);","exercise":"فهرست گروه‌های آموزشی را به یک فهرست واحد تبدیل و برای هر برچسب نسخه کوچک و بزرگ بساز.","status":"published","sort_order":12,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-13","course_id":"javascript-intermediate","title":"کپی سطحی و تغییرناپذیری","slug":"javascript-intermediate-13","summary":"کپی سطحی با spread فقط سطح اول را کپی می‌کند؛ اشیای تو در تو همچنان مرجع مشترک دارند.","content_html":"<h3>هدف درس</h3><p>یک نسخه تازه از داده بساز و تغییر را روی نسخه انجام بده.</p><h3>نمونه و بررسی</h3><p>برای سطح تو در تو نیز کپی مستقل بساز.</p><pre><code>const original = {name: \"سارا\", settings: {theme: \"light\"}};\nconst copy = {...original, name: \"مینا\"};\ncopy.settings = {...original.settings, theme: \"dark\"};\nconsole.log(original, copy);</code></pre><h3>تمرین عملی</h3><p>شیء تنظیمات را بدون تغییر شیء اصلی به‌روزرسانی کن و تفاوت کپی سطحی را نشان بده.</p><h3>نکته فنی</h3><p>spread برای داده تو در تو به‌تنهایی deep clone نیست.</p><h3>معیار موفقیت</h3><p>تغییر نسخه جدید روی شیء اصلی اثر نگذارد.</p>","starter_code":"const original = {name: \"سارا\", settings: {theme: \"light\"}};\nconst copy = {...original, name: \"مینا\"};\ncopy.settings = {...original.settings, theme: \"dark\"};\nconsole.log(original, copy);","exercise":"شیء تنظیمات را بدون تغییر شیء اصلی به‌روزرسانی کن و تفاوت کپی سطحی را نشان بده.","status":"published","sort_order":13,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-14","course_id":"javascript-intermediate","title":"تجزیه ساختاریافته با destructuring","slug":"javascript-intermediate-14","summary":"Destructuring مقدارهای آرایه یا ویژگی‌های شیء را به متغیرهای جدا می‌دهد و می‌تواند مقدار پیش‌فرض داشته باشد.","content_html":"<h3>هدف درس</h3><p>چند ویژگی را با یک دستور از شیء جدا کن.</p><h3>نمونه و بررسی</h3><p>برای تغییر نام متغیر از الگوی title: courseTitle استفاده کن.</p><pre><code>const course = {title: \"JavaScript\", level: \"intermediate\", language: \"fa\"};\nconst {title, level, duration = 20} = course;\nconsole.log(title, level, duration);</code></pre><h3>تمرین عملی</h3><p>از شیء پاسخ API نام، وضعیت و مقدار پیش‌فرض تصویر را استخراج کن.</p><h3>نکته فنی</h3><p>مقدار پیش‌فرض فقط هنگام undefined اعمال می‌شود، نه null.</p><h3>معیار موفقیت</h3><p>ویژگی‌های موجود و مقدار پیش‌فرض درست استخراج شوند.</p>","starter_code":"const course = {title: \"JavaScript\", level: \"intermediate\", language: \"fa\"};\nconst {title, level, duration = 20} = course;\nconsole.log(title, level, duration);","exercise":"از شیء پاسخ API نام، وضعیت و مقدار پیش‌فرض تصویر را استخراج کن.","status":"published","sort_order":14,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-15","course_id":"javascript-intermediate","title":"پارامترهای rest و spread","slug":"javascript-intermediate-15","summary":"rest چند آرگومان باقی‌مانده را در آرایه جمع می‌کند؛ spread آرایه یا شیء را در محل مصرف باز می‌کند.","content_html":"<h3>هدف درس</h3><p>تعداد متغیر ورودی‌ها را مدیریت کن.</p><h3>نمونه و بررسی</h3><p>rest باید آخرین پارامتر تعریف تابع باشد.</p><pre><code>function average(...values) {\n  return values.length ? values.reduce((sum, n) =&gt; sum + n, 0) / values.length : 0;\n}\nconsole.log(average(12, 16, 20));</code></pre><h3>تمرین عملی</h3><p>تابعی برای محاسبه میانگین تعداد نامشخصی از نمره‌ها بساز و آن را با آرایه spread فراخوانی کن.</p><h3>نکته فنی</h3><p>spread کپی عمیق ایجاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>تابع با یک، چند و صفر ورودی رفتار تعریف‌شده داشته باشد.</p>","starter_code":"function average(...values) {\n  return values.length ? values.reduce((sum, n) => sum + n, 0) / values.length : 0;\n}\nconsole.log(average(12, 16, 20));","exercise":"تابعی برای محاسبه میانگین تعداد نامشخصی از نمره‌ها بساز و آن را با آرایه spread فراخوانی کن.","status":"published","sort_order":15,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-16","course_id":"javascript-intermediate","title":"دسترسی ایمن با optional chaining","slug":"javascript-intermediate-16","summary":"عملگر ?. پیش از دسترسی به ویژگی یا فراخوانی، null و undefined را بررسی می‌کند و از خطای دسترسی جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>دسترسی به مسیرهای احتمالیِ خالی را ایمن کن.</p><h3>نمونه و بررسی</h3><p>optional chaining را فقط جایی به کار ببر که نبودن داده قابل قبول است.</p><pre><code>const student = {profile: {name: \"آوا\"}};\nconsole.log(student.profile?.name);\nconsole.log(student.contact?.email);</code></pre><h3>تمرین عملی</h3><p>از پاسخ ناقص پروفایل، نام شهر و نشانی ایمیل اختیاری را بدون خطا بخوان.</p><h3>نکته فنی</h3><p>این عملگر خطای ساختار داده را پنهان نکند؛ داده ضروری را جداگانه اعتبارسنجی کن.</p><h3>معیار موفقیت</h3><p>مسیر موجود خوانده و مسیر ناموجود بدون TypeError مدیریت شود.</p>","starter_code":"const student = {profile: {name: \"آوا\"}};\nconsole.log(student.profile?.name);\nconsole.log(student.contact?.email);","exercise":"از پاسخ ناقص پروفایل، نام شهر و نشانی ایمیل اختیاری را بدون خطا بخوان.","status":"published","sort_order":16,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-17","course_id":"javascript-intermediate","title":"مقدار جایگزین با nullish coalescing","slug":"javascript-intermediate-17","summary":"عملگر ?? فقط برای null و undefined مقدار جایگزین می‌دهد؛ برخلاف || مقدارهای معتبر مانند صفر و رشته خالی را جایگزین نمی‌کند.","content_html":"<h3>هدف درس</h3><p>تفاوت مقدار خالی با مقدار صفر را در منطق پیش‌فرض‌گذاری رعایت کن.</p><h3>نمونه و بررسی</h3><p>برای مقدارهای عددی معتبر مانند صفر از ?? استفاده کن.</p><pre><code>const savedLimit = 0;\nconst limit = savedLimit ?? 10;\nconst fallback = savedLimit || 10;\nconsole.log(limit, fallback);</code></pre><h3>تمرین عملی</h3><p>برای شمارنده‌ای که صفر مقدار معتبر است، مقدار پیش‌فرض را با ?? تعیین کن.</p><h3>نکته فنی</h3><p>ترکیب ?? با && یا || بدون پرانتز مجاز نیست.</p><h3>معیار موفقیت</h3><p>صفر حفظ شود و فقط null یا undefined مقدار جایگزین بگیرند.</p>","starter_code":"const savedLimit = 0;\nconst limit = savedLimit ?? 10;\nconst fallback = savedLimit || 10;\nconsole.log(limit, fallback);","exercise":"برای شمارنده‌ای که صفر مقدار معتبر است، مقدار پیش‌فرض را با ?? تعیین کن.","status":"published","sort_order":17,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-18","course_id":"javascript-intermediate","title":"مجموعه یکتا با Set","slug":"javascript-intermediate-18","summary":"Set فقط یک نمونه از هر مقدار را نگه می‌دارد و برای حذف مقدارهای تکراری یا بررسی عضویت مناسب است.","content_html":"<h3>هدف درس</h3><p>تکرار مقدارهای اولیه را حذف کن.</p><h3>نمونه و بررسی</h3><p>برای بررسی عضویت از has استفاده کن.</p><pre><code>const tags = [\"html\", \"css\", \"html\", \"js\"];\nconst uniqueTags = [...new Set(tags)];\nconsole.log(uniqueTags);</code></pre><h3>تمرین عملی</h3><p>از آرایه شناسه‌های تکراری، فهرست یکتا بساز و وجود یک شناسه را بررسی کن.</p><h3>نکته فنی</h3><p>اشیای جداگانه با محتوای مشابه در Set همچنان دو مرجع متفاوت‌اند.</p><h3>معیار موفقیت</h3><p>تکرار رشته‌ها حذف و ترتیب ورود مقدارهای یکتا حفظ شود.</p>","starter_code":"const tags = [\"html\", \"css\", \"html\", \"js\"];\nconst uniqueTags = [...new Set(tags)];\nconsole.log(uniqueTags);","exercise":"از آرایه شناسه‌های تکراری، فهرست یکتا بساز و وجود یک شناسه را بررسی کن.","status":"published","sort_order":18,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-19","course_id":"javascript-intermediate","title":"نگاشت کلید و مقدار با Map","slug":"javascript-intermediate-19","summary":"Map نگاشت کلید به مقدار است؛ برخلاف شیء، کلید می‌تواند هر نوع داده باشد و اندازه با size مشخص می‌شود.","content_html":"<h3>هدف درس</h3><p>داده‌های کلید-مقدار را با Map مدیریت کن.</p><h3>نمونه و بررسی</h3><p>برای تغییر مقدار از set و برای حذف از delete استفاده کن.</p><pre><code>const progress = new Map();\nprogress.set(\"student-12\", 8);\nprogress.set(\"student-13\", 5);\nconsole.log(progress.get(\"student-12\"), progress.size);</code></pre><h3>تمرین عملی</h3><p>وضعیت پیشرفت چند دانش‌آموز را با شناسه به‌عنوان کلید ذخیره و یک مقدار را به‌روزرسانی کن.</p><h3>نکته فنی</h3><p>Map ترتیب درج را حفظ می‌کند و کلیدهای آن می‌توانند غیررشته‌ای باشند.</p><h3>معیار موفقیت</h3><p>خواندن، به‌روزرسانی و شمارش رکوردها درست انجام شود.</p>","starter_code":"const progress = new Map();\nprogress.set(\"student-12\", 8);\nprogress.set(\"student-13\", 5);\nconsole.log(progress.get(\"student-12\"), progress.size);","exercise":"وضعیت پیشرفت چند دانش‌آموز را با شناسه به‌عنوان کلید ذخیره و یک مقدار را به‌روزرسانی کن.","status":"published","sort_order":19,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-20","course_id":"javascript-intermediate","title":"تاریخ و زمان با Date","slug":"javascript-intermediate-20","summary":"Date زمان را به‌صورت timestamp نگه می‌دارد. برای نمایش وابسته به زبان و منطقه از Intl.DateTimeFormat استفاده کن.","content_html":"<h3>هدف درس</h3><p>زمان را از تاریخ نمایشی جدا نگه دار و در زمان نمایش قالب‌بندی کن.</p><h3>نمونه و بررسی</h3><p>برای داده‌های سرور زمان استاندارد ISO و منطقه زمانی صریح در نظر بگیر.</p><pre><code>const createdAt = new Date(\"2026-11-07T10:30:00Z\");\nconst formatter = new Intl.DateTimeFormat(\"fa-IR\", {dateStyle: \"long\", timeStyle: \"short\", timeZone: \"Asia/Kabul\"});\nconsole.log(formatter.format(createdAt));</code></pre><h3>تمرین عملی</h3><p>تاریخ ثبت‌نام را با منطقه زمانی مشخص و قالب فارسی نمایش بده.</p><h3>نکته فنی</h3><p>تجزیه رشته‌های تاریخ مبهم ممکن است بین محیط‌ها تفاوت داشته باشد.</p><h3>معیار موفقیت</h3><p>تاریخ معتبر و با منطقه زمانی موردنظر نمایش داده شود.</p>","starter_code":"const createdAt = new Date(\"2026-11-07T10:30:00Z\");\nconst formatter = new Intl.DateTimeFormat(\"fa-IR\", {dateStyle: \"long\", timeStyle: \"short\", timeZone: \"Asia/Kabul\"});\nconsole.log(formatter.format(createdAt));","exercise":"تاریخ ثبت‌نام را با منطقه زمانی مشخص و قالب فارسی نمایش بده.","status":"published","sort_order":20,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-21","course_id":"javascript-intermediate","title":"الگوهای متنی با Regular Expression","slug":"javascript-intermediate-21","summary":"عبارت منظم برای بررسی الگوی متن کاربرد دارد. test نتیجه تطبیق را به‌صورت Boolean برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>قالب متن را با regex بررسی کن.</p><h3>نمونه و بررسی</h3><p>از ^ و $ برای تطبیق کل رشته استفاده کن.</p><pre><code>const idPattern = /^[a-z0-9]{12}$/;\nconsole.log(idPattern.test(\"ab12cd34ef56\"));\nconsole.log(idPattern.test(\"AB12\"));</code></pre><h3>تمرین عملی</h3><p>الگوی شناسه ۱۲ کاراکتری شامل حروف کوچک انگلیسی و رقم بساز و ورودی‌های مرزی را آزمایش کن.</p><h3>نکته فنی</h3><p>regex به‌تنهایی جایگزین بررسی سمت سرور و سیاست امنیتی نیست.</p><h3>معیار موفقیت</h3><p>شناسه معتبر پذیرفته و شناسه با حروف بزرگ یا طول نادرست رد شود.</p>","starter_code":"const idPattern = /^[a-z0-9]{12}$/;\nconsole.log(idPattern.test(\"ab12cd34ef56\"));\nconsole.log(idPattern.test(\"AB12\"));","exercise":"الگوی شناسه ۱۲ کاراکتری شامل حروف کوچک انگلیسی و رقم بساز و ورودی‌های مرزی را آزمایش کن.","status":"published","sort_order":21,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-22","course_id":"javascript-intermediate","title":"خطاهای سفارشی با throw","slug":"javascript-intermediate-22","summary":"throw برای اعلام خطای قابل‌انتظار در منطق برنامه استفاده می‌شود. خطا باید پیام و نوع معنادار داشته باشد.","content_html":"<h3>هدف درس</h3><p>شرط نامعتبر را به خطای روشن تبدیل کن.</p><h3>نمونه و بررسی</h3><p>نوع خطا را متناسب با مشکل انتخاب کن.</p><pre><code>function setScore(score) {\n  if (!Number.isFinite(score) || score &lt; 0 || score &gt; 100) {\n    throw new RangeError(\"نمره باید بین صفر تا صد باشد\");\n  }\n  return score;\n}\nconsole.log(setScore(85));</code></pre><h3>تمرین عملی</h3><p>تابعی برای تعیین درصد پیشرفت بنویس که مقدار خارج از بازه را با RangeError رد کند.</p><h3>نکته فنی</h3><p>خطای سفارشی باید در لایه مناسب گرفته شود و بی‌صدا نادیده نماند.</p><h3>معیار موفقیت</h3><p>ورودی معتبر برگردد و ورودی نامعتبر خطای قابل تشخیص ایجاد کند.</p>","starter_code":"function setScore(score) {\n  if (!Number.isFinite(score) || score < 0 || score > 100) {\n    throw new RangeError(\"نمره باید بین صفر تا صد باشد\");\n  }\n  return score;\n}\nconsole.log(setScore(85));","exercise":"تابعی برای تعیین درصد پیشرفت بنویس که مقدار خارج از بازه را با RangeError رد کند.","status":"published","sort_order":22,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-23","course_id":"javascript-intermediate","title":"چرخه عمر Promise","slug":"javascript-intermediate-23","summary":"Promise نماینده نتیجه آینده یک عملیات است و سه وضعیت pending، fulfilled و rejected دارد.","content_html":"<h3>هدف درس</h3><p>وضعیت‌های اصلی Promise را درک و نتیجه آن را دریافت کن.</p><h3>نمونه و بررسی</h3><p>resolve و reject را فقط یک بار تعیین تکلیف کن.</p><pre><code>const task = new Promise((resolve) =&gt; {\n  resolve(\"داده آماده شد\");\n});\ntask.then(value =&gt; console.log(value));</code></pre><h3>تمرین عملی</h3><p>یک Promise بساز که در مسیر موفق مقدار دوره و در مسیر ناموفق پیام خطا را برگرداند.</p><h3>نکته فنی</h3><p>Promise به معنی اجرای خودکار عملیات پس‌زمینه نیست؛ فقط نتیجه آینده را مدل می‌کند.</p><h3>معیار موفقیت</h3><p>هر دو مسیر موفق و ناموفق قابل مشاهده و مدیریت باشند.</p>","starter_code":"const task = new Promise((resolve) => {\n  resolve(\"داده آماده شد\");\n});\ntask.then(value => console.log(value));","exercise":"یک Promise بساز که در مسیر موفق مقدار دوره و در مسیر ناموفق پیام خطا را برگرداند.","status":"published","sort_order":23,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-24","course_id":"javascript-intermediate","title":"زنجیره‌سازی Promise","slug":"javascript-intermediate-24","summary":"then نتیجه را به مرحله بعد می‌فرستد و بازگشت Promise باعث زنجیره‌سازی عملیات وابسته می‌شود.","content_html":"<h3>هدف درس</h3><p>خروجی یک مرحله را به مرحله بعدی تحویل بده.</p><h3>نمونه و بررسی</h3><p>هر مرحله مقدار لازم را return کند.</p><pre><code>Promise.resolve(4)\n  .then(value =&gt; value * 3)\n  .then(value =&gt; `امتیاز: ${value}`)\n  .then(console.log);</code></pre><h3>تمرین عملی</h3><p>سه مرحله تبدیل داده را در زنجیره Promise اجرا کن و خطا را در catch بگیر.</p><h3>نکته فنی</h3><p>اگر در then مقدار Promise برگردانی، زنجیره منتظر نتیجه آن می‌ماند.</p><h3>معیار موفقیت</h3><p>مراحل به ترتیب اجرا شوند و خطا به catch برسد.</p>","starter_code":"Promise.resolve(4)\n  .then(value => value * 3)\n  .then(value => `امتیاز: ${value}`)\n  .then(console.log);","exercise":"سه مرحله تبدیل داده را در زنجیره Promise اجرا کن و خطا را در catch بگیر.","status":"published","sort_order":24,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-25","course_id":"javascript-intermediate","title":"نوشتن تابع async","slug":"javascript-intermediate-25","summary":"تابع async همیشه Promise برمی‌گرداند و می‌توان داخل آن از await برای خواندن نتیجه عملیات ناهمگام استفاده کرد.","content_html":"<h3>هدف درس</h3><p>یک تابع ناهمگام تعریف و Promise خروجی آن را بررسی کن.</p><h3>نمونه و بررسی</h3><p>حتی return یک رشته در تابع async به Promise تبدیل می‌شود.</p><pre><code>async function loadMessage() {\n  return \"آماده\";\n}\nloadMessage().then(console.log);</code></pre><h3>تمرین عملی</h3><p>تابعی async بساز که داده ساختگی را برگرداند و نتیجه را با then دریافت کن.</p><h3>نکته فنی</h3><p>خطای داخل async به Promise ردشده تبدیل می‌شود.</p><h3>معیار موفقیت</h3><p>فراخوانی تابع مقدار مورد انتظار را در then دریافت کند.</p>","starter_code":"async function loadMessage() {\n  return \"آماده\";\n}\nloadMessage().then(console.log);","exercise":"تابعی async بساز که داده ساختگی را برگرداند و نتیجه را با then دریافت کن.","status":"published","sort_order":25,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-26","course_id":"javascript-intermediate","title":"انتظار برای عملیات با await","slug":"javascript-intermediate-26","summary":"await اجرای ادامه همان تابع async را تا تعیین تکلیف Promise متوقف می‌کند، نه کل رشته اصلی JavaScript را.","content_html":"<h3>هدف درس</h3><p>ترتیب منطقی چند کار ناهمگام را مدیریت کن.</p><h3>نمونه و بررسی</h3><p>await را داخل تابع async یا محیط ماژولی مجاز استفاده کن.</p><pre><code>const wait = ms =&gt; new Promise(resolve =&gt; setTimeout(resolve, ms));\nasync function announce() {\n  await wait(300);\n  console.log(\"درخواست آماده شد\");\n}\nannounce();</code></pre><h3>تمرین عملی</h3><p>دو عملیات ساختگی را به ترتیب با await اجرا کن و ترتیب پیام‌ها را ثبت کن.</p><h3>نکته فنی</h3><p>await کل مرورگر را متوقف نمی‌کند؛ فقط ادامه تابع async را منتظر می‌گذارد.</p><h3>معیار موفقیت</h3><p>پیام دوم فقط پس از پایان عملیات اول نمایش داده شود.</p>","starter_code":"const wait = ms => new Promise(resolve => setTimeout(resolve, ms));\nasync function announce() {\n  await wait(300);\n  console.log(\"درخواست آماده شد\");\n}\nannounce();","exercise":"دو عملیات ساختگی را به ترتیب با await اجرا کن و ترتیب پیام‌ها را ثبت کن.","status":"published","sort_order":26,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-27","course_id":"javascript-intermediate","title":"مدیریت خطای ناهمگام","slug":"javascript-intermediate-27","summary":"try/catch خطاهای زمان انتظار و اجرای عملیات async را می‌گیرد؛ finally برای پاک‌سازی در هر دو حالت مناسب است.","content_html":"<h3>هدف درس</h3><p>خطای ناهمگام را مدیریت و پاک‌سازی را تضمین کن.</p><h3>نمونه و بررسی</h3><p>خطا را با اطلاعات مفید ثبت کن و آن را بی‌دلیل مخفی نکن.</p><pre><code>async function readCourse() {\n  try {\n    throw new Error(\"دوره پیدا نشد\");\n  } catch (error) {\n    console.error(error.message);\n  } finally {\n    console.log(\"پایان درخواست\");\n  }\n}\nreadCourse();</code></pre><h3>تمرین عملی</h3><p>عملیات دریافت پروفایل را با مسیر موفق و ناموفق شبیه‌سازی و وضعیت loading را در finally پاک کن.</p><h3>نکته فنی</h3><p>finally در هر دو مسیر اجرا می‌شود؛ خطای داخل finally می‌تواند نتیجه قبلی را تغییر دهد.</p><h3>معیار موفقیت</h3><p>در حالت موفق و خطا loading پاک و پیام مناسب نمایش داده شود.</p>","starter_code":"async function readCourse() {\n  try {\n    throw new Error(\"دوره پیدا نشد\");\n  } catch (error) {\n    console.error(error.message);\n  } finally {\n    console.log(\"پایان درخواست\");\n  }\n}\nreadCourse();","exercise":"عملیات دریافت پروفایل را با مسیر موفق و ناموفق شبیه‌سازی و وضعیت loading را در finally پاک کن.","status":"published","sort_order":27,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-28","course_id":"javascript-intermediate","title":"دریافت داده با Fetch","slug":"javascript-intermediate-28","summary":"fetch درخواست HTTP می‌فرستد و Promise پاسخ را برمی‌گرداند. پاسخ 404 یا 500 الزاماً Promise را reject نمی‌کند؛ response.ok را بررسی کن.","content_html":"<h3>هدف درس</h3><p>چرخه درخواست، بررسی پاسخ و خواندن JSON را اجرا کن.</p><h3>نمونه و بررسی</h3><p>پیش از response.json مقدار response.ok را بررسی کن.</p><pre><code>async function getPosts() {\n  const response = await fetch(\"https://jsonplaceholder.typicode.com/posts?_limit=3\");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  return response.json();\n}\ngetPosts().then(console.log).catch(console.error);</code></pre><h3>تمرین عملی</h3><p>سه رکورد آزمایشی دریافت کن، status را بررسی و JSON را به تابع نمایش تحویل بده.</p><h3>نکته فنی</h3><p>خطای شبکه و خطای HTTP دو حالت متفاوت‌اند و باید جداگانه قابل تشخیص باشند.</p><h3>معیار موفقیت</h3><p>داده JSON در پاسخ موفق خوانده و پاسخ ناموفق به خطای روشن تبدیل شود.</p>","starter_code":"async function getPosts() {\n  const response = await fetch(\"https://jsonplaceholder.typicode.com/posts?_limit=3\");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  return response.json();\n}\ngetPosts().then(console.log).catch(console.error);","exercise":"سه رکورد آزمایشی دریافت کن، status را بررسی و JSON را به تابع نمایش تحویل بده.","status":"published","sort_order":28,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-29","course_id":"javascript-intermediate","title":"پارامترها و headerهای درخواست","slug":"javascript-intermediate-29","summary":"URLSearchParams ساخت query string را امن‌تر می‌کند و headers برای فرستادن نوع محتوا یا اطلاعات مجاز درخواست به کار می‌رود.","content_html":"<h3>هدف درس</h3><p>پارامترهای query و headerهای HTTP را از هم تفکیک کن.</p><h3>نمونه و بررسی</h3><p>برای ساخت query از URLSearchParams استفاده کن.</p><pre><code>const params = new URLSearchParams({q: \"javascript\", limit: \"5\"});\nconst url = `/api/search?${params}`;\nconst options = {headers: {Accept: \"application/json\"}};\nconsole.log(url, options);</code></pre><h3>تمرین عملی</h3><p>درخواستی با پارامتر جست‌وجو، صفحه و header Accept آماده کن و URL نهایی را بررسی کن.</p><h3>نکته فنی</h3><p>هرگز کلید محرمانه را در کد frontend قرار نده.</p><h3>معیار موفقیت</h3><p>پارامترهای فارسی و فاصله‌دار درست encode و header موردنیاز تنظیم شود.</p>","starter_code":"const params = new URLSearchParams({q: \"javascript\", limit: \"5\"});\nconst url = `/api/search?${params}`;\nconst options = {headers: {Accept: \"application/json\"}};\nconsole.log(url, options);","exercise":"درخواستی با پارامتر جست‌وجو، صفحه و header Accept آماده کن و URL نهایی را بررسی کن.","status":"published","sort_order":29,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-30","course_id":"javascript-intermediate","title":"لغو درخواست با AbortController","slug":"javascript-intermediate-30","summary":"AbortController امکان لغو درخواست fetch را فراهم می‌کند؛ signal به درخواست داده می‌شود و abort عملیات را لغو می‌کند.","content_html":"<h3>هدف درس</h3><p>درخواست غیرضروری را در زمان مناسب لغو کن.</p><h3>نمونه و بررسی</h3><p>برای هر درخواست مستقل controller جدا بساز.</p><pre><code>const controller = new AbortController();\nfetch(\"/api/courses\", {signal: controller.signal})\n  .catch(error =&gt; {\n    if (error.name === \"AbortError\") console.log(\"درخواست لغو شد\");\n    else console.error(error);\n  });\ncontroller.abort();</code></pre><h3>تمرین عملی</h3><p>دکمه لغو برای جست‌وجوی طولانی بساز و پس از لغو، پیام مناسب نشان بده.</p><h3>نکته فنی</h3><p>لغو fetch معمولاً با AbortError گزارش می‌شود و باید از خطای شبکه جدا شود.</p><h3>معیار موفقیت</h3><p>درخواست لغوشده پیام لغو نشان دهد و خطاهای دیگر اشتباه دسته‌بندی نشوند.</p>","starter_code":"const controller = new AbortController();\nfetch(\"/api/courses\", {signal: controller.signal})\n  .catch(error => {\n    if (error.name === \"AbortError\") console.log(\"درخواست لغو شد\");\n    else console.error(error);\n  });\ncontroller.abort();","exercise":"دکمه لغو برای جست‌وجوی طولانی بساز و پس از لغو، پیام مناسب نشان بده.","status":"published","sort_order":30,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-31","course_id":"javascript-intermediate","title":"محدودسازی فراخوانی با debounce","slug":"javascript-intermediate-31","summary":"debounce اجرای تابع را تا پایان یک بازه بدون رویداد عقب می‌اندازد و برای جست‌وجوی تایپی از درخواست‌های پرتعداد جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>اجرای callback را تا توقف موقت ورودی به تعویق بینداز.</p><h3>نمونه و بررسی</h3><p>timer قبلی را پیش از ساخت timer جدید پاک کن.</p><pre><code>function debounce(callback, delay) {\n  let timer;\n  return (...args) =&gt; {\n    clearTimeout(timer);\n    timer = setTimeout(() =&gt; callback(...args), delay);\n  };\n}\nconst searchLater = debounce(value =&gt; console.log(value), 300);</code></pre><h3>تمرین عملی</h3><p>برای ورودی جست‌وجو debounce با تأخیر ۳۰۰ میلی‌ثانیه بساز و تعداد اجراها را بشمار.</p><h3>نکته فنی</h3><p>debounce اجرای نهایی را عقب می‌اندازد؛ برای اجرای دوره‌ای مداوم throttle مناسب‌تر است.</p><h3>معیار موفقیت</h3><p>در تایپ سریع فقط آخرین مقدار پس از مکث پردازش شود.</p>","starter_code":"function debounce(callback, delay) {\n  let timer;\n  return (...args) => {\n    clearTimeout(timer);\n    timer = setTimeout(() => callback(...args), delay);\n  };\n}\nconst searchLater = debounce(value => console.log(value), 300);","exercise":"برای ورودی جست‌وجو debounce با تأخیر ۳۰۰ میلی‌ثانیه بساز و تعداد اجراها را بشمار.","status":"published","sort_order":31,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-32","course_id":"javascript-intermediate","title":"واگذاری رویداد به والد","slug":"javascript-intermediate-32","summary":"Event Delegation با ثبت یک شنونده روی والد، رویداد عناصر فرزند پویا را مدیریت می‌کند. closest هدف منطقی را پیدا می‌کند.","content_html":"<h3>هدف درس</h3><p>رویداد فرزندان موجود و آینده را از طریق والد مدیریت کن.</p><h3>نمونه و بررسی</h3><p>از closest و بررسی محدوده والد برای تشخیص عنصر هدف استفاده کن.</p><pre><code>document.querySelector(\"#course-list\")?.addEventListener(\"click\", event =&gt; {\n  const button = event.target.closest(\"button[data-course]\");\n  if (!button) return;\n  console.log(button.dataset.course);\n});</code></pre><h3>تمرین عملی</h3><p>فهرست دوره‌ها را پویا بساز و با یک شنونده والد، کلیک دکمه هر دوره را تشخیص بده.</p><h3>نکته فنی</h3><p>رویدادهای زیادی bubble نمی‌شوند؛ delegation برای رویدادهای مناسب کاربرد دارد.</p><h3>معیار موفقیت</h3><p>دکمه‌های افزوده‌شده پس از بارگذاری نیز با همان شنونده کار کنند.</p>","starter_code":"document.querySelector(\"#course-list\")?.addEventListener(\"click\", event => {\n  const button = event.target.closest(\"button[data-course]\");\n  if (!button) return;\n  console.log(button.dataset.course);\n});","exercise":"فهرست دوره‌ها را پویا بساز و با یک شنونده والد، کلیک دکمه هر دوره را تشخیص بده.","status":"published","sort_order":32,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-33","course_id":"javascript-intermediate","title":"ماژول‌های نام‌دار","slug":"javascript-intermediate-33","summary":"ماژول‌های ES کد را به فایل‌های مستقل تقسیم می‌کنند. export و import نام‌دار باید نام یکسانی داشته باشند.","content_html":"<h3>هدف درس</h3><p>کد مشترک را بین فایل‌های مستقل تقسیم کن.</p><h3>نمونه و بررسی</h3><p>فایل ورودی را با type=\"module\" بارگذاری کن.</p><pre><code>// math.js\nexport function sum(a, b) { return a + b; }\n// app.js\nimport { sum } from \"./math.js\";\nconsole.log(sum(4, 6));</code></pre><h3>تمرین عملی</h3><p>تابع محاسبه درصد را در فایل جدا export و در فایل اصلی import کن.</p><h3>نکته فنی</h3><p>مسیر نسبی import باید دقیق باشد و ماژول‌ها در file:// ممکن است به سرور محلی نیاز داشته باشند.</p><h3>معیار موفقیت</h3><p>تابع از فایل جدا بدون خطای مسیر وارد و اجرا شود.</p>","starter_code":"// math.js\nexport function sum(a, b) { return a + b; }\n// app.js\nimport { sum } from \"./math.js\";\nconsole.log(sum(4, 6));","exercise":"تابع محاسبه درصد را در فایل جدا export و در فایل اصلی import کن.","status":"published","sort_order":33,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-34","course_id":"javascript-intermediate","title":"export پیش‌فرض و بارگذاری پویا","slug":"javascript-intermediate-34","summary":"یک ماژول می‌تواند export default داشته باشد. import() بارگذاری پویا را به شکل Promise انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>ماژول غیرضروری را هنگام نیاز بارگذاری کن.</p><h3>نمونه و بررسی</h3><p>نام export پیش‌فرض در محل import قابل انتخاب است.</p><pre><code>// greeting.js\nexport default function greet(name) { return `سلام ${name}`; }\n// app.js\nimport(\"./greeting.js\").then(module =&gt; console.log(module.default(\"آوا\")));</code></pre><h3>تمرین عملی</h3><p>یک بخش گزارش‌گیری را فقط هنگام کلیک کاربر با import() بارگذاری کن.</p><h3>نکته فنی</h3><p>بارگذاری پویا باید خطای مسیر یا شبکه را نیز مدیریت کند.</p><h3>معیار موفقیت</h3><p>ماژول در زمان نیاز بارگذاری و نتیجه آن نمایش داده شود.</p>","starter_code":"// greeting.js\nexport default function greet(name) { return `سلام ${name}`; }\n// app.js\nimport(\"./greeting.js\").then(module => console.log(module.default(\"آوا\")));","exercise":"یک بخش گزارش‌گیری را فقط هنگام کلیک کاربر با import() بارگذاری کن.","status":"published","sort_order":34,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-35","course_id":"javascript-intermediate","title":"ذخیره موقت نشست با sessionStorage","slug":"javascript-intermediate-35","summary":"sessionStorage مشابه localStorage است اما داده را برای طول عمر همان زبانه مرورگر نگه می‌دارد؛ پس از پایان نشست زبانه پاک می‌شود.","content_html":"<h3>هدف درس</h3><p>داده موقت وابسته به نشست زبانه را ذخیره کن.</p><h3>نمونه و بررسی</h3><p>برای داده‌ای که باید بین نشست‌ها بماند از storage مناسب دیگری استفاده کن.</p><pre><code>sessionStorage.setItem(\"active-tab\", \"progress\");\nconst tab = sessionStorage.getItem(\"active-tab\");\nconsole.log(tab);</code></pre><h3>تمرین عملی</h3><p>تب فعال پنل را در sessionStorage نگه دار و با refresh همان زبانه بازیابی کن.</p><h3>نکته فنی</h3><p>sessionStorage فضای امن برای رمز یا توکن حساس محسوب نمی‌شود.</p><h3>معیار موفقیت</h3><p>تب پس از refresh همان زبانه بازیابی شود و در زبانه جدید رفتار جداگانه داشته باشد.</p>","starter_code":"sessionStorage.setItem(\"active-tab\", \"progress\");\nconst tab = sessionStorage.getItem(\"active-tab\");\nconsole.log(tab);","exercise":"تب فعال پنل را در sessionStorage نگه دار و با refresh همان زبانه بازیابی کن.","status":"published","sort_order":35,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-36","course_id":"javascript-intermediate","title":"پروژه نهایی: جست‌وجوی دوره از API","slug":"javascript-intermediate-36","summary":"در پروژه پایانی Fetch، async/await، debounce، AbortController، filter و DOM را ترکیب می‌کنی تا جست‌وجوی دوره وضعیت loading، خطا و نتیجه خالی داشته باشد.","content_html":"<h3>هدف درس</h3><p>چند مفهوم ناهمگام و ساختار داده را در یک رابط جست‌وجو ادغام کن.</p><h3>نمونه و بررسی</h3><p>درخواست شبکه را از تابع نمایش نتیجه جدا نگه دار و حالت‌های رابط را مشخص کن.</p><pre><code>const input = document.querySelector(\"#course-search\");\nconst output = document.querySelector(\"#results\");\nlet controller;\nasync function searchCourses(query) {\n  controller?.abort();\n  controller = new AbortController();\n  output.textContent = \"در حال جست‌وجو...\";\n  try {\n    const response = await fetch(`/api/courses?q=${encodeURIComponent(query)}`, {signal: controller.signal});\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    const courses = await response.json();\n    output.textContent = courses.length ? courses.map(course =&gt; course.title).join(\"، \") : \"نتیجه‌ای پیدا نشد\";\n  } catch (error) {\n    if (error.name !== \"AbortError\") output.textContent = \"دریافت اطلاعات ناموفق بود\";\n  }\n}\n// searchCourses(\"javascript\");</code></pre><h3>تمرین عملی</h3><p>پروژه را با API آزمایشی یا داده ساختگی کامل کن؛ debounce جست‌وجو، لغو درخواست قبلی، حالت loading، خطا، نتیجه خالی و نمایش چند نتیجه را آزمایش کن.</p><h3>نکته فنی</h3><p>API نمونه ممکن است نیازمند مسیر واقعی و CORS مناسب باشد؛ برای تست مستقل می‌توانی پاسخ ساختگی جایگزین کنی.</p><h3>معیار موفقیت</h3><p>در تایپ سریع درخواست قبلی لغو شود و نتیجه، خطا و حالت خالی به‌درستی نمایش داده شوند.</p>","starter_code":"const input = document.querySelector(\"#course-search\");\nconst output = document.querySelector(\"#results\");\nlet controller;\nasync function searchCourses(query) {\n  controller?.abort();\n  controller = new AbortController();\n  output.textContent = \"در حال جست‌وجو...\";\n  try {\n    const response = await fetch(`/api/courses?q=${encodeURIComponent(query)}`, {signal: controller.signal});\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    const courses = await response.json();\n    output.textContent = courses.length ? courses.map(course => course.title).join(\"، \") : \"نتیجه‌ای پیدا نشد\";\n  } catch (error) {\n    if (error.name !== \"AbortError\") output.textContent = \"دریافت اطلاعات ناموفق بود\";\n  }\n}\n// searchCourses(\"javascript\");","exercise":"پروژه را با API آزمایشی یا داده ساختگی کامل کن؛ debounce جست‌وجو، لغو درخواست قبلی، حالت loading، خطا، نتیجه خالی و نمایش چند نتیجه را آزمایش کن.","status":"published","sort_order":36,"estimated_minutes":75},{"id":"curriculum-324-javascript-advanced-01","course_id":"javascript-advanced","title":"مدیریت ویژگی‌های شیء با Property Descriptor","slug":"javascript-advanced-01","summary":"Descriptor تعیین می‌کند ویژگی قابل‌نوشتن، حذف و پیمایش باشد یا نه.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های شیء را با descriptor کنترل کن.</p><h3>نمونه و بررسی</h3><p>برای بررسی دقیق از Object.getOwnPropertyDescriptor استفاده کن.</p><pre><code>const item={}; Object.defineProperty(item,\"id\",{value:7,writable:false,enumerable:true}); console.log(Object.getOwnPropertyDescriptor(item,\"id\"));</code></pre><h3>تمرین عملی</h3><p>شیئی بساز که شناسه آن ثابت و عنوانش قابل تغییر باشد.</p><h3>نکته فنی</h3><p>writable و configurable دو کنترل مستقل‌اند.</p><h3>معیار موفقیت</h3><p>شناسه تغییرناپذیر بماند و عنوان قابل تغییر باشد.</p>","starter_code":"const item={}; Object.defineProperty(item,\"id\",{value:7,writable:false,enumerable:true}); console.log(Object.getOwnPropertyDescriptor(item,\"id\"));","exercise":"شیئی بساز که شناسه آن ثابت و عنوانش قابل تغییر باشد.","status":"published","sort_order":1,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-02","course_id":"javascript-advanced","title":"Getter و Setter برای اعتبارسنجی","slug":"javascript-advanced-02","summary":"Accessorها خواندن و نوشتن ویژگی را به منطق کنترل‌شده متصل می‌کنند.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی را در setter انجام بده.</p><h3>نمونه و بررسی</h3><p>Getter بهتر است بدون اثر جانبی باشد.</p><pre><code>const user = {\n  _score: 0,\n  get score() {\n    return this._score;\n  },\n  set score(value) {\n    if (!Number.isFinite(value) || value &lt; 0 || value &gt; 100) {\n      throw new RangeError(\"نمره باید عددی بین صفر تا صد باشد\");\n    }\n    this._score = value;\n  }\n};\nuser.score = 90;\nconsole.log(user.score);</code></pre><h3>تمرین عملی</h3><p>ویژگی progress بساز که فقط عدد بین صفر تا صد بپذیرد.</p><h3>نکته فنی</h3><p>در setter فقط مقایسه بازه کافی نیست؛ NaN با مقایسه‌های معمولی از شرط عبور می‌کند، بنابراین Number.isFinite نیز لازم است.</p><h3>معیار موفقیت</h3><p>مقدار معتبر خوانده شود و مقدار خارج از بازه خطا بدهد.</p>","starter_code":"const user = {\n  _score: 0,\n  get score() {\n    return this._score;\n  },\n  set score(value) {\n    if (!Number.isFinite(value) || value < 0 || value > 100) {\n      throw new RangeError(\"نمره باید عددی بین صفر تا صد باشد\");\n    }\n    this._score = value;\n  }\n};\nuser.score = 90;\nconsole.log(user.score);","exercise":"ویژگی progress بساز که فقط عدد بین صفر تا صد بپذیرد.","status":"published","sort_order":2,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-03","course_id":"javascript-advanced","title":"Proxy برای رهگیری دسترسی","slug":"javascript-advanced-03","summary":"Proxy عملیات روی شیء را با trapهایی مانند get و set رهگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>عملیات شیء را با handler کنترل کن.</p><h3>نمونه و بررسی</h3><p>رفتار عادی را با Reflect حفظ کن.</p><pre><code>const state=new Proxy({theme:\"dark\"},{set(t,k,v){if(k===\"theme\"&amp;&amp;!['dark','light'].includes(v))return false; return Reflect.set(t,k,v)}}); state.theme=\"light\";</code></pre><h3>تمرین عملی</h3><p>تغییر تم را محدود و دسترسی به ویژگی‌ها را ثبت کن.</p><h3>نکته فنی</h3><p>Proxy مرز امنیتی سمت سرور نیست.</p><h3>معیار موفقیت</h3><p>مقدار نامعتبر وارد state نشود.</p>","starter_code":"const state=new Proxy({theme:\"dark\"},{set(t,k,v){if(k===\"theme\"&&!['dark','light'].includes(v))return false; return Reflect.set(t,k,v)}}); state.theme=\"light\";","exercise":"تغییر تم را محدود و دسترسی به ویژگی‌ها را ثبت کن.","status":"published","sort_order":3,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-04","course_id":"javascript-advanced","title":"Reflect و عملیات بازتابی","slug":"javascript-advanced-04","summary":"Reflect API عملیات عمومی شیء را با خروجی قابل پیش‌بینی فراهم می‌کند.","content_html":"<h3>هدف درس</h3><p>عملیات شیء را از طریق Reflect اجرا کن.</p><h3>نمونه و بررسی</h3><p>نتیجه Boolean عملیات را بررسی کن.</p><pre><code>const x={name:\"Ava\"}; Reflect.set(x,\"level\",2); console.log(Reflect.has(x,\"name\"),Reflect.ownKeys(x));</code></pre><h3>تمرین عملی</h3><p>تابعی برای set، has و فهرست کلیدها با Reflect بساز.</p><h3>نکته فنی</h3><p>شکست بعضی عملیات false برمی‌گرداند.</p><h3>معیار موفقیت</h3><p>حالت موفق و ناموفق گزارش شود.</p>","starter_code":"const x={name:\"Ava\"}; Reflect.set(x,\"level\",2); console.log(Reflect.has(x,\"name\"),Reflect.ownKeys(x));","exercise":"تابعی برای set، has و فهرست کلیدها با Reflect بساز.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-05","course_id":"javascript-advanced","title":"WeakRef و ارجاع ضعیف","slug":"javascript-advanced-05","summary":"WeakRef ارجاعی می‌سازد که به‌تنهایی مانع garbage collection نمی‌شود.","content_html":"<h3>هدف درس</h3><p>ارجاع قوی و ضعیف را مقایسه کن.</p><h3>نمونه و بررسی</h3><p>deref ممکن است undefined بدهد.</p><pre><code>let data={label:\"cache\"}; const ref=new WeakRef(data); console.log(ref.deref()?.label); data=null;</code></pre><h3>تمرین عملی</h3><p>نمونه‌ای بساز که نبود شیء پس از deref را مدیریت کند.</p><h3>نکته فنی</h3><p>زمان GC قابل پیش‌بینی نیست.</p><h3>معیار موفقیت</h3><p>کد در هر دو حالت بدون خطا باشد.</p>","starter_code":"let data={label:\"cache\"}; const ref=new WeakRef(data); console.log(ref.deref()?.label); data=null;","exercise":"نمونه‌ای بساز که نبود شیء پس از deref را مدیریت کند.","status":"published","sort_order":5,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-06","course_id":"javascript-advanced","title":"BigInt برای اعداد صحیح بزرگ","slug":"javascript-advanced-06","summary":"BigInt اعداد صحیح فراتر از محدوده امن Number را دقیق نگه می‌دارد.","content_html":"<h3>هدف درس</h3><p>از پسوند n برای عدد صحیح بزرگ استفاده کن.</p><h3>نمونه و بررسی</h3><p>BigInt و Number را مستقیم در عملیات مخلوط نکن.</p><pre><code>const count=9007199254740993n; console.log(count+7n);</code></pre><h3>تمرین عملی</h3><p>شمارنده بسیار بزرگ را بدون افت دقت افزایش بده.</p><h3>نکته فنی</h3><p>JSON به‌طور پیش‌فرض BigInt را serialize نمی‌کند.</p><h3>معیار موفقیت</h3><p>نتیجه دقیق و تبدیل انتقالی آگاهانه باشد.</p>","starter_code":"const count=9007199254740993n; console.log(count+7n);","exercise":"شمارنده بسیار بزرگ را بدون افت دقت افزایش بده.","status":"published","sort_order":6,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-07","course_id":"javascript-advanced","title":"دقت اعشاری در محاسبات مالی","slug":"javascript-advanced-07","summary":"Number ممیز شناور دودویی است؛ مبلغ را در واحد صحیح کوچک‌تر نگه دار.","content_html":"<h3>هدف درس</h3><p>گرد کردن را تا لایه نمایش به تعویق بینداز.</p><h3>نمونه و بررسی</h3><p>واحد پول را در نام متغیر مشخص کن.</p><pre><code>const pricePul=1250*100; const totalPul=pricePul+2750; console.log(totalPul/100);</code></pre><h3>تمرین عملی</h3><p>سبد خرید را با واحد صحیح پول محاسبه کن.</p><h3>نکته فنی</h3><p>خطای ممیز شناور می‌تواند جمع مالی را مخدوش کند.</p><h3>معیار موفقیت</h3><p>جمع دقیق و سیاست گردکردن مستند باشد.</p>","starter_code":"const pricePul=1250*100; const totalPul=pricePul+2750; console.log(totalPul/100);","exercise":"سبد خرید را با واحد صحیح پول محاسبه کن.","status":"published","sort_order":7,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-08","course_id":"javascript-advanced","title":"TypedArray برای داده عددی","slug":"javascript-advanced-08","summary":"TypedArray داده را با نوع عددی و حافظه فشرده نگه می‌دارد.","content_html":"<h3>هدف درس</h3><p>نوع آرایه را بر اساس دامنه داده انتخاب کن.</p><h3>نمونه و بررسی</h3><p>تبدیل خارج از دامنه را بررسی کن.</p><pre><code>const values=new Int16Array([120,-30,450]); values[1]=25; console.log(values,values.BYTES_PER_ELEMENT);</code></pre><h3>تمرین عملی</h3><p>داده حسگر را در Int16Array ذخیره و مقادیر مرزی را آزمایش کن.</p><h3>نکته فنی</h3><p>مقدار خارج از محدوده ممکن است wrap شود.</p><h3>معیار موفقیت</h3><p>نوع و مقدارهای مرزی درست مدیریت شوند.</p>","starter_code":"const values=new Int16Array([120,-30,450]); values[1]=25; console.log(values,values.BYTES_PER_ELEMENT);","exercise":"داده حسگر را در Int16Array ذخیره و مقادیر مرزی را آزمایش کن.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-09","course_id":"javascript-advanced","title":"ArrayBuffer و DataView","slug":"javascript-advanced-09","summary":"ArrayBuffer حافظه خام و DataView ابزار خواندن انواع مختلف با کنترل endianness است.","content_html":"<h3>هدف درس</h3><p>offset و نوع داده را دقیق تعیین کن.</p><h3>نمونه و بررسی</h3><p>endianness را در هر دو سمت یکسان بگیر.</p><pre><code>const b=new ArrayBuffer(8),v=new DataView(b); v.setUint32(0,2026,false); v.setFloat32(4,3.5,false); console.log(v.getUint32(0,false),v.getFloat32(4,false));</code></pre><h3>تمرین عملی</h3><p>رکورد باینری با عدد صحیح و اعشاری بساز و بخوان.</p><h3>نکته فنی</h3><p>دسترسی خارج از محدوده RangeError می‌دهد.</p><h3>معیار موفقیت</h3><p>مقادیر خوانده‌شده با مقادیر نوشته‌شده برابر باشند.</p>","starter_code":"const b=new ArrayBuffer(8),v=new DataView(b); v.setUint32(0,2026,false); v.setFloat32(4,3.5,false); console.log(v.getUint32(0,false),v.getFloat32(4,false));","exercise":"رکورد باینری با عدد صحیح و اعشاری بساز و بخوان.","status":"published","sort_order":9,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-10","course_id":"javascript-advanced","title":"structuredClone و کپی عمیق","slug":"javascript-advanced-10","summary":"structuredClone بسیاری از ساختارهای داده را به‌صورت عمیق کپی می‌کند.","content_html":"<h3>هدف درس</h3><p>از کپی عمیق برای snapshot داده استفاده کن.</p><h3>نمونه و بررسی</h3><p>بررسی کن داده قابل clone باشد.</p><pre><code>const a={profile:{name:\"Nima\"}}; const b=structuredClone(a); b.profile.name=\"Ava\"; console.log(a.profile.name,b.profile.name);</code></pre><h3>تمرین عملی</h3><p>شیء تو در تو را مستقل کپی و تغییر بده.</p><h3>نکته فنی</h3><p>تابع و DOM Node قابل clone نیستند.</p><h3>معیار موفقیت</h3><p>تغییر کپی روی اصل اثر نگذارد.</p>","starter_code":"const a={profile:{name:\"Nima\"}}; const b=structuredClone(a); b.profile.name=\"Ava\"; console.log(a.profile.name,b.profile.name);","exercise":"شیء تو در تو را مستقل کپی و تغییر بده.","status":"published","sort_order":10,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-11","course_id":"javascript-advanced","title":"Iterator سفارشی","slug":"javascript-advanced-11","summary":"Iterator قرارداد next با value و done را پیاده می‌کند.","content_html":"<h3>هدف درس</h3><p>قرارداد iterator را اجرا کن.</p><h3>نمونه و بررسی</h3><p>وضعیت پیمایش را داخل iterator نگه دار.</p><pre><code>const range={from:1,to:3,[Symbol.iterator](){let n=this.from;const end=this.to;return{next(){return n&lt;=end?{value:n++,done:false}:{done:true}}}}}; console.log([...range]);</code></pre><h3>تمرین عملی</h3><p>شیء بازه صفحات را برای for...of قابل پیمایش کن.</p><h3>نکته فنی</h3><p>پس از پایان done باید true باشد.</p><h3>معیار موفقیت</h3><p>هر مقدار دقیقاً یک بار و به ترتیب برگردد.</p>","starter_code":"const range={from:1,to:3,[Symbol.iterator](){let n=this.from;const end=this.to;return{next(){return n<=end?{value:n++,done:false}:{done:true}}}}}; console.log([...range]);","exercise":"شیء بازه صفحات را برای for...of قابل پیمایش کن.","status":"published","sort_order":11,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-12","course_id":"javascript-advanced","title":"Generator و تولید تنبل","slug":"javascript-advanced-12","summary":"Generator با yield مقدار را تدریجی تولید و وضعیت اجرا را حفظ می‌کند.","content_html":"<h3>هدف درس</h3><p>از function* و yield استفاده کن.</p><h3>نمونه و بررسی</h3><p>Generator مصرف‌شده از ابتدا restart نمی‌شود.</p><pre><code>function* ids(n){for(let i=1;i&lt;=n;i++)yield `lesson-${i}`} console.log([...ids(3)]);</code></pre><h3>تمرین عملی</h3><p>مولد صفحه‌ها بساز که مقدار بعدی را هنگام درخواست تولید کند.</p><h3>نکته فنی</h3><p>تولید تنبل از ساخت آرایه کامل جلوگیری می‌کند.</p><h3>معیار موفقیت</h3><p>مقدارها به‌ترتیب و تدریجی تولید شوند.</p>","starter_code":"function* ids(n){for(let i=1;i<=n;i++)yield `lesson-${i}`} console.log([...ids(3)]);","exercise":"مولد صفحه‌ها بساز که مقدار بعدی را هنگام درخواست تولید کند.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-13","course_id":"javascript-advanced","title":"Async Iterator و for await","slug":"javascript-advanced-13","summary":"Async Iterator نتیجه next را به‌صورت Promise می‌دهد و for await آن را پیمایش می‌کند.","content_html":"<h3>هدف درس</h3><p>داده ناهمگام را تدریجی پیمایش کن.</p><h3>نمونه و بررسی</h3><p>ترتیب دریافت را حفظ کن.</p><pre><code>async function* pages() {\n  yield 1;\n  await new Promise(resolve =&gt; setTimeout(resolve, 50));\n  yield 2;\n}\nasync function readPages() {\n  for await (const page of pages()) {\n    console.log(page);\n  }\n}\nreadPages();</code></pre><h3>تمرین عملی</h3><p>جریان صفحه‌های نتایج را با مکث ناهمگام تولید کن.</p><h3>نکته فنی</h3><p>این نمونه در یک فایل معمولی نیز اجرا می‌شود، چون حلقه for await داخل تابع async قرار گرفته است.</p><h3>معیار موفقیت</h3><p>هر صفحه پس از آماده شدن پردازش شود.</p>","starter_code":"async function* pages() {\n  yield 1;\n  await new Promise(resolve => setTimeout(resolve, 50));\n  yield 2;\n}\nasync function readPages() {\n  for await (const page of pages()) {\n    console.log(page);\n  }\n}\nreadPages();","exercise":"جریان صفحه‌های نتایج را با مکث ناهمگام تولید کن.","status":"published","sort_order":13,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-14","course_id":"javascript-advanced","title":"Promise.all برای عملیات مستقل","slug":"javascript-advanced-14","summary":"Promise.all همه نتایج را به ترتیب ورودی برمی‌گرداند و با رد شدن یکی، کل Promise رد می‌شود.","content_html":"<h3>هدف درس</h3><p>عملیات مستقل را موازی اجرا کن.</p><h3>نمونه و بررسی</h3><p>پاسخ HTTP ناموفق را خودت reject کن.</p><pre><code>async function loadDashboard() {\n  const [profile, courses] = await Promise.all([\n    fetch(\"/api/profile\").then(response =&gt; {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    }),\n    fetch(\"/api/courses\").then(response =&gt; {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    })\n  ]);\n  console.log(profile, courses);\n}\nloadDashboard().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>دو منبع مستقل داشبورد را هم‌زمان دریافت کن.</p><h3>نکته فنی</h3><p>نمونه داخل تابع async قرار دارد؛ برای هر پاسخ HTTP نیز response.ok بررسی شده تا خطای 404 به‌اشتباه موفقیت تلقی نشود.</p><h3>معیار موفقیت</h3><p>هر دو نتیجه پس از موفقیت در دسترس باشند.</p>","starter_code":"async function loadDashboard() {\n  const [profile, courses] = await Promise.all([\n    fetch(\"/api/profile\").then(response => {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    }),\n    fetch(\"/api/courses\").then(response => {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    })\n  ]);\n  console.log(profile, courses);\n}\nloadDashboard().catch(console.error);","exercise":"دو منبع مستقل داشبورد را هم‌زمان دریافت کن.","status":"published","sort_order":14,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-15","course_id":"javascript-advanced","title":"Promise.allSettled برای تاب‌آوری","slug":"javascript-advanced-15","summary":"allSettled وضعیت همه Promiseها را حتی در صورت شکست بعضی از آن‌ها جمع‌آوری می‌کند.","content_html":"<h3>هدف درس</h3><p>وضعیت هر عملیات را جداگانه پردازش کن.</p><h3>نمونه و بررسی</h3><p>پیش از خواندن value یا reason، status را بررسی کن.</p><pre><code>async function inspectPanels() {\n  const results = await Promise.allSettled([\n    Promise.resolve(\"profile\"),\n    Promise.reject(new Error(\"offline\"))\n  ]);\n  for (const result of results) {\n    if (result.status === \"fulfilled\") console.log(\"ready:\", result.value);\n    else console.error(\"failed:\", result.reason);\n  }\n}\ninspectPanels();</code></pre><h3>تمرین عملی</h3><p>سه پنل مستقل را بارگذاری کن و موفق‌ها را حتی با شکست یکی نمایش بده.</p><h3>نکته فنی</h3><p>برای هر نتیجه ابتدا status بررسی می‌شود؛ فقط نتیجه fulfilled دارای value و نتیجه rejected دارای reason است.</p><h3>معیار موفقیت</h3><p>موفقیت و شکست هر بخش جدا نمایش داده شود.</p>","starter_code":"async function inspectPanels() {\n  const results = await Promise.allSettled([\n    Promise.resolve(\"profile\"),\n    Promise.reject(new Error(\"offline\"))\n  ]);\n  for (const result of results) {\n    if (result.status === \"fulfilled\") console.log(\"ready:\", result.value);\n    else console.error(\"failed:\", result.reason);\n  }\n}\ninspectPanels();","exercise":"سه پنل مستقل را بارگذاری کن و موفق‌ها را حتی با شکست یکی نمایش بده.","status":"published","sort_order":15,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-16","course_id":"javascript-advanced","title":"Promise.race و timeout","slug":"javascript-advanced-16","summary":"race با نخستین Promise تعیین‌تکلیف‌شده نتیجه می‌دهد اما عملیات بازنده را متوقف نمی‌کند.","content_html":"<h3>هدف درس</h3><p>حد انتظار را مستقل از درخواست تعریف کن.</p><h3>نمونه و بررسی</h3><p>برای توقف واقعی fetch از signal استفاده کن.</p><pre><code>const timeout=new Promise((_,reject)=&gt;setTimeout(()=&gt;reject(Error(\"timeout\")),2000)); Promise.race([fetch('/api/status'),timeout]).catch(console.error);</code></pre><h3>تمرین عملی</h3><p>timeout بساز و نسخه دارای AbortController را برای لغو واقعی اضافه کن.</p><h3>نکته فنی</h3><p>race به‌تنهایی منابع عملیات بازنده را آزاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>timeout گزارش و درخواست در نسخه نهایی لغو شود.</p>","starter_code":"const timeout=new Promise((_,reject)=>setTimeout(()=>reject(Error(\"timeout\")),2000)); Promise.race([fetch('/api/status'),timeout]).catch(console.error);","exercise":"timeout بساز و نسخه دارای AbortController را برای لغو واقعی اضافه کن.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-17","course_id":"javascript-advanced","title":"Promise.any و نخستین موفقیت","slug":"javascript-advanced-17","summary":"Promise.any نخستین fulfilled را می‌دهد و اگر همه رد شوند AggregateError می‌دهد.","content_html":"<h3>هدف درس</h3><p>از چند منبع نخستین موفقیت را بگیر.</p><h3>نمونه و بررسی</h3><p>پاسخ HTTP ناموفق را به rejection تبدیل کن.</p><pre><code>Promise.any([Promise.reject(\"A\"),Promise.resolve(\"mirror B\")]).then(console.log).catch(e=&gt;console.log(e.errors));</code></pre><h3>تمرین عملی</h3><p>دو منبع جایگزین را بررسی و نخستین پاسخ معتبر را انتخاب کن.</p><h3>نکته فنی</h3><p>همه شکست‌ها در AggregateError قرار می‌گیرند.</p><h3>معیار موفقیت</h3><p>یک موفقیت کافی باشد و شکست همگانی گزارش شود.</p>","starter_code":"Promise.any([Promise.reject(\"A\"),Promise.resolve(\"mirror B\")]).then(console.log).catch(e=>console.log(e.errors));","exercise":"دو منبع جایگزین را بررسی و نخستین پاسخ معتبر را انتخاب کن.","status":"published","sort_order":17,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-18","course_id":"javascript-advanced","title":"Top-level await در ES Module","slug":"javascript-advanced-18","summary":"ماژول می‌تواند پیش از export، داده ناهمگام را در سطح بالا دریافت کند.","content_html":"<h3>هدف درس</h3><p>آماده‌سازی async در سطح ماژول انجام بده.</p><h3>نمونه و بررسی</h3><p>فایل باید با type=module بارگذاری شود.</p><pre><code>const response=await fetch('/config.json'); if(!response.ok) throw Error('config'); export const config=await response.json();</code></pre><h3>تمرین عملی</h3><p>ماژول پیکربندی بساز که قبل از export تنظیمات را آماده کند.</p><h3>نکته فنی</h3><p>وابستگی‌های واردکننده ممکن است منتظر بمانند.</p><h3>معیار موفقیت</h3><p>مصرف‌کننده فقط پیکربندی آماده دریافت کند.</p>","starter_code":"const response=await fetch('/config.json'); if(!response.ok) throw Error('config'); export const config=await response.json();","exercise":"ماژول پیکربندی بساز که قبل از export تنظیمات را آماده کند.","status":"published","sort_order":18,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-19","course_id":"javascript-advanced","title":"MutationObserver برای DOM","slug":"javascript-advanced-19","summary":"MutationObserver تغییرات ساختار و ویژگی DOM را بدون polling گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>تغییرات DOM را مشاهده کن.</p><h3>نمونه و بررسی</h3><p>فقط mutationهای موردنیاز را فعال کن.</p><pre><code>const node=document.querySelector('#list'); const observer=new MutationObserver(records=&gt;console.log(records.length)); if(node) observer.observe(node,{childList:true,subtree:true});</code></pre><h3>تمرین عملی</h3><p>افزوده شدن کارت جدید را تشخیص بده و observer را disconnect کن.</p><h3>نکته فنی</h3><p>callback به‌صورت ناهمگام اجرا می‌شود.</p><h3>معیار موفقیت</h3><p>تغییر تشخیص داده و observer پاک‌سازی شود.</p>","starter_code":"const node=document.querySelector('#list'); const observer=new MutationObserver(records=>console.log(records.length)); if(node) observer.observe(node,{childList:true,subtree:true});","exercise":"افزوده شدن کارت جدید را تشخیص بده و observer را disconnect کن.","status":"published","sort_order":19,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-20","course_id":"javascript-advanced","title":"IntersectionObserver و بارگذاری تنبل","slug":"javascript-advanced-20","summary":"IntersectionObserver ورود عنصر به viewport را تشخیص می‌دهد و برای lazy loading مفید است.","content_html":"<h3>هدف درس</h3><p>ورود عنصر به محدوده دید را تشخیص بده.</p><h3>نمونه و بررسی</h3><p>پس از بارگذاری unobserve کن.</p><pre><code>const observer=new IntersectionObserver(entries=&gt;entries.forEach(e=&gt;{if(e.isIntersecting){console.log(e.target.id);observer.unobserve(e.target)}}),{rootMargin:'100px'}); document.querySelectorAll('[data-watch]').forEach(x=&gt;observer.observe(x));</code></pre><h3>تمرین عملی</h3><p>تصاویر درس را نزدیک viewport بارگذاری کن.</p><h3>نکته فنی</h3><p>این API جایگزین اندازه‌گیری دقیق پیکسلی نیست.</p><h3>معیار موفقیت</h3><p>هر تصویر فقط یک بار بارگذاری شود.</p>","starter_code":"const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){console.log(e.target.id);observer.unobserve(e.target)}}),{rootMargin:'100px'}); document.querySelectorAll('[data-watch]').forEach(x=>observer.observe(x));","exercise":"تصاویر درس را نزدیک viewport بارگذاری کن.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-21","course_id":"javascript-advanced","title":"ResizeObserver و اندازه کامپوننت","slug":"javascript-advanced-21","summary":"ResizeObserver تغییر اندازه عنصر را مستقل از اندازه پنجره گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>اندازه خود عنصر را مشاهده کن.</p><h3>نمونه و بررسی</h3><p>تغییر layout در callback را کنترل کن.</p><pre><code>const panel=document.querySelector('#panel'); const ro=new ResizeObserver(entries=&gt;console.log(entries[0].contentRect.width)); if(panel) ro.observe(panel);</code></pre><h3>تمرین عملی</h3><p>کارت آمار را با عرض container به حالت فشرده یا گسترده ببر.</p><h3>نکته فنی</h3><p>ممکن است حلقه resize ایجاد شود.</p><h3>معیار موفقیت</h3><p>تغییر breakpoint داخلی بدون loop تشخیص داده شود.</p>","starter_code":"const panel=document.querySelector('#panel'); const ro=new ResizeObserver(entries=>console.log(entries[0].contentRect.width)); if(panel) ro.observe(panel);","exercise":"کارت آمار را با عرض container به حالت فشرده یا گسترده ببر.","status":"published","sort_order":21,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-22","course_id":"javascript-advanced","title":"CustomEvent برای ارتباط اجزا","slug":"javascript-advanced-22","summary":"CustomEvent payload را در detail حمل می‌کند و وابستگی مستقیم کامپوننت‌ها را کم می‌کند.","content_html":"<h3>هدف درس</h3><p>ارتباط event-driven بساز.</p><h3>نمونه و بررسی</h3><p>نام رویداد و schema داده را مستند کن.</p><pre><code>document.addEventListener(\"course:completed\", event =&gt; {\n  console.log(\"progress update:\", event.detail);\n});\nconst completion = new CustomEvent(\"course:completed\", {\n  detail: {id: \"js-36\", score: 95}\n});\ndocument.dispatchEvent(completion);</code></pre><h3>تمرین عملی</h3><p>رویداد تکمیل درس را منتشر و در نوار پیشرفت دریافت کن.</p><h3>نکته فنی</h3><p>ابتدا شنونده ثبت می‌شود و بعد رویداد منتشر می‌شود؛ dispatch پیش از ثبت listener باعث از دست رفتن همان رویداد می‌شود.</p><h3>معیار موفقیت</h3><p>ناشر و شنونده مستقل و هماهنگ کار کنند.</p>","starter_code":"document.addEventListener(\"course:completed\", event => {\n  console.log(\"progress update:\", event.detail);\n});\nconst completion = new CustomEvent(\"course:completed\", {\n  detail: {id: \"js-36\", score: 95}\n});\ndocument.dispatchEvent(completion);","exercise":"رویداد تکمیل درس را منتشر و در نوار پیشرفت دریافت کن.","status":"published","sort_order":22,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-23","course_id":"javascript-advanced","title":"BroadcastChannel بین زبانه‌ها","slug":"javascript-advanced-23","summary":"BroadcastChannel پیام را میان contextهای هم‌مبدأ پخش می‌کند.","content_html":"<h3>هدف درس</h3><p>پیام بین زبانه‌ها ردوبدل کن.</p><h3>نمونه و بررسی</h3><p>payload را اعتبارسنجی و channel را ببند.</p><pre><code>const channel=new BroadcastChannel('academy'); channel.postMessage({type:'theme',value:'dark'}); channel.onmessage=e=&gt;console.log(e.data);</code></pre><h3>تمرین عملی</h3><p>تغییر تم را بین دو زبانه هم‌مبدأ همگام کن.</p><h3>نکته فنی</h3><p>فقط same-origin را پشتیبانی می‌کند.</p><h3>معیار موفقیت</h3><p>زبانه دیگر پیام را بگیرد و کانال cleanup شود.</p>","starter_code":"const channel=new BroadcastChannel('academy'); channel.postMessage({type:'theme',value:'dark'}); channel.onmessage=e=>console.log(e.data);","exercise":"تغییر تم را بین دو زبانه هم‌مبدأ همگام کن.","status":"published","sort_order":23,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-24","course_id":"javascript-advanced","title":"WebSocket و ارتباط دوطرفه","slug":"javascript-advanced-24","summary":"WebSocket اتصال پایدار دوطرفه می‌سازد و چرخه open، message، error و close باید مدیریت شود.","content_html":"<h3>هدف درس</h3><p>چرخه عمر اتصال را مدیریت کن.</p><h3>نمونه و بررسی</h3><p>فقط در readyState برابر OPEN ارسال کن.</p><pre><code>const socket = new WebSocket(\"wss://echo.websocket.events\");\nsocket.addEventListener(\"open\", () =&gt; socket.send(\"NEXORA\"));\nsocket.addEventListener(\"message\", event =&gt; console.log(event.data));\nsocket.addEventListener(\"error\", error =&gt; console.error(\"WebSocket error:\", error));\nsocket.addEventListener(\"close\", event =&gt; console.log(\"closed:\", event.code));</code></pre><h3>تمرین عملی</h3><p>نمایشگر وضعیت زنده بساز و هنگام خروج اتصال را ببند.</p><h3>نکته فنی</h3><p>این نشانی یک سرویس echo بیرونی برای آزمایش است و ممکن است همیشه در دسترس نباشد؛ در محصول واقعی از endpoint تحت کنترل خودت استفاده کن.</p><h3>معیار موفقیت</h3><p>بازشدن، پیام و بسته‌شدن کنترل‌شده دیده شود.</p>","starter_code":"const socket = new WebSocket(\"wss://echo.websocket.events\");\nsocket.addEventListener(\"open\", () => socket.send(\"NEXORA\"));\nsocket.addEventListener(\"message\", event => console.log(event.data));\nsocket.addEventListener(\"error\", error => console.error(\"WebSocket error:\", error));\nsocket.addEventListener(\"close\", event => console.log(\"closed:\", event.code));","exercise":"نمایشگر وضعیت زنده بساز و هنگام خروج اتصال را ببند.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-25","course_id":"javascript-advanced","title":"ReadableStream و پردازش جریانی","slug":"javascript-advanced-25","summary":"Streams API پاسخ بزرگ را chunk به chunk پردازش می‌کند.","content_html":"<h3>هدف درس</h3><p>داده را تدریجی مصرف کن.</p><h3>نمونه و بررسی</h3><p>reader را در پایان آزاد یا cancel کن.</p><pre><code>async function readReport() {\n  const response = await fetch(\"/api/report\");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  if (!response.body) throw new Error(\"ReadableStream در دسترس نیست\");\n  const reader = response.body.getReader();\n  try {\n    const {value, done} = await reader.read();\n    console.log({chunkBytes: value?.length, done});\n  } finally {\n    await reader.cancel();\n  }\n}\nreadReport().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>گزارش حجیم را قطعه‌ای بخوان و هنگام ترک صفحه لغو کن.</p><h3>نکته فنی</h3><p>کد نمونه یک chunk را می‌خواند و سپس reader را در finally لغو می‌کند؛ برای پردازش کامل باید تا done شدن جریان حلقه بخوانی.</p><h3>معیار موفقیت</h3><p>chunk خوانده و منابع هنگام لغو آزاد شوند.</p>","starter_code":"async function readReport() {\n  const response = await fetch(\"/api/report\");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  if (!response.body) throw new Error(\"ReadableStream در دسترس نیست\");\n  const reader = response.body.getReader();\n  try {\n    const {value, done} = await reader.read();\n    console.log({chunkBytes: value?.length, done});\n  } finally {\n    await reader.cancel();\n  }\n}\nreadReport().catch(console.error);","exercise":"گزارش حجیم را قطعه‌ای بخوان و هنگام ترک صفحه لغو کن.","status":"published","sort_order":25,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-26","course_id":"javascript-advanced","title":"IndexedDB برای ذخیره ساختاریافته","slug":"javascript-advanced-26","summary":"IndexedDB پایگاه داده ناهمگام مرورگر با object store و transaction است.","content_html":"<h3>هدف درس</h3><p>داده ساختاریافته را در مرورگر ذخیره کن.</p><h3>نمونه و بررسی</h3><p>schema را در onupgradeneeded مدیریت کن.</p><pre><code>const req=indexedDB.open('AcademyDB',1); req.onupgradeneeded=()=&gt;req.result.createObjectStore('lessons',{keyPath:'id'}); req.onsuccess=()=&gt;console.log('ready'); req.onerror=()=&gt;console.error(req.error);</code></pre><h3>تمرین عملی</h3><p>store درس بساز و درج و بازیابی رکورد را با transaction پیاده کن.</p><h3>نکته فنی</h3><p>داده حساس را در IndexedDB بدون حفاظت نگذار.</p><h3>معیار موفقیت</h3><p>ساخت، درج، بازیابی و خطا مدیریت شود.</p>","starter_code":"const req=indexedDB.open('AcademyDB',1); req.onupgradeneeded=()=>req.result.createObjectStore('lessons',{keyPath:'id'}); req.onsuccess=()=>console.log('ready'); req.onerror=()=>console.error(req.error);","exercise":"store درس بساز و درج و بازیابی رکورد را با transaction پیاده کن.","status":"published","sort_order":26,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-27","course_id":"javascript-advanced","title":"Cache API و راهبرد کش","slug":"javascript-advanced-27","summary":"Cache API پاسخ‌ها را ذخیره می‌کند؛ cache key و سیاست به‌روزرسانی باید روشن باشد.","content_html":"<h3>هدف درس</h3><p>پاسخ را ذخیره و بازیابی کن.</p><h3>نمونه و بررسی</h3><p>برای داده پویا سیاست network-first یا stale-while-revalidate انتخاب کن.</p><pre><code>async function cacheDemo() {\n  const cache = await caches.open(\"nexora-v1\");\n  await cache.put(\"/demo.txt\", new Response(\"academy\"));\n  const saved = await cache.match(\"/demo.txt\");\n  console.log(await saved?.text());\n}\ncacheDemo().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>فایل استاتیک نسخه‌دار را cache و cache قدیمی را پاک‌سازی کن.</p><h3>نکته فنی</h3><p>Cache API در محیط‌های امن مانند HTTPS یا localhost قابل استفاده است و برای فایل‌های پویا باید سیاست تازگی مشخص داشته باشی.</p><h3>معیار موفقیت</h3><p>نسخه جدید بدون نمایش فایل قدیمی ناخواسته ارائه شود.</p>","starter_code":"async function cacheDemo() {\n  const cache = await caches.open(\"nexora-v1\");\n  await cache.put(\"/demo.txt\", new Response(\"academy\"));\n  const saved = await cache.match(\"/demo.txt\");\n  console.log(await saved?.text());\n}\ncacheDemo().catch(console.error);","exercise":"فایل استاتیک نسخه‌دار را cache و cache قدیمی را پاک‌سازی کن.","status":"published","sort_order":27,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-28","course_id":"javascript-advanced","title":"Service Worker و چرخه عمر","slug":"javascript-advanced-28","summary":"Service Worker چرخه install، activate و fetch دارد و در secure context ثبت می‌شود.","content_html":"<h3>هدف درس</h3><p>چرخه عمر worker را پیاده کن.</p><h3>نمونه و بررسی</h3><p>scope و cache version را بررسی کن.</p><pre><code>if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').then(r=&gt;console.log(r.scope)).catch(console.error);</code></pre><h3>تمرین عملی</h3><p>worker بساز که فایل ضروری را cache و نسخه قدیمی را حذف کند.</p><h3>نکته فنی</h3><p>در localhost و HTTPS قابل استفاده است.</p><h3>معیار موفقیت</h3><p>ثبت، فعال‌سازی و کنترل scope تست شود.</p>","starter_code":"if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').then(r=>console.log(r.scope)).catch(console.error);","exercise":"worker بساز که فایل ضروری را cache و نسخه قدیمی را حذف کند.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-29","course_id":"javascript-advanced","title":"Web Worker برای پردازش سنگین","slug":"javascript-advanced-29","summary":"Web Worker محاسبات را از main thread جدا می‌کند اما DOM در worker در دسترس نیست.","content_html":"<h3>هدف درس</h3><p>کار CPU را از رشته اصلی خارج کن.</p><h3>نمونه و بررسی</h3><p>پیام‌ها را ساختاریافته و خطاها را مدیریت کن.</p><pre><code>// worker.js: self.onmessage=e=&gt;self.postMessage(e.data.values.reduce((a,b)=&gt;a+b,0));\n// main.js: const w=new Worker('./worker.js'); w.postMessage({values:[1,2,3]}); w.onmessage=e=&gt;console.log(e.data);</code></pre><h3>تمرین عملی</h3><p>محاسبه حجیم را به worker بسپار و نتیجه را به رابط برگردان.</p><h3>نکته فنی</h3><p>انتقال داده معمولاً structured clone است.</p><h3>معیار موفقیت</h3><p>رابط روان بماند و نتیجه صحیح برگردد.</p>","starter_code":"// worker.js: self.onmessage=e=>self.postMessage(e.data.values.reduce((a,b)=>a+b,0));\n// main.js: const w=new Worker('./worker.js'); w.postMessage({values:[1,2,3]}); w.onmessage=e=>console.log(e.data);","exercise":"محاسبه حجیم را به worker بسپار و نتیجه را به رابط برگردان.","status":"published","sort_order":29,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-30","course_id":"javascript-advanced","title":"Performance API و اندازه‌گیری","slug":"javascript-advanced-30","summary":"Performance mark و measure زمان اجرای بخش مشخص را اندازه می‌گیرند.","content_html":"<h3>هدف درس</h3><p>گلوگاه را با اندازه‌گیری واقعی پیدا کن.</p><h3>نمونه و بررسی</h3><p>شرایط و تعداد تکرارها را ثابت نگه دار.</p><pre><code>performance.mark('start'); const data=Array.from({length:1000},(_,i)=&gt;i*2); performance.mark('end'); performance.measure('build','start','end'); console.log(performance.getEntriesByName('build').at(-1).duration);</code></pre><h3>تمرین عملی</h3><p>دو روش ساخت فهرست را در چند اجرای تکراری مقایسه کن.</p><h3>نکته فنی</h3><p>یک اجرا تحت تأثیر JIT و نویز است.</p><h3>معیار موفقیت</h3><p>نتیجه تکرارپذیر باشد و از یک نمونه نتیجه‌گیری نشود.</p>","starter_code":"performance.mark('start'); const data=Array.from({length:1000},(_,i)=>i*2); performance.mark('end'); performance.measure('build','start','end'); console.log(performance.getEntriesByName('build').at(-1).duration);","exercise":"دو روش ساخت فهرست را در چند اجرای تکراری مقایسه کن.","status":"published","sort_order":30,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-31","course_id":"javascript-advanced","title":"PerformanceObserver و پایش منابع","slug":"javascript-advanced-31","summary":"PerformanceObserver ورودی‌های عملکردی مانند resource را به‌صورت رویدادی گزارش می‌کند.","content_html":"<h3>هدف درس</h3><p>پایش عملکرد بدون polling انجام بده.</p><h3>نمونه و بررسی</h3><p>supportedEntryTypes را بررسی کن.</p><pre><code>const observer=new PerformanceObserver(list=&gt;list.getEntries().forEach(e=&gt;console.log(e.name,e.duration))); observer.observe({type:'resource',buffered:true});</code></pre><h3>تمرین عملی</h3><p>منابع کند را ثبت و بعد observer را متوقف کن.</p><h3>نکته فنی</h3><p>پشتیبانی entry type بین مرورگرها فرق دارد.</p><h3>معیار موفقیت</h3><p>گزارش ثبت و observer پاک‌سازی شود.</p>","starter_code":"const observer=new PerformanceObserver(list=>list.getEntries().forEach(e=>console.log(e.name,e.duration))); observer.observe({type:'resource',buffered:true});","exercise":"منابع کند را ثبت و بعد observer را متوقف کن.","status":"published","sort_order":31,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-32","course_id":"javascript-advanced","title":"جلوگیری از XSS در DOM","slug":"javascript-advanced-32","summary":"ورودی غیرقابل‌اعتماد اگر به‌عنوان HTML اجرا شود می‌تواند XSS ایجاد کند؛ برای متن از textContent استفاده کن.","content_html":"<h3>هدف درس</h3><p>داده را از markup اجرایی جدا نگه دار.</p><h3>نمونه و بررسی</h3><p>برای HTML ضروری از sanitizer معتبر استفاده کن.</p><pre><code>const comment='&lt;img src=x onerror=alert(1)&gt;'; document.querySelector('#comment').textContent=comment;</code></pre><h3>تمرین عملی</h3><p>نمایش نظر کاربران را ایمن کن و خطر innerHTML را با نمونه توضیح بده.</p><h3>نکته فنی</h3><p>replace ساده sanitizer کامل نیست.</p><h3>معیار موفقیت</h3><p>ورودی به‌صورت متن نمایش یابد و اجرا نشود.</p>","starter_code":"const comment='<img src=x onerror=alert(1)>'; document.querySelector('#comment').textContent=comment;","exercise":"نمایش نظر کاربران را ایمن کن و خطر innerHTML را با نمونه توضیح بده.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-33","course_id":"javascript-advanced","title":"CSP و Trusted Types","slug":"javascript-advanced-33","summary":"CSP منابع و اسکریپت‌های مجاز را محدود می‌کند؛ Trusted Types در مرورگرهای پشتیبان sinkهای حساس را کنترل می‌کند.","content_html":"<h3>هدف درس</h3><p>سطح اجرای کد را محدود کن.</p><h3>نمونه و بررسی</h3><p>ابتدا Report-Only و سپس enforcement را آزمایش کن.</p><pre><code>// HTTP header example:\n// Content-Security-Policy: default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'</code></pre><h3>تمرین عملی</h3><p>سیاست CSP سایت را طراحی و منابع مجاز را فهرست کن.</p><h3>نکته فنی</h3><p>CSP جایگزین اصلاح XSS نیست.</p><h3>معیار موفقیت</h3><p>منابع ضروری کار و منابع ناخواسته مسدود شوند.</p>","starter_code":"// HTTP header example:\n// Content-Security-Policy: default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'","exercise":"سیاست CSP سایت را طراحی و منابع مجاز را فهرست کن.","status":"published","sort_order":33,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-34","course_id":"javascript-advanced","title":"Web Crypto API و digest","slug":"javascript-advanced-34","summary":"Web Crypto عملیات رمزنگاری مانند SHA-256 digest را فراهم می‌کند؛ hash ساده برای ذخیره گذرواژه مناسب نیست.","content_html":"<h3>هدف درس</h3><p>از API رمزنگاری استاندارد استفاده کن.</p><h3>نمونه و بررسی</h3><p>برای گذرواژه از Argon2id سمت سرور استفاده کن.</p><pre><code>async function createDigest() {\n  const data = new TextEncoder().encode(\"NEXORA\");\n  const hash = await crypto.subtle.digest(\"SHA-256\", data);\n  const hex = [...new Uint8Array(hash)]\n    .map(byte =&gt; byte.toString(16).padStart(2, \"0\"))\n    .join(\"\");\n  console.log(hex);\n}\ncreateDigest().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>digest یک فایل آزمایشی را محاسبه و تفاوت آن را با password hashing شرح بده.</p><h3>نکته فنی</h3><p>این نمونه باید در secure context مانند HTTPS یا localhost اجرا شود؛ SHA-256 ساده برای ذخیره گذرواژه مناسب نیست.</p><h3>معیار موفقیت</h3><p>digest تکرارپذیر باشد و رمز واقعی در frontend هش/ذخیره نشود.</p>","starter_code":"async function createDigest() {\n  const data = new TextEncoder().encode(\"NEXORA\");\n  const hash = await crypto.subtle.digest(\"SHA-256\", data);\n  const hex = [...new Uint8Array(hash)]\n    .map(byte => byte.toString(16).padStart(2, \"0\"))\n    .join(\"\");\n  console.log(hex);\n}\ncreateDigest().catch(console.error);","exercise":"digest یک فایل آزمایشی را محاسبه و تفاوت آن را با password hashing شرح بده.","status":"published","sort_order":34,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-35","course_id":"javascript-advanced","title":"Intl برای برنامه چندزبانه","slug":"javascript-advanced-35","summary":"Intl قالب‌بندی عدد، ارز، تاریخ و مرتب‌سازی وابسته به locale را انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>داده خام را از قالب نمایشی جدا نگه دار.</p><h3>نمونه و بررسی</h3><p>locale و timezone را صریح انتخاب کن.</p><pre><code>const money=new Intl.NumberFormat('fa-IR',{style:'currency',currency:'AFN'}); const sort=new Intl.Collator('fa',{numeric:true}); console.log(money.format(2450),['درس 10','درس 2'].sort(sort.compare));</code></pre><h3>تمرین عملی</h3><p>قیمت را با AFN و فهرست درس‌ها را با مرتب‌سازی عددی فارسی نمایش بده.</p><h3>نکته فنی</h3><p>خروجی ممکن است به داده‌های ICU محیط وابسته باشد.</p><h3>معیار موفقیت</h3><p>نمایش خوانا باشد و داده خام عددی بماند.</p>","starter_code":"const money=new Intl.NumberFormat('fa-IR',{style:'currency',currency:'AFN'}); const sort=new Intl.Collator('fa',{numeric:true}); console.log(money.format(2450),['درس 10','درس 2'].sort(sort.compare));","exercise":"قیمت را با AFN و فهرست درس‌ها را با مرتب‌سازی عددی فارسی نمایش بده.","status":"published","sort_order":35,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-36","course_id":"javascript-advanced","title":"پروژه نهایی: موتور همگام‌سازی آفلاین","slug":"javascript-advanced-36","summary":"پروژه ترکیبی IndexedDB، Service Worker، Cache، BroadcastChannel و مدیریت تعارض نسخه است.","content_html":"<h3>هدف درس</h3><p>APIهای پیشرفته را در معماری قابل آزمون ترکیب کن.</p><h3>نمونه و بررسی</h3><p>ذخیره محلی، صف ارسال و حل تعارض را جدا طراحی کن.</p><pre><code>const channel=new BroadcastChannel('academy-sync'); channel.postMessage({type:'progress',lessonId:'js-adv-36',revision:3}); channel.onmessage=e=&gt;console.log(e.data);</code></pre><h3>تمرین عملی</h3><p>پیشرفت آفلاین را ذخیره، هنگام اتصال صف را ارسال، تعارض را گزارش و تغییر را به زبانه دیگر اعلام کن.</p><h3>نکته فنی</h3><p>سرور منبع حقیقت است؛ درخواست‌ها باید idempotent و اعتبارسنجی شوند.</p><h3>معیار موفقیت</h3><p>قطع و وصل شبکه داده را از بین نبرد و تعارض پنهان نماند.</p>","starter_code":"const channel=new BroadcastChannel('academy-sync'); channel.postMessage({type:'progress',lessonId:'js-adv-36',revision:3}); channel.onmessage=e=>console.log(e.data);","exercise":"پیشرفت آفلاین را ذخیره، هنگام اتصال صف را ارسال، تعارض را گزارش و تغییر را به زبانه دیگر اعلام کن.","status":"published","sort_order":36,"estimated_minutes":120}]$lessons$::jsonb)
as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();

select c.id,c.title,count(l.id) as published_lessons from public.academy_courses c left join public.academy_lessons l on l.course_id=c.id and l.status='published' where c.status='published' group by c.id,c.title,c.sort_order order by c.sort_order,c.id;
select count(*) as total_published_lessons from public.academy_lessons where status='published';

-- NEXORA FORGE ACADEMY — AUTH, STUDENT STATUS AND SECURE QUIZ PATCH
-- Run once after academy-v2-final.sql and academy-curriculum-324.sql.

alter table public.academy_profiles
  add column if not exists student_code text,
  add column if not exists account_status text not null default 'active';
alter table public.academy_profiles drop constraint if exists academy_profiles_account_status_check;
alter table public.academy_profiles add constraint academy_profiles_account_status_check
  check(account_status in ('active','blocked'));

create or replace function public.academy_generate_student_code()
returns text language plpgsql volatile set search_path=public
as $student_code_gen$
declare
 alphabet constant text:='abcdefghjkmnpqrstuvwxyz23456789';
 bytes bytea; result text; i integer;
begin
 loop
  bytes:=gen_random_bytes(12);result:='';
  for i in 0..11 loop
   result:=result||substr(alphabet,(get_byte(bytes,i)%length(alphabet))+1,1);
  end loop;
  exit when not exists(select 1 from public.academy_profiles where student_code=result);
 end loop;
 return result;
end;
$student_code_gen$;

update public.academy_profiles
set student_code=public.academy_generate_student_code()
where student_code is null or student_code='';
create unique index if not exists academy_profiles_student_code_uidx
on public.academy_profiles(student_code);

revoke update on public.academy_profiles from authenticated;
grant update(display_name,avatar_path) on public.academy_profiles to authenticated;
alter table public.academy_profiles
 alter column student_code set not null,
 alter column student_code set default public.academy_generate_student_code();

create or replace function public.academy_handle_new_user()
returns trigger language plpgsql security definer set search_path=public
as $academy_new_user$
declare requested_code text:=lower(coalesce(new.raw_user_meta_data->>'student_code',''));
begin
 if requested_code<>'' and requested_code !~ '^[a-z0-9]{12}$' then
  raise exception 'Student code must be exactly 12 lowercase letters or digits';
 end if;
 insert into public.academy_profiles(user_id,display_name,student_code,account_status)
 values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''),
  case when requested_code='' then public.academy_generate_student_code() else requested_code end,'active')
 on conflict(user_id) do update set
  display_name=excluded.display_name,
  student_code=coalesce(public.academy_profiles.student_code,excluded.student_code);
 insert into public.academy_user_roles(user_id,role) values(new.id,'student') on conflict do nothing;
 return new;
end;
$academy_new_user$;

create or replace function public.academy_is_active_user()
returns boolean language sql stable security definer set search_path=public
as $academy_active_user$
 select exists(select 1 from public.academy_profiles p
  where p.user_id=(select auth.uid()) and p.account_status='active');
$academy_active_user$;
revoke all on function public.academy_is_active_user() from public;
grant execute on function public.academy_is_active_user() to authenticated;

create table if not exists public.academy_auth_rate_limits(
 key_hash text primary key,
 window_started_at timestamptz not null default now(),
 attempt_count integer not null default 0,
 blocked_until timestamptz
);
alter table public.academy_auth_rate_limits enable row level security;
revoke all on public.academy_auth_rate_limits from anon,authenticated;

create or replace function public.academy_check_login_rate_limit(p_key_hash text,p_failed boolean default false)
returns jsonb language plpgsql security definer set search_path=public
as $academy_rate_limit$
declare r public.academy_auth_rate_limits%rowtype; now_at timestamptz:=now();
begin
 if auth.role()<>'service_role' then raise exception 'Service role required'; end if;
 insert into public.academy_auth_rate_limits(key_hash) values(p_key_hash) on conflict(key_hash) do nothing;
 select * into r from public.academy_auth_rate_limits where key_hash=p_key_hash for update;
 if r.blocked_until is not null and r.blocked_until>now_at then
  return jsonb_build_object('allowed',false,'retry_after',ceil(extract(epoch from (r.blocked_until-now_at)))::integer);
 end if;
 if r.window_started_at<now_at-interval '15 minutes' then
  update public.academy_auth_rate_limits set window_started_at=now_at,
   attempt_count=case when p_failed then 1 else 0 end,blocked_until=null where key_hash=p_key_hash;
  return jsonb_build_object('allowed',true,'remaining',case when p_failed then 7 else 8 end);
 end if;
 if p_failed then
  update public.academy_auth_rate_limits set attempt_count=attempt_count+1,
   blocked_until=case when attempt_count+1>=8 then now_at+interval '15 minutes' else null end
   where key_hash=p_key_hash returning * into r;
 end if;
 if r.attempt_count>=8 and r.blocked_until is not null then
  return jsonb_build_object('allowed',false,'retry_after',900);
 end if;
 return jsonb_build_object('allowed',true,'remaining',greatest(0,8-r.attempt_count));
end;
$academy_rate_limit$;
revoke all on function public.academy_check_login_rate_limit(text,boolean) from public,anon,authenticated;
grant execute on function public.academy_check_login_rate_limit(text,boolean) to service_role;

drop function if exists public.academy_admin_student_overview();
create function public.academy_admin_student_overview()
returns table(user_id uuid,email text,display_name text,student_code text,account_status text,
 created_at timestamptz,completed_lessons bigint,quiz_attempts bigint)
language sql stable security definer set search_path=public
as $academy_admin_overview$
 select p.user_id,u.email,p.display_name,p.student_code,p.account_status,u.created_at,
  (select count(*) from public.academy_lesson_progress lp where lp.user_id=p.user_id and lp.status='completed'),
  (select count(*) from public.academy_quiz_attempts qa where qa.user_id=p.user_id)
 from public.academy_profiles p join auth.users u on u.id=p.user_id
 where public.academy_is_admin() order by u.created_at desc;
$academy_admin_overview$;
revoke all on function public.academy_admin_student_overview() from public,anon;
grant execute on function public.academy_admin_student_overview() to authenticated;

drop policy if exists "academy_avatars_owner_read" on storage.objects;
create policy "academy_avatars_owner_read" on storage.objects
for select to authenticated using(bucket_id='academy-avatars' and public.academy_is_active_user()
 and ((storage.foldername(name))[1]=(select auth.uid())::text or public.academy_is_admin()));
drop policy if exists "academy_avatars_owner_insert" on storage.objects;
create policy "academy_avatars_owner_insert" on storage.objects
for insert to authenticated with check(bucket_id='academy-avatars' and public.academy_is_active_user()
 and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists "academy_avatars_owner_update" on storage.objects;
create policy "academy_avatars_owner_update" on storage.objects
for update to authenticated using(bucket_id='academy-avatars' and public.academy_is_active_user()
 and (storage.foldername(name))[1]=(select auth.uid())::text)
with check(bucket_id='academy-avatars' and public.academy_is_active_user()
 and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists "academy_avatars_owner_delete" on storage.objects;
create policy "academy_avatars_owner_delete" on storage.objects
for delete to authenticated using(bucket_id='academy-avatars' and public.academy_is_active_user()
 and (storage.foldername(name))[1]=(select auth.uid())::text);

drop policy if exists "progress_read_self_or_admin" on public.academy_lesson_progress;
create policy "progress_read_self_or_admin" on public.academy_lesson_progress
for select to authenticated using((user_id=(select auth.uid()) and public.academy_is_active_user()) or public.academy_is_admin());
drop policy if exists "progress_insert_self" on public.academy_lesson_progress;
create policy "progress_insert_self" on public.academy_lesson_progress
for insert to authenticated with check(user_id=(select auth.uid()) and public.academy_is_active_user()
 and exists(select 1 from public.academy_lessons l join public.academy_courses c on c.id=l.course_id
  where l.id=lesson_id and l.status='published' and c.status='published'));
drop policy if exists "progress_update_self" on public.academy_lesson_progress;
create policy "progress_update_self" on public.academy_lesson_progress
for update to authenticated using(user_id=(select auth.uid()) and public.academy_is_active_user())
with check(user_id=(select auth.uid()) and public.academy_is_active_user());

drop policy if exists "attempts_read_self_or_admin" on public.academy_quiz_attempts;
create policy "attempts_read_self_or_admin" on public.academy_quiz_attempts
for select to authenticated using((user_id=(select auth.uid()) and public.academy_is_active_user()) or public.academy_is_admin());
drop policy if exists "answers_read_self_or_admin" on public.academy_quiz_answers;
create policy "answers_read_self_or_admin" on public.academy_quiz_answers
for select to authenticated using(
 (exists(select 1 from public.academy_quiz_attempts a where a.id=attempt_id and a.user_id=(select auth.uid()))
  and public.academy_is_active_user()) or public.academy_is_admin());

create or replace function public.academy_submit_quiz(p_quiz_id uuid,p_answers jsonb)
returns jsonb language plpgsql security definer set search_path=public
as $academy_submit_secure$
declare
 v_user uuid:=auth.uid();v_attempt uuid:=gen_random_uuid();
 v_max numeric(8,2):=0;v_score numeric(8,2):=0;v_percent integer:=0;v_pass integer;
 q record;v_selected uuid;v_correct uuid;v_awarded numeric(8,2);
 v_question_count integer;v_submitted_count integer;
begin
 if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
 if not public.academy_is_active_user() then raise exception 'ACCOUNT_BLOCKED'; end if;
 if coalesce(jsonb_typeof(p_answers),'null')<>'array' then raise exception 'INVALID_ANSWERS'; end if;
 if jsonb_array_length(p_answers)>100 then raise exception 'TOO_MANY_ANSWERS'; end if;
 if not exists(select 1 from public.academy_quizzes where id=p_quiz_id and status='published') then raise exception 'QUIZ_UNAVAILABLE'; end if;
 select pass_percent into v_pass from public.academy_quizzes where id=p_quiz_id;
 select count(*) into v_question_count from public.academy_quiz_questions where quiz_id=p_quiz_id;
 select count(distinct item->>'question_id') into v_submitted_count
 from jsonb_array_elements(p_answers) as a(item)
 where jsonb_typeof(item)='object' and item ? 'question_id' and item ? 'option_id';
 if v_question_count=0 or v_question_count<>v_submitted_count or jsonb_array_length(p_answers)<>v_question_count then
  raise exception 'INCOMPLETE_OR_DUPLICATE_ANSWERS';
 end if;
 if exists(select 1 from jsonb_array_elements(p_answers) as a(item)
  where jsonb_typeof(item)<>'object'
   or coalesce(item->>'question_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(item->>'option_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
  raise exception 'INVALID_ANSWER_FORMAT';
 end if;
 if exists(select 1 from jsonb_array_elements(p_answers) as a(item)
  where not exists(select 1 from public.academy_quiz_questions q
   join public.academy_quiz_options o on o.question_id=q.id
   where q.id=(item->>'question_id')::uuid and q.quiz_id=p_quiz_id
    and o.id=(item->>'option_id')::uuid)) then
  raise exception 'INVALID_ANSWER_REFERENCE';
 end if;
 for q in select id,points from public.academy_quiz_questions where quiz_id=p_quiz_id loop
  v_max:=v_max+q.points;
  select (item->>'option_id')::uuid into v_selected from jsonb_array_elements(p_answers) as a(item)
   where item->>'question_id'=q.id::text;
  select option_id into v_correct from public.academy_quiz_correct_answers where question_id=q.id;
  if v_correct is null then raise exception 'QUIZ_KEY_MISSING'; end if;
  v_awarded:=case when v_selected=v_correct then q.points else 0 end;
  v_score:=v_score+v_awarded;
 end loop;
 if v_max<=0 then raise exception 'QUIZ_HAS_NO_POINTS'; end if;
 v_percent:=round((v_score/v_max)*100)::integer;
 insert into public.academy_quiz_attempts(id,quiz_id,user_id,score,max_score,percent,passed)
 values(v_attempt,p_quiz_id,v_user,v_score,v_max,v_percent,v_percent>=v_pass);
 for q in select id from public.academy_quiz_questions where quiz_id=p_quiz_id loop
  select (item->>'option_id')::uuid into v_selected from jsonb_array_elements(p_answers) as a(item)
   where item->>'question_id'=q.id::text;
  select option_id into v_correct from public.academy_quiz_correct_answers where question_id=q.id;
  insert into public.academy_quiz_answers(attempt_id,question_id,selected_option_id,is_correct,awarded_points)
  values(v_attempt,q.id,v_selected,v_selected=v_correct,
   case when v_selected=v_correct then (select points from public.academy_quiz_questions where id=q.id) else 0 end);
 end loop;
 return jsonb_build_object('attempt_id',v_attempt,'score',v_score,'max_score',v_max,'percent',v_percent,'passed',v_percent>=v_pass);
end;
$academy_submit_secure$;
revoke all on function public.academy_submit_quiz(uuid,jsonb) from public,anon;
grant execute on function public.academy_submit_quiz(uuid,jsonb) to authenticated;

